VRT_L("1re-d-chimie-r01",{"duree":20,"titre":"Les alcanes : structure et nomenclature","accroche":"Le gaz de cuisine est un alcane.","intro":"Les alcanes sont des hydrocarbures saturés : seulement des liaisons simples.","objectifs":["écrire la formule générale","décrire la géométrie","nommer un alcane ramifié"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>alcane</strong> est un hydrocarbure saturé de formule <strong>CₙH₂ₙ₊₂</strong>. Chaque carbone est tétraédrique, avec des angles d'environ 109°.</div>"},{"t":"Nomenclature","html":"<ol><li>Trouver la chaîne carbonée la plus longue.</li><li>Numéroter pour donner les plus petits indices aux ramifications.</li><li>Nommer les groupes alkyles par ordre alphabétique.</li></ol><p>CH₃−CH(CH₃)−CH₂−CH₃ : 2-méthylbutane.</p>","labo":{"type":"trier","invite":"Choisis un alcane.","items":[["Méthane","CH₄, biogaz."],["Propane","C₃H₈."],["Butane","C₄H₁₀, gaz domestique."]]}},{"t":"Isomérie","html":"<p>Le butane et le 2-méthylpropane ont la même formule brute C₄H₁₀ : ce sont des isomères de chaîne.</p>","retenir":"Chaîne la plus longue, indices les plus petits."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> La formule générale des alcanes est :</p><ol type='a'><li>CₙH₂ₙ</li><li>CₙH₂ₙ₊₂</li><li>CₙH₂ₙ₋₂</li><li>CₙHₙ</li></ol><details><summary>Voir la réponse</summary><p><strong>CₙH₂ₙ₊₂</strong>. Chaque carbone est lié à quatre atomes par des liaisons simples.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Formule brute de l'alcane à 5 carbones ?</p><details><summary>Voir la réponse</summary><p>(Réponse : C₅H₁₂.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un hydrocarbure A, alcane, a une masse molaire de 72 g/mol. M(C) = 12 g/mol ; M(H) = 1 g/mol.</p><p><strong>Consigne 1.</strong> Détermine sa formule brute.</p><p><strong>Consigne 2.</strong> Écris et nomme les formules semi-développées de ses isomères.</p><details><summary>Voir une réponse attendue</summary><p>14n + 2 = 72, n = 5 : C₅H₁₂. Isomères : pentane CH₃−(CH₂)₃−CH₃ ; 2-méthylbutane CH₃−CH(CH₃)−CH₂−CH₃ ; 2,2-diméthylpropane C(CH₃)₄.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["CₙH₂ₙ₊₂.","Tétraèdre.","Nomenclature."],"exo":"<p>Formule brute de l'alcane à 5 carbones ? <em>(Réponse : C₅H₁₂.)</em></p>","quiz":[{"q":"La formule générale des alcanes est :","r":["CₙH₂ₙ","CₙH₂ₙ₊₂","CₙH₂ₙ₋₂","CₙHₙ"],"b":1,"e":"Chaque carbone est lié à quatre atomes par des liaisons simples."},{"q":"Dans un alcane, les liaisons carbone-carbone sont :","r":["doubles","triples","simples","ioniques"],"b":2,"e":"Les alcanes sont des hydrocarbures saturés."},{"q":"L'alcane à 3 atomes de carbone est :","r":["le butane","l'éthane","le pentane","le propane"],"b":3,"e":"Préfixes : méth-1, éth-2, prop-3, but-4, pent-5."},{"q":"Le nom de CH₃-CH(CH₃)-CH₃ est :","r":["méthylpropane","butane","propane","diméthyléthane"],"b":0,"e":"Chaîne principale de 3 carbones avec un groupe méthyle en 2."},{"q":"La formule brute du butane est :","r":["C₄H₈","C₄H₁₀","C₄H₆","C₃H₈"],"b":1,"e":"n = 4 : C₄H₂ₓ₄₊₂."},{"q":"Autour d'un carbone d'alcane, la géométrie est :","r":["plane","linéaire","tétraédrique","carrée"],"b":2,"e":"Angles de liaison voisins de 109°."},{"q":"Le butane et le méthylpropane sont :","r":["le même composé","des alcènes","des alcools","des isomères"],"b":3,"e":"Même formule brute C₄H₁₀, enchaînements différents."},{"q":"Le gaz domestique des bouteilles contient surtout :","r":["du butane","du méthane","de l'éthylène","de l'acétylène"],"b":0,"e":"Il est liquéfié sous pression."},{"q":"La masse molaire du propane C₃H₈ (C = 12, H = 1) vaut :","r":["42 g/mol","44 g/mol","36 g/mol","48 g/mol"],"b":1,"e":"3 × 12 + 8 × 1 = 44."},{"q":"Pour nommer un alcane ramifié, on choisit d'abord :","r":["le groupe substituant le plus petit de la molécule","le premier carbone écrit dans la formule","la chaîne carbonée la plus longue","la chaîne carbonée la plus courte"],"b":2,"e":"On numérote ensuite pour donner les plus petits indices aux ramifications."}],"c":"1re D","m":"chimie","rang":1,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une vendeuse de gaz de Bafoussam se demande ce que contient sa bouteille, qui renferme surtout du butane.","tache":"Donne sa formule brute et dessine sa formule semi-développée."},"gratuit":true});
VRT_L("1re-d-chimie-r02",{"duree":20,"titre":"Propriétés des alcanes et préparation du méthane","accroche":"Bien brûler pour ne pas s'intoxiquer.","intro":"Les alcanes brûlent et subissent des substitutions ; le méthane se prépare au laboratoire.","objectifs":["écrire une combustion","décrire une substitution","préparer le méthane"],"parties":[{"t":"Combustion","html":"<div class='def'><b>Définition</b>La <strong>combustion complète</strong> d'un alcane donne du dioxyde de carbone et de l'eau : CH₄ + 2O₂ → CO₂ + 2H₂O. Incomplète, elle produit du monoxyde de carbone, toxique.</div>"},{"t":"Substitution","verrou":true},{"t":"Préparation du méthane","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":2,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une famille de Bamenda cuisine au gaz dans une pièce fermée et ressent des maux de tête.","tache":"Explique le danger et donne un conseil."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r03",{"duree":20,"titre":"Alcènes et alcynes : structure et nomenclature","accroche":"Une double ou une triple liaison.","intro":"Les alcènes et les alcynes sont des hydrocarbures insaturés.","objectifs":["écrire leurs formules générales","décrire leur géométrie","les nommer"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>alcène</strong> (CₙH₂ₙ) contient une double liaison C=C, plane, angles de 120°. Un <strong>alcyne</strong> (CₙH₂ₙ₋₂) contient une triple liaison C≡C, linéaire.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Isomérie Z/E","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":3,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Dans une plantation de Penja, on mûrit les bananes avec de l'éthylène, le plus simple des alcènes.","tache":"Donne sa formule et sa géométrie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r04",{"duree":20,"titre":"Propriétés des alcènes et alcynes ; acétylène","accroche":"Des additions et des plastiques.","intro":"La liaison multiple permet des réactions d'addition et de polymérisation.","objectifs":["écrire des additions","appliquer la règle de Markovnikov","décrire une polymérisation"],"parties":[{"t":"Additions","html":"<div class='def'><b>Définition</b>Les alcènes et alcynes donnent des <strong>additions</strong> : H₂, Br₂ (décoloration de l'eau de brome), HCl, H₂O. <strong>Règle de Markovnikov</strong> : lors de l'addition de HX, H se fixe sur le carbone le plus hydrogéné.</div>"},{"t":"Polymérisation","verrou":true},{"t":"Acétylène","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":4,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une entreprise de Douala doit produire 120 kg d'isolants en polyéthylène.","tache":"Écris l'équation de polymérisation et calcule la masse d'éthylène nécessaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r05",{"duree":20,"titre":"Composés oxygénés : généralités","accroche":"Alcool, aldéhyde, cétone, acide.","intro":"Un groupe fonctionnel oxygéné donne à la molécule ses propriétés.","objectifs":["reconnaître les groupes fonctionnels","nommer les composés simples","trouver une formule brute"],"parties":[{"t":"Groupes fonctionnels","html":"<div class='def'><b>Définition</b>Un <strong>groupe fonctionnel</strong> est un groupe d'atomes responsable des propriétés : alcool (−OH), aldéhyde (−CHO), cétone (C=O entre deux carbones), acide carboxylique (−COOH), ester (−COO−).</div>"},{"t":"Nomenclature","verrou":true},{"t":"Formule brute","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":5,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Le vin de palme de la région de l'Ouest s'aigrit en quelques jours.","tache":"Nomme les composés oxygénés en jeu."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r06",{"duree":20,"titre":"Propriétés physiques et tests des aldéhydes et cétones","accroche":"Un précipité, un miroir d'argent.","intro":"Des réactifs simples distinguent aldéhydes et cétones.","objectifs":["utiliser la DNPH","distinguer aldéhyde et cétone","expliquer les températures d'ébullition"],"parties":[{"t":"Tests","html":"<div class='def'><b>Définition</b>La <strong>DNPH</strong> donne un précipité jaune-orangé avec les aldéhydes et les cétones. Seuls les <strong>aldéhydes</strong> réduisent la liqueur de Fehling (précipité rouge brique), le réactif de Tollens (miroir d'argent) et rosissent le réactif de Schiff.</div>"},{"t":"Propriétés physiques","verrou":true},{"t":"Démarche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":6,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Au laboratoire d'un lycée de Bafia, deux flacons sans étiquette contiennent l'un de l'éthanal, l'autre de la propanone.","tache":"Propose un test pour les identifier."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r07",{"duree":20,"titre":"Les composés aromatiques : généralités","accroche":"Le benzène, un cycle très stable.","intro":"Les composés aromatiques contiennent le noyau benzénique.","objectifs":["décrire le benzène","expliquer la délocalisation","nommer des dérivés"],"parties":[{"t":"Le benzène","html":"<div class='def'><b>Définition</b>Le <strong>benzène</strong> C₆H₆ est un cycle plan de six carbones. Ses six électrons π sont <strong>délocalisés</strong> sur tout le cycle : toutes les liaisons C−C mesurent 140 pm.</div>"},{"t":"Dérivés","verrou":true},{"t":"Sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":7,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Un vendeur de carburant frelaté à Kousseri manipule l'essence sans gants ni masque.","tache":"Explique le danger."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r08",{"duree":20,"titre":"Propriétés chimiques des composés aromatiques","accroche":"Substituer plutôt qu'additionner.","intro":"Le noyau benzénique donne surtout des substitutions, qui le conservent.","objectifs":["écrire une halogénation","écrire une nitration","écrire une addition"],"parties":[{"t":"Substitutions","html":"<div class='def'><b>Définition</b>Le benzène donne principalement des <strong>substitutions</strong> : halogénation (Cl₂ avec AlCl₃), nitration (HNO₃ avec H₂SO₄), alkylation de Friedel-Crafts.</div>"},{"t":"Additions","verrou":true},{"t":"Le TNT","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":8,"apc":{"module":"Chimie organique : hydrocarbures et composés oxygénés","famille":"Usage des produits pétroliers et des matières plastiques","agir":"Identifier et utiliser de façon sûre les composés organiques","situation":"Une carrière de la région du Centre utilise des explosifs dérivés du toluène.","tache":"Écris la nitration du toluène et calcule la masse de TNT obtenue à partir de 250 g de toluène, avec 80 % de rendement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r09",{"duree":20,"titre":"Action des acides et des ions métalliques sur les métaux","accroche":"Un clou qui se couvre de cuivre.","intro":"Ces réactions mettent en jeu un transfert d'électrons : ce sont des oxydoréductions.","objectifs":["écrire l'action d'un acide sur un métal","écrire une réaction métal-ion","définir oxydant et réducteur"],"parties":[{"t":"Concepts clés","html":"<div class='def'><b>Définition</b>Un <strong>oxydant</strong> capte des électrons ; un <strong>réducteur</strong> en cède. L'<strong>oxydation</strong> est une perte d'électrons, la <strong>réduction</strong> un gain.</div>"},{"t":"Exemples","html":"<p>Zn + 2H₃O⁺ → Zn²⁺ + H₂ + 2H₂O. Un clou de fer dans une solution de sulfate de cuivre : Fe + Cu²⁺ → Fe²⁺ + Cu.</p>","labo":{"type":"calcul","f":"mole","vals":{"m":27,"M":27}}},{"t":"Calcul","html":"<p>2Al + 6H₃O⁺ → 2Al³⁺ + 3H₂ + 6H₂O. 27 g d'aluminium (1 mol) donnent 1,5 mol de H₂, soit 36 L si V_m = 24 L/mol.</p>","retenir":"Oxydation : perte d'électrons."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le fer réagit avec l'acide chlorhydrique en libérant :</p><ol type='a'><li>du dioxygène</li><li>du dihydrogène</li><li>du dichlore</li><li>du dioxyde de carbone</li></ol><details><summary>Voir la réponse</summary><p><strong>du dihydrogène</strong>. Fe + 2H⁺ → Fe²⁺ + H₂.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Dans Fe + Cu²⁺ → Fe²⁺ + Cu, qui est oxydé ?</p><details><summary>Voir la réponse</summary><p>(Réponse : le fer.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un bijoutier de Foumban veut connaître la composition d'un laiton (cuivre et zinc). Il attaque 10 g d'alliage par un excès d'acide chlorhydrique et recueille 1,2 L de dihydrogène. M(Zn) = 65,4 g/mol ; V_m = 24 L/mol.</p><p><strong>Consigne 1.</strong> Écris l'équation de la réaction et indique quel métal réagit.</p><p><strong>Consigne 2.</strong> Calcule le pourcentage massique de zinc.</p><details><summary>Voir une réponse attendue</summary><p>Zn + 2H₃O⁺ → Zn²⁺ + H₂ + 2H₂O ; le cuivre ne réagit pas. n(H₂) = 0,05 mol = n(Zn), m = 3,27 g, soit 32,7 % de zinc.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la sécurité au laboratoire."}],"revision":["Oxydant, réducteur.","Oxydation, réduction.","Bilan."],"exo":"<p>Dans Fe + Cu²⁺ → Fe²⁺ + Cu, qui est oxydé ? <em>(Réponse : le fer.)</em></p>","quiz":[{"q":"Le fer réagit avec l'acide chlorhydrique en libérant :","r":["du dioxygène","du dihydrogène","du dichlore","du dioxyde de carbone"],"b":1,"e":"Fe + 2H⁺ → Fe²⁺ + H₂."},{"q":"Le cuivre réagit-il avec l'acide chlorhydrique dilué ?","r":["oui, vivement","oui, avec dégagement de chlore","non","oui, il devient rouge"],"b":2,"e":"Le cuivre est moins réducteur que l'hydrogène."},{"q":"Un clou de fer plongé dans une solution de sulfate de cuivre se couvre :","r":["de rouille","de sel","de fer pur métallique","d'un dépôt de cuivre"],"b":3,"e":"Fe + Cu²⁺ → Fe²⁺ + Cu."},{"q":"Dans cette réaction, le fer :","r":["est oxydé","est réduit","ne réagit pas","se dépose"],"b":0,"e":"Il perd des électrons."},{"q":"Les ions Cu²⁺ dans cette réaction sont :","r":["oxydés","réduits","spectateurs","détruits"],"b":1,"e":"Ils gagnent des électrons."},{"q":"La couleur bleue d'une solution est due aux ions :","r":["Fe²⁺","Zn²⁺","Cu²⁺","Na⁺"],"b":2,"e":"Fe²⁺ est vert pâle ; Zn²⁺ et Na⁺ incolores."},{"q":"Un réducteur est une espèce qui :","r":["capte des électrons","capte des protons","cède des protons","cède des électrons"],"b":3,"e":"Ex. : les métaux."},{"q":"Un oxydant est une espèce qui :","r":["capte des électrons","cède des électrons","cède des protons","ne réagit jamais"],"b":0,"e":"Ex. : Cu²⁺, H⁺."},{"q":"Le zinc plongé dans une solution de Cu²⁺ :","r":["ne réagit pas","se recouvre de cuivre","dégage du dioxygène","se colore en bleu"],"b":1,"e":"Zn + Cu²⁺ → Zn²⁺ + Cu."},{"q":"Le test du dihydrogène est :","r":["le trouble de l'eau de chaux par le gaz dégagé","le rallumage d'une bûchette incandescente","une légère détonation à l'approche d'une flamme","une coloration bleue"],"b":2,"e":"Il brûle avec le dioxygène de l'air."}],"c":"1re D","m":"chimie","rang":9,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un chaudronnier de Garoua nettoie des copeaux d'aluminium de 27 g avec de l'acide chlorhydrique en excès.","tache":"Quel volume de gaz se dégage-t-il ?"},"gratuit":true});
VRT_L("1re-d-chimie-r10",{"duree":20,"titre":"Couples oxydant-réducteur","accroche":"Deux formes d'une même espèce.","intro":"Chaque oxydant est associé à un réducteur conjugué : ils forment un couple.","objectifs":["définir un couple","écrire une demi-équation","combiner deux demi-équations"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>couple oxydant/réducteur</strong> est formé de deux espèces liées par la demi-équation <strong>Ox + ne⁻ ⇌ Red</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":10,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Une bijoutière de Foumban dépose une fine couche d'argent sur un bijou en cuivre plongé dans une solution d'ions argent.","tache":"Écris les demi-équations et le bilan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r11",{"duree":20,"titre":"Classification électrochimique","accroche":"Prévoir qui réagit avec qui.","intro":"Classer les couples permet de prévoir les réactions spontanées.","objectifs":["classer des couples","appliquer la règle du gamma","prévoir l'action des acides"],"parties":[{"t":"La classification","html":"<div class='def'><b>Définition</b>On classe les couples selon leur potentiel standard E°. L'oxydant le plus fort réagit spontanément avec le réducteur le plus fort (<strong>règle du gamma</strong>).</div>"},{"t":"Ordre utile","verrou":true},{"t":"Prévisions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":11,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un menuisier de Kribi range ses clous en fer dans une boîte en cuivre humide.","tache":"Lequel des deux métaux sera attaqué ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r12",{"duree":20,"titre":"La pile Daniell : description","accroche":"Une pile de laboratoire de 1,1 V.","intro":"La pile Daniell exploite la réaction entre le zinc et les ions cuivre, sans contact direct.","objectifs":["décrire la pile","écrire sa notation conventionnelle","indiquer les pôles"],"parties":[{"t":"Description","html":"<div class='def'><b>Définition</b>La <strong>pile Daniell</strong> comprend une lame de zinc dans une solution de Zn²⁺ et une lame de cuivre dans une solution de Cu²⁺, reliées par un <strong>pont salin</strong>.</div>"},{"t":"Fonctionnement","verrou":true},{"t":"Notation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":12,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Au club scientifique d'un lycée de Bertoua, des élèves fabriquent une pile Daniell pour allumer une diode.","tache":"Décris le montage et indique les pôles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r13",{"duree":20,"titre":"Potentiels et force électromotrice d'une pile","accroche":"Calculer la tension à vide.","intro":"Les potentiels standards permettent de prévoir la force électromotrice d'une pile.","objectifs":["définir le potentiel standard","calculer une f.é.m.","identifier les pôles"],"parties":[{"t":"Potentiel standard","html":"<div class='def'><b>Définition</b>Le <strong>potentiel standard</strong> E° d'un couple est mesuré par rapport à l'électrode standard à hydrogène (E° = 0 V).</div>"},{"t":"Force électromotrice","verrou":true},{"t":"Pôles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":13,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un électricien de Ngaoundéré veut une pile de plus de 1 V avec des métaux de récupération : zinc, plomb, cuivre.","tache":"Quel couple de métaux choisir ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r14",{"duree":20,"titre":"Couples autres que métal/ion métallique","accroche":"Permanganate, dichromate, iode.","intro":"Beaucoup d'oxydants et de réducteurs ne sont pas des métaux ; leurs demi-équations font intervenir l'eau et les ions H⁺.","objectifs":["équilibrer une demi-équation en milieu acide","citer des couples usuels","écrire un bilan"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>Pour équilibrer une demi-équation en milieu acide : équilibrer l'élément principal, puis O avec H₂O, puis H avec H⁺, puis les charges avec e⁻.</div>"},{"t":"Couples usuels","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":14,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Les éthylotests chimiques utilisés à Yaoundé virent de l'orange au vert en présence d'alcool.","tache":"Explique ce changement de couleur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r15",{"duree":20,"titre":"Dosages d'oxydoréduction","accroche":"Trouver une concentration inconnue.","intro":"Un dosage utilise une réaction rapide et totale ; l'équivalence se repère par un changement de couleur.","objectifs":["décrire le montage","écrire la relation à l'équivalence","calculer une concentration"],"parties":[{"t":"Équivalence","html":"<div class='def'><b>Définition</b>À l'<strong>équivalence</strong>, les réactifs ont été introduits dans les proportions stœchiométriques. Pour MnO₄⁻ + 5Fe²⁺ : n(Fe²⁺) = 5 × n(MnO₄⁻).</div>"},{"t":"Exemple","verrou":true},{"t":"Repérage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":15,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Le club scientifique d'un lycée de l'Ouest dose l'alcool dans le sang d'un élève par le dichromate, selon le règlement intérieur qui fixe le seuil à 0,5 g/L.","tache":"Indique la démarche pour décider."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r16",{"duree":20,"titre":"Électrolyse, corrosion et protection des métaux","accroche":"La rouille coûte cher.","intro":"L'électrolyse force une réaction ; la corrosion est une oxydation naturelle des métaux.","objectifs":["décrire une électrolyse","expliquer la corrosion du fer","choisir une protection"],"parties":[{"t":"Électrolyse","html":"<div class='def'><b>Définition</b>Une <strong>électrolyse</strong> est une réaction d'oxydoréduction forcée par un générateur. L'oxydation a lieu à l'anode (reliée au pôle +), la réduction à la cathode.</div>"},{"t":"Corrosion","verrou":true},{"t":"Protection","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":16,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Les tôles des maisons du quartier de Bonabéri, près de la mer, rouillent très vite.","tache":"Explique pourquoi et propose deux protections."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-chimie-r17",{"duree":20,"titre":"Le nombre d'oxydation","accroche":"Un compteur d'électrons.","intro":"Le nombre d'oxydation généralise les notions d'oxydation et de réduction, même sans ions.","objectifs":["appliquer les règles","calculer un nombre d'oxydation","repérer oxydation et réduction"],"parties":[{"t":"Règles","html":"<div class='def'><b>Définition</b>Le <strong>nombre d'oxydation</strong> (n.o.) vaut 0 pour un corps simple, la charge pour un ion monoatomique ; O vaut −2 (sauf peroxydes), H vaut +1 ; la somme des n.o. est égale à la charge de l'édifice.</div>"},{"t":"Exemples","html":"<p>Mn dans MnO₄⁻ : +7. Cr dans Cr₂O₇²⁻ : +6. S dans H₂SO₄ : +6.</p>","labo":{"type":"etapes","items":[["Charge","somme des n.o."],["Oxygène","−2 chacun."],["Hydrogène","+1 chacun."],["Inconnu","par différence."]]}},{"t":"Interprétation","html":"<p>Une oxydation est une augmentation du n.o. ; une réduction, une diminution.</p>","retenir":"Somme des n.o. = charge."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le nombre d'oxydation (n.o.) de l'oxygène est généralement :</p><ol type='a'><li>+II</li><li>0</li><li>−II</li><li>−I</li></ol><details><summary>Voir la réponse</summary><p><strong>−II</strong>. Sauf dans les peroxydes (−I).</p></details><p><strong>Application directe des savoirs.</strong></p><p>n.o. du carbone dans CO₂ ?</p><details><summary>Voir la réponse</summary><p>(Réponse : +4.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Dans l'industrie des engrais, l'ammoniac est oxydé : 4NH₃ + 5O₂ → 4NO + 6H₂O, puis NO devient NO₂ puis HNO₃.</p><p><strong>Consigne 1.</strong> Calcule le nombre d'oxydation de l'azote dans NH₃, NO, NO₂, HNO₃ et N₂.</p><p><strong>Consigne 2.</strong> Montre que la première réaction est une oxydoréduction en précisant l'oxydant et le réducteur.</p><details><summary>Voir une réponse attendue</summary><p>N : −3 (NH₃), +2 (NO), +4 (NO₂), +5 (HNO₃), 0 (N₂). L'azote passe de −3 à +2 (oxydé) ; l'oxygène de 0 à −2 (réduit) : O₂ est l'oxydant, NH₃ le réducteur.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Règles.","Calculs.","Augmentation : oxydation."],"exo":"<p>n.o. du carbone dans CO₂ ? <em>(Réponse : +4.)</em></p>","quiz":[{"q":"Le nombre d'oxydation (n.o.) de l'oxygène est généralement :","r":["+II","0","−II","−I"],"b":2,"e":"Sauf dans les peroxydes (−I)."},{"q":"Le n.o. de l'hydrogène dans les composés est généralement :","r":["−I","0","+II","+I"],"b":3,"e":"Sauf dans les hydrures métalliques."},{"q":"Le n.o. d'un corps simple (Fe, O₂, Cl₂) est :","r":["0","+I","−II","égal à sa masse"],"b":0,"e":"Aucun transfert d'électrons."},{"q":"Le n.o. du soufre dans H₂SO₄ est :","r":["+IV","+VI","−II","+II"],"b":1,"e":"2(+I) + x + 4(−II) = 0."},{"q":"Le n.o. du soufre dans H₂S est :","r":["+II","+VI","−II","0"],"b":2,"e":"Somme nulle : 2 × (+I) + x = 0, donc x = −II."},{"q":"Le n.o. du manganèse dans MnO₄⁻ est :","r":["+II","+IV","−I","+VII"],"b":3,"e":"x + 4(−II) = −1."},{"q":"La somme des n.o. dans un ion vaut :","r":["la charge de l'ion","zéro toujours","le nombre d'atomes","la masse molaire"],"b":0,"e":"Ex. : SO₄²⁻ : somme = −2."},{"q":"Une oxydation correspond à :","r":["une diminution du n.o.","une augmentation du n.o.","un n.o. inchangé","un n.o. nul"],"b":1,"e":"L'élément perd des électrons."},{"q":"Le n.o. de l'azote dans NH₃ est :","r":["+III","0","−III","+V"],"b":2,"e":"Somme nulle : x + 3 × (+I) = 0, donc x = −III."},{"q":"Le n.o. de l'azote dans HNO₃ est :","r":["−III","+III","+I","+V"],"b":3,"e":"(+I) + x + 3(−II) = 0."}],"c":"1re D","m":"chimie","rang":17,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Un réparateur de batteries de Dschang manipule l'acide des batteries, H₂SO₄ ; il range aussi du dioxyde de soufre SO₂ et du sulfure d'hydrogène H₂S, à l'odeur d'œuf pourri. Son apprenti croit que le soufre a toujours le même nombre d'oxydation.","tache":"Calcule le nombre d'oxydation du soufre dans H₂SO₄, SO₂ et H₂S, puis réponds à l'apprenti."},"gratuit":true});
VRT_L("1re-d-chimie-r18",{"duree":20,"titre":"Utiliser le nombre d'oxydation","accroche":"Équilibrer sans ions.","intro":"Les n.o. permettent d'équilibrer des réactions en voie sèche, comme la métallurgie.","objectifs":["équilibrer avec les n.o.","étudier une réduction d'oxyde","décrire une métallurgie"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Définition</b>La somme des augmentations de n.o. doit être égale à la somme des diminutions.</div>"},{"t":"Exemples","verrou":true},{"t":"Voie sèche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"chimie","rang":18,"apc":{"module":"Oxydoréduction","famille":"Protection des métaux et production d'énergie","agir":"Prévenir la corrosion et exploiter les réactions d'oxydoréduction","situation":"Dans une usine de Douala, on récupère le cuivre d'oxydes usés en les chauffant dans un courant d'ammoniac : il se forme du cuivre, de l'eau et du diazote. Le contremaître note : CuO + NH₃ → Cu + H₂O + N₂ et veut savoir quelle masse d'ammoniac prévoir pour 1 mol de CuO.","tache":"Équilibre l'équation à l'aide des nombres d'oxydation, puis donne la quantité d'ammoniac pour 1 mol de CuO."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r01",{"duree":20,"titre":"Les droits de l'homme","accroche":"Des droits pour chaque être humain, partout.","intro":"Les droits de l'homme sont les droits que toute personne possède du seul fait qu'elle est un être humain. Ils sont proclamés par des textes internationaux et par la Constitution camerounaise.","objectifs":["définir les droits de l'homme","en connaître les caractères","citer les textes qui les proclament"],"parties":[{"t":"Définition et caractères","html":"<div class='def'><b>Définition</b>Les <strong>droits de l'homme</strong> sont l'ensemble des droits et libertés fondamentaux reconnus à toute personne humaine, sans distinction de sexe, d'origine, de religion ou d'opinion.</div><p>Ils sont <strong>universels</strong> (valables pour tous), <strong>inaliénables</strong> (on ne peut pas les céder), <strong>indivisibles</strong> et <strong>interdépendants</strong> (tous se tiennent).</p>"},{"t":"Les catégories de droits","html":"<ul><li><strong>Droits civils et politiques</strong> : droit à la vie, liberté d'expression, droit de vote, procès équitable.</li><li><strong>Droits économiques, sociaux et culturels</strong> : droit à l'éducation, à la santé, au travail, au logement.</li><li><strong>Droits de solidarité</strong> : droit à la paix, au développement, à un environnement sain.</li></ul>","retenir":"Trois générations de droits : civils et politiques, économiques et sociaux, de solidarité.","labo":{"type":"trier","invite":"Choisis une catégorie de droits.","items":[["Civils et politiques","vie, expression, vote, procès équitable."],["Économiques, sociaux et culturels","éducation, santé, travail, logement."],["De solidarité","paix, développement, environnement sain."]]}},{"t":"Les textes fondamentaux","html":"<ul><li>la <strong>Déclaration universelle des droits de l'homme</strong>, adoptée par l'ONU le 10 décembre 1948 ;</li><li>la <strong>Charte africaine des droits de l'homme et des peuples</strong>, adoptée en 1981 ;</li><li>la <strong>Convention relative aux droits de l'enfant</strong> de 1989 ;</li><li>le <strong>préambule de la Constitution</strong> camerounaise du 18 janvier 1996.</li></ul><div class='attention'><b>Attention</b>à chaque droit correspond un devoir : respecter les droits des autres.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Les droits de l'homme sont reconnus à toute personne :</p><ol type='a'><li>seulement si elle paie ses impôts</li><li>à partir de l'âge de la majorité électorale</li><li>seulement si elle est de nationalité camerounaise</li><li>du seul fait qu'elle est un être humain</li></ol><details><summary>Voir la réponse</summary><p><strong>du seul fait qu'elle est un être humain</strong>. Ils sont universels.</p></details><p><strong>Vérification des savoir-faire.</strong></p><p>Le droit à l'éducation appartient à quelle catégorie ?</p><details><summary>Voir la réponse</summary><p>(Réponse : aux droits économiques, sociaux et culturels.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Situation-problème.</strong> Document : rapport d'une ONG signalant des enfants travaillant dans une carrière de pierres à la périphérie de Yaoundé, sans scolarisation.</p><p><strong>Tâche 1.</strong> Identifie deux droits de l'enfant violés.</p><p><strong>Tâche 2.</strong> Propose deux actions et les acteurs à mobiliser.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>Droit à l'éducation et droit d'être protégé contre l'exploitation économique. Actions : signalement aux services des Affaires sociales et à la CDHC ; campagne de sensibilisation des parents avec les chefs de quartier et une aide à la scolarisation.</p></details></div>","retenir":"Savoir-être mobilisé : Tolérance et respect de l'autre."}],"revision":["Droits universels, inaliénables, indivisibles.","Civils et politiques ; économiques, sociaux et culturels ; de solidarité.","DUDH 1948, Charte africaine 1981, CDE 1989, Constitution 1996."],"exo":"<p>Le droit à l'éducation appartient à quelle catégorie ? <em>(Réponse : aux droits économiques, sociaux et culturels.)</em></p>","quiz":[{"q":"Les droits de l'homme sont reconnus à toute personne :","r":["seulement si elle paie ses impôts","à partir de l'âge de la majorité électorale","seulement si elle est de nationalité camerounaise","du seul fait qu'elle est un être humain"],"b":3,"e":"Ils sont universels."},{"q":"La Déclaration universelle des droits de l'homme a été adoptée le :","r":["10 décembre 1948","24 octobre 1945","25 mai 1963","18 janvier 1996"],"b":0,"e":"Adoptée par l'Assemblée générale de l'ONU à Paris."},{"q":"Dire que les droits de l'homme sont inaliénables signifie :","r":["qu'ils ne concernent que les étrangers","qu'on ne peut pas les céder ni les perdre","qu'ils changent selon les pays","qu'on peut les vendre à un tiers"],"b":1,"e":"Personne ne peut y renoncer ni en être privé arbitrairement."},{"q":"Le droit à l'éducation fait partie des droits :","r":["civils et politiques uniquement","de solidarité entre les peuples","économiques, sociaux et culturels","réservés aux adultes"],"b":2,"e":"Comme la santé, le travail, le logement."},{"q":"Le droit de vote fait partie des droits :","r":["économiques et sociaux","de solidarité","culturels seulement","civils et politiques"],"b":3,"e":"Il permet de participer à la vie politique."},{"q":"Le droit à un environnement sain est un droit :","r":["de solidarité","civil et politique","économique et individuel","réservé aux États"],"b":0,"e":"Les droits de solidarité concernent toute la collectivité."},{"q":"La Charte africaine des droits de l'homme et des peuples a été adoptée en :","r":["1948","1981","1963","2002"],"b":1,"e":"Elle a été adoptée à Nairobi et est entrée en vigueur en 1986."},{"q":"La Convention relative aux droits de l'enfant date de :","r":["1948","1996","1989","2000"],"b":2,"e":"Adoptée par l'ONU le 20 novembre 1989."},{"q":"Au Cameroun, les droits fondamentaux sont proclamés dans :","r":["le règlement intérieur des écoles","le Code de la route","les statuts des partis politiques","le préambule de la Constitution"],"b":3,"e":"Le préambule de la Constitution de 1996 les énumère."},{"q":"À chaque droit correspond :","r":["le devoir de respecter les droits des autres","un impôt particulier à payer chaque année à l'État","une autorisation du chef de l'État","un privilège réservé à certains"],"b":0,"e":"Droits et devoirs vont ensemble."}],"c":"1re D","m":"ecm","rang":1,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Dans un village du Mayo-Tsanaga, une fille de 13 ans est retirée de l'école par son père qui veut la marier ; sa camarade de classe s'indigne mais ne sait pas comment réagir.","tache":"Identifie deux droits de l'enfant violés et indique deux personnes ou structures auxquelles la camarade peut s'adresser."},"gratuit":true});
VRT_L("1re-d-ecm-r02",{"duree":20,"titre":"Les institutions de protection des droits de l'homme","accroche":"Qui défend nos droits quand ils sont violés ?","intro":"Des institutions nationales et internationales veillent au respect des droits de l'homme : elles reçoivent les plaintes, enquêtent, sensibilisent et sanctionnent.","objectifs":["citer des institutions nationales de protection","citer des institutions internationales et africaines","savoir comment les saisir"],"parties":[{"t":"Au Cameroun","html":"<div class='def'><b>Définition</b>Une <strong>institution de protection des droits de l'homme</strong> est un organisme chargé de promouvoir les droits, de recevoir les plaintes et de faire cesser les violations.</div><ul><li>la <strong>Commission des droits de l'homme du Cameroun</strong> (CDHC), créée en 2019 pour remplacer la Commission nationale des droits de l'homme et des libertés ;</li><li>les <strong>tribunaux</strong>, gardiens des libertés individuelles ;</li><li>le <strong>Parlement</strong>, qui vote les lois protectrices ;</li><li>les <strong>ministères</strong> chargés des Affaires sociales et de la Promotion de la femme et de la famille ;</li><li>les <strong>associations et ONG</strong> de défense des droits.</li></ul>"},{"t":"Au niveau africain et mondial","verrou":true},{"t":"Saisir une institution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":2,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Moussa, 17 ans, a été gardé à vue quatre jours dans un commissariat de Maroua sans voir de magistrat ni pouvoir prévenir sa famille ; son oncle veut « régler l'affaire avec de l'argent ».","tache":"Indique les droits de Moussa qui ont été méconnus et propose à son oncle une démarche légale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r03",{"duree":20,"titre":"TD : étude d'une structure locale de promotion des droits de l'homme","accroche":"Enquêter près de chez soi.","intro":"Ce travail dirigé conduit à identifier et étudier une structure de sa localité qui promeut les droits de l'homme : centre social, association, clinique juridique, antenne de la CDHC.","objectifs":["préparer une enquête","présenter une structure","évaluer son action"],"parties":[{"t":"Préparer l'enquête","html":"<div class='def'><b>Définition</b>Une <strong>enquête</strong> est une recherche d'informations auprès de personnes et de documents, menée avec un questionnaire préparé et une méthode.</div><ol><li>Choisir la structure et prendre rendez-vous.</li><li>Rédiger un questionnaire : missions, public, activités, moyens, difficultés.</li><li>Répartir les rôles : questions, prise de notes, photographies autorisées.</li></ol>"},{"t":"Présenter la structure","verrou":true},{"t":"Évaluer et restituer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":3,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Ton groupe doit enquêter sur le centre social de ton arrondissement. Le responsable n'accorde que 30 minutes d'entretien et refuse que l'on photographie les personnes accueillies.","tache":"Rédige cinq questions prioritaires pour l'entretien et explique comment respecter la règle sur les photographies."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r04",{"duree":20,"titre":"Le concept d'intégrité morale","accroche":"Être droit même quand personne ne regarde.","intro":"L'intégrité morale est une qualité essentielle du citoyen et de l'agent public. Son absence ouvre la porte à la corruption, à la fraude et au détournement.","objectifs":["définir l'intégrité morale","identifier ses manifestations et ses contraires","en mesurer l'importance pour la société"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>intégrité morale</strong> est la qualité d'une personne honnête, droite et incorruptible, qui agit conformément aux règles et à sa conscience, même lorsqu'elle pourrait tirer profit d'un manquement.</div><p>Elle se manifeste par l'<strong>honnêteté</strong>, la <strong>probité</strong>, le <strong>respect de la parole donnée</strong>, la <strong>loyauté</strong> et le <strong>sens du bien commun</strong>.</p>"},{"t":"Les atteintes à l'intégrité","verrou":true},{"t":"Pourquoi l'intégrité est-elle essentielle ?","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":4,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"À l'approche du Probatoire, un message circule dans ta classe : « sujets disponibles contre 5 000 F ». Sept camarades veulent payer ; ta meilleure amie hésite.","tache":"Rédige un message de huit lignes pour la convaincre de refuser, en utilisant deux arguments liés à l'intégrité morale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r05",{"duree":20,"titre":"Les institutions de promotion et de préservation de l'intégrité morale au Cameroun","accroche":"Les gardiens de la probité publique.","intro":"Pour lutter contre la corruption et les détournements, le Cameroun a mis en place des institutions de prévention, de contrôle et de répression.","objectifs":["citer les institutions de lutte contre la corruption","préciser le rôle de chacune","savoir dénoncer un acte de corruption"],"parties":[{"t":"Les institutions de prévention","html":"<div class='def'><b>Définition</b>Une <strong>institution de préservation de l'intégrité morale</strong> est un organisme public chargé de prévenir, contrôler ou sanctionner les atteintes à la probité.</div><ul><li>la <strong>Commission nationale anti-corruption</strong> (CONAC), créée en 2006 : prévention, enquêtes, sensibilisation, réception des dénonciations ;</li><li>les <strong>cellules de lutte contre la corruption</strong> dans les ministères ;</li><li>l'<strong>Agence nationale d'investigation financière</strong> (ANIF) contre le blanchiment.</li></ul>"},{"t":"Les institutions de contrôle et de répression","verrou":true},{"t":"Dénoncer un acte de corruption","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":5,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"Pour obtenir l'acte de naissance de son fils, une mère de Sangmélima s'entend dire par un agent : « reviens demain avec 3 000 F, sinon ton dossier dort ». L'acte est en principe délivré gratuitement.","tache":"Identifie l'infraction commise et indique à la mère deux institutions qu'elle peut saisir, avec la démarche à suivre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r06",{"duree":20,"titre":"TD : l'intégrité morale en milieu scolaire","accroche":"L'école, première école de l'intégrité.","intro":"Le lycée est un lieu où l'on apprend aussi à être honnête. Ce travail dirigé repère les atteintes à l'intégrité en milieu scolaire et construit des réponses.","objectifs":["identifier les atteintes à l'intégrité à l'école","en analyser les causes et les conséquences","élaborer une charte d'intégrité"],"parties":[{"t":"Les atteintes en milieu scolaire","html":"<div class='def'><b>Définition</b>Une <strong>atteinte à l'intégrité en milieu scolaire</strong> est tout comportement malhonnête qui fausse l'évaluation, l'accès aux services ou la vie commune à l'école.</div><ul><li>la tricherie aux devoirs et aux examens ;</li><li>l'achat de notes ou de places ;</li><li>la falsification de bulletins ou de signatures ;</li><li>le vol de matériel ;</li><li>le harcèlement en échange de notes.</li></ul>"},{"t":"Causes et conséquences","verrou":true},{"t":"Une charte d'intégrité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":6,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"Lors d'une composition, l'enseignant de ton lycée de Bertoua découvre que 18 copies sur 52 sont identiques. Le club d'éducation à la citoyenneté veut agir avant les examens officiels.","tache":"Propose une charte de cinq engagements et deux actions du club pour la faire vivre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r07",{"duree":20,"titre":"Les médias et leur impact sur l'opinion publique","accroche":"Ce que nous pensons dépend de ce que nous lisons.","intro":"Les médias informent, éduquent et divertissent ; ils façonnent aussi l'opinion publique, pour le meilleur et parfois pour le pire.","objectifs":["définir les médias et l'opinion publique","citer les types de médias","analyser leur influence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Les <strong>médias</strong> sont les moyens de diffusion de l'information auprès d'un large public : presse écrite, radio, télévision, internet et réseaux sociaux. L'<strong>opinion publique</strong> est l'ensemble des idées et jugements partagés par une grande partie de la population sur une question.</div>"},{"t":"Les rôles des médias","verrou":true},{"t":"Impacts positifs et négatifs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":7,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Un message audio partagé 2 000 fois sur WhatsApp affirme qu'un vaccin distribué gratuitement à Douala « rend stérile ». Dans ton quartier, des parents refusent de faire vacciner leurs enfants.","tache":"Explique l'impact de ce message sur l'opinion publique et propose trois gestes pour lutter contre cette fausse nouvelle."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r08",{"duree":20,"titre":"La protection de l'opinion publique au Cameroun","accroche":"Liberté de la presse et responsabilité.","intro":"La liberté de communication est garantie, mais elle s'exerce dans le respect de la loi. Des textes et des institutions protègent le public contre la manipulation et les dérives.","objectifs":["connaître le cadre juridique de la communication","citer les institutions de régulation","identifier les limites de la liberté d'expression"],"parties":[{"t":"Le cadre juridique","html":"<div class='def'><b>Définition</b>La <strong>protection de l'opinion publique</strong> désigne l'ensemble des règles et institutions qui garantissent une information libre, pluraliste et responsable, et protègent le public contre les abus.</div><p>La <strong>loi du 19 décembre 1990</strong> sur la liberté de communication sociale organise la presse et l'audiovisuel ; le Code pénal sanctionne la diffamation, la propagation de fausses nouvelles et l'incitation à la haine. La loi de 2010 sur la cybersécurité et la cybercriminalité encadre internet.</p>"},{"t":"Les institutions de régulation","verrou":true},{"t":"Les limites de la liberté d'expression","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":8,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Un blogueur de Bafoussam publie la photo d'un enseignant de ton lycée avec la légende « voleur de notes », sans aucune preuve ; la publication est partagée 600 fois.","tache":"Explique pourquoi cette publication dépasse les limites de la liberté d'expression et indique les recours possibles pour l'enseignant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r09",{"duree":20,"titre":"TD : la publicité dans les médias","accroche":"Décoder un message qui veut nous faire acheter.","intro":"La publicité finance de nombreux médias. Ce travail dirigé apprend à analyser une publicité et à repérer ses procédés de persuasion.","objectifs":["définir la publicité","analyser une affiche ou un spot","adopter un comportement de consommateur averti"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>publicité</strong> est un message diffusé dans les médias pour faire connaître un produit, un service ou une idée et inciter le public à l'acheter ou à l'adopter.</div><p>On distingue la publicité <strong>commerciale</strong> et la publicité <strong>institutionnelle</strong> ou d'intérêt général (campagne contre le paludisme, pour la sécurité routière).</p>"},{"t":"Analyser une publicité","verrou":true},{"t":"Le consommateur averti","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":9,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Une affiche de Douala vante une crème qui « éclaircit la peau en 7 jours, 100 % sans danger », avec la photo d'une jeune femme souriante et le slogan « Brille comme une star ».","tache":"Analyse cette publicité (cible, procédés) et explique pourquoi elle peut être dangereuse et trompeuse."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r10",{"duree":20,"titre":"Les atteintes à l'intégrité physique, morale et au patrimoine","accroche":"Protéger la personne et ses biens.","intro":"La loi protège la personne humaine dans son corps, dans son honneur et dans ses biens. Le Code pénal du 12 juillet 2016 punit les atteintes à ces droits.","objectifs":["distinguer les trois types d'atteintes","en donner des exemples","connaître les conduites à tenir"],"parties":[{"t":"Les atteintes à l'intégrité physique","html":"<div class='def'><b>Définition</b>Une <strong>atteinte à l'intégrité physique</strong> est un acte qui blesse le corps d'une personne ou met sa vie en danger.</div><p>Exemples : coups et blessures, meurtre, viol, mutilations génitales, châtiments corporels excessifs, bagarres.</p>"},{"t":"Les atteintes à l'intégrité morale","html":"<p>Elles blessent la dignité, l'honneur ou l'équilibre psychologique : injures, diffamation, menaces, harcèlement (y compris sur internet), humiliations, discriminations.</p><p>Les <strong>femmes</strong> en sont souvent victimes : violences conjugales, mariages forcés ou précoces, mutilations, et dans le monde du travail discrimination à l'embauche, inégalités de salaire, harcèlement sexuel, licenciement pour grossesse, interdits par le Code pénal et le Code du travail. Des associations comme l'ALVF (Association de lutte contre les violences faites aux femmes) accompagnent les victimes.</p>","retenir":"Les mots et les écrans peuvent aussi blesser.","labo":{"type":"trier","invite":"Choisis une atteinte.","items":[["Intégrité physique","coups, blessures, viol, mutilations."],["Intégrité morale","injures, diffamation, harcèlement."],["Patrimoine","vol, escroquerie, destruction de biens."]]}},{"t":"Les atteintes au patrimoine","html":"<p>Elles visent les biens d'une personne ou de la collectivité : vol, escroquerie, abus de confiance, destruction de biens, détournement de biens publics, incendie volontaire.</p><p><strong>Conduite à tenir</strong> : protéger la victime, alerter (police 117, gendarmerie, sapeurs-pompiers 118), conserver les preuves, porter plainte.</p><div class='attention'><b>Attention</b>la vengeance personnelle et la « justice populaire » sont elles-mêmes des infractions.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Les coups et blessures sont une atteinte à l'intégrité :</p><ol type='a'><li>morale</li><li>physique</li><li>patrimoniale</li><li>électorale</li></ol><details><summary>Voir la réponse</summary><p><strong>physique</strong>. Ils blessent le corps.</p></details><p><strong>Vérification des savoir-faire.</strong></p><p>Un élève publie des moqueries répétées sur un camarade dans un groupe de classe. Quelle atteinte commet-il ?</p><details><summary>Voir la réponse</summary><p>(Réponse : une atteinte à l'intégrité morale, par cyberharcèlement.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Situation-problème.</strong> Dans un quartier de Douala, un élève est frappé et filmé par des camarades ; la vidéo est partagée avec des moqueries ; son téléphone lui est volé.</p><p><strong>Tâche 1.</strong> Identifie les trois types d'atteintes.</p><p><strong>Tâche 2.</strong> Indique la conduite à tenir pour un témoin.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>Physique (coups), morale (vidéo humiliante, moqueries), patrimoine (vol du téléphone). Le témoin protège la victime, alerte un adulte ou la police, ne partage pas la vidéo et témoigne.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Physique : coups, blessures, viol, mutilations.","Morale : injures, diffamation, harcèlement, discrimination.","Patrimoine : vol, escroquerie, destruction, détournement ; alerter, preuves, plainte."],"exo":"<p>Un élève publie des moqueries répétées sur un camarade dans un groupe de classe. Quelle atteinte commet-il ? <em>(Réponse : une atteinte à l'intégrité morale, par cyberharcèlement.)</em></p>","quiz":[{"q":"Les coups et blessures sont une atteinte à l'intégrité :","r":["morale","physique","patrimoniale","électorale"],"b":1,"e":"Ils blessent le corps."},{"q":"L'injure est une atteinte à l'intégrité :","r":["physique","au patrimoine","morale","territoriale"],"b":2,"e":"Elle blesse la dignité."},{"q":"Le vol est une atteinte :","r":["à l'intégrité physique","à l'intégrité morale seulement","au droit de vote","au patrimoine"],"b":3,"e":"Il vise les biens."},{"q":"Le Code pénal camerounais en vigueur date du :","r":["12 juillet 2016","19 décembre 1990","14 août 1992","18 janvier 1996"],"b":0,"e":"Loi n° 2016/007 du 12 juillet 2016."},{"q":"Le cyberharcèlement est une atteinte à l'intégrité :","r":["patrimoniale","morale","physique","territoriale"],"b":1,"e":"Les mots en ligne peuvent blesser."},{"q":"L'escroquerie consiste à :","r":["frapper une personne pour lui faire peur","insulter un voisin","obtenir un bien par la tromperie","voter deux fois"],"b":2,"e":"C'est une atteinte au patrimoine."},{"q":"Le numéro de la police au Cameroun est :","r":["118","119","112","117"],"b":3,"e":"Le 118 est celui des sapeurs-pompiers."},{"q":"La « justice populaire » est :","r":["elle-même une infraction","une forme légale de justice","recommandée par la loi","un droit des victimes"],"b":0,"e":"Seule la justice officielle peut juger."},{"q":"Les mutilations génitales féminines sont une atteinte :","r":["au patrimoine","à l'intégrité physique","à la liberté de la presse","au droit de vote"],"b":1,"e":"Elles blessent gravement le corps."},{"q":"Face à une agression, il faut d'abord :","r":["filmer la scène pour les réseaux","se venger de l'agresseur","protéger la victime et alerter","fuir sans rien dire"],"b":2,"e":"Protéger, alerter, témoigner."}],"c":"1re D","m":"ecm","rang":10,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Au marché de Mbouda, un voleur présumé est rattrapé par la foule qui commence à le frapper ; un commerçant crie de le brûler. Tu es présent avec ton grand frère.","tache":"Identifie les atteintes commises dans cette scène et décris la conduite responsable à tenir."},"gratuit":true});
VRT_L("1re-d-ecm-r11",{"duree":20,"titre":"L'extrémisme violent","accroche":"Quand les idées deviennent des armes.","intro":"L'extrémisme violent menace la paix au Cameroun, notamment avec les attaques de Boko Haram dans l'Extrême-Nord et les violences armées dans les régions du Nord-Ouest et du Sud-Ouest.","objectifs":["définir l'extrémisme violent","identifier ses causes et ses manifestations","connaître les signes de radicalisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>extrémisme violent</strong> est l'attitude de personnes ou de groupes qui adoptent des idées extrêmes (religieuses, politiques, ethniques) et utilisent la violence pour les imposer.</div><p>Le <strong>terrorisme</strong> en est une forme : il vise à semer la terreur dans la population par des attentats, des enlèvements ou des massacres.</p>"},{"t":"Causes et manifestations","verrou":true},{"t":"Les signes de radicalisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":11,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Ton cousin de 17 ans, à Kousséri, a quitté l'école, ne parle plus à sa famille, passe ses nuits à regarder des vidéos de combattants et répète qu'« un vrai homme doit prendre les armes ».","tache":"Identifie trois signes de radicalisation et propose une démarche pour l'aider."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r12",{"duree":20,"titre":"La notion de paix","accroche":"Plus que l'absence de guerre.","intro":"La paix est un bien précieux que le Cameroun a appris à mesurer face aux crises. Elle ne se réduit pas à l'absence de combats : elle suppose la justice, le respect et la sécurité de tous.","objectifs":["définir la paix","distinguer paix négative et paix positive","identifier les facteurs de paix"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>paix</strong> est l'état d'une société ou de relations entre États où règnent la sécurité, la concorde et le respect mutuel, sans violence ni conflit armé.</div><p>On distingue la <strong>paix négative</strong> (absence de guerre) et la <strong>paix positive</strong> (présence de justice, de droits respectés et de bonnes relations).</p>"},{"t":"Les niveaux de la paix","verrou":true},{"t":"Les facteurs de paix","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":12,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Dans ton quartier de Yaoundé, aucune bagarre n'a eu lieu depuis un an, mais les familles de deux communautés ne se parlent plus et refusent les mariages mixtes.","tache":"Explique pourquoi cette situation n'est pas une paix véritable et propose deux actions pour construire une paix positive."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r13",{"duree":20,"titre":"TD : les symboles de la paix au Cameroun","accroche":"Enquête sur les signes qui unissent.","intro":"Chaque culture camerounaise possède des signes, objets et rites qui expriment la paix et la réconciliation. Ce travail dirigé les fait découvrir par l'enquête.","objectifs":["recenser des symboles de paix","en expliquer la signification","présenter les résultats d'une enquête"],"parties":[{"t":"Les symboles universels","html":"<div class='def'><b>Définition</b>Un <strong>symbole de paix</strong> est un objet, une image, un geste ou un rite qui représente la paix et la réconciliation dans une culture.</div><ul><li>la <strong>colombe</strong> portant un rameau d'olivier ;</li><li>le <strong>drapeau blanc</strong> ;</li><li>la <strong>poignée de main</strong> et l'accolade ;</li><li>le <strong>flambeau</strong> de la paix.</li></ul>"},{"t":"Des symboles camerounais","verrou":true},{"t":"Mener l'enquête","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":13,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Ta classe de 1re prépare une exposition sur les symboles de la paix pour la Journée internationale de la paix. Les élèves viennent de cinq régions différentes.","tache":"Propose un plan d'enquête en quatre étapes et un tableau à trois colonnes pour présenter les résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r14",{"duree":20,"titre":"Les stratégies de promotion de la paix","accroche":"Construire la paix au quotidien.","intro":"La paix se prépare et s'entretient. Les États, les communautés et chaque citoyen disposent de stratégies pour prévenir les conflits et renforcer la cohésion.","objectifs":["citer des stratégies de promotion de la paix","identifier les acteurs","proposer des actions à son niveau"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>stratégie de promotion de la paix</strong> est un ensemble d'actions organisées pour prévenir les conflits, réduire les tensions et renforcer la cohésion sociale.</div>"},{"t":"Les stratégies","verrou":true},{"t":"Les acteurs et le rôle du jeune","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":14,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Dans ton lycée, des bagarres opposent régulièrement les élèves de deux quartiers rivaux ; trois blessés ont été recensés depuis la rentrée et des insultes circulent sur un groupe en ligne.","tache":"Propose une stratégie de paix en trois actions, en précisant pour chacune les acteurs mobilisés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r15",{"duree":20,"titre":"Le règlement pacifique des différends","accroche":"Résoudre les conflits sans violence.","intro":"Un différend peut opposer deux personnes, deux communautés ou deux États. Il existe des moyens pacifiques de le régler, du dialogue jusqu'au juge international. L'affaire de Bakassi en est un exemple célèbre.","objectifs":["définir un différend","citer les modes de règlement pacifique","analyser l'exemple de Bakassi"],"parties":[{"t":"Différend et modes de règlement","html":"<div class='def'><b>Définition</b>Un <strong>différend</strong> est un désaccord sur un droit, un intérêt ou un fait entre deux ou plusieurs parties. Son <strong>règlement pacifique</strong> consiste à y mettre fin sans recourir à la force.</div><ul><li><strong>la négociation</strong> : discussion directe entre les parties ;</li><li><strong>les bons offices et la médiation</strong> : un tiers rapproche les parties et propose une solution ;</li><li><strong>la conciliation</strong> : une commission examine et propose ;</li><li><strong>l'arbitrage</strong> : des arbitres choisis rendent une décision obligatoire ;</li><li><strong>le règlement judiciaire</strong> : un tribunal, comme la Cour internationale de justice, tranche.</li></ul>"},{"t":"L'exemple de Bakassi","verrou":true},{"t":"À l'échelle de chacun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":15,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Deux familles de Foumban se disputent une parcelle de 2 hectares héritée d'un ancêtre commun ; les jeunes des deux familles ont déjà échangé des menaces et des coups de machette ont été évités de justesse.","tache":"Propose, dans l'ordre, trois modes de règlement pacifique adaptés à ce différend et justifie leur choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r16",{"duree":20,"titre":"Dossier : la lutte contre l'extrémisme violent au Cameroun","accroche":"Défendre, prévenir, réintégrer.","intro":"Face à Boko Haram et aux groupes armés, le Cameroun combine une réponse sécuritaire, judiciaire, sociale et éducative. Ce dossier analyse cette lutte et la place des citoyens.","objectifs":["présenter les moyens de lutte contre l'extrémisme violent","analyser leurs résultats et leurs limites","proposer des actions citoyennes"],"parties":[{"t":"Les réponses sécuritaire et judiciaire","html":"<div class='def'><b>Définition</b>La <strong>lutte contre l'extrémisme violent</strong> est l'ensemble des actions qui visent à prévenir la radicalisation, à protéger les populations et à neutraliser les groupes violents.</div><ul><li>engagement des forces de défense et de sécurité, dont la Force multinationale mixte du bassin du lac Tchad avec les pays voisins ;</li><li>comités de vigilance des populations dans l'Extrême-Nord ;</li><li>loi du 23 décembre 2014 contre le terrorisme.</li></ul>"},{"t":"Les réponses sociales et éducatives","verrou":true},{"t":"Résultats, limites et rôle du citoyen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":16,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Dans un village du Mayo-Sava, l'école a rouvert après trois ans de fermeture due aux attaques ; 40 % des élèves sont des enfants déplacés et plusieurs jeunes du village ont rejoint autrefois un groupe armé avant de se rendre.","tache":"Analyse deux défis de ce village et propose trois actions complémentaires pour éviter le retour de l'extrémisme violent."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r17",{"duree":20,"titre":"L'importance du vivre ensemble au Cameroun","accroche":"Plus de deux cents ethnies, une seule nation.","intro":"Le Cameroun est souvent présenté comme « l'Afrique en miniature » pour la diversité de ses peuples, de ses langues, de ses religions et de ses paysages. Vivre ensemble est la condition de sa stabilité et de son développement.","objectifs":["définir le vivre ensemble","identifier les éléments de la diversité camerounaise","expliquer l'importance du vivre ensemble"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>vivre ensemble</strong> est la capacité de personnes et de communautés différentes à partager pacifiquement un même espace, dans le respect mutuel, l'égalité des droits et la solidarité.</div>"},{"t":"La diversité camerounaise","verrou":true},{"t":"Pourquoi vivre ensemble ?","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":17,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Lors de l'élection du délégué de ta classe à Buea, un candidat déclare : « ne votez pas pour lui, il n'est pas de chez nous ». La classe compte des élèves de six régions et deux sous-systèmes.","tache":"Montre en quoi ce discours menace le vivre ensemble et rédige un appel de six lignes pour une campagne fondée sur les idées."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-ecm-r18",{"duree":20,"titre":"Dossier : la Commission nationale pour la promotion du bilinguisme et du multiculturalisme","accroche":"Une institution au service de l'unité.","intro":"Créée par décret du 23 janvier 2017, la Commission nationale pour la promotion du bilinguisme et du multiculturalisme (CNPBM) veille à l'égalité du français et de l'anglais et à la promotion de la diversité culturelle.","objectifs":["présenter la CNPBM","expliquer ses missions","évaluer son action et le rôle du citoyen"],"parties":[{"t":"Présentation","html":"<div class='def'><b>Définition</b>La <strong>CNPBM</strong> est un organe consultatif, placé auprès du président de la République, chargé de promouvoir le bilinguisme officiel (français et anglais) et le multiculturalisme au Cameroun.</div><p>Elle a été créée dans un contexte de tensions dans les régions du Nord-Ouest et du Sud-Ouest, où une partie de la population dénonçait une marginalisation de l'anglais et du sous-système anglophone.</p>"},{"t":"Les missions","verrou":true},{"t":"Évaluation et rôle du citoyen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"ecm","rang":18,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Un élève anglophone muté de Limbé à Ngaoundéré reçoit tous ses documents administratifs en français seulement et se fait moquer pour son accent ; il envisage d'abandonner l'école.","tache":"Explique en quoi ses droits et le vivre ensemble sont atteints, et indique deux actions possibles, dont une auprès de la CNPBM."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r01",{"duree":20,"titre":"Équations et inéquations du second degré","accroche":"Un discriminant suffit à tout savoir.","intro":"Le trinôme ax² + bx + c revient à chaque Probatoire. Son discriminant indique le nombre de solutions, et son signe résout les inéquations.","objectifs":["calculer le discriminant","résoudre une équation du second degré","résoudre une inéquation du second degré"],"parties":[{"t":"Le discriminant","html":"<div class='def'><b>Définition</b>Pour ax² + bx + c = 0 (a ≠ 0), le <strong>discriminant</strong> est Δ = b² − 4ac. Si Δ > 0, il y a deux solutions x = (−b ± √Δ) / (2a) ; si Δ = 0, une solution −b / (2a) ; si Δ &lt; 0, aucune solution réelle.</div>"},{"t":"Le signe du trinôme","html":"<p>Le trinôme a le signe de a <strong>à l'extérieur</strong> des racines et le signe contraire entre elles. Sans racine, il garde le signe de a.</p><p class='formule'>x² − 5x + 6 &lt; 0 ⇔ x ∈ ]2 ; 3[</p>","retenir":"Signe de a à l'extérieur des racines.","labo":{"type":"parabole","a":1,"b":-5,"c":6}},{"t":"La forme canonique","html":"<p class='formule'>ax² + bx + c = a[(x + b/(2a))² − Δ/(4a²)]</p><p>Le Probatoire D l'utilise pour factoriser puis résoudre.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Le discriminant de ax² + bx + c est :</p><ol type='a'><li>Δ = b² + 4ac</li><li>Δ = 4ac − b²</li><li>Δ = b − 4ac</li><li>Δ = b² − 4ac</li></ol><details><summary>Voir la réponse</summary><p><strong>Δ = b² − 4ac</strong>. C'est lui qui décide du nombre de racines réelles.</p></details><p><strong>Exercice.</strong></p><p>Résous 2x² + 3x − 2 = 0.</p><details><summary>Voir la réponse</summary><p>(Réponse : Δ = 25 ; x = 1/2 ou x = −2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un éleveur de Ngaoundéré veut clôturer un enclos rectangulaire avec 60 m de grillage ; l'enclos doit avoir une aire d'au moins 200 m².</p><p><strong>Tâche 1.</strong> Montre que la largeur x vérifie x² − 30x + 200 ≤ 0.</p><p><strong>Tâche 2.</strong> Résous l'inéquation et conclus.</p><details><summary>Voir une réponse attendue</summary><p>Longueur 30 − x ; x(30 − x) ≥ 200 ⇔ x² − 30x + 200 ≤ 0. Δ = 100, racines 10 et 20 : x ∈ [10 ; 20]. La largeur doit être comprise entre 10 m et 20 m.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Δ = b² − 4ac.","Solutions selon le signe de Δ.","Signe de a à l'extérieur des racines."],"exo":"<p>Résous 2x² + 3x − 2 = 0. <em>(Réponse : Δ = 25 ; x = 1/2 ou x = −2.)</em></p>","quiz":[{"q":"Le discriminant de ax² + bx + c est :","r":["Δ = b² + 4ac","Δ = 4ac − b²","Δ = b − 4ac","Δ = b² − 4ac"],"b":3,"e":"C'est lui qui décide du nombre de racines réelles."},{"q":"Si Δ > 0, l'équation ax² + bx + c = 0 a :","r":["deux solutions réelles distinctes","une seule solution réelle, appelée racine double","aucune solution réelle","une infinité de solutions"],"b":0,"e":"Elles valent (−b ± √Δ)/(2a)."},{"q":"Si Δ = 0, l'équation a :","r":["deux solutions distinctes","une solution double −b/(2a)","aucune solution","trois solutions"],"b":1,"e":"Le trinôme est alors un carré parfait."},{"q":"Les solutions de x² − 5x + 6 = 0 sont :","r":["−2 et −3","1 et 6","2 et 3","5 et 6"],"b":2,"e":"Δ = 25 − 24 = 1 ; x = (5 ± 1)/2."},{"q":"x² + x + 1 = 0 a dans ℝ :","r":["deux solutions","une solution","la solution 1","aucune solution"],"b":3,"e":"Δ = 1 − 4 = −3, négatif."},{"q":"Un trinôme est du signe de a :","r":["à l'extérieur des racines","entre les racines, bornes exclues","partout","nulle part"],"b":0,"e":"Il est du signe opposé à a entre les racines."},{"q":"L'ensemble des solutions de x² − 30x + 200 ≤ 0 est :","r":["]−∞ ; 10] ∪ [20 ; +∞[","[10 ; 20]","[−20 ; −10]","∅"],"b":1,"e":"Racines 10 et 20 ; a > 0, donc négatif entre les racines."},{"q":"La somme des racines de ax² + bx + c = 0 vaut :","r":["c/a","b/a","−b/a","−c/a"],"b":2,"e":"Relations entre coefficients et racines."},{"q":"Le produit des racines de ax² + bx + c = 0 vaut :","r":["−b/a","b/c","a/c","c/a"],"b":3,"e":"Relations entre coefficients et racines."},{"q":"La forme canonique de x² − 4x + 1 est :","r":["(x − 2)² − 3","(x − 4)² + 1","(x + 2)² − 3","(x − 2)² + 1"],"b":0,"e":"x² − 4x + 4 − 3."}],"c":"1re D","m":"maths","rang":1,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une couturière de Bafoussam veut un tissu rectangulaire dont la longueur dépasse la largeur de 3 m, pour une aire de 40 m².","tache":"Détermine les dimensions du tissu."},"gratuit":true});
VRT_L("1re-d-maths-r02",{"duree":20,"titre":"Systèmes se ramenant au second degré","accroche":"Deux nombres dont on connaît la somme et le produit.","intro":"Certains systèmes non linéaires se résolvent grâce à une équation auxiliaire du second degré.","objectifs":["utiliser somme et produit","exploiter une substitution","vérifier les solutions"],"parties":[{"t":"Somme et produit","html":"<div class='def'><b>Définition</b>Si x + y = S et xy = P, alors x et y sont les solutions de <strong>X² − SX + P = 0</strong>, à condition que S² − 4P ≥ 0.</div>"},{"t":"Exemple","verrou":true},{"t":"Forme x² + y²","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":2,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un propriétaire de Limbé clôture une parcelle rectangulaire de 34 m de périmètre et de 60 m² d'aire.","tache":"Détermine la longueur et la largeur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r03",{"duree":20,"titre":"Polynômes de degré 3 et factorisation","accroche":"Une racine évidente ouvre la voie.","intro":"Une racine connue d'un polynôme permet de le factoriser, puis de finir avec le second degré.","objectifs":["reconnaître une racine","factoriser par x − a","résoudre une équation de degré 3"],"parties":[{"t":"Racine et factorisation","html":"<div class='def'><b>Définition</b>Le réel a est une <strong>racine</strong> de P si P(a) = 0. Alors P(x) se factorise par (x − a) : P(x) = (x − a)Q(x).</div>"},{"t":"Identification","verrou":true},{"t":"Résolution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":3,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fabricant de boîtes à Douala modélise le volume d'une boîte par V(x) = x³ − 6x² + 11x − 6 et cherche les valeurs où ce volume s'annule.","tache":"Trouve ces valeurs."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r04",{"duree":20,"titre":"Signe d'un polynôme de degré 3","accroche":"Le tableau de signes fait tout le travail.","intro":"Une fois factorisé, un polynôme de degré 3 se lit dans un tableau de signes.","objectifs":["factoriser","dresser un tableau de signes","résoudre une inéquation"],"parties":[{"t":"La méthode","html":"<div class='def'><b>Définition</b>Pour étudier le <strong>signe</strong> d'un polynôme, on le factorise en facteurs du premier ou second degré, puis on dresse un tableau de signes.</div>"},{"t":"Exemple","verrou":true},{"t":"Inéquation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":4,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le bénéfice d'une petite unité de Kribi est modélisé par B(x) = x(x − 2)(x + 2), pour x exprimé en centaines d'articles, x positif.","tache":"Détermine les quantités qui donnent un bénéfice positif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r05",{"duree":20,"titre":"Équations irrationnelles","accroche":"On élève au carré, puis on trie.","intro":"Une équation avec racine carrée se résout en respectant une condition essentielle.","objectifs":["déterminer les conditions","résoudre","vérifier les solutions"],"parties":[{"t":"Le principe","html":"<div class='def'><b>Définition</b>Une équation <strong>irrationnelle</strong> contient l'inconnue sous un radical. <strong>√A = B ⇔ B ≥ 0 et A = B²</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Vérification","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":5,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour une rampe à Kumba, la longueur en mètres vérifie √(2x + 3) = x.","tache":"Détermine la valeur de x et justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r06",{"duree":20,"titre":"Inéquations irrationnelles","accroche":"Deux schémas à connaître.","intro":"Selon le sens de l'inégalité, on utilise des conditions différentes.","objectifs":["utiliser les équivalences","résoudre","présenter sur un axe"],"parties":[{"t":"Les équivalences","html":"<div class='def'><b>Définition</b><strong>√A &lt; B ⇔ A ≥ 0, B > 0 et A &lt; B²</strong>. Pour √A > B : ou bien B &lt; 0 et A ≥ 0, ou bien B ≥ 0 et A > B².</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":6,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"La vitesse d'un jet d'eau à Mbalmayo vérifie √(x + 2) &lt; x, avec x en dizaines de cm.","tache":"Détermine les valeurs de x possibles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r07",{"duree":20,"titre":"Systèmes linéaires à deux inconnues","accroche":"Deux droites, un point.","intro":"Résoudre un système, c'est chercher le point commun de deux droites.","objectifs":["résoudre par substitution","utiliser le déterminant","interpréter"],"parties":[{"t":"Le système","html":"<div class='def'><b>Définition</b>Le système ax + by = c ; a'x + b'y = c' a pour <strong>déterminant</strong> D = ab' − a'b. Si D ≠ 0, il a une solution unique.</div>"},{"t":"La méthode de Cramer","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":7,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Au marché de Foumbot, 2 tas de tomates et 3 tas de piment coûtent 1 200 F ; un tas de tomates coûte 100 F de plus qu'un tas de piment.","tache":"Trouve le prix de chaque tas."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r08",{"duree":20,"titre":"Systèmes linéaires à trois inconnues","accroche":"Pivot de Gauss : une inconnue à la fois.","intro":"La méthode du pivot triangularise le système. Ce type de système revient très souvent au Probatoire.","objectifs":["appliquer le pivot","remonter les inconnues","vérifier"],"parties":[{"t":"La méthode","html":"<div class='def'><b>Définition</b>Le <strong>pivot de Gauss</strong> remplace les lignes par des combinaisons pour obtenir un système triangulaire équivalent.</div>"},{"t":"Exemple","verrou":true},{"t":"Modéliser","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":8,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fermier de Foumban achète à crédit des bêtes. 10 poussins, 2 pourceaux et 1 chevreau coûtent 45 000 F ; 20 poussins, 1 pourceau et 2 chevreaux coûtent 45 000 F ; 30 poussins, 2 pourceaux et 2 chevreaux coûtent 65 000 F.","tache":"Détermine le prix unitaire de chaque espèce."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r09",{"duree":20,"titre":"Formules de transformation","accroche":"Transformer un produit, simplifier une somme.","intro":"Les formules d'addition et de duplication simplifient les expressions trigonométriques.","objectifs":["utiliser les formules d'addition","utiliser la duplication","écrire a cos x + b sin x"],"parties":[{"t":"Addition","html":"<div class='def'><b>Définition</b><strong>cos(a + b) = cos a cos b − sin a sin b</strong> ; <strong>sin(a + b) = sin a cos b + cos a sin b</strong>.</div>"},{"t":"Duplication","verrou":true},{"t":"Forme R cos(x − φ)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":9,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Dschang étudie une tension alternative de la forme √3 cos t + sin t.","tache":"Écris-la sous la forme R cos(t − φ)."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r10",{"duree":20,"titre":"Équations et inéquations trigonométriques","accroche":"Deux familles de solutions.","intro":"Il faut savoir traduire une équation par une égalité d'angles, puis choisir les solutions dans l'intervalle.","objectifs":["résoudre cos x = cos a","résoudre sin x = sin a","résoudre une inéquation sur un intervalle"],"parties":[{"t":"Les équations de base","html":"<div class='def'><b>Définition</b><strong>cos x = cos a ⇔ x = a + 2kπ ou x = −a + 2kπ</strong>. <strong>sin x = sin a ⇔ x = a + 2kπ ou x = π − a + 2kπ</strong>, k entier.</div>"},{"t":"Exemple","verrou":true},{"t":"Se ramener au second degré","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":10,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un technicien de Song Loulou cherche sur [0 ; 2π[ les instants où une tension vérifie 2 cos t − 1 = 0.","tache":"Détermine les solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r11",{"duree":20,"titre":"Premiers outils du dénombrement","accroche":"Compter sans tout écrire.","intro":"Deux principes simples, somme et produit, résolvent la plupart des comptages.","objectifs":["utiliser le principe additif","utiliser le principe multiplicatif","utiliser la factorielle"],"parties":[{"t":"Les principes","html":"<div class='def'><b>Définition</b><strong>Principe additif</strong> : on additionne si les cas s'excluent. <strong>Principe multiplicatif</strong> : on multiplie pour des choix successifs.</div>"},{"t":"Réunion","verrou":true},{"t":"Factorielle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":11,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une école de Garoua propose 3 entrées et 4 plats au déjeuner du samedi.","tache":"Détermine le nombre de menus possibles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r13",{"duree":20,"titre":"p-listes, arrangements et combinaisons","accroche":"L'ordre compte-t-il ? Peut-on répéter ?","intro":"Deux questions suffisent à choisir la bonne formule.","objectifs":["reconnaître chaque situation","appliquer les formules","résoudre un tirage"],"parties":[{"t":"Les trois formules","html":"<div class='def'><b>Définition</b>Choisir p éléments parmi n : <strong>p-liste</strong> nᵖ (ordre, répétition) ; <strong>arrangement</strong> n!/(n − p)! (ordre, sans répétition) ; <strong>combinaison</strong> n!/[p!(n − p)!] (sans ordre, sans répétition).</div>"},{"t":"Exemples","verrou":true},{"t":"Au Probatoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":13,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une PME de Douala choisit 6 responsables parmi 10 candidats, et prévoit une enveloppe à 100 F par groupe possible, pour un budget de 12 500 F.","tache":"Le budget suffit-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r12",{"duree":20,"titre":"Intégration : compter pour décider","accroche":"Tirage et budget d'un concours.","intro":"Le dénombrement sert à estimer le coût d'une organisation.","objectifs":["identifier le type de tirage","calculer","décider"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Une situation de <strong>choix simultané</strong> relève des combinaisons ; un choix ordonné relève des arrangements.</div>"},{"t":"Démarche","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":12,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le foyer d'un lycée de Mbouda organise un tirage : un jeu de 2 billets à gratter parmi 12, à 50 F par tirage possible.","tache":"Calcule le budget nécessaire pour imprimer un billet par tirage possible."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r14",{"duree":20,"titre":"Le barycentre","accroche":"Le point d'équilibre d'un système de points pondérés.","intro":"Le barycentre généralise le milieu : il tient compte du poids de chaque point.","objectifs":["définir le barycentre","le construire","utiliser la réduction vectorielle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Si a + b ≠ 0, le <strong>barycentre</strong> G de (A ; a) et (B ; b) est l'unique point tel que a·GA⃗ + b·GB⃗ = 0⃗. Alors AG⃗ = b/(a + b) · AB⃗.</div>"},{"t":"Réduction","verrou":true},{"t":"Associativité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":14,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un porteur de Bafang transporte deux seaux de 10 kg et 30 kg aux extrémités d'un bâton de 2 m.","tache":"Où doit-il placer l'épaule pour l'équilibre ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r15",{"duree":20,"titre":"Lignes de niveau","accroche":"Un ensemble de points défini par une égalité.","intro":"Les fonctions vectorielles du barycentre permettent de reconnaître des droites et des cercles.","objectifs":["réduire une somme vectorielle","reconnaître un cercle","reconnaître une droite"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>ligne de niveau</strong> k d'une fonction f du plan est l'ensemble des points M tels que f(M) = k.</div>"},{"t":"Les cas classiques","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":15,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Pour un forage, l'ingénieur de Mbalmayo cherche les points M tels que MA² + MB² = 24 m², avec AB = 4 m.","tache":"Décris cet ensemble."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r16",{"duree":20,"titre":"Notion de fonctions et d'applications","accroche":"Une machine qui associe au plus un résultat.","intro":"Avant d'étudier une fonction, il faut connaître son ensemble de définition.","objectifs":["déterminer un ensemble de définition","distinguer fonction et application","composer des fonctions"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>fonction</strong> associe à chaque élément de E au plus une image dans F. Une <strong>application</strong> associe à chaque élément de E exactement une image.</div>"},{"t":"Ensemble de définition","verrou":true},{"t":"Composée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":16,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le prix au kilo d'une denrée à Bafoussam est modélisé par p(x) = 1 200/(x − 2), où x est le jour du mois.","tache":"Pour quels jours la formule a-t-elle un sens ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r19",{"duree":20,"titre":"Fonctions et applications : entraînement","accroche":"Un ensemble de définition piège.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Il faut réunir toutes les conditions : dénominateur, radical, et éventuel quotient sous radical.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":19,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un tarif de taxi à Douala est f(x) = √(x² − 4) × 100 F, x étant la distance en km.","tache":"Indique les distances acceptées par la formule."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r17",{"duree":20,"titre":"Symétries et translations des courbes","accroche":"Construire une courbe à partir d'une autre.","intro":"Repérer une symétrie réduit l'étude d'une fonction ; une translation donne une courbe nouvelle à partir d'une courbe connue.","objectifs":["prouver un axe de symétrie","prouver un centre de symétrie","utiliser une translation"],"parties":[{"t":"Éléments de symétrie","html":"<div class='def'><b>Définition</b>La droite x = a est un <strong>axe de symétrie</strong> si f(2a − x) = f(x). Le point I(a ; b) est un <strong>centre de symétrie</strong> si f(2a − x) + f(x) = 2b.</div>"},{"t":"Translations","verrou":true},{"t":"Courbes associées","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":17,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un artisan de Foumban dessine une calebasse dont le profil suit y = x² − 4x + 1.","tache":"Indique l'axe de symétrie du profil."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r20",{"duree":20,"titre":"Symétries des courbes : entraînement","accroche":"Démontrer un centre de symétrie.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour un centre, on calcule f(2a − x) + f(x).</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":20,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une graphiste de Douala a tracé la courbe de f(x) = x² − 4x + 3 sur [0 ; 5] ; son client veut un motif symétrique et lui demande la courbe de g(x) = f(|x|) sur [−5 ; 5].","tache":"Explique la construction de la courbe de g à partir de celle de f et précise ses points d'intersection avec l'axe des abscisses."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r21",{"duree":20,"titre":"Limites et asymptotes","accroche":"Ce qui se passe au bout de la courbe.","intro":"Les limites décrivent le comportement d'une fonction aux bornes de son domaine et donnent les asymptotes.","objectifs":["calculer des limites usuelles","lever une indétermination","reconnaître une asymptote"],"parties":[{"t":"Les asymptotes","html":"<div class='def'><b>Définition</b>Si lim f(x) = ±∞ quand x tend vers a, la droite x = a est <strong>asymptote verticale</strong>. Si lim f(x) = b en ±∞, la droite y = b est <strong>asymptote horizontale</strong>.</div>"},{"t":"Fonctions rationnelles","verrou":true},{"t":"Indéterminations","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":21,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le coût moyen de production d'un savonnier de Bafoussam est C(x) = (2x + 600)/x pour x pains.","tache":"Que devient ce coût pour de très grandes quantités ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r22",{"duree":20,"titre":"Continuité","accroche":"Une courbe tracée sans lever le crayon.","intro":"La continuité garantit l'existence de solutions pour certaines équations.","objectifs":["définir la continuité en un point","reconnaître les fonctions continues","utiliser le théorème des valeurs intermédiaires"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>f est <strong>continue en a</strong> si lim f(x) = f(a) quand x tend vers a.</div>"},{"t":"Fonctions continues","verrou":true},{"t":"Valeurs intermédiaires","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":22,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un réservoir à Ngaoundéré se remplit selon une fonction continue ; il contient 200 L à 8 h et 1 000 L à 10 h.","tache":"Le volume a-t-il atteint 600 L entre 8 h et 10 h ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r23",{"duree":20,"titre":"Nombre dérivé et fonction dérivée","accroche":"La pente d'une courbe en un point.","intro":"Le nombre dérivé mesure la vitesse de variation et donne l'équation de la tangente.","objectifs":["définir le nombre dérivé","écrire une tangente","calculer des dérivées"],"parties":[{"t":"Le nombre dérivé","html":"<div class='def'><b>Définition</b>f est dérivable en a si (f(a + h) − f(a))/h a une limite finie quand h tend vers 0 ; cette limite est le <strong>nombre dérivé</strong> f'(a).</div>"},{"t":"La tangente","verrou":true},{"t":"Dérivées usuelles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":23,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le trajet d'une moto-taxi à Douala est modélisé par d(t) = t², en km, t en heures.","tache":"Quelle est la vitesse instantanée à t = 1 h ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r24",{"duree":20,"titre":"Utiliser la fonction dérivée","accroche":"Le signe de f' donne les variations.","intro":"La dérivée permet d'étudier les variations et de trouver un maximum ou un minimum.","objectifs":["relier signe de f' et variations","dresser un tableau de variation","résoudre un problème d'optimisation"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Définition</b>Si f' > 0 sur un intervalle, f y est <strong>strictement croissante</strong> ; si f' &lt; 0, f y est <strong>strictement décroissante</strong>.</div>"},{"t":"Exemple","html":"<p>f(x) = x³ − 3x, f'(x) = 3(x − 1)(x + 1). f croît sur ]−∞ ; −1], décroît sur [−1 ; 1], croît sur [1 ; +∞[. Maximum local f(−1) = 2, minimum local f(1) = −2.</p>","labo":{"type":"courbe","fn":"x3","xmin":-2,"xmax":2,"ymin":-8,"ymax":8,"x0":1}},{"t":"Optimisation","html":"<p>Clôture de 100 m le long d'un mur : A(x) = x(100 − 2x), A'(x) = 100 − 4x. Maximum pour x = 25 : A = 1 250 m².</p>","retenir":"Un extremum se lit là où f' s'annule en changeant de signe."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Si f'(x) &gt; 0 sur un intervalle, f y est :</p><ol type='a'><li>strictement croissante</li><li>strictement décroissante</li><li>constante</li><li>nulle</li></ol><details><summary>Voir la réponse</summary><p><strong>strictement croissante</strong>. Le signe de la dérivée donne le sens de variation.</p></details><p><strong>Exercice.</strong></p><p>Quel est le maximum de f(x) = −x² + 4x ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 4, pour x = 2.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un menuisier de Bertoua découpe un carré de côté x aux quatre coins d'une plaque de 30 cm sur 30 cm pour fabriquer une boîte sans couvercle. Le volume est V(x) = x(30 − 2x)², x ∈ ]0 ; 15[.</p><p><strong>Tâche 1.</strong> Calcule V'(x) et étudie son signe.</p><p><strong>Tâche 2.</strong> Pour quelle valeur de x le volume est-il maximal ? Calcule-le.</p><details><summary>Voir une réponse attendue</summary><p>V'(x) = (30 − 2x)(30 − 6x), positif sur ]0 ; 5[, négatif sur ]5 ; 15[. Maximum en x = 5 cm : V = 5 × 20² = 2 000 cm³.</p></details></div>","retenir":"Savoir-être mobilisé : Persévérance dans la recherche."}],"revision":["Signe de f'.","Tableau de variation.","Extremum."],"exo":"<p>Quel est le maximum de f(x) = −x² + 4x ? <em>(Réponse : 4, pour x = 2.)</em></p>","quiz":[{"q":"Si f'(x) > 0 sur un intervalle, f y est :","r":["strictement croissante","strictement décroissante","constante","nulle"],"b":0,"e":"Le signe de la dérivée donne le sens de variation."},{"q":"Si f' s'annule en changeant de signe en a, f admet en a :","r":["une asymptote","un extremum local","une discontinuité","rien"],"b":1,"e":"Maximum ou minimum."},{"q":"f(x) = x³ − 3x. f'(x) vaut :","r":["3x² − 3x","x² − 3","3x² − 3","3x − 3"],"b":2,"e":"On dérive terme à terme."},{"q":"f(x) = x³ − 3x est décroissante sur :","r":["[1 ; +∞[","]−∞ ; −1]","ℝ","[−1 ; 1]"],"b":3,"e":"f'(x) = 3(x² − 1) &lt; 0 entre −1 et 1."},{"q":"Le maximum de B(x) = −2x² + 24x − 40 est atteint en :","r":["x = 6","x = 12","x = 2","x = 10"],"b":0,"e":"B'(x) = −4x + 24 = 0."},{"q":"La dérivée de u × v est :","r":["u'v'","u'v + uv'","u'v − uv'","uv'"],"b":1,"e":"Formule du produit."},{"q":"La dérivée de u/v est :","r":["u'/v'","(u'v + uv')/v²","(u'v − uv')/v²","u'v − uv'"],"b":2,"e":"Formule du quotient."},{"q":"La dérivée de (2x + 1)/(x − 1) est :","r":["3/(x − 1)²","2/(x − 1)","−1/(x − 1)²","−3/(x − 1)²"],"b":3,"e":"(2(x − 1) − (2x + 1))/(x − 1)²."},{"q":"Pour trouver le sommet d'une bosse y = −x³ + 3x + 2 entre −2 et 2, on résout :","r":["y' = 0, soit x = ±1, puis on choisit x = 1","y = 0, soit x = 0 ou x = ±1","y'' = 0, soit le point d'inflexion d'abscisse x = 0","x = 0"],"b":0,"e":"y' = −3x² + 3 ; maximum en x = 1."},{"q":"Un tableau de variation se construit à partir :","r":["des valeurs de f en 0 seulement","du signe de la dérivée","de la courbe uniquement","du discriminant"],"b":1,"e":"On y reporte aussi les extrema."}],"c":"1re D","m":"maths","rang":24,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ben, à Edéa, dispose de 100 m de grillage pour clore une parcelle rectangulaire adossée à un mur.","tache":"Détermine la plus grande superficie possible."},"gratuit":true});
VRT_L("1re-d-maths-r26",{"duree":20,"titre":"Utiliser la dérivée : entraînement","accroche":"Le nombre de solutions d'une équation.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Le tableau de variation et les valeurs extrêmes donnent le nombre de solutions de f(x) = 0.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":26,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le profit d'une coopérative de Bertoua suit f(x) = x³ − 3x² + 1, pour une production x.","tache":"Combien de fois le profit s'annule-t-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r25",{"duree":20,"titre":"Intégration : bénéfice d'une PME","accroche":"Produire assez pour gagner.","intro":"Le Probatoire C 2022 étudiait le bénéfice d'une PME : coût, recette, seuil de rentabilité.","objectifs":["écrire le bénéfice","résoudre B(x) > 0","conclure avec la capacité"],"parties":[{"t":"Le modèle","html":"<div class='def'><b>Définition</b>Le <strong>bénéfice</strong> est B(x) = R(x) − C(x), recette moins coût.</div>"},{"t":"Exemple","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":25,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Des jeunes de Yaoundé montent une PME : coût C(x) = x² + 202 500 F, prix de vente 1 500 F l'unité, capacité 1 300.","tache":"Quel est le nombre minimal d'articles pour un bénéfice ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r32",{"duree":20,"titre":"Représentation des fonctions polynômes","accroche":"Du tableau de variation à la courbe.","intro":"L'étude complète d'un polynôme suit un plan fixe.","objectifs":["suivre le plan d'étude","placer les points remarquables","tracer la courbe"],"parties":[{"t":"Le plan d'étude","html":"<div class='def'><b>Définition</b>Étudier une fonction, c'est donner son <strong>ensemble de définition</strong>, ses <strong>limites</strong>, sa <strong>dérivée</strong>, son <strong>tableau de variation</strong>, puis tracer sa courbe.</div>"},{"t":"Exemple","verrou":true},{"t":"Le tracé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":32,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un ingénieur de Kribi trace le profil d'une dune avec y = x³ − 3x + 1, entre −2 et 2.","tache":"Donne les hauteurs extrêmes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r33",{"duree":20,"titre":"Représentation des fonctions rationnelles","accroche":"Asymptotes et centre de symétrie.","intro":"Les fonctions rationnelles simples ont des asymptotes qui guident le tracé.","objectifs":["étudier une homographique","étudier x + 1/x","tracer avec les asymptotes"],"parties":[{"t":"Homographique","html":"<div class='def'><b>Définition</b>Pour f(x) = (ax + b)/(cx + d), la droite x = −d/c est <strong>asymptote verticale</strong> et la droite y = a/c est <strong>asymptote horizontale</strong>. Leur intersection est centre de symétrie.</div>"},{"t":"Exemple","verrou":true},{"t":"Asymptote oblique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":33,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le rendement d'un champ de maïs à Bafia est modélisé par f(x) = (x + 1)/(x − 1) pour x > 1.","tache":"Décris l'évolution du rendement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r35",{"duree":20,"titre":"Fonctions rationnelles : entraînement","accroche":"Une division pour faire apparaître l'asymptote.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Écrire f(x) = ax + b + c/(x − d) montre l'asymptote oblique y = ax + b.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":35,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le coût moyen d'une fabrique de briques de Ngaoundéré suit f(x) = ax + b + c/(x + 1), en milliers de francs, pour x centaines de briques. Le comptable a relevé f(0) = 5, f(1) = 4 et f(3) = 5.","tache":"Trouve a, b et c."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r34",{"duree":20,"titre":"Intégration : lire une courbe","accroche":"Un sujet de Probatoire entièrement graphique.","intro":"Le Probatoire donne souvent la courbe d'une fonction et demande de la lire avant de retrouver son expression.","objectifs":["lire domaine et limites","lire les asymptotes","retrouver une expression"],"parties":[{"t":"Lecture","html":"<div class='def'><b>Définition</b>Lire une courbe, c'est en tirer le <strong>domaine</strong>, les <strong>limites</strong>, les <strong>asymptotes</strong>, le signe de f et de f'.</div>"},{"t":"Retrouver f","verrou":true},{"t":"Courbes associées","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":34,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Le bénéfice d'une coopérative de Mbouda est modélisé par f(x) = (x² − 3x + 6)/(x − 1) pour x > 1 (en centaines de milliers de francs, x en tonnes).","tache":"Écris f(x) sous la forme ax + b + c/(x − 1), puis donne l'asymptote oblique de la courbe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r18",{"duree":20,"titre":"Intégration : équilibre et fonctions","accroche":"Le barycentre au service du portage.","intro":"Ce problème relie barycentre et étude de fonction, comme dans les sujets de Probatoire.","objectifs":["modéliser un équilibre","utiliser une fonction","conclure"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Le point d'équilibre d'un système de charges est le <strong>barycentre</strong> des positions pondérées par les masses.</div>"},{"t":"Fonction de la masse","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":18,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une vendeuse de Kumba porte sur l'épaule un bâton de 2 m avec 10 kg de plantains à un bout et un panier de masse m à l'autre.","tache":"Exprime la position de l'épaule et commente."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r27",{"duree":20,"titre":"Composée de deux symétries orthogonales","accroche":"Deux miroirs font une rotation.","intro":"Composer deux réflexions donne une rotation ou une translation selon la position des axes.","objectifs":["composer deux réflexions","reconnaître la transformation obtenue","décomposer une rotation"],"parties":[{"t":"Le résultat","html":"<div class='def'><b>Définition</b>Si les axes Δ et Δ' sont <strong>sécants</strong> en O, s_Δ' ∘ s_Δ est la <strong>rotation</strong> de centre O et d'angle 2(Δ ; Δ'). S'ils sont <strong>parallèles</strong>, c'est une <strong>translation</strong> de vecteur double du vecteur qui va de Δ à Δ' perpendiculairement.</div>"},{"t":"Décomposition","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":27,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un artisan de Foumban veut reproduire un motif tourné de 60° à l'aide de deux miroirs.","tache":"Quel angle doit-il donner aux miroirs ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r29",{"duree":20,"titre":"Composée de réflexions : entraînement","accroche":"Décomposer une rotation, comme au Probatoire C.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>r(A ; θ) = s_(AB) ∘ s_Δ où Δ passe par A et vérifie 2(Δ ; (AB)) = θ.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":29,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un menuisier de Foumban fabrique un motif en étoile : il fait tourner une planchette [AB] de 4 cm autour de A d'un angle de −2π/3. Il doit tracer la droite Δ qui lui sert de guide, axe de symétrie entre B et son image B'.","tache":"Construis B' et indique comment tracer Δ."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r28",{"duree":20,"titre":"Composée de deux rotations","accroche":"Tourner deux fois autour du même point.","intro":"Composer deux rotations de même centre revient à additionner leurs angles.","objectifs":["composer des rotations de même centre","traiter des centres différents","reconnaître l'identité"],"parties":[{"t":"Même centre","html":"<div class='def'><b>Définition</b>r(O ; α) ∘ r(O ; β) est la <strong>rotation</strong> r(O ; α + β). Si α + β = 2kπ, c'est l'<strong>identité</strong>.</div>"},{"t":"Centres différents","verrou":true},{"t":"Méthode","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":28,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une roue de manège à Douala tourne de 45°, puis encore de 75° autour du même axe.","tache":"Quelle rotation obtient-on au total ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r30",{"duree":20,"titre":"Composée de rotations : entraînement","accroche":"Deux centres différents.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>r(B ; β) ∘ r(A ; α) se ramène à quatre réflexions dont deux s'annulent.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":30,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Sur un manège de Kribi, un siège tourne d'abord autour du pilier A d'un angle de −2π/3, puis autour du pilier B d'un angle de −2π/3 (AB = 6 m).","tache":"Donne la nature et l'angle du mouvement total r' ∘ r."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r31",{"duree":20,"titre":"Composée d'homothéties et de translations","accroche":"Agrandir, puis agrandir encore.","intro":"Les homothéties de même centre se composent en multipliant les rapports.","objectifs":["composer deux homothéties de même centre","composer homothétie et translation","déterminer centre et rapport"],"parties":[{"t":"Même centre","html":"<div class='def'><b>Définition</b>h(O ; k) ∘ h(O ; k') est l'<strong>homothétie</strong> h(O ; kk').</div>"},{"t":"Homothétie et translation","verrou":true},{"t":"Trouver un centre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":31,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un imprimeur de Yaoundé agrandit une affiche au double, puis encore de 1,5 depuis le même coin.","tache":"Quel est l'agrandissement total ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r36",{"duree":20,"titre":"Généralités sur les suites numériques","accroche":"Une liste de nombres qui suit une règle.","intro":"Une suite peut être donnée par une formule ou par une relation de récurrence.","objectifs":["calculer des termes","étudier le sens de variation","utiliser le raisonnement par récurrence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>suite</strong> associe à chaque entier n un réel uₙ. Elle est définie <strong>explicitement</strong> (uₙ = 2n + 1) ou <strong>par récurrence</strong> (u₀ = 1, uₙ₊₁ = 2uₙ + 1).</div>"},{"t":"Sens de variation","verrou":true},{"t":"Récurrence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":36,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une tontine de quartier à Douala commence avec 1 membre et chaque mois chaque membre en invite un, plus le fondateur un de plus : uₙ₊₁ = 2uₙ + 1.","tache":"Combien de membres au bout de 3 mois ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r37",{"duree":20,"titre":"Suites arithmétiques et géométriques","accroche":"Ajouter ou multiplier la même quantité.","intro":"Ces deux suites modélisent salaires, épargne et populations.","objectifs":["reconnaître chaque suite","calculer le terme général","calculer une somme"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une suite est <strong>arithmétique</strong> de raison r si uₙ₊₁ = uₙ + r ; elle est <strong>géométrique</strong> de raison q si vₙ₊₁ = q·vₙ.</div>"},{"t":"Formules","verrou":true},{"t":"Intérêts composés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":37,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un fermier de Foumbot place 1 000 000 F à 15 % d'intérêts composés pour financer un élevage de 3 000 000 F dans 8 ans.","tache":"Ce placement suffira-t-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r38",{"duree":20,"titre":"Caractéristiques de position et de dispersion","accroche":"Moyenne, médiane, variance d'une série regroupée.","intro":"Pour une série regroupée en classes, on remplace chaque classe par son centre.","objectifs":["calculer la moyenne","calculer variance et écart type","trouver la médiane par interpolation"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Pour une série en classes de centres cᵢ et d'effectifs nᵢ (total N) : <strong>moyenne</strong> x̄ = Σnᵢcᵢ/N ; <strong>variance</strong> V = Σnᵢcᵢ²/N − x̄² ; <strong>écart type</strong> σ = √V.</div>"},{"t":"Exemple","verrou":true},{"t":"Médiane","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":38,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une association de Douala relève les dépenses quotidiennes de ses membres, regroupées en classes, pour fixer une cotisation.","tache":"Indique les calculs utiles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r39",{"duree":20,"titre":"Représentations graphiques des séries en classes","accroche":"Histogramme et polygone des effectifs cumulés.","intro":"Le graphique donne une lecture rapide de la série et permet de lire la médiane.","objectifs":["tracer un histogramme","tracer le polygone des effectifs cumulés","lire la médiane"],"parties":[{"t":"L'histogramme","html":"<div class='def'><b>Définition</b>Dans un <strong>histogramme</strong>, chaque classe est représentée par un rectangle dont l'<strong>aire</strong> est proportionnelle à l'effectif.</div>"},{"t":"Classes inégales","html":"<p>Si une classe est deux fois plus large, la hauteur de son rectangle est l'effectif divisé par 2.</p>","retenir":"Aire proportionnelle à l'effectif.","labo":{"type":"stats","classes":[0,10,20,30],"eff":[5,15,20,10],"amplitude":10}},{"t":"Effectifs cumulés","html":"<p>Le polygone des effectifs cumulés croissants relie les points (borne droite ; effectif cumulé). La médiane est l'abscisse du point d'ordonnée N/2.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Pour une série en classes d'amplitudes inégales, dans un histogramme, on représente :</p><ol type='a'><li>des aires proportionnelles aux effectifs</li><li>des hauteurs égales aux effectifs, quelle que soit l'amplitude</li><li>des bâtons</li><li>des secteurs</li></ol><details><summary>Voir la réponse</summary><p><strong>des aires proportionnelles aux effectifs</strong>. Il faut corriger par l'amplitude.</p></details><p><strong>Exercice.</strong></p><p>Classe [4 ; 8[ de fréquence 35 % : hauteur si l'unité est la classe de longueur 1 ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 8,75.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Les dépenses de 90 clients d'un supermarché de Yaoundé (en milliers de F) : [0 ; 10[ : 20 ; [10 ; 30[ : 40 ; [30 ; 60[ : 30.</p><p><strong>Tâche 1.</strong> Calcule les hauteurs des rectangles de l'histogramme (unité : classe de 10).</p><p><strong>Tâche 2.</strong> Trace le polygone des effectifs cumulés croissants et lis la médiane.</p><details><summary>Voir une réponse attendue</summary><p>Hauteurs : 20, 40/2 = 20, 30/3 = 10. ECC : 20, 60, 90. Médiane (45e valeur) : 10 + (45 − 20)/40 × 20 = 22,5 milliers de F.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Aire proportionnelle.","Classes inégales.","Polygone et médiane."],"exo":"<p>Classe [4 ; 8[ de fréquence 35 % : hauteur si l'unité est la classe de longueur 1 ? <em>(Réponse : 8,75.)</em></p>","quiz":[{"q":"Pour une série en classes d'amplitudes inégales, dans un histogramme, on représente :","r":["des aires proportionnelles aux effectifs","des hauteurs égales aux effectifs, quelle que soit l'amplitude","des bâtons","des secteurs"],"b":0,"e":"Il faut corriger par l'amplitude."},{"q":"Le polygone des effectifs cumulés croissants permet de lire :","r":["la variance et l'écart type","la médiane et les quartiles","l'écart type","le mode exact"],"b":1,"e":"On lit l'abscisse correspondant à N/2, N/4…"},{"q":"Le polygone des effectifs relie :","r":["les bornes inférieures des classes de l'histogramme","les axes","les milieux des sommets des rectangles de l'histogramme","l'origine aux sommets"],"b":2,"e":"Il se superpose à l'histogramme."},{"q":"Dans un histogramme à classes égales, la hauteur est proportionnelle :","r":["au centre","à l'amplitude","à la borne","à l'effectif"],"b":3,"e":"Les largeurs sont égales."},{"q":"L'effectif cumulé croissant d'une classe est :","r":["la somme des effectifs des classes jusqu'à elle incluse","son effectif seul, sans les classes précédentes","l'effectif total de la série, quelle que soit la classe","la moyenne"],"b":0,"e":"On cumule depuis la première classe."},{"q":"La médiane d'une série en classes se calcule par :","r":["la moyenne des bornes de la classe médiane","interpolation linéaire dans la classe médiane","le mode","l'étendue"],"b":1,"e":"On suppose une répartition uniforme dans la classe."},{"q":"Effectifs cumulés 5, 20, 40, 50 pour [0;5[, [5;10[, [10;15[, [15;20[ : la médiane est dans :","r":["[5 ; 10[","[0 ; 5[","[10 ; 15[","[15 ; 20["],"b":2,"e":"25 est atteint dans la troisième classe."},{"q":"Cette médiane vaut :","r":["12,5","10","15","11,25"],"b":3,"e":"10 + 5 × (25 − 20)/20."},{"q":"Un diagramme circulaire convient pour :","r":["un caractère qualitatif ou des parts d'un tout","une série chronologique sur plusieurs années","deux caractères quantitatifs","une dérivée"],"b":0,"e":"Chaque secteur représente une part."},{"q":"Le mode d'une série en classes correspond :","r":["à la première classe, celle des plus petites valeurs","à la classe de plus grande densité d'effectif","à la classe médiane","à la dernière classe"],"b":1,"e":"Avec des amplitudes égales : le plus grand effectif."}],"c":"1re D","m":"maths","rang":39,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un journaliste de Yaoundé présente le temps passé devant la télévision le dimanche, en classes inégales.","tache":"Comment doit-il tracer l'histogramme ?"},"gratuit":true});
VRT_L("1re-d-maths-r41",{"duree":20,"titre":"Représentations graphiques : entraînement","accroche":"Un sujet de Probatoire D-TI 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Avec des fréquences, on remplace N par 100.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":41,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une radio de Garoua veut savoir si la moitié des auditeurs regarde la télévision plus de 3 h le dimanche.","tache":"Réponds avec la médiane."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r40",{"duree":20,"titre":"Intégration : statistiques d'une association","accroche":"Des chiffres pour organiser une construction.","intro":"Le Probatoire D 2024 blanc partait d'un village qui finance une école : contributions, âges, choix de superviseurs.","objectifs":["calculer une moyenne","lire la classe modale","dénombrer un choix"],"parties":[{"t":"Les outils","html":"<div class='def'><b>Définition</b><strong>Moyenne</strong>, <strong>médiane</strong> et <strong>classe modale</strong> résument une série ; le dénombrement compte les choix possibles.</div>"},{"t":"Exemple","verrou":true},{"t":"Choix","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":40,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Trois groupes d'un village de l'Ouest financent une école ; leurs 54 membres ont entre 25 et 50 ans.","tache":"Calcule l'âge moyen et le nombre de façons de choisir 3 superviseurs."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r42",{"duree":20,"titre":"Droites orthogonales dans l'espace","accroche":"Orthogonales sans se couper.","intro":"Dans l'espace, deux droites peuvent être orthogonales sans être sécantes.","objectifs":["définir l'orthogonalité","utiliser le produit scalaire","raisonner dans un cube"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Deux droites de l'espace sont <strong>orthogonales</strong> si leurs parallèles menées par un même point sont perpendiculaires, c'est-à-dire si leurs vecteurs directeurs ont un produit scalaire nul.</div>"},{"t":"Dans le cube","verrou":true},{"t":"Piège du Probatoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":42,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un charpentier de Bandjoun vérifie qu'une poutre et un chevron qui ne se touchent pas sont bien d'équerre.","tache":"Comment le vérifier avec des vecteurs ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r45",{"duree":20,"titre":"Droites orthogonales : entraînement","accroche":"Vrai ou faux, comme au Probatoire C 2022.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour montrer que deux droites sont orthogonales, il suffit qu'une droite soit orthogonale à un plan contenant l'autre.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":45,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un élève de Bafang dessine un cube en carton pour un exposé.","tache":"Utilise le cube pour réfuter l'affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r43",{"duree":20,"titre":"Plans orthogonaux","accroche":"Un mur et le sol.","intro":"Deux plans orthogonaux se reconnaissent à leurs vecteurs normaux.","objectifs":["définir des plans orthogonaux","utiliser les vecteurs normaux","vérifier par le calcul"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Deux plans sont <strong>orthogonaux</strong> si l'un contient une droite orthogonale à l'autre ; de façon équivalente, leurs <strong>vecteurs normaux</strong> sont orthogonaux.</div>"},{"t":"Exemple","verrou":true},{"t":"Vecteur normal","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":43,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un maçon de Ngaoundéré vérifie qu'un mur d'équation x − y = 3 est orthogonal à une dalle x + y + z = 0 dans son repère.","tache":"Conclus."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r46",{"duree":20,"titre":"Plans orthogonaux : entraînement","accroche":"Trouver un paramètre.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On écrit n⃗ · n⃗' = 0 et on résout en m.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":46,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un menuisier de Bamenda règle l'inclinaison d'un panneau dont le plan dépend d'un réglage m.","tache":"Explique comment trouver le réglage qui le rend orthogonal à la table."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r44",{"duree":20,"titre":"Droite et plan orthogonaux","accroche":"Un poteau bien vertical.","intro":"Une droite orthogonale à un plan l'est à toutes ses droites.","objectifs":["caractériser une droite orthogonale à un plan","utiliser vecteur directeur et vecteur normal","écrire un plan"],"parties":[{"t":"Théorème","html":"<div class='def'><b>Définition</b>Une droite est <strong>orthogonale à un plan</strong> si elle est orthogonale à deux droites sécantes de ce plan ; son vecteur directeur est alors colinéaire au vecteur normal.</div>"},{"t":"Exemple","verrou":true},{"t":"Écrire un plan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":44,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"À la construction d'une antenne à Bertoua, le mât doit être orthogonal au sol d'équation z = 0.","tache":"Quelle direction doit avoir le mât ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r47",{"duree":20,"titre":"Droite et plan orthogonaux : entraînement","accroche":"Le point d'intersection, comme au Probatoire C 2026.","intro":"Cette séance d'entraînement reprend la notion avec un exercice du niveau du Probatoire.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On remplace la représentation paramétrique dans l'équation du plan.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":47,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Un architecte de Douala vérifie qu'un pilier traverse une dalle à angle droit.","tache":"Donne les deux étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r48",{"duree":20,"titre":"Présentation du concept de graphe","accroche":"Des points et des liens.","intro":"Un graphe modélise des relations : routes entre villes, amitiés, vols.","objectifs":["définir sommets et arêtes","reconnaître un graphe simple","reconnaître un graphe complet"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>graphe</strong> est formé de <strong>sommets</strong> reliés par des <strong>arêtes</strong>. Son <strong>ordre</strong> est le nombre de sommets.</div>"},{"t":"Graphe simple et complet","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":48,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Ali, à Yaoundé, veut inviter 5 amis, dont certains ne s'entendent pas : A avec D ; B avec C, D, E ; D avec E.","tache":"Représente la situation par un graphe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r49",{"duree":20,"titre":"Nombre d'arêtes et somme des degrés","accroche":"Chaque arête compte deux fois.","intro":"La somme des degrés est toujours le double du nombre d'arêtes.","objectifs":["calculer un degré","utiliser la formule des degrés","compter les arêtes d'un graphe complet"],"parties":[{"t":"Théorème","html":"<div class='def'><b>Définition</b>Le <strong>degré</strong> d'un sommet est le nombre d'arêtes qui y aboutissent. <strong>La somme des degrés est égale au double du nombre d'arêtes.</strong></div>"},{"t":"Conséquence","verrou":true},{"t":"Graphe complet","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":49,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une compagnie aérienne veut relier 5 villes du Cameroun deux à deux.","tache":"Combien de vols aller simple doit-elle prévoir ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-maths-r50",{"duree":20,"titre":"Intégration : un réseau de vols","accroche":"Graphes et espace au service d'une compagnie.","intro":"Le Probatoire D 2022 traduisait des liaisons aériennes par un graphe.","objectifs":["construire un graphe","le caractériser","compter les vols"],"parties":[{"t":"Modèle","html":"<div class='def'><b>Définition</b>Chaque ville est un <strong>sommet</strong>, chaque liaison une <strong>arête</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"maths","rang":50,"apc":{"module":"Mathématiques de Première","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser et résoudre des situations de la vie économique et sociale","situation":"Une compagnie relie Douala, Yaoundé, Garoua, Maroua et Bertoua l'une à toutes les autres.","tache":"Construis le graphe et calcule le nombre de vols aller simple."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r01",{"duree":20,"titre":"Mesures et incertitudes","accroche":"Aucune mesure n'est parfaite.","intro":"Toute mesure s'accompagne d'une incertitude. Savoir l'évaluer, c'est savoir quelle confiance accorder au résultat.","objectifs":["utiliser les unités du Système international","évaluer une incertitude","écrire un résultat correctement"],"parties":[{"t":"Mesure et incertitude","html":"<div class='def'><b>Définition</b>Le résultat d'une mesure s'écrit <strong>x = x̄ ± U</strong>, où U est l'<strong>incertitude</strong>, avec l'unité. L'incertitude relative vaut U/x̄.</div>"},{"t":"Série de mesures","html":"<p>Pour n mesures répétées de moyenne x̄ et d'écart type σ, l'incertitude vaut U = k·σ/√n, k étant le facteur d'élargissement.</p><p class='formule'>n = 12, σ = 0,27 cm, k = 2,18 : U = 2,18 × 0,27/√12 ≈ 0,17 cm</p>","labo":{"type":"calcul","f":"incert","vals":{"x":20,"d":0.5}}},{"t":"Écrire le résultat","html":"<p>f' = (10,41 ± 0,17) cm. On arrondit l'incertitude à deux chiffres significatifs au plus, et la valeur au même rang.</p>","retenir":"Valeur, incertitude, unité."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Toute mesure est entachée :</p><ol type='a'><li>d'aucune erreur</li><li>d'une erreur toujours nulle</li><li>d'une incertitude</li><li>d'une erreur connue exactement</li></ol><details><summary>Voir la réponse</summary><p><strong>d'une incertitude</strong>. On ne connaît jamais la valeur vraie.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Une longueur vaut 20 cm à 0,5 cm près : incertitude relative ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 2,5 %.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Pour vérifier un pendule de laboratoire, deux groupes du lycée de Mbouda mesurent sa période. Groupe A : 10 mesures, moyenne 1,52 s, écart type 0,04 s (k = 2,26). Groupe B : 5 mesures, moyenne 1,49 s, écart type 0,06 s (k = 2,78).</p><p><strong>Consigne 1.</strong> Écris le résultat de chaque groupe avec son incertitude.</p><p><strong>Consigne 2.</strong> Les deux résultats sont-ils compatibles ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>U_A = 2,26 × 0,04/√10 ≈ 0,03 s : T = (1,52 ± 0,03) s. U_B = 2,78 × 0,06/√5 ≈ 0,07 s : T = (1,49 ± 0,07) s. Les intervalles [1,49 ; 1,55] et [1,42 ; 1,56] se chevauchent : les résultats sont compatibles.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["x = x̄ ± U.","U = kσ/√n.","Arrondir au même rang."],"exo":"<p>Une longueur vaut 20 cm à 0,5 cm près : incertitude relative ? <em>(Réponse : 2,5 %.)</em></p>","quiz":[{"q":"Toute mesure est entachée :","r":["d'aucune erreur","d'une erreur toujours nulle","d'une incertitude","d'une erreur connue exactement"],"b":2,"e":"On ne connaît jamais la valeur vraie."},{"q":"Le résultat d'une mesure s'écrit :","r":["valeur seule, avec tous les chiffres affichés","incertitude seule","valeur ± incertitude, sans unité","valeur ± incertitude, avec l'unité"],"b":3,"e":"Ex. : T = (1,52 ± 0,03) s."},{"q":"L'erreur systématique est :","r":["une erreur qui décale toutes les mesures dans le même sens","une erreur au hasard","une erreur nulle","une erreur de calcul commise par l'opérateur lors de la conversion"],"b":0,"e":"Ex. : un appareil mal étalonné."},{"q":"L'erreur aléatoire :","r":["est toujours dans le même sens, d'une mesure à l'autre","varie au hasard d'une mesure à l'autre","est nulle","disparaît avec un appareil faux"],"b":1,"e":"On la réduit en multipliant les mesures."},{"q":"Pour réduire l'incertitude aléatoire, on :","r":["fait une seule mesure","change d'unité","répète la mesure et on calcule la moyenne","arrondit au hasard chaque résultat obtenu"],"b":2,"e":"L'incertitude de la moyenne diminue avec le nombre de mesures."},{"q":"L'incertitude relative de (2,00 ± 0,04) m vaut :","r":["4 %","0,04 %","0,5 %","2 %"],"b":3,"e":"0,04 / 2,00 = 0,02."},{"q":"Deux résultats sont compatibles si :","r":["leurs intervalles d'incertitude se chevauchent","leurs valeurs sont identiques","leurs unités diffèrent","l'un est plus grand que l'autre, à l'unité près"],"b":0,"e":"Ils peuvent correspondre à la même valeur vraie."},{"q":"Le nombre de chiffres significatifs de 0,0350 est :","r":["4","3","5","2"],"b":1,"e":"Les zéros de tête ne comptent pas."},{"q":"L'incertitude d'une moyenne vaut U = k × σ / √n. Si n augmente :","r":["U augmente","U ne change pas","U diminue","U devient négatif"],"b":2,"e":"Le dénominateur √n grandit."},{"q":"La précision d'un appareil est liée :","r":["à sa couleur","à son prix","à la taille totale de l'instrument","à sa plus petite graduation"],"b":3,"e":"On ne lit pas mieux que la graduation."}],"c":"1re D","m":"physique","rang":1,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Au laboratoire du lycée de Mbouda, douze groupes mesurent la distance focale d'une même lentille et obtiennent une moyenne de 10,41 cm avec un écart type de 0,27 cm.","tache":"Présente le résultat avec son incertitude (k = 2,18)."},"gratuit":true});
VRT_L("1re-d-physique-r02",{"duree":20,"titre":"Notion de modèle","accroche":"Une représentation simplifiée du réel.","intro":"Les physiciens remplacent le réel par des modèles qui permettent de prévoir.","objectifs":["définir un modèle","donner des exemples","connaître les limites d'un modèle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>modèle</strong> est une représentation simplifiée d'un phénomène, qui permet de l'expliquer et de prévoir son évolution dans un <strong>domaine de validité</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":2,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un élève de Garoua modélise le ballon de football par un point pour calculer sa trajectoire.","tache":"Ce modèle permet-il d'étudier l'effet donné au ballon ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r03",{"duree":20,"titre":"Travail d'une force","accroche":"Une force qui déplace son point d'application travaille.","intro":"Le travail mesure l'énergie transférée par une force lors d'un déplacement.","objectifs":["calculer le travail d'une force constante","calculer le travail du poids","calculer le travail d'un couple"],"parties":[{"t":"Force constante","html":"<div class='def'><b>Définition</b>Le <strong>travail</strong> d'une force constante F⃗ sur un déplacement AB⃗ est <strong>W = F × AB × cos α</strong>, en joules (J). Il est moteur si W > 0, résistant si W &lt; 0.</div>"},{"t":"Poids et ressort","verrou":true},{"t":"Couple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":3,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un pousseur du marché de Mokolo tire son chariot avec une force de 50 N inclinée de 30° sur 10 m.","tache":"Calcule le travail fourni."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r04",{"duree":20,"titre":"Puissance d'une force","accroche":"Le même travail, plus ou moins vite.","intro":"La puissance mesure la rapidité avec laquelle une force effectue un travail.","objectifs":["définir la puissance","utiliser P = F·v","calculer la puissance d'un couple"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>puissance moyenne</strong> est P = W/Δt, en watts (W). Pour une force constante, la puissance instantanée vaut <strong>P = F × v × cos α</strong>.</div>"},{"t":"Couple","verrou":true},{"t":"Unités","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":4,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Le moteur d'une moulinette à maïs d'une meunière de Bafoussam exerce un couple de 20 N·m à 1 500 tr/min.","tache":"Quelle est sa puissance mécanique ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r05",{"duree":20,"titre":"Énergie cinétique et théorème de l'énergie cinétique","accroche":"Plus on va vite, plus il faut freiner longtemps.","intro":"L'énergie cinétique dépend de la masse et du carré de la vitesse. Le théorème relie sa variation aux travaux des forces.","objectifs":["calculer une énergie cinétique","énoncer le théorème","calculer une distance de freinage"],"parties":[{"t":"Énergie cinétique","html":"<div class='def'><b>Définition</b>Un solide de masse m en translation à la vitesse v possède l'<strong>énergie cinétique</strong> Ec = ½mv², en joules.</div>"},{"t":"Le théorème","verrou":true},{"t":"Freinage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":5,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Sur l'axe Douala-Yaoundé, un car de 1 000 kg roulant à 72 km/h freine avec une force de 5 000 N.","tache":"Quelle distance lui faut-il pour s'arrêter ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r06",{"duree":20,"titre":"Énergie potentielle","accroche":"De l'énergie en réserve.","intro":"Un solide en hauteur ou un ressort comprimé stockent de l'énergie potentielle.","objectifs":["calculer l'énergie potentielle de pesanteur","choisir une référence","calculer l'énergie élastique"],"parties":[{"t":"Pesanteur","html":"<div class='def'><b>Définition</b>L'<strong>énergie potentielle de pesanteur</strong> vaut Ep = mgz + constante, z étant l'altitude comptée sur un axe vertical vers le haut ; on choisit souvent Ep = 0 au niveau de référence.</div>"},{"t":"Exemple","verrou":true},{"t":"Élastique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":6,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un ouvrier de Kribi hisse un sac de ciment de 50 kg sur un échafaudage de 2 m.","tache":"Quelle énergie potentielle le sac a-t-il gagnée ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r07",{"duree":20,"titre":"Énergie mécanique et sa conservation","accroche":"Sans frottement, rien ne se perd.","intro":"L'énergie mécanique se conserve si seules des forces conservatives travaillent.","objectifs":["définir l'énergie mécanique","appliquer la conservation","tenir compte des frottements"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>énergie mécanique</strong> est Em = Ec + Ep. En l'absence de frottements, elle se <strong>conserve</strong>.</div>"},{"t":"Chute libre","verrou":true},{"t":"Frottements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":7,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Un enfant de Limbé descend un toboggan de 2 m de haut ; il arrive en bas à 5 m/s.","tache":"Montre que des frottements ont agi."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r08",{"duree":20,"titre":"La chaleur et ses modes de transfert","accroche":"Conduction, convection, rayonnement.","intro":"La chaleur est un transfert d'énergie qui va spontanément du corps chaud vers le corps froid.","objectifs":["distinguer chaleur et température","citer les modes de transfert","calculer une quantité de chaleur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>chaleur</strong> Q est l'énergie transférée d'un corps chaud à un corps froid. Sans changement d'état, <strong>Q = m·c·Δθ</strong>, c étant la chaleur massique.</div>"},{"t":"Modes de transfert","verrou":true},{"t":"Changement d'état","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":8,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Une vendeuse de bouillie de Ngaoundéré chauffe 2 kg d'eau de 25 °C à 100 °C (c = 4 190 J/kg/°C).","tache":"Calcule l'énergie nécessaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r09",{"duree":20,"titre":"Calorimétrie et échanges de chaleur","accroche":"Dans un calorimètre, rien ne s'échappe.","intro":"Le calorimètre isole un système pour mesurer les échanges de chaleur.","objectifs":["énoncer le principe des échanges","trouver une température d'équilibre","mesurer une chaleur massique"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Dans un <strong>calorimètre</strong> isolé, la somme des quantités de chaleur échangées est nulle : <strong>ΣQ = 0</strong>, c'est-à-dire chaleur cédée = chaleur reçue.</div>"},{"t":"Exemple","verrou":true},{"t":"Capacité du calorimètre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":9,"apc":{"module":"Mesures, énergie mécanique et chaleur","famille":"Utilisation rationnelle de l'énergie","agir":"Évaluer et économiser l'énergie dans les activités quotidiennes","situation":"Pour estimer la température du foyer d'un forgeron de Foumban, on plonge un morceau de fer chauffé dans de l'eau d'un calorimètre.","tache":"Explique la démarche."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r10",{"duree":20,"titre":"Lentilles minces : caractéristiques","accroche":"Converger ou diverger.","intro":"Une lentille mince dévie la lumière ; ses foyers et sa vergence la caractérisent.","objectifs":["distinguer les lentilles","définir foyers et distance focale","calculer une vergence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>lentille mince</strong> convergente a des bords minces ; une divergente, des bords épais. La <strong>vergence</strong> vaut C = 1/f', en dioptries (δ), f' étant en mètres : C > 0 pour une convergente.</div>"},{"t":"Les rayons particuliers","html":"<ul><li>Un rayon passant par le centre optique O n'est pas dévié.</li><li>Un rayon parallèle à l'axe émerge en passant par F'.</li><li>Un rayon passant par F émerge parallèle à l'axe.</li></ul>","labo":{"type":"lentille","f":10,"oa":-30}},{"t":"Vergences","html":"<p>C = (n − 1)(1/R₁ − 1/R₂). Lentille biconvexe, R = 5 cm, n = 1,5 : C = 20 δ, f' = 5 cm. Lentilles accolées : C = C₁ + C₂ (théorème des vergences).</p>","retenir":"C = 1/f' en dioptries."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Une lentille convergente est :</p><ol type='a'><li>plus épaisse au centre qu'aux bords</li><li>plus mince au centre qu'aux bords</li><li>plate</li><li>opaque</li></ol><details><summary>Voir la réponse</summary><p><strong>plus épaisse au centre qu'aux bords</strong>. Elle fait converger les rayons.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Vergence d'une lentille de f' = 20 cm ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 5 δ.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un opticien du marché Central dispose de trois lentilles : L₁ de vergence +5 δ, L₂ de vergence −4 δ, et L₃ biconvexe en verre d'indice 1,5 dont les deux faces ont un rayon de courbure de 10 cm.</p><p><strong>Consigne 1.</strong> Calcule la distance focale de chaque lentille et donne sa nature.</p><p><strong>Consigne 2.</strong> Laquelle choisir pour fabriquer une loupe ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>L₁ : f' = 20 cm, convergente. L₂ : f' = −25 cm, divergente. L₃ : C = (1,5 − 1)(1/0,1 + 1/0,1) = 10 δ, f' = 10 cm, convergente. Pour une loupe, on choisit la convergente la plus puissante : L₃.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Convergente ou divergente.","Rayons particuliers.","C = 1/f'."],"exo":"<p>Vergence d'une lentille de f' = 20 cm ? <em>(Réponse : 5 δ.)</em></p>","quiz":[{"q":"Une lentille convergente est :","r":["plus épaisse au centre qu'aux bords","plus mince au centre qu'aux bords","plate","opaque"],"b":0,"e":"Elle fait converger les rayons."},{"q":"Le foyer image F' d'une lentille convergente est :","r":["le centre optique, par lequel les rayons passent sans déviation","le point où convergent les rayons parallèles à l'axe","un point de l'objet","le bord de la lentille"],"b":1,"e":"Il est situé après la lentille."},{"q":"La vergence C d'une lentille vaut :","r":["f'","f' × 2","1 / f'","f' / 2"],"b":2,"e":"f' en mètres, C en dioptries."},{"q":"Une lentille de distance focale 0,1 m a une vergence de :","r":["0,1 δ","1 δ","100 δ","10 δ"],"b":3,"e":"C = 1 / f' = 1 / 0,1 = 10 dioptries."},{"q":"Une lentille divergente a une vergence :","r":["négative","positive","nulle","infinie"],"b":0,"e":"Sa distance focale est négative."},{"q":"Un rayon passant par le centre optique :","r":["est dévié vers le foyer","n'est pas dévié","est réfléchi","est absorbé"],"b":1,"e":"Propriété du centre optique."},{"q":"Un rayon passant par le foyer objet F ressort :","r":["par le centre","vers le foyer objet","parallèle à l'axe optique","perpendiculaire à l'axe"],"b":2,"e":"Principe du retour inverse."},{"q":"L'unité de la vergence est :","r":["le mètre (m)","le watt","le degré","la dioptrie (δ)"],"b":3,"e":"La vergence est l'inverse d'une longueur : 1 δ = 1 m⁻¹."},{"q":"Plus une lentille est bombée :","r":["plus elle est convergente","moins elle est convergente","plus elle est divergente","rien ne change"],"b":0,"e":"Sa distance focale diminue."},{"q":"La loupe est :","r":["une lentille divergente","une lentille convergente","un miroir plan","un prisme"],"b":1,"e":"Elle grossit les objets proches."}],"c":"1re D","m":"physique","rang":10,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un réparateur de lunettes du marché Central reçoit une lentille sans étiquette.","tache":"Comment savoir si elle est convergente ?"},"gratuit":true});
VRT_L("1re-d-physique-r11",{"duree":20,"titre":"Image donnée par une lentille et relation de conjugaison","accroche":"Calculer où se forme l'image.","intro":"La relation de conjugaison et le grandissement donnent la position et la taille de l'image.","objectifs":["construire une image","appliquer la relation de conjugaison","calculer le grandissement"],"parties":[{"t":"Conjugaison","html":"<div class='def'><b>Définition</b>Avec des distances algébriques mesurées depuis O : <strong>1/OA' − 1/OA = 1/f'</strong>. Le <strong>grandissement</strong> vaut γ = A'B'/AB = OA'/OA.</div>"},{"t":"Exemple","verrou":true},{"t":"Construction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":11,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un photographe de Douala place un sujet à 30 cm d'un objectif de distance focale 10 cm.","tache":"Où mettre le capteur ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r12",{"duree":20,"titre":"L'œil et ses défauts","accroche":"Accommoder, corriger.","intro":"L'œil se comporte comme une lentille convergente de vergence variable devant un écran, la rétine.","objectifs":["décrire l'œil réduit","définir PP et PR","corriger myopie et hypermétropie"],"parties":[{"t":"L'œil réduit","html":"<div class='def'><b>Définition</b>L'<strong>œil réduit</strong> est modélisé par une lentille convergente (cristallin) placée devant un écran fixe (rétine). L'<strong>accommodation</strong> modifie sa vergence pour garder l'image nette.</div>"},{"t":"Défauts","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":12,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un élève de Bertoua voit mal le tableau du fond de la classe ; l'ophtalmologue mesure son PR à 2 m.","tache":"Identifie le défaut et propose une correction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r13",{"duree":20,"titre":"La loupe","accroche":"Voir plus grand ce qui est petit.","intro":"La loupe est une lentille convergente de courte distance focale.","objectifs":["expliquer le fonctionnement","définir puissance et grossissement","calculer"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>La <strong>loupe</strong> est une lentille convergente de petite distance focale. L'objet placé entre le foyer F et O en donne une image <strong>virtuelle, droite et agrandie</strong>.</div>"},{"t":"Puissance et grossissement","verrou":true},{"t":"Usage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":13,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un horloger du marché de Mokolo utilise une loupe de distance focale 5 cm.","tache":"Calcule sa puissance intrinsèque et son grossissement commercial."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r14",{"duree":20,"titre":"Le microscope","accroche":"Voir une cellule de 10 µm.","intro":"Le microscope associe deux lentilles convergentes pour un fort grossissement.","objectifs":["décrire le microscope","définir l'intervalle optique","calculer puissance et grossissement"],"parties":[{"t":"Description","html":"<div class='def'><b>Définition</b>Le <strong>microscope</strong> comporte un objectif de très petite distance focale f₁ et un oculaire de petite distance focale f₂. L'<strong>intervalle optique</strong> Δ est la distance F₁'F₂.</div>"},{"t":"Formules","verrou":true},{"t":"Utilisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":14,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Au laboratoire d'analyses d'un hôpital de Bafoussam, un microscope a f₁ = 0,4 cm, f₂ = 5 cm et O₁O₂ = 25,4 cm.","tache":"Calcule son grossissement commercial."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r15",{"duree":20,"titre":"Puissance et grossissement d'un instrument","accroche":"Comparer des instruments d'optique.","intro":"Puissance et grossissement permettent de comparer les instruments.","objectifs":["définir la puissance","définir le grossissement","calculer le diamètre apparent"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>puissance</strong> d'un instrument est P = α'/AB (δ), α' étant l'angle sous lequel on voit l'image. Le <strong>grossissement</strong> est G = α'/α, α étant l'angle sous lequel on verrait l'objet à l'œil nu.</div>"},{"t":"Grossissement commercial","verrou":true},{"t":"Diamètre apparent","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":15,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un vendeur du marché Mboppi propose deux loupes : 10 δ et 20 δ.","tache":"Laquelle grossit le plus ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r16",{"duree":20,"titre":"Spectres lumineux","accroche":"La lumière blanche contient toutes les couleurs.","intro":"Un prisme décompose la lumière ; le spectre renseigne sur la source et sur la matière traversée.","objectifs":["décrire le spectre de la lumière blanche","distinguer émission et absorption","situer le visible parmi les ondes"],"parties":[{"t":"Spectres","html":"<div class='def'><b>Définition</b>Un <strong>spectre d'émission</strong> est formé de raies colorées sur fond noir ; un <strong>spectre d'absorption</strong>, de raies noires sur le fond coloré du spectre continu.</div>"},{"t":"Ondes électromagnétiques","verrou":true},{"t":"Température et couleur","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":16,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Un forgeron de Bamessing chauffe une barre d'acier jusqu'à ce qu'elle devienne orange (λ ≈ 600 nm).","tache":"Estime sa température."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r17",{"duree":20,"titre":"Interaction lumière-matière","accroche":"Un photon, un saut d'énergie.","intro":"La lumière échange de l'énergie avec la matière par paquets : les photons.","objectifs":["calculer l'énergie d'un photon","interpréter une transition","distinguer émission et absorption"],"parties":[{"t":"Le photon","html":"<div class='def'><b>Définition</b>La lumière de fréquence ν est formée de <strong>photons</strong> d'énergie <strong>E = hν = hc/λ</strong>, h = 6,62 × 10⁻³⁴ J·s. En pratique : E (eV) ≈ 1 240/λ (nm).</div>"},{"t":"Transitions","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":17,"apc":{"module":"Optique et lumière","famille":"Protection et amélioration de la vision","agir":"Choisir et utiliser des instruments d'optique","situation":"Les lampes à vapeur de sodium des carrefours de Douala émettent une lumière jaune-orange de 589 nm.","tache":"Calcule l'énergie d'un photon émis."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r18",{"duree":20,"titre":"Les générateurs électriques","accroche":"La pile ne délivre pas toute sa f.é.m.","intro":"Un générateur réel a une force électromotrice et une résistance interne.","objectifs":["schématiser un générateur","appliquer U = E − rI","associer des générateurs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un générateur linéaire a pour caractéristique <strong>U = E − rI</strong>, E étant sa force électromotrice (V) et r sa résistance interne (Ω).</div>"},{"t":"Associations","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":18,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un réparateur de radios de Bafang associe 4 piles de 1,5 V en série pour un poste.","tache":"Calcule la f.é.m. obtenue."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r19",{"duree":20,"titre":"Les récepteurs électriques","accroche":"Moteurs et électrolyseurs ont une f.c.é.m.","intro":"Un récepteur actif convertit l'énergie électrique en une autre forme que la chaleur.","objectifs":["schématiser un récepteur","appliquer U = E' + r'I","distinguer récepteurs passifs et actifs"],"parties":[{"t":"Caractéristique","html":"<div class='def'><b>Définition</b>Un récepteur actif linéaire (moteur, électrolyseur) vérifie <strong>U = E' + r'I</strong>, E' étant sa force contre-électromotrice.</div>"},{"t":"Récepteurs passifs","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":19,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un ventilateur alimenté par un panneau solaire à Maroua a une f.c.é.m. de 6 V et une résistance interne de 2 Ω.","tache":"Calcule la tension à ses bornes pour 0,5 A."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r20",{"duree":20,"titre":"Point de fonctionnement d'un circuit","accroche":"Là où générateur et récepteur s'accordent.","intro":"Le point de fonctionnement est l'intersection des caractéristiques du générateur et du récepteur.","objectifs":["trouver graphiquement le point","appliquer la loi de Pouillet","exploiter la caractéristique d'une diode"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>point de fonctionnement</strong> d'un circuit est le point (I ; U) commun aux caractéristiques du générateur et du récepteur.</div>"},{"t":"Loi de Pouillet","html":"<p class='formule'>I = (E − E') / (R + r + r')</p><p>E = 12 V, r = 2 Ω, résistor R = 10 Ω : I = 1 A et U = 10 V.</p>","labo":{"type":"fonctionnement","e":12,"r":2,"rc":10}},{"t":"Diode","html":"<p>Avec une diode de seuil 0,6 V en série avec R : I = (E − 0,6)/(R + r) si E > 0,6 V.</p>","retenir":"Pouillet : courant d'un circuit série."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le point de fonctionnement d'un circuit est :</p><ol type='a'><li>le point où la tension aux bornes du générateur est maximale et l'intensité nulle</li><li>le zéro du voltmètre</li><li>le milieu du circuit</li><li>l'intersection des caractéristiques du générateur et du récepteur</li></ol><details><summary>Voir la réponse</summary><p><strong>l'intersection des caractéristiques du générateur et du récepteur</strong>. Il donne U et I réellement obtenus.</p></details><p><strong>Application directe des savoirs.</strong></p><p>E = 9 V, r = 1 Ω, R = 8 Ω : I ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 1 A.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Une batterie (E = 12 V, r = 0,5 Ω) alimente en série un moteur (E' = 8 V, r' = 1,5 Ω) et un rhéostat de 2 Ω, dans un atelier de Limbé.</p><p><strong>Consigne 1.</strong> Calcule l'intensité du courant.</p><p><strong>Consigne 2.</strong> Calcule la tension aux bornes de la batterie et du moteur.</p><details><summary>Voir une réponse attendue</summary><p>I = (12 − 8)/(0,5 + 1,5 + 2) = 1 A. U(batterie) = 12 − 0,5 = 11,5 V ; U(moteur) = 8 + 1,5 = 9,5 V.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Intersection.","Pouillet.","Diode."],"exo":"<p>E = 9 V, r = 1 Ω, R = 8 Ω : I ? <em>(Réponse : 1 A.)</em></p>","quiz":[{"q":"Le point de fonctionnement d'un circuit est :","r":["le point où la tension aux bornes du générateur est maximale et l'intensité nulle","le zéro du voltmètre","le milieu du circuit","l'intersection des caractéristiques du générateur et du récepteur"],"b":3,"e":"Il donne U et I réellement obtenus."},{"q":"Générateur E = 12 V, r = 2 Ω et résistor R = 4 Ω : l'intensité vaut :","r":["2 A","3 A","6 A","1 A"],"b":0,"e":"I = E / (R + r) = 12 / 6."},{"q":"Dans ce circuit, la tension aux bornes du résistor vaut :","r":["12 V","8 V","4 V","6 V"],"b":1,"e":"U = R I = 4 × 2."},{"q":"La loi de Pouillet pour un circuit simple s'écrit :","r":["I = (E + E') / (R + r + r')","I = E + E'","I = (E − E') / (R + r + r')","I = R / E"],"b":2,"e":"Somme des f.é.m. moins f.c.é.m. sur la résistance totale."},{"q":"Générateur 12 V (r = 1 Ω) et moteur E' = 6 V, r' = 2 Ω : I =","r":["6 A","4 A","1 A","2 A"],"b":3,"e":"Loi de Pouillet : I = (12 − 6) / (1 + 2) = 2 A."},{"q":"La caractéristique d'un résistor est :","r":["une droite passant par l'origine","une droite décroissante ne passant pas par l'origine","une courbe en cloche","horizontale"],"b":0,"e":"U = R I : c'est une droite passant par l'origine, de pente R."},{"q":"Graphiquement, le point de fonctionnement se lit :","r":["à l'origine des axes, où U et I sont nuls","à l'intersection des deux courbes U = f(I)","sur l'axe des tensions seulement","nulle part"],"b":1,"e":"Méthode graphique."},{"q":"Si la résistance du récepteur augmente, l'intensité :","r":["augmente","reste constante","diminue","devient infinie"],"b":2,"e":"Le dénominateur augmente."},{"q":"La puissance maximale transférée à un résistor est obtenue quand :","r":["R = 0","R est infinie","R = 2r","R = r"],"b":3,"e":"Adaptation d'impédance."},{"q":"Le point de fonctionnement d'une lampe alimentée par une pile détermine :","r":["sa luminosité réelle","sa couleur","sa masse","sa durée de vie seulement"],"b":0,"e":"Il fixe la puissance reçue."}],"c":"1re D","m":"physique","rang":20,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de chantier à Edéa, de résistance 10 Ω, est branchée sur une batterie de 12 V et 2 Ω.","tache":"Détermine le point de fonctionnement."},"gratuit":true});
VRT_L("1re-d-physique-r21",{"duree":20,"titre":"Champ magnétique et flux magnétique","accroche":"Compter les lignes de champ qui traversent une bobine.","intro":"Le flux magnétique mesure la quantité de champ qui traverse une surface.","objectifs":["décrire un champ magnétique","calculer le champ d'un solénoïde","calculer un flux"],"parties":[{"t":"Champ magnétique","html":"<div class='def'><b>Définition</b>Le <strong>champ magnétique</strong> B⃗ se mesure en teslas (T) au teslamètre. Dans un solénoïde long : B = μ₀NI/L, μ₀ = 4π × 10⁻⁷ SI.</div>"},{"t":"Flux","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":21,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un électricien de Douala étudie une bobine de 100 spires de 50 cm² placée dans un champ de 0,2 T.","tache":"Calcule le flux maximal."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r22",{"duree":20,"titre":"Induction et auto-induction","accroche":"Un flux qui varie crée une tension.","intro":"Toute variation de flux à travers un circuit y fait naître une force électromotrice induite.","objectifs":["énoncer la loi de Faraday","appliquer la loi de Lenz","décrire l'auto-induction"],"parties":[{"t":"Loi de Faraday","html":"<div class='def'><b>Définition</b>Une variation de flux crée une <strong>f.é.m. induite</strong> e = −ΔΦ/Δt. Le courant induit s'oppose, par ses effets, à la cause qui lui donne naissance (<strong>loi de Lenz</strong>).</div>"},{"t":"Exemple","verrou":true},{"t":"Auto-induction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":22,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Une lampe de vélo d'un élève de Bamenda s'allume grâce à une dynamo.","tache":"Explique l'origine du courant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r23",{"duree":20,"titre":"Les générateurs électromagnétiques","accroche":"De Song Loulou à la dynamo de vélo.","intro":"L'alternateur transforme une énergie mécanique de rotation en énergie électrique alternative.","objectifs":["décrire un alternateur","relier fréquence et vitesse de rotation","citer des exemples"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>Un <strong>alternateur</strong> comprend un rotor (aimant ou électroaimant) qui tourne devant un stator (bobines). La variation de flux crée une tension alternative.</div>"},{"t":"Fréquence","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":23,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un groupe électrogène d'un quartier de Bertoua doit fournir du 50 Hz avec un alternateur à 2 paires de pôles.","tache":"À quelle vitesse le moteur doit-il tourner ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-physique-r24",{"duree":20,"titre":"Énergie, puissance et rendement électriques","accroche":"Toute l'énergie n'arrive pas à destination.","intro":"Dans une chaîne énergétique, chaque convertisseur perd une partie de l'énergie, surtout en chaleur.","objectifs":["faire le bilan d'un générateur","faire le bilan d'un récepteur","calculer le rendement d'une chaîne"],"parties":[{"t":"Générateur","html":"<div class='def'><b>Définition</b>Un générateur fournit la puissance totale EI, en perd rI² par effet Joule et délivre UI. Son <strong>rendement</strong> vaut ρ = UI/EI = U/E.</div>"},{"t":"Récepteur","verrou":true},{"t":"Chaîne énergétique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"physique","rang":24,"apc":{"module":"Électricité et électromagnétisme","famille":"Utilisation rationnelle de l'énergie électrique","agir":"Exploiter des générateurs et des récepteurs avec un bon rendement","situation":"Un kit solaire d'une école de Kousseri alimente une pompe : batterie de rendement 83 %, moteur de rendement 86 %.","tache":"Calcule le rendement global et propose une amélioration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r01",{"duree":20,"titre":"Cellules animale et végétale au microscope optique","accroche":"Deux cellules, des points communs et des différences.","intro":"La cellule est l'unité de base du vivant ; le microscope optique révèle son organisation.","objectifs":["décrire les deux types de cellules","les comparer","calculer une taille réelle"],"parties":[{"t":"La cellule","html":"<div class='def'><b>Définition</b>La <strong>cellule</strong> est l'unité structurale et fonctionnelle du vivant : une membrane plasmique, un cytoplasme et un noyau.</div>"},{"t":"Comparaison","html":"<p>La cellule végétale possède en plus une paroi pectocellulosique, une grande vacuole et, dans les parties vertes, des chloroplastes.</p>","retenir":"Paroi, vacuole, chloroplastes : cellule végétale.","labo":{"type":"osmose","c":9,"veg":true}},{"t":"Taille réelle","html":"<p class='formule'>taille réelle = taille sur l'image / grossissement</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Au microscope optique, la cellule végétale se distingue de la cellule animale par :</p><ol type='a'><li>un noyau central et une membrane plasmique</li><li>une paroi pectocellulosique et une grande vacuole</li><li>des mitochondries et un appareil de Golgi</li><li>un cytoplasme granuleux et de petites vacuoles</li></ol><details><summary>Voir la réponse</summary><p><strong>une paroi pectocellulosique et une grande vacuole</strong>. Noyau, membrane et cytoplasme existent dans les deux cellules ; la paroi et la grande vacuole sont propres au végétal.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Image de 15 mm au grossissement × 600 : taille réelle ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 25 µm.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Exploiter les connaissances sur la cellule et les gènes pour améliorer la production.</p><p><strong>Situation.</strong> Au laboratoire d'un lycée de Bafia, un élève observe au grossissement × 400 deux préparations : la première montre des cellules polygonales jointives, avec une grande vacuole ; la seconde des cellules arrondies, isolées, sans paroi. Sur la photo, une cellule mesure 16 mm.</p><p><strong>Consigne 1.</strong> Identifie l'origine de chaque préparation et justifie.</p><p><strong>Consigne 2.</strong> Calcule la taille réelle de la cellule photographiée.</p><details><summary>Voir une réponse attendue</summary><p>La première est végétale (paroi, grande vacuole, cellules jointives), par exemple l'épiderme d'oignon ; la seconde animale, par exemple la muqueuse buccale. Taille réelle : 16 mm/400 = 0,04 mm = 40 µm.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Membrane, cytoplasme, noyau.","Spécificités végétales."],"exo":"<p>Image de 15 mm au grossissement × 600 : taille réelle ? <em>(Réponse : 25 µm.)</em></p>","quiz":[{"q":"Au microscope optique, la cellule végétale se distingue de la cellule animale par :","r":["un noyau central et une membrane plasmique","une paroi pectocellulosique et une grande vacuole","des mitochondries et un appareil de Golgi","un cytoplasme granuleux et de petites vacuoles"],"b":1,"e":"Noyau, membrane et cytoplasme existent dans les deux cellules ; la paroi et la grande vacuole sont propres au végétal."},{"q":"Les chloroplastes se trouvent :","r":["dans toutes les cellules animales et végétales","dans le noyau des cellules de la racine","dans les cellules chlorophylliennes des végétaux","dans les globules rouges des mammifères"],"b":2,"e":"Ils contiennent la chlorophylle et réalisent la photosynthèse."},{"q":"Le grossissement d'un microscope muni d'un objectif ×40 et d'un oculaire ×10 est :","r":["×50","×4","×4 000","×400"],"b":3,"e":"Le grossissement total est le produit des deux : 40 × 10 = 400."},{"q":"Pour colorer le noyau d'une cellule d'épiderme d'oignon, on utilise :","r":["le vert de méthyle acétique ou le bleu de méthylène","l'eau iodée, qui colore le noyau en violet","l'eau de chaux, qui fait apparaître le noyau","la liqueur de Fehling, qui colore le noyau en rouge"],"b":0,"e":"Ces colorants se fixent sur l'ADN du noyau et le rendent visible."},{"q":"La cellule est :","r":["le plus petit organe, formé de plusieurs tissus","l'unité structurale et fonctionnelle des êtres vivants","un ensemble de tissus aux fonctions voisines","la molécule d'ADN qui porte l'information héréditaire de l'individu"],"b":1,"e":"Tout être vivant est formé d'une ou de plusieurs cellules."},{"q":"Une cellule de la muqueuse buccale est :","r":["une cellule végétale","une cellule à chloroplastes","une cellule animale sans paroi","une bactérie"],"b":2,"e":"On la prélève en grattant l'intérieur de la joue ; elle n'a pas de paroi."},{"q":"La membrane plasmique :","r":["fabrique la chlorophylle de la cellule","renferme l'ADN et dirige la cellule","est rigide et donne sa forme à la cellule animale","limite la cellule et contrôle les échanges"],"b":3,"e":"Elle est fine et souple et règle les entrées et sorties de substances."},{"q":"Le pouvoir séparateur du microscope optique est d'environ :","r":["0,2 µm","0,2 nm","2 mm","2 cm"],"b":0,"e":"Deux points plus proches que 0,2 µm ne sont pas distingués : les organites fins restent invisibles."},{"q":"Une cellule végétale placée dans l'eau salée concentrée :","r":["éclate parce que l'eau y entre en grande quantité","se plasmolyse, sa vacuole perd de l'eau","grossit, sa vacuole se remplit d'eau salée","ne change pas, grâce à sa paroi rigide"],"b":1,"e":"L'eau sort de la vacuole vers le milieu plus concentré par osmose."},{"q":"Le cytoplasme est :","r":["la paroi rigide qui entoure la cellule","le contenu du noyau, autour des chromosomes","le milieu situé entre la membrane et le noyau","un organite entouré d'une double membrane"],"b":2,"e":"Il contient les organites baignant dans le hyaloplasme."}],"c":"1re D","m":"svt","rang":1,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Au laboratoire d'un lycée de Bafia, un élève compare une cellule d'épiderme d'oignon et une cellule de sa muqueuse buccale.","tache":"Présente trois différences."},"gratuit":true});
VRT_L("1re-d-svt-r02",{"duree":20,"titre":"TP 1 : préparations microscopiques","accroche":"De l'oignon et la joue sous l'objectif.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Réaliser une <strong>préparation microscopique</strong> : un échantillon mince entre lame et lamelle, éventuellement coloré, pour l'observer au microscope.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":2,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Le professeur d'un lycée de Mbouda demande un compte rendu de la préparation d'épiderme d'oignon.","tache":"Rédige le protocole en quatre étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r03",{"duree":20,"titre":"Ultrastructure et rôles des organites","accroche":"Au microscope électronique, la cellule est une usine.","intro":"Le microscope électronique révèle les organites et leurs fonctions.","objectifs":["identifier les organites","associer organite et fonction","relier structure et fonction"],"parties":[{"t":"Les organites","html":"<div class='def'><b>Définition</b>Un <strong>organite</strong> est une structure cellulaire spécialisée : noyau, mitochondrie, chloroplaste, réticulum endoplasmique, appareil de Golgi, ribosome, vacuole, lysosome.</div>"},{"t":"Fonctions","verrou":true},{"t":"Reconnaître","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":3,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un médecin de Garoua compare deux cellules d'un patient au microscope électronique : une cellule du pancréas, riche en réticulum endoplasmique granuleux et en appareils de Golgi, et une cellule de graisse, qui en a très peu.","tache":"Que peux-tu déduire de l'activité de la cellule du pancréas ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r04",{"duree":20,"titre":"TP 2 : électronographies des organites","accroche":"Reconnaître un organite à sa silhouette.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Une <strong>électronographie</strong> est une image obtenue au microscope électronique ; elle montre l'ultrastructure.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":4,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un élève de Bamenda doit légender une électronographie de cellule de feuille.","tache":"Donne trois critères pour reconnaître le chloroplaste."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r05",{"duree":20,"titre":"Structure et composition d'un chromosome","accroche":"De l'ADN enroulé autour de protéines.","intro":"Les chromosomes portent l'information génétique ; ils se condensent pendant la division.","objectifs":["décrire un chromosome","donner sa composition","lire un caryotype"],"parties":[{"t":"Composition","html":"<div class='def'><b>Définition</b>Un <strong>chromosome</strong> est formé d'<strong>ADN</strong> associé à des protéines (histones). Hors division, il forme la chromatine dispersée.</div>"},{"t":"Structure","verrou":true},{"t":"Caryotype","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":5,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un enfant de Yaoundé présente des signes évocateurs de trisomie 21 ; le laboratoire photographie ses chromosomes et compte 47 chromosomes, dont trois chromosomes de la paire 21.","tache":"Explique ce que montre le caryotype et l'origine possible de l'anomalie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r06",{"duree":20,"titre":"L'ADN, support de l'information génétique","accroche":"Une expérience sur des bactéries l'a prouvé.","intro":"Des expériences de transformation bactérienne ont montré que l'ADN porte l'information héréditaire.","objectifs":["décrire l'expérience de Griffith","interpréter Avery","décrire la molécule d'ADN"],"parties":[{"t":"Les expériences","html":"<div class='def'><b>Définition</b>La <strong>transformation bactérienne</strong> est l'acquisition d'un caractère héréditaire par une bactérie à partir de l'ADN d'une autre bactérie.</div>"},{"t":"Griffith et Avery","verrou":true},{"t":"La molécule","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":6,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Lors d'une conférence au lycée de Garoua, un élève demande comment on sait que l'ADN porte les gènes.","tache":"Résume l'argument expérimental."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r07",{"duree":20,"titre":"TP 3 : maquette de l'ADN","accroche":"Des capsules et des pailles.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Une <strong>maquette</strong> est un modèle concret qui représente la structure d'une molécule.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":7,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un club scientifique de Kribi prépare une maquette d'ADN pour la journée portes ouvertes.","tache":"Donne les règles à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r08",{"duree":20,"titre":"La division cellulaire : la mitose","accroche":"Une cellule devient deux cellules identiques.","intro":"La mitose répartit équitablement les chromosomes entre deux cellules filles.","objectifs":["décrire les phases","reconnaître une phase sur un document","expliquer la conservation de l'information"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>mitose</strong> est la division d'une cellule en deux cellules filles génétiquement identiques entre elles et à la cellule mère.</div>"},{"t":"Les phases","verrou":true},{"t":"Conservation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":8,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une élève de Dschang observe la pointe d'une racine d'oignon au microscope : sur 200 cellules comptées à 1 mm de la pointe, 40 sont en division ; à 1 cm de la pointe, aucune.","tache":"Explique cette différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r09",{"duree":20,"titre":"TP 4 : observation des cellules en division","accroche":"Les mitoses de la pointe de racine.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Observer les <strong>phases de la mitose</strong> sur des cellules en division, réelles ou en images.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":9,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"En TP à Limbé, un groupe ne voit aucune cellule en division sur sa préparation.","tache":"Propose deux explications."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r10",{"duree":20,"titre":"Cycle cellulaire et rôles de la mitose","accroche":"Doubler l'ADN, puis le partager.","intro":"Entre deux mitoses, la cellule réplique son ADN pendant l'interphase.","objectifs":["décrire le cycle cellulaire","interpréter une courbe de quantité d'ADN","citer les rôles de la mitose"],"parties":[{"t":"Le cycle","html":"<div class='def'><b>Définition</b>Le <strong>cycle cellulaire</strong> comprend l'interphase (G1, S, G2) et la mitose. La quantité d'ADN double pendant la phase S.</div>"},{"t":"Courbe","verrou":true},{"t":"Rôles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":10,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un agriculteur de Bertoua multiplie son manioc par boutures et obtient des plants identiques.","tache":"Explique cette ressemblance."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r11",{"duree":20,"titre":"Intégration : multiplier une variété performante","accroche":"Cloner pour conserver.","intro":"Un producteur veut multiplier une variété sans perdre ses qualités.","objectifs":["mobiliser la mitose","argumenter","proposer une technique"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>multiplication végétative</strong> produit des individus génétiquement identiques grâce à la mitose.</div>"},{"t":"Démarche","verrou":true},{"t":"Production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":11,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une coopérative de Mbalmayo possède un plant de manioc très productif et résistant à la mosaïque.","tache":"Propose comment le multiplier sans perdre ses qualités."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r12",{"duree":20,"titre":"Le renouvellement permanent des molécules","accroche":"Nos protéines se refont sans cesse.","intro":"Les molécules de la cellule sont constamment détruites et resynthétisées.","objectifs":["définir le renouvellement moléculaire","interpréter une expérience de marquage","citer les molécules organiques"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>renouvellement moléculaire</strong> est la destruction et la synthèse permanentes des molécules de la cellule : glucides, lipides, protides, acides nucléiques.</div>"},{"t":"Marquage","verrou":true},{"t":"Intérêt","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":12,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une infirmière de Ngaoundéré explique qu'un enfant mal nourri cicatrise lentement.","tache":"Relie cette observation au renouvellement moléculaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r13",{"duree":20,"titre":"TP 5 : tests des molécules organiques","accroche":"Eau iodée, Fehling, biuret.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Des <strong>réactifs</strong> mettent en évidence les molécules organiques des aliments et des cellules.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":13,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une ménagère de Bafoussam veut savoir si sa pâte d'arachide contient surtout des lipides.","tache":"Propose un test simple."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r14",{"duree":20,"titre":"Biosynthèse des protéines : la transcription","accroche":"Copier un gène en ARN messager.","intro":"La transcription produit dans le noyau une copie d'un gène : l'ARN messager.","objectifs":["définir la transcription","décrire son mécanisme","écrire un ARNm"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>transcription</strong> est la synthèse d'un ARN messager à partir d'un brin d'ADN, dans le noyau, par l'ARN polymérase.</div>"},{"t":"Complémentarité","verrou":true},{"t":"Sortie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":14,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Pour une maquette au lycée de Kumba, un élève doit transcrire le brin TACGGATTC.","tache":"Écris l'ARNm correspondant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r15",{"duree":20,"titre":"TP 6 : maquettes de la transcription et de l'ARNm","accroche":"Construire un ARN avec du carton.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Modéliser la <strong>transcription</strong> en fabriquant un ARNm complémentaire d'un brin d'ADN.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":15,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Au club SVT d'un lycée de Bertoua, un élève fabrique l'ARNm de la séquence d'ADN 3'-TAC GGA TTC-5' et écrit 5'-ATG CCT AAG-3'.","tache":"Corrige l'ARNm et explique son erreur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r16",{"duree":20,"titre":"Biosynthèse des protéines : la traduction","accroche":"Lire l'ARN trois lettres à la fois.","intro":"Au niveau des ribosomes, la séquence de l'ARNm est traduite en une chaîne d'acides aminés.","objectifs":["définir codon et anticodon","utiliser le code génétique","décrire les étapes"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>traduction</strong> est la synthèse d'une protéine à partir de l'ARNm, au niveau des ribosomes, grâce aux ARN de transfert.</div>"},{"t":"Le code génétique","verrou":true},{"t":"Les étapes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":16,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un laboratoire de Yaoundé séquence l'ARNm d'une protéine anormale : 5'-AUG GUG CAC UAA-3'. Code génétique : AUG = Met ; GUG = Val ; CAC = His ; UAA = stop.","tache":"Trouve la séquence de la protéine et explique la méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r17",{"duree":20,"titre":"TP 7 : maquette de la traduction","accroche":"Un ribosome en carton.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Modéliser la <strong>traduction</strong> : ribosome, ARNm, ARNt et chaîne d'acides aminés.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":17,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un élève de Garoua lit l'ARNm 5'-AUG UUU UAA GGC-3' et s'arrête au codon UAA ; son camarade dit qu'il faut lire GGC aussi.","tache":"Qui a raison ? Donne le peptide obtenu."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r18",{"duree":20,"titre":"Le devenir des protéines synthétisées","accroche":"Du ribosome à l'extérieur de la cellule.","intro":"Les protéines sécrétées suivent un trajet précis dans la cellule.","objectifs":["décrire le trajet des protéines sécrétées","citer des exemples","interpréter une expérience de marquage"],"parties":[{"t":"Le trajet","html":"<div class='def'><b>Définition</b>Les <strong>protéines sécrétées</strong> passent du réticulum endoplasmique granuleux à l'appareil de Golgi, puis sont libérées par exocytose.</div>"},{"t":"Exemples","verrou":true},{"t":"Marquage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":18,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"On injecte des acides aminés radioactifs à des cellules du pancréas, puis on mesure la radioactivité : à 3 min, 80 % dans le réticulum endoplasmique granuleux ; à 20 min, 70 % dans le Golgi ; à 2 h, 85 % dans les vésicules de sécrétion.","tache":"Interprète ce trajet."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r19",{"duree":20,"titre":"Intégration : du gène à la maladie","accroche":"La drépanocytose expliquée par la biosynthèse.","intro":"Une mutation modifie l'ARNm, puis la protéine, puis le caractère.","objectifs":["mobiliser transcription et traduction","expliquer une maladie génétique","sensibiliser"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>mutation</strong> d'un gène peut changer un codon, donc un acide aminé, donc la forme et la fonction de la protéine.</div>"},{"t":"La drépanocytose","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":19,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une association de Douala organise une journée de dépistage de la drépanocytose.","tache":"Rédige un texte d'information expliquant le lien entre gène et maladie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r20",{"duree":20,"titre":"Génie génétique : les plantes transgéniques","accroche":"Un gène venu d'ailleurs.","intro":"Le génie génétique transfère un gène d'un organisme à un autre pour lui donner un caractère nouveau.","objectifs":["définir un OGM","citer des caractéristiques","discuter des enjeux"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>organisme génétiquement modifié</strong> (OGM) a reçu un gène étranger, le <strong>transgène</strong>, qui lui confère un caractère nouveau.</div>"},{"t":"Exemples","verrou":true},{"t":"Enjeux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":20,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Dans un débat à la radio de Maroua, des cultivateurs discutent d'un coton résistant aux insectes.","tache":"Présente un avantage et une précaution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r21",{"duree":20,"titre":"Génie génétique : obtenir une plante transgénique","accroche":"Une bactérie comme taxi.","intro":"Une bactérie du sol, Agrobacterium, sert de vecteur pour introduire un gène dans une plante.","objectifs":["citer les outils","décrire les étapes","expliquer le rôle du vecteur"],"parties":[{"t":"Les outils","html":"<div class='def'><b>Définition</b>Les <strong>enzymes de restriction</strong> coupent l'ADN à des sites précis ; la <strong>ligase</strong> recolle les fragments ; le <strong>plasmide Ti</strong> d'Agrobacterium sert de vecteur.</div>"},{"t":"Les étapes","verrou":true},{"t":"Contrôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":21,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un chercheur d'un institut agronomique de Yaoundé veut introduire un gène de résistance dans une variété de cacaoyer.","tache":"Présente les étapes de la technique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r22",{"duree":20,"titre":"TP 8 : technique d'obtention des plantes transgéniques (virtuel)","accroche":"Une simulation en laboratoire.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Reproduire sur logiciel ou sur schéma les <strong>étapes du transfert de gène</strong> chez une plante.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":22,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un groupe de Bafoussam présente sa simulation sans mentionner la sélection.","tache":"Quelle étape manque et pourquoi est-elle utile ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r23",{"duree":20,"titre":"Intégration : un OGM pour nos champs ?","accroche":"Débattre avec des arguments scientifiques.","intro":"Le génie génétique soulève des espoirs et des inquiétudes : il faut argumenter.","objectifs":["présenter la technique","peser avantages et risques","proposer une position argumentée"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>biosécurité</strong> regroupe les règles qui encadrent l'utilisation des OGM pour protéger la santé et l'environnement.</div>"},{"t":"Arguments","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":23,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un groupement paysan de l'Extrême-Nord hésite à adopter un coton transgénique.","tache":"Rédige un texte argumenté pour l'éclairer."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r24",{"duree":20,"titre":"Équipement enzymatique et réactions cellulaires","accroche":"Chaque réaction a son enzyme.","intro":"Les réactions chimiques de la cellule sont catalysées par des enzymes spécifiques.","objectifs":["définir une enzyme","relier équipement enzymatique et métabolisme","expliquer une intolérance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>enzyme</strong> est une protéine qui accélère une réaction chimique sans être consommée : c'est un <strong>biocatalyseur</strong>.</div>"},{"t":"Équipement enzymatique","verrou":true},{"t":"Déficit","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":24,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un élève de Bamenda a des ballonnements chaque fois qu'il boit du lait.","tache":"Propose une explication."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r25",{"duree":20,"titre":"Caractéristiques de l'activité enzymatique","accroche":"Spécifique, sensible à la chaleur et au pH.","intro":"L'activité d'une enzyme dépend du substrat, de la température et du pH.","objectifs":["définir la spécificité","décrire l'effet de la température","décrire l'effet du pH"],"parties":[{"t":"Spécificité","html":"<div class='def'><b>Définition</b>Une enzyme a une <strong>double spécificité</strong> : de substrat (elle reconnaît une molécule) et d'action (elle catalyse une réaction précise).</div>"},{"t":"Température","verrou":true},{"t":"pH","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":25,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une vendeuse de Kumba garde ses fruits au réfrigérateur pour qu'ils mûrissent moins vite.","tache":"Explique le principe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r26",{"duree":20,"titre":"TP 9 : mettre en évidence la catalyse enzymatique","accroche":"L'amylase de la salive digère l'amidon.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Montrer l'<strong>action de l'amylase salivaire</strong> sur l'empois d'amidon et l'influence de la température.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":26,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Un groupe de Garoua ne met pas de tube témoin.","tache":"Pourquoi est-ce une erreur ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r27",{"duree":20,"titre":"Structure et fonction des protéines enzymatiques","accroche":"La forme fait la fonction.","intro":"L'activité d'une enzyme dépend de sa forme dans l'espace, en particulier de son site actif.","objectifs":["définir le site actif","décrire le complexe enzyme-substrat","expliquer la dénaturation"],"parties":[{"t":"Site actif","html":"<div class='def'><b>Définition</b>Le <strong>site actif</strong> est la région de l'enzyme où se fixe le substrat ; sa forme est complémentaire de celle du substrat.</div>"},{"t":"Complexe","verrou":true},{"t":"Dénaturation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":27,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une ménagère de Douala attendrit sa viande avec des feuilles de papayer.","tache":"Explique ce procédé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r28",{"duree":20,"titre":"TP 10 : maquette du complexe enzyme-substrat","accroche":"Une clé et sa serrure.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et schématiser","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Construire un <strong>modèle</strong> montrant la complémentarité entre site actif et substrat.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":28,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Au lycée de Mbalmayo, un élève explique la spécificité enzymatique avec une maquette.","tache":"Décris ce que la maquette doit montrer."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r29",{"duree":20,"titre":"Applications de la catalyse enzymatique dans l'agroalimentaire","accroche":"Pain, bière, fromage, jus.","intro":"Les enzymes et les micro-organismes transforment les aliments.","objectifs":["citer des applications","expliquer leur principe","respecter l'hygiène"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>biotechnologies alimentaires</strong> utilisent des enzymes ou des micro-organismes pour transformer des matières premières.</div>"},{"t":"Exemples","verrou":true},{"t":"Conditions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":29,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une brasseuse de bil-bil de Maroua fait germer le sorgho avant de préparer sa boisson.","tache":"Explique l'intérêt de la germination."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r30",{"duree":20,"titre":"Intégration : améliorer une production artisanale","accroche":"Des enzymes au service d'une coopérative.","intro":"Une transformation artisanale réussit mieux quand on maîtrise les conditions de l'activité enzymatique.","objectifs":["mobiliser les caractéristiques des enzymes","proposer des améliorations","rédiger un protocole"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>L'activité d'une enzyme est maximale à sa <strong>température et à son pH optimaux</strong> ; la chaleur excessive la détruit.</div>"},{"t":"Démarche","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":30,"apc":{"module":"Identité biologique, code génétique et enzymes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Exploiter les connaissances sur la cellule et les gènes pour améliorer la production","situation":"Une coopérative de Garoua produit du bil-bil de qualité irrégulière.","tache":"Propose un protocole amélioré en quatre étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r31",{"duree":20,"titre":"Évaluer la dépense énergétique","accroche":"Combien d'énergie dépense ton corps ?","intro":"La dépense énergétique se mesure par la chaleur produite ou par le dioxygène consommé.","objectifs":["définir la dépense énergétique","utiliser le coefficient thermique de l'O₂","calculer le quotient respiratoire"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> est la quantité d'énergie utilisée par l'organisme par unité de temps. On l'évalue par <strong>calorimétrie directe</strong> (chaleur) ou <strong>indirecte</strong> (dioxygène consommé).</div>"},{"t":"Calcul","verrou":true},{"t":"Quotient respiratoire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":31,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un entraîneur de Garoua mesure qu'un athlète consomme 120 L de dioxygène en une heure d'effort.","tache":"Calcule sa dépense énergétique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r32",{"duree":20,"titre":"TP 13 : intensité respiratoire d'un mammifère","accroche":"Un respiromètre et une souris.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>L'<strong>intensité respiratoire</strong> est le volume de dioxygène consommé par unité de masse et de temps.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":32,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au laboratoire d'un lycée de Dschang, une souris de 20 g consomme 12 mL d'O₂ en 10 minutes.","tache":"Calcule son intensité respiratoire."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r33",{"duree":20,"titre":"Facteurs de variation de la dépense énergétique","accroche":"Effort, froid, croissance.","intro":"La dépense énergétique varie selon l'activité et l'état de l'organisme.","objectifs":["citer les facteurs","interpréter un tableau","adapter la ration"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>dépense énergétique</strong> totale comprend le métabolisme de base et les dépenses liées à l'activité, à la thermorégulation, à la croissance et à la digestion.</div>"},{"t":"Facteurs","verrou":true},{"t":"Conséquence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":33,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un docker du port de Douala et un employé de bureau mangent la même ration.","tache":"Lequel risque un déficit énergétique ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r34",{"duree":20,"titre":"Le métabolisme de base","accroche":"L'énergie dépensée sans rien faire.","intro":"Même au repos complet, l'organisme dépense de l'énergie pour vivre.","objectifs":["définir le métabolisme de base","connaître les conditions de mesure","citer des valeurs"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>métabolisme de base</strong> est la dépense énergétique minimale d'un sujet au repos, à jeun depuis 12 h, à la neutralité thermique et éveillé.</div>"},{"t":"Valeurs","verrou":true},{"t":"Utilité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":34,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un médecin de Yaoundé mesure le métabolisme de base d'un patient soupçonné de trouble thyroïdien.","tache":"Indique les conditions de mesure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r35",{"duree":20,"titre":"Les apports énergétiques des repas","accroche":"17, 38, 17 : les nombres de l'énergie.","intro":"L'énergie des aliments se calcule à partir de leur composition en nutriments.","objectifs":["connaître les valeurs énergétiques","calculer l'apport d'un repas","comparer apport et dépense"],"parties":[{"t":"Valeurs","html":"<div class='def'><b>Définition</b>La <strong>valeur énergétique</strong> d'un nutriment est l'énergie libérée par 1 g : glucides 17 kJ/g, lipides 38 kJ/g, protides 17 kJ/g.</div>"},{"t":"Calcul","verrou":true},{"t":"Équilibre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":35,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un élève de Limbé mange au déjeuner 150 g de riz cuit (40 g de glucides), 20 g d'huile et 30 g de poisson (protides).","tache":"Calcule l'énergie apportée."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r36",{"duree":20,"titre":"Dépenses énergétiques de la respiration","accroche":"Brûler le glucose avec le dioxygène.","intro":"La respiration cellulaire oxyde complètement le glucose et libère beaucoup d'énergie.","objectifs":["écrire l'équation de la respiration","relier énergie et ATP","citer les conditions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>respiration cellulaire</strong> est l'oxydation complète des métabolites (glucose) en présence de dioxygène : C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + énergie.</div>"},{"t":"Énergie","verrou":true},{"t":"ATP","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":36,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un footballeur de Bamenda mesure sa respiration : 15 cycles par minute au repos avec 0,5 L par cycle ; 40 cycles par minute pendant un sprint avec 2 L par cycle.","tache":"Calcule le débit ventilatoire dans les deux cas et explique son augmentation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r37",{"duree":20,"titre":"TP 14 : mise en évidence de la respiration","accroche":"L'eau de chaux se trouble.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Montrer qu'un être vivant <strong>consomme du dioxygène</strong> et <strong>rejette du dioxyde de carbone</strong>.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":37,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au lycée de Mbalmayo, un groupe oublie le bocal témoin.","tache":"Pourquoi le résultat est-il discutable ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r38",{"duree":20,"titre":"Mécanisme et localisation de la respiration","accroche":"Du cytoplasme à la mitochondrie.","intro":"La respiration se déroule en trois grandes étapes dans deux compartiments de la cellule.","objectifs":["décrire la glycolyse","décrire le cycle de Krebs","localiser la chaîne respiratoire"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La respiration comprend la <strong>glycolyse</strong> (cytoplasme : glucose → 2 pyruvates + 2 ATP), le <strong>cycle de Krebs</strong> (matrice mitochondriale : CO₂ libéré) et la <strong>chaîne respiratoire</strong> (membrane interne : O₂ consommé, ATP produit).</div>"},{"t":"Localisation","verrou":true},{"t":"Bilan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":38,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au laboratoire, on isole des mitochondries de foie de bœuf et on mesure le dioxygène consommé en 10 minutes : sans substrat, 0 µmol ; avec du glucose, 0 µmol ; avec du pyruvate, 12 µmol. Un élève pense que les mitochondries « brûlent » directement le glucose.","tache":"Analyse ces résultats et réponds à l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r39",{"duree":20,"titre":"Dépenses énergétiques de la fermentation","accroche":"Sans dioxygène, un peu d'énergie quand même.","intro":"La fermentation dégrade incomplètement le glucose en l'absence de dioxygène.","objectifs":["écrire la fermentation alcoolique","comparer l'énergie libérée","citer les produits"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>fermentation</strong> est une dégradation incomplète du glucose sans dioxygène. Alcoolique : C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ + énergie.</div>"},{"t":"Énergie","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":39,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Une productrice de vin de palme de Bandjoun constate que la sève mousse et devient alcoolisée en quelques heures.","tache":"Explique ce phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r40",{"duree":20,"titre":"TP 15 : mise en évidence des fermentations","accroche":"Mousse, odeur d'alcool, goût de vinaigre.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Mettre en évidence les <strong>fermentations alcoolique et acétique</strong> et leurs produits.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":40,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au club scientifique de Bafang, l'eau de chaux ne se trouble pas.","tache":"Propose deux causes possibles."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r41",{"duree":20,"titre":"TP : boissons fermentées, vinaigre et biogaz","accroche":"Trois productions locales.","intro":"Cette séance de travaux pratiques met en œuvre la démarche expérimentale : protocole, observation, interprétation et compte rendu.","objectifs":["suivre un protocole","observer et mesurer","interpréter un résultat"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Réaliser des <strong>productions utiles</strong> grâce aux fermentations : boisson, vinaigre, biogaz.</div>"},{"t":"Matériel et protocole","verrou":true},{"t":"Observation et sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":41,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un éleveur de porcs de Mbouda veut valoriser le lisier de sa porcherie.","tache":"Propose une production et son principe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r42",{"duree":20,"titre":"Mécanismes et localisation de la fermentation","accroche":"Tout se passe dans le cytoplasme.","intro":"La fermentation commence comme la respiration, par la glycolyse, mais s'arrête dans le cytoplasme.","objectifs":["décrire les étapes","localiser la fermentation","comparer les types de fermentation"],"parties":[{"t":"Mécanisme","html":"<div class='def'><b>Définition</b>La <strong>fermentation</strong> comprend la glycolyse (glucose → 2 pyruvates + 2 ATP), puis la transformation du pyruvate en éthanol et CO₂ (alcoolique) ou en lactate (lactique), dans le <strong>cytoplasme</strong>.</div>"},{"t":"Rôle de la seconde étape","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":42,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Une fabricante de yaourts de Ngaoundéré ensemence le lait avec des bactéries lactiques.","tache":"Explique la transformation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r43",{"duree":20,"titre":"Comparer respiration et fermentation","accroche":"38 contre 2.","intro":"Respiration et fermentation diffèrent par leurs conditions, leurs produits et leur rendement.","objectifs":["comparer les deux voies","calculer les rendements","expliquer la différence"],"parties":[{"t":"Comparaison","html":"<div class='def'><b>Définition</b>La <strong>respiration</strong> est une oxydation complète en présence d'O₂ (38 ATP, rendement environ 40 %) ; la <strong>fermentation</strong> est une dégradation incomplète sans O₂ (2 ATP, rendement environ 2 %).</div>"},{"t":"Explication","verrou":true},{"t":"Conséquence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":43,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un boulanger de Yaoundé laisse sa pâte lever dans un récipient fermé.","tache":"Explique pourquoi la pâte gonfle et pourquoi elle ne s'arrête pas aussitôt."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r44",{"duree":20,"titre":"Intégration : jus de canne et bâton de manioc","accroche":"Un sujet du Probatoire 2026.","intro":"Une unité locale veut comprendre pourquoi le jus de canne fermente plus vite que le manioc non traité.","objectifs":["mobiliser fermentation et digestion des glucides","proposer des améliorations","rédiger un protocole"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Les levures fermentent directement les sucres simples ; les <strong>sucres complexes</strong> (amidon) doivent d'abord être hydrolysés par des enzymes.</div>"},{"t":"Réponse attendue","verrou":true},{"t":"Bâton de manioc","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":44,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Une unité locale produit des boissons à base de jus de canne et constate que le manioc non traité fermente beaucoup plus lentement.","tache":"Rédige un texte d'une dizaine de lignes expliquant cette différence et propose deux aménagements."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r45",{"duree":20,"titre":"Le captage de l'énergie lumineuse","accroche":"La chlorophylle absorbe le bleu et le rouge.","intro":"Les pigments chlorophylliens captent la lumière utilisée par la photosynthèse.","objectifs":["citer les pigments","lire un spectre d'absorption","extraire la chlorophylle"],"parties":[{"t":"Pigments","html":"<div class='def'><b>Définition</b>Les <strong>pigments chlorophylliens</strong> (chlorophylles a et b, caroténoïdes), situés dans les thylakoïdes des chloroplastes, absorbent l'énergie lumineuse.</div>"},{"t":"Spectre","verrou":true},{"t":"Extraction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":45,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un maraîcher de Foumbot cultive des légumes sous des filets verts.","tache":"Explique pourquoi un filet vert est un mauvais choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r46",{"duree":20,"titre":"Photosynthèse : la phase chimique","accroche":"Fabriquer du sucre avec le CO₂.","intro":"Dans le stroma, le CO₂ est incorporé dans des molécules organiques.","objectifs":["décrire le cycle de Calvin","localiser la phase chimique","relier aux deux phases"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>phase chimique</strong> (cycle de Calvin), dans le stroma du chloroplaste, fixe le CO₂ sur un accepteur (le ribulose diphosphate) grâce à une enzyme, la RubisCO, et produit des glucides.</div>"},{"t":"Besoins","verrou":true},{"t":"Preuve","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":46,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au laboratoire, on fournit à des algues du CO₂ marqué au carbone 14, à la lumière. Au bout de 10 min, on éteint la lumière et on mesure les composés marqués : un composé à 3 atomes de carbone (APG) augmente, un composé à 5 atomes (RuBP) diminue.","tache":"Explique ces résultats et prévois l'évolution de la fixation du CO₂ à l'obscurité."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r47",{"duree":20,"titre":"Photosynthèse : la phase photochimique","accroche":"La lumière casse l'eau.","intro":"Dans les thylakoïdes, l'énergie lumineuse est convertie en énergie chimique.","objectifs":["décrire la photolyse de l'eau","localiser la phase photochimique","expliquer l'origine de l'O₂"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>phase photochimique</strong>, dans les thylakoïdes, utilise la lumière pour oxyder l'eau (<strong>photolyse</strong>) : elle libère du dioxygène et produit de l'ATP et du NADPH,H⁺.</div>"},{"t":"Origine de l'O₂","verrou":true},{"t":"Lien","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":47,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un élève de Dschang éclaire une plante aquatique (élodée) et voit des bulles se dégager.","tache":"Identifie le gaz et son origine."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r48",{"duree":20,"titre":"Importance de la photosynthèse","accroche":"Toute la nourriture commence par une feuille.","intro":"La photosynthèse fournit la matière organique et le dioxygène dont dépend presque toute la vie.","objectifs":["écrire l'équation globale","expliquer son importance","relier au programme génétique"],"parties":[{"t":"Équation","html":"<div class='def'><b>Définition</b>La <strong>photosynthèse</strong> : 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O, grâce à l'énergie lumineuse captée par la chlorophylle.</div>"},{"t":"Importance","verrou":true},{"t":"Programme génétique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":48,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"La forêt du bassin du Congo, dont une partie couvre l'Est du Cameroun, est menacée par la déforestation.","tache":"Explique son importance pour l'atmosphère."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r49",{"duree":20,"titre":"Intégration : réussir une culture sous serre","accroche":"Lumière, CO₂, eau.","intro":"Un maraîcher veut améliorer le rendement de ses tomates en jouant sur les facteurs de la photosynthèse.","objectifs":["identifier les facteurs limitants","proposer des aménagements","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>facteur limitant</strong> est le facteur qui, en quantité insuffisante, limite l'intensité de la photosynthèse.</div>"},{"t":"Facteurs","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":49,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un maraîcher de Foumbot constate des rendements faibles dans sa serre de tomates mal éclairée et peu aérée.","tache":"Propose des aménagements argumentés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r50",{"duree":20,"titre":"Organisation d'un écosystème","accroche":"Qui mange qui dans la forêt ?","intro":"Un écosystème associe des êtres vivants et leur milieu de vie.","objectifs":["définir écosystème, biotope, biocénose","classer les êtres vivants","construire une chaîne alimentaire"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>écosystème</strong> est formé d'un <strong>biotope</strong> (milieu physique) et d'une <strong>biocénose</strong> (êtres vivants) en interaction.</div>"},{"t":"Niveaux trophiques","verrou":true},{"t":"Chaînes et réseaux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":50,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Au parc national de la Bénoué, des élèves observent herbes, antilopes, lions et vautours.","tache":"Construis une chaîne alimentaire et classe ces êtres vivants."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r51",{"duree":20,"titre":"Flux et dissipation de l'énergie dans un écosystème","accroche":"Seuls 10 % passent au niveau suivant.","intro":"L'énergie traverse l'écosystème en sens unique et se dissipe à chaque niveau.","objectifs":["décrire le flux d'énergie","calculer un rendement écologique","construire une pyramide"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>flux d'énergie</strong> part de la lumière captée par les producteurs et passe d'un niveau trophique à l'autre ; à chaque niveau, une grande partie est <strong>dissipée</strong> en chaleur par la respiration.</div>"},{"t":"Rendement","verrou":true},{"t":"Pyramide","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":51,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un éleveur de l'Adamaoua se demande pourquoi produire de la viande demande beaucoup plus de surface que produire des céréales.","tache":"Explique avec le flux d'énergie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r52",{"duree":20,"titre":"Le cycle naturel du carbone","accroche":"Réservoirs et flux.","intro":"Le carbone circule entre l'atmosphère, les êtres vivants, les océans et les roches.","objectifs":["citer les réservoirs","décrire les flux","construire un schéma du cycle"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cycle du carbone</strong> est la circulation du carbone entre des <strong>réservoirs</strong> : atmosphère (CO₂), biomasse, océans, sols, roches carbonatées et combustibles fossiles.</div>"},{"t":"Flux","verrou":true},{"t":"Équilibre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":52,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Pour un exposé au lycée de Kribi, un élève doit schématiser le cycle du carbone.","tache":"Liste les réservoirs et les flux à représenter."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r53",{"duree":20,"titre":"Les modifications du cycle du carbone par l'Homme","accroche":"Trop de CO₂ dans l'air.","intro":"Les activités humaines libèrent du carbone stocké depuis des millions d'années.","objectifs":["citer les activités en cause","interpréter l'augmentation du CO₂","proposer des solutions"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les activités humaines modifient le <strong>cycle du carbone</strong> en transférant le carbone des réservoirs fossiles et forestiers vers l'atmosphère.</div>"},{"t":"Causes","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":53,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Dans l'Adamaoua, les feux de brousse brûlent chaque année de grandes surfaces.","tache":"Explique leur effet sur le cycle du carbone et propose des mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r54",{"duree":20,"titre":"Le cycle de l'azote","accroche":"Les haricots enrichissent le sol.","intro":"L'azote passe de l'air au sol puis aux êtres vivants grâce à des micro-organismes.","objectifs":["décrire les étapes","expliquer le rôle des légumineuses","raisonner l'usage des engrais"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cycle de l'azote</strong> comprend la fixation de l'azote atmosphérique, la nitrification, l'assimilation par les plantes et la dénitrification.</div>"},{"t":"Fixation","verrou":true},{"t":"Pratique agricole","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":54,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Un cultivateur de la Lékié constate que son maïs pousse mieux après une saison d'arachide.","tache":"Explique cette observation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r55",{"duree":20,"titre":"Intégration : préserver la fertilité et le carbone","accroche":"Jachère, légumineuses, reboisement.","intro":"Une communauté rurale veut nourrir sa population sans épuiser le sol ni détruire la forêt.","objectifs":["mobiliser les cycles du carbone et de l'azote","proposer des pratiques","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Une <strong>agriculture durable</strong> maintient la fertilité du sol et le stock de carbone : rotations avec légumineuses, compost, limitation des feux, reboisement.</div>"},{"t":"Arguments","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":55,"apc":{"module":"Énergétique biologique et écosystèmes","famille":"Recherche d'un meilleur équilibre de vie","agir":"Améliorer la production d'énergie par l'organisme et préserver les écosystèmes","situation":"Dans un village de l'Est, les rendements baissent et la forêt recule à cause des feux et de l'agriculture itinérante.","tache":"Rédige un texte argumenté et propose un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r56",{"duree":20,"titre":"Le soi","accroche":"Une carte d'identité moléculaire.","intro":"Chaque individu porte à la surface de ses cellules des molécules qui le caractérisent.","objectifs":["définir le soi","citer les marqueurs du soi","expliquer la compatibilité"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>soi</strong> est l'ensemble des molécules propres à un individu, déterminées par ses gènes, et tolérées par son système immunitaire.</div>"},{"t":"Marqueurs","html":"<p>Les molécules du CMH (système HLA chez l'Homme) sont présentes sur presque toutes les cellules ; les marqueurs des groupes sanguins A, B, O sont sur les hématies.</p>","labo":{"type":"abo"}},{"t":"Compatibilité","html":"<p>Une greffe réussit mieux entre personnes de CMH proches ; une transfusion doit respecter la compatibilité des groupes sanguins.</p>","retenir":"Le soi est génétiquement déterminé."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Le soi désigne :</p><ol type='a'><li>l'ensemble des microbes qui vivent dans l'organisme</li><li>l'ensemble des molécules propres à un individu</li><li>l'ensemble des anticorps reçus par la vaccination</li><li>les aliments absorbés par l'intestin</li></ol><details><summary>Voir la réponse</summary><p><strong>l'ensemble des molécules propres à un individu</strong>. Le système immunitaire le tolère normalement.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Qui est donneur universel de globules rouges ?</p><details><summary>Voir la réponse</summary><p>(Réponse : le groupe O.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition.</p><p><strong>Situation.</strong> Mme Ngo, du groupe sanguin B, doit être transfusée à l'hôpital de Bafoussam. Les donneurs disponibles sont des groupes A, B, AB et O.</p><p><strong>Consigne 1.</strong> Explique ce qu'est un marqueur du soi sur les hématies.</p><p><strong>Consigne 2.</strong> Quels donneurs conviennent ? Justifie.</p><details><summary>Voir une réponse attendue</summary><p>Les hématies portent des molécules propres à l'individu (A, B ou aucune), déterminées par ses gènes. Elle a des anticorps anti-A : seuls les donneurs B et O conviennent.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la santé."}],"revision":["Soi.","CMH, groupes sanguins.","Compatibilité."],"exo":"<p>Qui est donneur universel de globules rouges ? <em>(Réponse : le groupe O.)</em></p>","quiz":[{"q":"Le soi désigne :","r":["l'ensemble des microbes qui vivent dans l'organisme","l'ensemble des molécules propres à un individu","l'ensemble des anticorps reçus par la vaccination","les aliments absorbés par l'intestin"],"b":1,"e":"Le système immunitaire le tolère normalement."},{"q":"Les marqueurs du soi sur les cellules sont surtout :","r":["les glucides de réserve du cytoplasme","les chromosomes du noyau de chaque cellule","les molécules du CMH (HLA chez l'Homme)","les anticorps fixés à la membrane des hématies"],"b":2,"e":"Elles sont codées par des gènes très variables."},{"q":"Les molécules HLA sont :","r":["identiques chez tous les êtres humains d'une même famille","absentes de la surface des cellules humaines","des anticorps libres dans le plasma sanguin","propres à chaque individu, sauf chez les vrais jumeaux"],"b":3,"e":"Leur grande diversité explique les rejets de greffe."},{"q":"Les marqueurs des groupes sanguins A, B, O sont portés par :","r":["les globules rouges","les plaquettes seulement","les neurones","les os"],"b":0,"e":"Ce sont des antigènes de surface des hématies."},{"q":"Une greffe entre vrais jumeaux :","r":["est toujours rejetée","est bien tolérée","est impossible","provoque une infection"],"b":1,"e":"Ils ont les mêmes molécules HLA."},{"q":"La tolérance du soi s'acquiert :","r":["seulement à l'âge adulte, après la puberté","par la vaccination contre les maladies de l'enfance","pendant le développement des lymphocytes","par l'alimentation reçue pendant les premières années"],"b":2,"e":"Les lymphocytes qui attaquent le soi sont éliminés."},{"q":"Une maladie auto-immune survient quand :","r":["un virus infecte les cellules du foie","on manque de vitamines pendant longtemps","on reçoit un vaccin de rappel","le système immunitaire attaque le soi"],"b":3,"e":"Ex. : certains diabètes de type 1."},{"q":"Le groupe O possède sur ses hématies :","r":["ni antigène A ni antigène B","l'antigène A seulement","l'antigène B seulement","les antigènes A et B à la fois"],"b":0,"e":"C'est pourquoi on l'appelait donneur universel."},{"q":"Le facteur Rhésus positif signifie :","r":["l'absence d'antigène D à la surface des hématies","la présence de l'antigène D sur les hématies","la présence d'anticorps anti-D dans le plasma","l'appartenance au groupe sanguin AB"],"b":1,"e":"Rh− signifie l'absence de cet antigène."},{"q":"Le système immunitaire a pour rôle :","r":["de digérer les aliments","de produire l'énergie","de maintenir l'intégrité du soi","de fabriquer les hormones sexuelles"],"b":2,"e":"Il élimine ce qui est étranger ou anormal."}],"c":"1re D","m":"svt","rang":56,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"À l'hôpital de district de Mbalmayo, un patient du groupe A a besoin d'une transfusion.","tache":"Quels groupes de donneurs conviennent ? Justifie."},"gratuit":true});
VRT_L("1re-d-svt-r57",{"duree":20,"titre":"Le non-soi","accroche":"Tout ce qui est étranger.","intro":"Le système immunitaire reconnaît et combat ce qui n'appartient pas au soi.","objectifs":["définir le non-soi et l'antigène","citer des exemples","expliquer un rejet"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>non-soi</strong> regroupe les éléments étrangers reconnus par le système immunitaire : microbes, cellules greffées, cellules modifiées. Une molécule qui déclenche une réaction est un <strong>antigène</strong>.</div>"},{"t":"Exemples","verrou":true},{"t":"Rejet","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":57,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un homme de Bafoussam reçoit un rein de son frère jumeau sans traitement antirejet.","tache":"Explique pourquoi la greffe réussit."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r58",{"duree":20,"titre":"Les principales cellules immunitaires","accroche":"Une armée aux rôles variés.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et coopèrent pour défendre l'organisme.","objectifs":["citer les cellules","préciser leur rôle","situer leur origine"],"parties":[{"t":"Les cellules","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> (globules blancs) assurent l'immunité : phagocytes (macrophages, granulocytes), lymphocytes B, lymphocytes T4 et T8.</div>"},{"t":"Rôles","verrou":true},{"t":"Origine","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":58,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un laborantin de Limbé observe un frottis sanguin coloré.","tache":"Comment reconnaître un lymphocyte d'un granulocyte ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r59",{"duree":20,"titre":"Le VIH : contamination et mode d'action","accroche":"Un virus qui détruit les défenseurs.","intro":"Le VIH infecte les lymphocytes T4 et affaiblit progressivement les défenses.","objectifs":["citer les voies de transmission","décrire le cycle du virus","décrire le dépistage"],"parties":[{"t":"Le virus","html":"<div class='def'><b>Définition</b>Le <strong>VIH</strong> est un rétrovirus : son information génétique est un ARN, copié en ADN par la <strong>transcriptase inverse</strong>. Sa protéine gp120 se fixe sur le récepteur CD4 des LT4.</div>"},{"t":"Transmission","verrou":true},{"t":"Cycle et dépistage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":59,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un jeune de Kousseri craint d'avoir été contaminé en partageant le repas d'une personne séropositive.","tache":"Rassure-le avec des arguments scientifiques."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r60",{"duree":20,"titre":"Multiplication du VIH, conséquences et lutte","accroche":"Freiner le virus, protéger les autres.","intro":"Le VIH se multiplie dans les LT4 et détruit peu à peu l'immunité ; la lutte associe prévention et traitement.","objectifs":["expliquer la chute des LT4","décrire les conséquences","proposer des moyens de lutte"],"parties":[{"t":"Multiplication","html":"<div class='def'><b>Définition</b>Le VIH se <strong>multiplie</strong> dans les LT4 infectés, qui libèrent de nouveaux virus et meurent : le nombre de LT4 diminue progressivement.</div>"},{"t":"Conséquences","verrou":true},{"t":"Lutte","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":60,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Une association de Ngaoundéré prépare une campagne de dépistage dans les marchés.","tache":"Propose trois messages clés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r61",{"duree":20,"titre":"Intégration : une campagne contre le VIH au lycée","accroche":"Informer sans faire peur.","intro":"Le club santé veut sensibiliser les élèves au VIH.","objectifs":["mobiliser les connaissances sur le VIH","concevoir une affiche","rédiger un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>La <strong>sensibilisation</strong> consiste à informer et à encourager des comportements protecteurs, sans stigmatiser.</div>"},{"t":"Contenu","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":61,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Le club santé d'un lycée de Bamenda veut organiser une semaine de lutte contre le VIH.","tache":"Rédige un texte de dix lignes et un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r62",{"duree":20,"titre":"La sexualité précoce et ses conséquences","accroche":"Trop tôt, trop de risques.","intro":"Une sexualité précoce, souvent non protégée, expose les jeunes à de nombreux risques.","objectifs":["définir la sexualité précoce","citer ses conséquences","proposer des moyens de prévention"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>sexualité précoce</strong> désigne des rapports sexuels chez des adolescents qui ne sont pas encore prêts physiquement, psychologiquement et socialement.</div>"},{"t":"Conséquences","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":62,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Une élève de 15 ans à Bertoua subit la pression de son copain.","tache":"Donne-lui des conseils argumentés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r63",{"duree":20,"titre":"Les mutilations génitales et leurs conséquences","accroche":"Une pratique dangereuse et interdite.","intro":"Les mutilations génitales féminines portent gravement atteinte à la santé.","objectifs":["définir les mutilations","citer leurs conséquences","proposer des moyens de lutte"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>mutilations génitales féminines</strong> sont toutes les interventions qui lèsent ou enlèvent une partie des organes génitaux externes féminins sans raison médicale.</div>"},{"t":"Conséquences","verrou":true},{"t":"Lutte","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":63,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Dans un village de l'Est, une association recense 12 jeunes filles excisées l'an dernier, dont 3 ont été hospitalisées pour hémorragie. Le chef veut une campagne d'information.","tache":"Propose le contenu d'une affiche avec trois conséquences et un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r64",{"duree":20,"titre":"Les stupéfiants et la santé reproductive","accroche":"Tramadol, cannabis, alcool.","intro":"La prise de stupéfiants augmente les comportements à risque et nuit à la fertilité et au fœtus.","objectifs":["citer des stupéfiants","décrire leurs effets","proposer des moyens de prévention"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>stupéfiant</strong> est une substance qui agit sur le système nerveux et crée une dépendance : cannabis, tramadol détourné, cocaïne ; l'alcool a des effets comparables à forte dose.</div>"},{"t":"Effets sur la reproduction","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":64,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Dans un quartier de Maroua, des jeunes consomment du tramadol mélangé à des boissons sucrées.","tache":"Rédige un message de prévention."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r65",{"duree":20,"titre":"Intégration : sensibiliser à la santé reproductive","accroche":"Affiche et slogan du Probatoire.","intro":"Les sujets demandent souvent des outils de sensibilisation sur la santé reproductive des jeunes.","objectifs":["exploiter des données","concevoir une affiche","rédiger un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>outil de sensibilisation</strong> (affiche, slogan, causerie) informe et incite à adopter des comportements protecteurs.</div>"},{"t":"Démarche","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":65,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un tableau régional indique, pour 1 000 jeunes filles d'Afrique centrale : mariages précoces 280 en 2015 et 210 en 2025 ; grossesses précoces 120 puis 95.","tache":"Calcule la baisse en pourcentage de chaque indicateur et conçois une affiche avec un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r66",{"duree":20,"titre":"L'alimentation équilibrée","accroche":"Manger de tout, en bonnes proportions.","intro":"Une alimentation équilibrée couvre les besoins en énergie et en nutriments.","objectifs":["définir l'alimentation équilibrée","citer les groupes d'aliments","répartir les apports"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>alimentation équilibrée</strong> apporte, en quantité et en qualité, l'énergie et les nutriments nécessaires : environ 50 à 55 % de glucides, 30 à 35 % de lipides et 12 à 15 % de protides.</div>"},{"t":"Groupes d'aliments","verrou":true},{"t":"Répartition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":66,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Une mère de Bafia sert à ses enfants du manioc matin, midi et soir.","tache":"Explique pourquoi ce régime est déséquilibré et propose des compléments."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r67",{"duree":20,"titre":"Composer un menu équilibré","accroche":"Du ndolé, du plantain, un fruit.","intro":"Composer un menu, c'est associer plusieurs groupes d'aliments dans chaque repas.","objectifs":["composer un menu","vérifier son équilibre","adapter aux besoins"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>menu équilibré</strong> associe à chaque repas un féculent, une source de protides, des légumes ou des fruits, un produit laitier si possible, et de l'eau.</div>"},{"t":"Exemple","verrou":true},{"t":"Adapter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":67,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"La cantine d'un lycée de Douala sert souvent du riz blanc à l'huile.","tache":"Propose un menu équilibré à coût modéré."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r68",{"duree":20,"titre":"TP 16 : choix et composition de menus équilibrés","accroche":"Calculer l'énergie d'un menu.","intro":"Ce TP met en œuvre le calcul des apports et la composition d'un menu à partir d'une table de composition des aliments.","objectifs":["utiliser une table de composition","calculer l'apport énergétique","corriger un menu"],"parties":[{"t":"Le but","html":"<div class='def'><b>Définition</b>Une <strong>table de composition</strong> donne, pour 100 g d'aliment, les masses de glucides, lipides et protides.</div>"},{"t":"Protocole","verrou":true},{"t":"Résultat","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":68,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un groupe de 1re D de Bafoussam calcule que son menu tire 50 % de son énergie des lipides.","tache":"Propose une correction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r69",{"duree":20,"titre":"Conséquences de la mauvaise alimentation et de l'inactivité","accroche":"Kwashiorkor ou obésité.","intro":"Une alimentation déséquilibrée et l'inactivité physique favorisent de nombreuses maladies.","objectifs":["citer les maladies par carence","citer les maladies par excès","proposer une prévention"],"parties":[{"t":"Carences","html":"<div class='def'><b>Définition</b>Une <strong>carence</strong> est un manque d'un nutriment : protides (kwashiorkor), énergie globale (marasme), fer (anémie), iode (goitre), vitamine A (troubles de la vision).</div>"},{"t":"Excès et inactivité","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":69,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"Un médecin de Yaoundé constate de plus en plus de jeunes obèses qui passent leurs journées devant les écrans.","tache":"Propose des conseils argumentés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r70",{"duree":20,"titre":"Intégration : une cantine équilibrée","accroche":"Bien nourrir sans trop dépenser.","intro":"Le responsable d'une cantine doit proposer des repas équilibrés avec un budget limité.","objectifs":["mobiliser les règles de l'équilibre","composer des menus locaux","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>repas équilibré</strong> associe féculent, protides, légumes ou fruits, et apporte une énergie adaptée.</div>"},{"t":"Ressources locales","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":70,"apc":{"module":"Immunité, santé reproductive et nutrition","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre les problèmes liés à la santé reproductive des jeunes et à la malnutrition","situation":"L'intendant d'un internat de Bafang dispose d'un budget limité pour 200 élèves.","tache":"Propose un menu équilibré pour un déjeuner et justifie-le."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r71",{"duree":20,"titre":"L'origine de l'énergie solaire","accroche":"Le Soleil, un réacteur de fusion.","intro":"L'énergie reçue par la Terre provient de réactions nucléaires au cœur du Soleil.","objectifs":["expliquer l'origine de l'énergie solaire","décrire son transfert","citer ses usages"],"parties":[{"t":"Origine","html":"<div class='def'><b>Définition</b>Au cœur du Soleil, la <strong>fusion nucléaire</strong> transforme l'hydrogène en hélium et libère une énergie considérable, émise sous forme de <strong>rayonnement électromagnétique</strong>.</div>"},{"t":"Transfert","html":"<p>Le rayonnement traverse le vide spatial et atteint la Terre en environ 8 minutes ; il comprend de l'ultraviolet, du visible et de l'infrarouge.</p>","labo":{"type":"etapes","items":[["Fusion","cœur du Soleil."],["Rayonnement","à travers l'espace."],["Terre","réception."],["Usages","photosynthèse, panneaux."]]}},{"t":"Usages","html":"<p>Photosynthèse, climat, cycle de l'eau, énergie solaire photovoltaïque et thermique.</p>","retenir":"Fusion de l'hydrogène en hélium."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> L'énergie du Soleil provient :</p><ol type='a'><li>de la combustion du charbon et du gaz</li><li>de la fission de l'uranium de son noyau</li><li>de réactions de fusion nucléaire dans son cœur</li><li>de réactions chimiques ordinaires en surface</li></ol><details><summary>Voir la réponse</summary><p><strong>de réactions de fusion nucléaire dans son cœur</strong>. Des noyaux d'hydrogène fusionnent pour former de l'hélium.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>En combien de temps la lumière du Soleil atteint-elle la Terre ?</p><details><summary>Voir la réponse</summary><p>(Réponse : environ 8 minutes.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Limiter les effets des phénomènes naturels et préserver son environnement.</p><p><strong>Situation.</strong> Une école de Kousseri s'équipe de panneaux solaires. Un élève affirme que le Soleil « brûle du charbon » pour produire sa lumière.</p><p><strong>Consigne 1.</strong> Corrige cette affirmation en expliquant l'origine de l'énergie solaire.</p><p><strong>Consigne 2.</strong> Explique comment cette énergie parvient jusqu'aux panneaux.</p><details><summary>Voir une réponse attendue</summary><p>L'énergie solaire provient de la fusion nucléaire de l'hydrogène en hélium au cœur du Soleil. Elle est émise sous forme de rayonnement électromagnétique qui traverse le vide et atteint la Terre en environ 8 minutes.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de l'environnement."}],"revision":["Fusion.","Rayonnement.","Usages."],"exo":"<p>En combien de temps la lumière du Soleil atteint-elle la Terre ? <em>(Réponse : environ 8 minutes.)</em></p>","quiz":[{"q":"L'énergie du Soleil provient :","r":["de la combustion du charbon et du gaz","de la fission de l'uranium de son noyau","de réactions de fusion nucléaire dans son cœur","de réactions chimiques ordinaires en surface"],"b":2,"e":"Des noyaux d'hydrogène fusionnent pour former de l'hélium."},{"q":"La fusion nucléaire solaire transforme :","r":["l'hélium en hydrogène","le carbone en oxygène","l'eau en vapeur","l'hydrogène en hélium"],"b":3,"e":"Une petite perte de masse est convertie en énergie."},{"q":"L'énergie solaire nous parvient sous forme :","r":["de rayonnement électromagnétique","de vent","de chaleur transportée par l'air de l'espace","de son"],"b":0,"e":"Elle traverse le vide spatial à la vitesse de la lumière."},{"q":"La lumière du Soleil met environ :","r":["1 seconde pour atteindre la Terre","8 minutes pour atteindre la Terre","1 jour pour atteindre la Terre","8 heures pour atteindre la Terre"],"b":1,"e":"La distance est d'environ 150 millions de km."},{"q":"Le spectre solaire comprend :","r":["uniquement la lumière visible, du violet au rouge","les rayons X, les rayons gamma et les ondes radio, sans lumière visible","les ultraviolets, la lumière visible et les infrarouges","uniquement les infrarouges qui chauffent la Terre"],"b":2,"e":"La plus grande part de l'énergie est dans le visible et le proche infrarouge."},{"q":"La température de surface du Soleil est d'environ :","r":["100 K","1 000 000 K","300 K","5 800 K"],"b":3,"e":"Elle détermine le maximum d'émission dans le visible."},{"q":"La relation E = mc² explique :","r":["que la perte de masse libère une énorme énergie","que la photosynthèse libère de l'énergie à partir du CO₂","que la respiration produit la lumière des étoiles","que la gravité retient les planètes autour du Soleil"],"b":0,"e":"c² est un très grand nombre."},{"q":"Le Soleil est :","r":["une planète","une étoile","un satellite","une comète"],"b":1,"e":"C'est l'étoile la plus proche de la Terre."},{"q":"L'énergie solaire est à l'origine :","r":["des séismes, des volcans, de la tectonique des plaques et des montagnes","du magnétisme terrestre et des aurores polaires","du climat, des vents, du cycle de l'eau et de la photosynthèse","des marées et des courants des fleuves seulement"],"b":2,"e":"La géologie interne dépend, elle, de l'énergie interne."},{"q":"Les panneaux photovoltaïques convertissent :","r":["la chaleur en eau","le vent en lumière","l'électricité en lumière solaire","l'énergie lumineuse en électricité"],"b":3,"e":"C'est une utilisation directe de l'énergie solaire."}],"c":"1re D","m":"svt","rang":71,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une école de Kousseri installe des panneaux solaires pour s'éclairer.","tache":"Explique l'origine de l'énergie captée."},"gratuit":true});
VRT_L("1re-d-svt-r72",{"duree":20,"titre":"La Terre ne reçoit qu'une partie du rayonnement","accroche":"Un tiers repart vers l'espace.","intro":"Une partie du rayonnement solaire est réfléchie, une autre absorbée par l'atmosphère et la surface.","objectifs":["définir l'albédo","décrire le devenir du rayonnement","comparer des surfaces"],"parties":[{"t":"Albédo","html":"<div class='def'><b>Définition</b>L'<strong>albédo</strong> est la fraction du rayonnement réfléchie par une surface. L'albédo moyen de la Terre est d'environ 30 %.</div>"},{"t":"Devenir","verrou":true},{"t":"Surfaces","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":72,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Dans le Nord, la déforestation remplace la forêt par des sols nus et clairs.","tache":"Comment évolue l'albédo de la région ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r73",{"duree":20,"titre":"Constante solaire et bilan radiatif","accroche":"Ce qui entre doit ressortir.","intro":"La Terre reçoit et émet de l'énergie : l'équilibre de ces flux fixe sa température moyenne.","objectifs":["définir la constante solaire","établir le bilan radiatif","expliquer l'équilibre"],"parties":[{"t":"Constante solaire","html":"<div class='def'><b>Définition</b>La <strong>constante solaire</strong> est la puissance reçue par 1 m² placé perpendiculairement aux rayons, au sommet de l'atmosphère : environ 1 361 W/m².</div>"},{"t":"Puissance moyenne","verrou":true},{"t":"Bilan radiatif","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":73,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Garoua mesure qu'un panneau solaire reçoit beaucoup plus à midi qu'au lever du Soleil.","tache":"Explique cette différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r74",{"duree":20,"titre":"L'effet de serre","accroche":"Sans lui, il ferait −18 °C.","intro":"Certains gaz de l'atmosphère retiennent une partie de l'infrarouge émis par la Terre.","objectifs":["définir l'effet de serre","citer les gaz à effet de serre","distinguer effet naturel et renforcé"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet de serre</strong> est le réchauffement de la surface dû à des gaz atmosphériques (vapeur d'eau, CO₂, méthane) qui absorbent l'infrarouge émis par la Terre et en renvoient une partie vers le sol.</div>"},{"t":"Importance","verrou":true},{"t":"Effet renforcé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":74,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Les pêcheurs de Kribi observent que la mer gagne sur la plage d'année en année.","tache":"Relie cette observation à l'effet de serre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r75",{"duree":20,"titre":"Intégration : un climat qui change au Nord","accroche":"Des pluies irrégulières.","intro":"Les agriculteurs du Nord observent des saisons des pluies plus courtes et plus irrégulières.","objectifs":["mobiliser bilan radiatif et effet de serre","proposer des actions d'adaptation","rédiger un texte"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Le <strong>réchauffement climatique</strong> modifie la répartition des pluies et accroît les sécheresses dans les régions sahéliennes.</div>"},{"t":"Actions","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":75,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Dans la région de Maroua, les pluies commencent plus tard et s'arrêtent plus tôt qu'autrefois.","tache":"Rédige des conseils argumentés pour les agriculteurs."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r76",{"duree":20,"titre":"L'inégale répartition de l'énergie solaire","accroche":"Pourquoi l'équateur est plus chaud que les pôles.","intro":"La quantité d'énergie reçue dépend de la latitude et des saisons.","objectifs":["expliquer l'effet de la latitude","expliquer les saisons","relier aux climats"],"parties":[{"t":"Latitude","html":"<div class='def'><b>Définition</b>Plus la latitude augmente, plus les rayons arrivent <strong>obliquement</strong> : la même énergie se répartit sur une plus grande surface et chaque m² reçoit moins.</div>"},{"t":"Saisons","verrou":true},{"t":"Conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":76,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"À Yaoundé, la température moyenne varie de 23 °C à 26 °C au cours de l'année ; à Paris, de 5 °C en janvier à 20 °C en juillet. Un élève se demande pourquoi il n'y a pas d'hiver froid au Cameroun.","tache":"Explique cette différence à l'aide de l'inclinaison des rayons solaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r77",{"duree":20,"titre":"Les mouvements atmosphériques","accroche":"Harmattan et mousson.","intro":"Les différences de température créent des différences de pression qui mettent l'air en mouvement.","objectifs":["expliquer la naissance des vents","décrire la circulation générale","relier aux saisons du Cameroun"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>L'air chauffé s'élève et crée une zone de <strong>basse pression</strong> ; l'air froid descend et crée une <strong>haute pression</strong>. Le <strong>vent</strong> souffle des hautes vers les basses pressions.</div>"},{"t":"Circulation générale","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":77,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Le long de la côte de Limbé, les pirogues rentrent facilement à la plage en fin de journée.","tache":"Explique ce phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r78",{"duree":20,"titre":"Les mouvements océaniques","accroche":"Des fleuves dans la mer.","intro":"Les vents et les différences de densité mettent en mouvement les eaux océaniques.","objectifs":["décrire les courants de surface","décrire la circulation profonde","expliquer le rôle climatique"],"parties":[{"t":"Courants de surface","html":"<div class='def'><b>Définition</b>Les <strong>courants de surface</strong> sont entraînés par les vents ; le courant de Guinée longe la côte du golfe de Guinée.</div>"},{"t":"Circulation profonde","verrou":true},{"t":"Rôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":78,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Les pêcheurs du golfe de Guinée remarquent des saisons où le poisson abonde près des côtes.","tache":"Propose une explication."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r79",{"duree":20,"titre":"Intégration : pêche et vents de la côte","accroche":"Lire le ciel et la mer.","intro":"Une coopérative de pêcheurs veut organiser ses sorties en tenant compte des vents et des courants.","objectifs":["mobiliser brises et courants","proposer un calendrier","argumenter"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Les <strong>brises</strong> et les <strong>courants</strong> résultent de l'inégal réchauffement de la terre et de la mer.</div>"},{"t":"Conseils","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":79,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"La coopérative des pêcheurs de Limbé veut réduire le carburant de ses pirogues à moteur.","tache":"Propose une organisation des sorties."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r86",{"duree":20,"titre":"Altération et érosion des roches","accroche":"La roche devient sol.","intro":"Sous l'action de l'eau, de la chaleur et des êtres vivants, les roches se dégradent.","objectifs":["distinguer altération et érosion","décrire l'altération physique et chimique","relier aux sols tropicaux"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>L'<strong>altération</strong> est la dégradation des roches sur place ; l'<strong>érosion</strong> est l'enlèvement des produits de cette dégradation par l'eau, le vent ou la glace.</div>"},{"t":"Deux types d'altération","verrou":true},{"t":"En milieu tropical","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":86,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Sur une route de l'Ouest, un talus de granite est devenu une terre rouge friable.","tache":"Explique cette transformation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r87",{"duree":20,"titre":"Transport des produits d'altération et d'érosion","accroche":"Les rivières trient les grains.","intro":"Les produits de l'érosion sont transportés par l'eau et le vent, puis triés selon leur taille.","objectifs":["citer les modes de transport","expliquer le tri","relier énergie et transport"],"parties":[{"t":"Modes de transport","html":"<div class='def'><b>Définition</b>Les particules sont transportées par <strong>roulement</strong>, <strong>saltation</strong>, <strong>suspension</strong> ou en <strong>solution</strong> (ions dissous).</div>"},{"t":"Tri","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":87,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Après une forte pluie à Bafoussam, la rivière est boueuse et roule des cailloux.","tache":"Explique ce que transporte la rivière."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r88",{"duree":20,"titre":"Sédimentation et diagenèse","accroche":"Du sable au grès.","intro":"Les sédiments se déposent puis se transforment lentement en roches.","objectifs":["définir sédimentation et diagenèse","décrire les étapes de la diagenèse","citer des exemples"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>sédimentation</strong> est le dépôt des particules dans un bassin (lac, mer, delta). La <strong>diagenèse</strong> est l'ensemble des transformations qui changent un sédiment meuble en roche sédimentaire.</div>"},{"t":"Étapes","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":88,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Au bord du lac Tchad, des couches de boue s'accumulent chaque année.","tache":"Que deviendront-elles dans des millions d'années ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r89",{"duree":20,"titre":"Diagenèse et roches sédimentaires","accroche":"Grès, calcaire, charbon, pétrole.","intro":"Les roches sédimentaires se classent selon leur origine.","objectifs":["classer les roches sédimentaires","reconnaître quelques roches","expliquer leur intérêt"],"parties":[{"t":"Classification","html":"<div class='def'><b>Définition</b>Les <strong>roches sédimentaires</strong> sont détritiques (grès, argile, conglomérat), chimiques ou biochimiques (calcaire, sel) ou organiques (charbon, pétrole).</div>"},{"t":"Reconnaître","verrou":true},{"t":"Intérêt","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":89,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une cimenterie au Cameroun utilise du calcaire extrait d'une carrière du Nord.","tache":"Comment le géologue vérifie-t-il qu'il s'agit bien de calcaire ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r90",{"duree":20,"titre":"Séries et cycles sédimentaires","accroche":"Quand la mer avance et recule.","intro":"La succession des couches enregistre les variations du niveau marin.","objectifs":["définir une série sédimentaire","reconnaître transgression et régression","lire une colonne stratigraphique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>série sédimentaire</strong> est une succession de couches déposées dans un même bassin. Un <strong>cycle sédimentaire</strong> comprend une transgression puis une régression.</div>"},{"t":"Transgression et régression","verrou":true},{"t":"Lecture","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":90,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Dans le bassin sédimentaire de Douala, un forage traverse de bas en haut : grès, argiles, calcaires.","tache":"Interprète cette succession."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r91",{"duree":20,"titre":"La chronologie relative et ses principes","accroche":"Plus bas, plus ancien.","intro":"Des principes simples permettent d'ordonner les événements géologiques.","objectifs":["énoncer les principes","les appliquer à une coupe","dater relativement un événement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>chronologie relative</strong> ordonne les événements géologiques les uns par rapport aux autres, sans donner d'âge en années.</div>"},{"t":"Principes","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":91,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une coupe géologique près de Garoua montre trois couches traversées par un filon de basalte.","tache":"Ordonne les événements."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r92",{"duree":20,"titre":"Reconstitution des milieux sédimentaires","accroche":"Lire le passé dans une roche.","intro":"Les caractères d'une roche et ses fossiles renseignent sur le milieu où elle s'est formée.","objectifs":["utiliser le principe d'actualisme","exploiter les fossiles","reconstituer un milieu"],"parties":[{"t":"Actualisme","html":"<div class='def'><b>Définition</b>Le <strong>principe d'actualisme</strong> : les phénomènes qui ont agi dans le passé sont les mêmes que ceux observés aujourd'hui.</div>"},{"t":"Indices","verrou":true},{"t":"Reconstitution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":92,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Des élèves de Kumba découvrent des coquillages fossiles dans une roche loin de la mer.","tache":"Que peux-tu en déduire ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r93",{"duree":20,"titre":"Intégration : lutter contre le ravinement","accroche":"Des ravines menacent le quartier.","intro":"Les pluies violentes creusent des ravines dans les sols nus et menacent les habitations.","objectifs":["mobiliser altération, érosion et transport","proposer des solutions","rédiger un texte et un slogan"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Le <strong>ravinement</strong> est une forme d'érosion due à l'eau qui ruisselle et creuse des sillons dans un sol nu.</div>"},{"t":"Solutions","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":93,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"À Maroua, des ravines profondes se forment après chaque saison des pluies et menacent des maisons.","tache":"Rédige un texte argumenté et propose un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r80",{"duree":20,"titre":"Les ondes sismiques","accroche":"Un séisme fait vibrer toute la Terre.","intro":"Les séismes produisent des ondes qui traversent le globe et renseignent sur sa structure.","objectifs":["distinguer ondes P, S et L","lire un sismogramme","localiser un épicentre"],"parties":[{"t":"Les ondes","html":"<div class='def'><b>Définition</b>Un séisme émet des <strong>ondes P</strong> (longitudinales, les plus rapides, traversent solides et liquides), des <strong>ondes S</strong> (transversales, ne traversent pas les liquides) et des <strong>ondes L</strong> (de surface, les plus destructrices).</div>"},{"t":"Le sismogramme","verrou":true},{"t":"Localisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":80,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Une station sismique de Yaoundé enregistre les ondes P puis, 40 secondes plus tard, les ondes S d'un séisme.","tache":"Que permet de calculer ce retard ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r81",{"duree":20,"titre":"Comportement des ondes sismiques dans le globe","accroche":"Des zones où les ondes disparaissent.","intro":"Les ondes changent de vitesse et de direction à certaines profondeurs : ces anomalies révèlent la structure interne.","objectifs":["décrire réfraction et réflexion","interpréter la zone d'ombre","déduire l'état du noyau externe"],"parties":[{"t":"Réfraction","html":"<div class='def'><b>Définition</b>À chaque changement de milieu (discontinuité), les ondes sont <strong>réfractées</strong> (déviées) et partiellement <strong>réfléchies</strong>.</div>"},{"t":"Zone d'ombre","verrou":true},{"t":"Noyau externe liquide","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":81,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un réseau de stations sur tout le globe enregistre un séisme survenu en Indonésie.","tache":"Explique pourquoi certaines stations ne reçoivent pas d'ondes P directes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r82",{"duree":20,"titre":"Les enveloppes internes du globe","accroche":"Croûte, manteau, noyau.","intro":"La sismologie a permis de découvrir les grandes enveloppes de la Terre et leurs limites.","objectifs":["nommer les enveloppes","nommer les discontinuités","distinguer lithosphère et asthénosphère"],"parties":[{"t":"Les enveloppes","html":"<div class='def'><b>Définition</b>La Terre comprend la <strong>croûte</strong>, le <strong>manteau</strong> et le <strong>noyau</strong> (externe liquide, interne solide), séparés par des discontinuités : Moho, Gutenberg (2 900 km), Lehmann (5 150 km).</div>"},{"t":"Croûtes","verrou":true},{"t":"Lithosphère et asthénosphère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":82,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Bamenda fabrique une maquette en coupe de la Terre.","tache":"Liste les enveloppes et les discontinuités à représenter."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r83",{"duree":20,"titre":"Composition et propriétés des enveloppes","accroche":"Plus on descend, plus c'est dense et chaud.","intro":"Chaque enveloppe a une composition, une densité et une température propres.","objectifs":["donner la composition des enveloppes","décrire l'évolution de la densité","décrire l'évolution de la température"],"parties":[{"t":"Composition","html":"<div class='def'><b>Définition</b>La croûte est riche en silicium, oxygène et aluminium ; le <strong>manteau</strong> est formé de <strong>péridotite</strong> ; le <strong>noyau</strong> est surtout fait de <strong>fer et de nickel</strong>.</div>"},{"t":"Densité","verrou":true},{"t":"Température","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":83,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Un élève de Kumba lit que la masse volumique moyenne de la Terre est d'environ 5,5 g/cm³, alors que le granite de son quartier n'a que 2,7 g/cm³ et le basalte du mont Cameroun 3 g/cm³.","tache":"Explique cette différence à l'aide de la structure interne du globe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r84",{"duree":20,"titre":"L'énergie interne de la Terre","accroche":"Une chaleur venue de l'intérieur.","intro":"La Terre produit de la chaleur qui s'évacue par le volcanisme, les séismes et la convection.","objectifs":["citer l'origine de l'énergie interne","décrire sa dissipation","citer des usages"],"parties":[{"t":"Origine","html":"<div class='def'><b>Définition</b>L'<strong>énergie interne</strong> de la Terre provient surtout de la <strong>désintégration d'éléments radioactifs</strong> (uranium, thorium, potassium) et de la chaleur primitive.</div>"},{"t":"Dissipation","verrou":true},{"t":"Usages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":84,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Des habitants de Buea s'interrogent sur l'origine des éruptions du mont Cameroun.","tache":"Explique l'origine de l'énergie qui les provoque."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-svt-r85",{"duree":20,"titre":"Intégration : se préparer aux séismes","accroche":"Savoir où et comment agir.","intro":"La région du mont Cameroun connaît une activité sismique et volcanique : la population doit s'y préparer.","objectifs":["mobiliser les connaissances sur les séismes","proposer des consignes","rédiger un texte et une affiche"],"parties":[{"t":"Notion","html":"<div class='def'><b>Définition</b>Un <strong>séisme</strong> libère brutalement de l'énergie accumulée dans les roches ; ses ondes de surface causent l'essentiel des dégâts.</div>"},{"t":"Consignes","verrou":true},{"t":"Production","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"svt","rang":85,"apc":{"module":"Énergie solaire, structure de la Terre et roches sédimentaires","famille":"Préservation de l'environnement","agir":"Limiter les effets des phénomènes naturels et préserver son environnement","situation":"Le mont Cameroun est entré en éruption en 1999 et en 2000, et des secousses sont parfois ressenties à Buea. Le proviseur du lycée veut organiser un exercice d'alerte pour 1 200 élèves répartis dans 24 salles.","tache":"Rédige les consignes à afficher dans les salles et propose l'organisation de l'évacuation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-definitions",{"c":"1re D","m":"philo","rang":1,"titre":"Définir la philosophie","duree":25,"accroche":"Une seule discipline commence par se demander ce qu'elle est : la philosophie.","intro":"En série scientifique, tu découvres la philosophie cette année. Elle ne donne pas de formules, mais elle apprend à interroger les formules elles-mêmes : qu'est-ce que savoir ? Qu'est-ce qui est juste ? Pour commencer, il faut savoir ce que les philosophes entendent par « philosophie ».","objectifs":["donner l'étymologie et plusieurs définitions de la philosophie","distinguer la conception spontanée et la conception savante","reconnaître les grandes questions de la philosophie"],"parties":[{"t":"La conception spontanée et l'étymologie","html":"<p>Dans le langage courant, « avoir une philosophie », c'est avoir une <strong>manière de vivre</strong> (« ma philosophie : ne jamais abandonner ») ou rester calme dans l'épreuve (« prendre les choses avec philosophie »). C'est la <strong>conception spontanée</strong>.</p><div class='def'><b>Étymologie</b>Du grec <strong>philein</strong> (aimer) et <strong>sophia</strong> (sagesse, savoir) : <strong>amour de la sagesse</strong>. Pythagore aurait refusé le titre de « sage » (sophos) pour se dire « ami de la sagesse » (philosophos) : le philosophe <strong>cherche</strong> le savoir, il ne le possède pas.</div>","retenir":"Conception spontanée : une manière de vivre. Étymologie : amour, recherche de la sagesse."},{"t":"Quelques définitions savantes","html":"<ul><li><strong>Platon</strong> : l'étonnement est le commencement de la philosophie ; elle conduit des apparences à la vérité (allégorie de la caverne).</li><li><strong>Aristote</strong> : la philosophie est la <strong>science des premiers principes et des premières causes</strong>.</li><li><strong>Descartes</strong> : elle est comme un <strong>arbre</strong> dont les racines sont la métaphysique, le tronc la physique et les branches la médecine, la mécanique et la morale.</li><li><strong>Kant</strong> la ramène à quatre questions : <strong>Que puis-je savoir ? Que dois-je faire ? Que m'est-il permis d'espérer ? Qu'est-ce que l'homme ?</strong></li><li><strong>Marcien Towa</strong> : philosopher, c'est examiner de façon critique, y compris ses propres traditions, pour se libérer.</li></ul><div class='astuce'><b>Astuce</b>Retiens les quatre questions de Kant : elles reviennent sans cesse dans les sujets (connaissance, morale, religion, homme).</div>","retenir":"Platon : l'étonnement ; Aristote : premières causes ; Descartes : l'arbre ; Kant : quatre questions ; Towa : la critique libératrice.","labo":{"type":"trier","invite":"Choisis une notion de la leçon.","items":[["Conception spontanée","Conception spontanée : manière de vivre ; savante : réflexion rigoureuse."],["Philein","Philein + sophia : amour de la sagesse (Pythagore)."],["Aristote","Aristote : premiers principes ; Descartes : l'arbre ; Kant : quatre questions."],["rationnelle","Réflexion rationnelle, critique, totalisante."],["La science mesure","La science mesure ; la philosophie interroge le sens et la valeur."]]}},{"t":"Ce qui définit l'attitude philosophique","html":"<div class='def'><b>Trois caractères</b>La philosophie est une réflexion <strong>rationnelle</strong> (elle argumente), <strong>critique</strong> (elle ne reçoit aucune idée sans examen) et <strong>totalisante</strong> (elle cherche le sens d'ensemble : l'homme, le monde, la valeur des choses).</div><div class='ex'><b>Philosophie et sciences</b>Le physicien mesure la chute d'un corps ; le philosophe demande ce que vaut une loi scientifique, si la science peut tout expliquer, si tout ce qui est techniquement possible est moralement permis (clonage, armes, intelligence artificielle).</div><div class='savais'><b>Le savais-tu ?</b>Jusqu'au XVIIIᵉ siècle, la physique s'appelait « philosophie naturelle » : le grand livre de Newton (1687) s'intitule <em>Principes mathématiques de la philosophie naturelle</em>.</div>","retenir":"Rationnelle, critique, totalisante : la philosophie interroge le sens et la valeur, là où la science mesure."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans le langage courant, « prendre les choses avec philosophie » signifie :</p><ol type='a'><li>rester calme et serein</li><li>étudier Platon</li><li>refuser de penser</li><li>faire de la science</li></ol><details><summary>Voir la réponse</summary><p><strong>rester calme et serein</strong>. C'est la conception spontanée.</p></details><p><strong>Exercice.</strong></p><p>Définis les concepts « philosophie » et « opinion » et donne pour chacun une citation avec son auteur.</p><details><summary>Voir la réponse</summary><p>(Réponse : Philosophie : réflexion rationnelle, critique et totalisante sur les questions fondamentales ; « On n'apprend pas la philosophie, on apprend à philosopher » (Kant). Opinion (doxa) : avis reçu sans examen ; « Ce que je sais, c'est que je ne sais rien » (Socrate), qui oppose la conscience de son ignorance aux fausses certitudes.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Sujet.</strong> En 1re C à Bertoua, un camarade déclare : « Nous sommes des scientifiques : la philosophie, c'est du bavardage. La science répond à tout. »</p><p><strong>Consigne.</strong> Rédige une réponse argumentée (12 à 15 lignes) qui montre ce que la philosophie apporte à un futur scientifique, avec au moins une définition étudiée et un exemple actuel.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>La science explique comment les phénomènes se produisent, mais elle ne dit pas ce qu'il faut faire de ses découvertes. Kant rappelle que la question « Que dois-je faire ? » est distincte de « Que puis-je savoir ? ». Exemple : l'intelligence artificielle permet de produire de fausses vidéos très réalistes ; la technique le permet, mais est-ce juste de les diffuser ? De plus, Descartes faisait de la physique une branche de la philosophie : les grands savants (Newton, Einstein) ont réfléchi aux fondements de leur science. La philosophie n'est donc pas un bavardage : elle apprend à examiner les principes et les usages du savoir.</p></details></div>","retenir":"Savoir-être mobilisé : ouverture d'esprit et sens de la responsabilité."}],"revision":["Conception spontanée : manière de vivre ; savante : réflexion rigoureuse.","<strong>Philein</strong> + <strong>sophia</strong> : amour de la sagesse (Pythagore).","Aristote : premiers principes ; Descartes : l'arbre ; Kant : quatre questions.","Réflexion <strong>rationnelle</strong>, <strong>critique</strong>, <strong>totalisante</strong>.","La science mesure ; la philosophie interroge le sens et la valeur."],"exo":"<p>Définis les concepts « philosophie » et « opinion » et donne pour chacun une citation avec son auteur. <em>(Réponse : Philosophie : réflexion rationnelle, critique et totalisante sur les questions fondamentales ; « On n'apprend pas la philosophie, on apprend à philosopher » (Kant). Opinion (doxa) : avis reçu sans examen ; « Ce que je sais, c'est que je ne sais rien » (Socrate), qui oppose la conscience de son ignorance aux fausses certitudes.)</em></p>","quiz":[{"q":"Dans le langage courant, « prendre les choses avec philosophie » signifie :","r":["rester calme et serein","étudier Platon","refuser de penser","faire de la science"],"b":0,"e":"C'est la conception spontanée."},{"q":"Le philosophe, selon Pythagore, est celui qui :","r":["possède la sagesse","aime et cherche la sagesse","enseigne la géométrie","dirige la cité"],"b":1,"e":"Philosophos : ami de la sagesse."},{"q":"Pour Platon, la philosophie commence par :","r":["la peur","la richesse","l'étonnement","la guerre"],"b":2,"e":"S'étonner, c'est voir que l'évidence pose question."},{"q":"L'image de l'arbre est de :","r":["Kant","Aristote","Towa","Descartes"],"b":3,"e":"Racines : métaphysique ; tronc : physique ; branches : médecine, mécanique, morale."},{"q":"« Que dois-je faire ? » relève de :","r":["la morale","la physique","la religion","la logique"],"b":0,"e":"C'est la deuxième question de Kant."},{"q":"Une réflexion critique :","r":["accepte toutes les opinions","examine les idées avant de les admettre","refuse la raison","récite les traditions"],"b":1,"e":"Aucune idée n'est reçue sans examen."},{"q":"Le caractère « totalisant » de la philosophie signifie qu'elle :","r":["étudie un seul objet","fait des calculs","cherche un sens d'ensemble","dure longtemps"],"b":2,"e":"Elle interroge l'homme, le monde et les valeurs."},{"q":"Newton parlait de « philosophie naturelle » pour désigner :","r":["la morale","la religion","la poésie","la physique"],"b":3,"e":"Ses Principia de 1687."},{"q":"Marcien Towa voit dans la philosophie :","r":["une critique libératrice","une récitation des ancêtres","une science exacte","un loisir"],"b":0,"e":"Examiner même ses propres traditions pour se libérer."},{"q":"Aristote définit la philosophie comme :","r":["l'art de bien parler","la science des premiers principes et des premières causes","l'amour des richesses","l'étude des étoiles"],"b":1,"e":"Définition de la Métaphysique."}],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Montrer l'utilité de la réflexion philosophique pour un futur scientifique","situation":"En 1re C à Bertoua, un camarade déclare : « Nous sommes des scientifiques : la philosophie, c'est du bavardage. La science répond à tout. »","tache":"Lui répondre de manière argumentée avec des définitions et un exemple actuel."},"gratuit":true});
VRT_L("1re-d-francais-communication",{"c":"1re D","m":"francais","rang":2,"titre":"Communication : les conditions de la communication","duree":55,"accroche":"« Allô ? Tu m'entends ? » : même une conversation banale obéit à des règles.","intro":"Leçon de langue (rubrique Communication). On observe un échange réel de la vie scolaire, on y identifie les facteurs de la communication et ce qui la fait réussir ou échouer, puis on formule la règle et on s'entraîne au format de l'épreuve de langue : repérage, analyse, interprétation.","objectifs":["identifier les six facteurs de la communication","associer à chaque facteur sa fonction du langage","expliquer les causes d'échec d'une communication"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (échange composé pour la leçon) :</p><blockquote>Message du délégué, envoyé à 23 h dans le groupe WhatsApp de la 1re C : « Dvr de maths reporté à jeudi, svp passez l'info. »<br>Réponse d'un élève venu de Bamenda : « Sorry, what is Dvr? »<br>Réponse d'une élève, le lendemain à 7 h : « Je n'avais plus de forfait hier… Quel devoir ? »<br>Le délégué, en classe : « Écoutez tous : le devoir de mathématiques est reporté à jeudi, à 10 heures. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Qui parle (émetteur) ? À qui (récepteur) ? Pour dire quoi (message) ? De quoi parle-t-on (référent) ?</li><li>Par quels moyens le message passe-t-il (canal) ? Dans quelle langue et sous quelle forme (code) ?</li><li>Pourquoi l'élève de Bamenda ne comprend-il pas ? Pourquoi l'élève du matin n'a-t-elle rien reçu ?</li><li>Compare le premier et le dernier message : qu'a changé le délégué ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Émetteur : le délégué ; récepteurs : les élèves de la classe ; message : le report du devoir ; référent : le devoir de mathématiques. 2. Canal : messagerie écrite puis voix en classe ; code : français abrégé (« Dvr », « svp »), puis français courant. 3. L'élève anglophone ne partage pas le <strong>code</strong> (abréviation, langue) ; l'autre n'a pas eu accès au <strong>canal</strong> (plus de forfait) : ce sont des <strong>bruits</strong>. 4. Il a changé de canal (oral, en présence de tous) et de code (mots entiers, précisions), et ajouté l'heure : la communication réussit.</p></details><div class='def'><b>Ce que montre l'observation</b>La <strong>communication</strong> est la transmission d'un <strong>message</strong> d'un <strong>émetteur</strong> à un <strong>récepteur</strong>, à propos d'un <strong>référent</strong>, par un <strong>canal</strong>, au moyen d'un <strong>code</strong> commun. Elle échoue quand un de ces facteurs fait défaut : on parle de <strong>bruit</strong>.</div>","retenir":"Six facteurs : émetteur, récepteur, message, référent, canal, code ; le bruit fait échouer la communication."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Analyser une situation de communication pour transmettre un message compris de tous","situation":"Le délégué de ta classe à Garoua envoie dans le groupe WhatsApp : « Dvr de maths reporté à jeudi, svp passez l'info ». Plusieurs élèves anglophones et un nouvel élève venu de Maroua n'ont rien compris ; d'autres n'avaient plus de connexion.","tache":"Analyser les facteurs et les causes de l'échec, puis réécrire le message."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-renaissance",{"c":"1re D","m":"histoire","rang":1,"titre":"L'Europe de la Renaissance (XVᵉ-XVIᵉ siècles)","duree":25,"accroche":"Une imprimerie, des caravelles et une nouvelle idée de l'homme : l'Europe change de visage.","intro":"Entre le milieu du XVᵉ et la fin du XVIᵉ siècle, l'Europe connaît un renouveau des arts, des sciences et des idées, et part à la découverte du monde. C'est aussi le moment où des navigateurs portugais atteignent les côtes du Cameroun, auquel ils donnent son nom.","objectifs":["définir la Renaissance et l'humanisme","présenter les transformations artistiques, scientifiques et religieuses","expliquer les grandes découvertes et leurs conséquences pour l'Afrique"],"parties":[{"t":"La Renaissance et l'humanisme","html":"<div class='def'><b>Définitions</b>La <strong>Renaissance</strong> est le renouveau culturel européen des XVᵉ et XVIᵉ siècles, né en <strong>Italie</strong> (Florence, Rome, Venise), qui s'inspire de l'Antiquité grecque et romaine. L'<strong>humanisme</strong> est le mouvement intellectuel qui place l'<strong>homme</strong>, sa dignité et sa raison au centre de la réflexion.</div><ul><li><strong>L'imprimerie</strong> : Gutenberg met au point les caractères mobiles à Mayence (Bible vers 1455) ; les livres se diffusent rapidement.</li><li><strong>Les humanistes</strong> : Érasme (<em>Éloge de la folie</em>, 1511), Thomas More (<em>Utopie</em>, 1516), Rabelais, Montaigne.</li><li><strong>Les mécènes</strong> : les Médicis à Florence, les papes à Rome financent artistes et savants.</li></ul>","retenir":"Renaissance : renouveau inspiré de l'Antiquité, né en Italie ; humanisme : l'homme au centre ; diffusion par l'imprimerie."},{"t":"Arts, sciences et religion","html":"<ul><li><strong>Arts</strong> : perspective, étude du corps humain. Léonard de Vinci (<em>La Joconde</em>), Michel-Ange (plafond de la chapelle Sixtine), Raphaël.</li><li><strong>Sciences</strong> : <strong>Copernic</strong> (1543) affirme que la Terre tourne autour du Soleil (héliocentrisme) ; Vésale décrit l'anatomie humaine.</li><li><strong>Religion</strong> : en <strong>1517</strong>, <strong>Martin Luther</strong> critique la vente des indulgences : c'est la <strong>Réforme protestante</strong> ; Calvin la prolonge. L'Église catholique répond par la <strong>Contre-Réforme</strong> (concile de Trente, 1545-1563).</li></ul><div class='attention'><b>Attention</b>La Renaissance n'est pas une rupture totale avec le Moyen Âge, et elle reste réservée à une élite urbaine et instruite.</div>","retenir":"Vinci, Michel-Ange ; Copernic (1543) ; Luther (1517) : Réforme et Contre-Réforme.","labo":{"type":"etapes","invite":"Avance étape par étape.","items":[["Renaissance","Renaissance (XVᵉ-XVIᵉ s.) : renouveau né en Italie, inspiré de l'Antiquité."],["Humanisme","Humanisme : l'homme au centre ; imprimerie de Gutenberg (vers 1455)."],["Copernic","Vinci, Michel-Ange ; Copernic 1543 ; Luther 1517."],["1492","Découvertes : 1488 Dias, 1492 Colomb, 1498 Vasco de Gama."],["Rio dos Camarões","Vers 1472 : Fernando Póo, Rio dos Camarões."]]}},{"t":"Les grandes découvertes et l'Afrique","html":"<ul><li>Causes : recherche de l'or et des épices, contournement de l'Empire ottoman (prise de Constantinople en <strong>1453</strong>), progrès techniques (caravelle, boussole, astrolabe).</li><li>Étapes : Bartolomeu Dias passe le cap de Bonne-Espérance (1488) ; <strong>Christophe Colomb</strong> atteint l'Amérique (1492) ; Vasco de Gama arrive en Inde (1498) ; Magellan et Elcano font le tour du monde (1519-1522).</li></ul><div class='ex'><b>Le Cameroun</b>Vers <strong>1472</strong>, le Portugais <strong>Fernando Póo</strong> entre dans l'estuaire du Wouri ; les marins, frappés par l'abondance des crevettes, le nomment <strong>Rio dos Camarões</strong>, la « rivière des crevettes » : c'est l'origine du nom <strong>Cameroun</strong>.</div><div class='attention'><b>Conséquences</b>Premiers contacts commerciaux avec l'Afrique, puis développement de la <strong>traite atlantique</strong> pour fournir des esclaves aux plantations d'Amérique ; destruction des sociétés amérindiennes.</div>","retenir":"1453, 1488, 1492, 1498 ; vers 1472, Rio dos Camarões ; le revers des découvertes : traite et conquêtes."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources (9 points)</h3><p><strong>1.</strong> Présente et analyse deux facteurs qui expliquent la Renaissance en Europe aux XVe et XVIe siècles. Le candidat répondra par un texte de 10 à 15 lignes, en un seul paragraphe. (5 pts)</p><p><strong>2. Texte à corriger (4 pts).</strong> Le texte ci-dessous contient quatre informations erronées.</p><blockquote>« La Renaissance commence en Allemagne au XVe siècle. Gutenberg y invente la boussole vers 1450. Les humanistes, comme Érasme, veulent revenir aux textes de l'Antiquité. En 1543, Galilée publie un ouvrage qui place la Terre au centre de l'univers. Les princes deviennent mécènes des artistes. »</blockquote><p>a) Relève les quatre informations erronées. (2 pts) b) Réécris le texte en corrigeant ces erreurs. (2 pts)</p><details><summary>Voir le corrigé de la première partie</summary><p><strong>1.</strong> Préambule : aux XVe-XVIe siècles, l'Europe connaît un renouveau des arts, des lettres et des sciences appelé Renaissance. Éléments : l'invention de l'imprimerie par Gutenberg vers 1450, qui diffuse rapidement les livres et les idées ; la redécouverte des auteurs grecs et latins par les humanistes, favorisée par l'arrivée de savants byzantins en Italie après 1453 ; on peut aussi citer le mécénat des princes et des riches marchands. Explications : ces facteurs permettent la circulation du savoir et financent les artistes. Bilan : la Renaissance naît de la conjonction d'innovations techniques, intellectuelles et économiques.</p><p><em>Barème : préambule 1 pt (existence 0,5, pertinence 0,5) ; deux éléments 2 pts ; explications 1 pt ; bilan 1 pt.</em></p><p><strong>2.</strong> Erreurs : 1) en Allemagne → en Italie ; 2) la boussole → l'imprimerie à caractères mobiles ; 3) Galilée → Copernic ; 4) la Terre au centre → le Soleil au centre (héliocentrisme). Texte corrigé : « La Renaissance commence en Italie au XVe siècle. Gutenberg invente l'imprimerie à caractères mobiles vers 1450. Les humanistes, comme Érasme, veulent revenir aux textes de l'Antiquité. En 1543, Copernic publie un ouvrage qui place le Soleil au centre de l'univers. Les princes deviennent mécènes des artistes. »</p></details><h3>Deuxième partie : l'évaluation des compétences (9 points)</h3><p><strong>Thème : Promotion de la culture et de l'esprit critique</strong></p><p><strong>Document 1 : Un idéal humaniste</strong></p><blockquote>« Science sans conscience n'est que ruine de l'âme. »</blockquote><p><em>Source : François Rabelais, <i>Pantagruel</i>, 1532, chapitre VIII (lettre de Gargantua à son fils).</em></p><p><strong>Document 2 : Quelques repères de la Renaissance</strong></p><table><tr><th>Date</th><th>Événement</th></tr><tr><td>vers 1450</td><td>Imprimerie à caractères mobiles de Gutenberg (Mayence)</td></tr><tr><td>1492</td><td>Christophe Colomb atteint l'Amérique</td></tr><tr><td>1503-1506</td><td>Léonard de Vinci peint <i>La Joconde</i></td></tr><tr><td>1543</td><td>Copernic publie sa théorie héliocentrique</td></tr></table><p><em>Source : Réalisation VÉRITAS, d'après le programme d'histoire de Première.</em></p><p><strong>Consigne.</strong> À partir des documents et de tes connaissances, rédige une production cohérente dont les grandes lignes reposent sur les tâches suivantes :</p><ol><li>Explique le sens de la phrase de Rabelais et montre qu'elle résume l'idéal humaniste. (3 pts)</li><li>Montre, à partir du document 2 et de tes connaissances, que la Renaissance est un renouveau à la fois artistique, scientifique et géographique. (3 pts)</li><li>Propose deux actions pour que les jeunes Camerounais développent aujourd'hui leur esprit critique face aux informations qu'ils reçoivent. (3 pts)</li></ol><p><em>Ta production comportera trois paragraphes, sans numéros ni tirets. Présentation : 2 points.</em></p><details><summary>Voir le corrigé de la deuxième partie</summary><p>Tâche 1 : pour Rabelais, le savoir doit s'accompagner de morale et de jugement ; l'humanisme place l'homme au centre, valorise l'éducation complète, le retour aux textes anciens et l'esprit critique. Tâche 2 : renouveau artistique (Léonard de Vinci), scientifique (Copernic, héliocentrisme), technique (imprimerie) et géographique (voyage de Colomb, 1492). Tâche 3 : créer des clubs de lecture et de débat dans les établissements ; apprendre à vérifier les sources des informations reçues sur les réseaux sociaux.</p><p><em>Barème de chaque tâche : pertinence 1 pt, correction de la langue 1 pt, cohérence 1 pt. Présentation : 2 pts.</em></p></details></div>","retenir":"Savoir-être mobilisé : esprit critique et devoir de mémoire."}],"revision":["<strong>Renaissance</strong> (XVᵉ-XVIᵉ s.) : renouveau né en Italie, inspiré de l'Antiquité.","<strong>Humanisme</strong> : l'homme au centre ; imprimerie de Gutenberg (vers 1455).","Vinci, Michel-Ange ; <strong>Copernic</strong> 1543 ; <strong>Luther</strong> 1517.","Découvertes : 1488 Dias, <strong>1492</strong> Colomb, 1498 Vasco de Gama.","Vers 1472 : Fernando Póo, <strong>Rio dos Camarões</strong>."],"exo":"<p>Associe chaque date à son événement : 1455, 1492, 1517, 1543. <em>(Réponse : 1455 : Bible de Gutenberg ; 1492 : Colomb en Amérique ; 1517 : thèses de Luther ; 1543 : Copernic, héliocentrisme.)</em></p>","quiz":[{"q":"La Renaissance est née en :","r":["Italie","Angleterre","Espagne","Allemagne"],"b":0,"e":"Florence, Rome et Venise en sont les grands foyers."},{"q":"L'imprimerie à caractères mobiles est mise au point par :","r":["Copernic","Gutenberg","Érasme","Luther"],"b":1,"e":"À Mayence, Bible vers 1455."},{"q":"<em>Éloge de la folie</em> est d'un humaniste :","r":["Rabelais","Montaigne","Érasme","Thomas More"],"b":2,"e":"Érasme, 1511."},{"q":"Copernic affirme que :","r":["la Terre est plate","le Soleil tourne autour de la Terre","la Lune est une planète","la Terre tourne autour du Soleil"],"b":3,"e":"L'héliocentrisme, 1543."},{"q":"La Réforme protestante commence en :","r":["1517","1492","1453","1545"],"b":0,"e":"Martin Luther et les 95 thèses."},{"q":"Christophe Colomb atteint l'Amérique en :","r":["1488","1492","1498","1522"],"b":1,"e":"Au service des rois d'Espagne."},{"q":"Le nom « Cameroun » vient de :","r":["un roi douala","un fleuve du Nord","Rio dos Camarões, la rivière des crevettes","un mot allemand"],"b":2,"e":"Nom donné par les Portugais à l'estuaire du Wouri."},{"q":"La prise de Constantinople par les Ottomans date de :","r":["1517","1492","1498","1453"],"b":3,"e":"Elle pousse les Européens à chercher d'autres routes vers l'Asie."},{"q":"Une conséquence dramatique des grandes découvertes pour l'Afrique est :","r":["la traite atlantique","l'imprimerie","l'humanisme","la Contre-Réforme"],"b":0,"e":"Déportation de millions d'Africains vers l'Amérique."},{"q":"La caravelle, la boussole et l'astrolabe sont :","r":["des œuvres d'art","des progrès techniques de navigation","des livres humanistes","des religions"],"b":1,"e":"Ils rendent possibles les voyages au long cours."}],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les transformations de l'Europe et leurs effets sur l'Afrique","situation":"Un guide du musée maritime de Douala prépare une visite pour des collégiens. Il veut leur expliquer d'où vient le nom « Cameroun » et pourquoi l'arrivée des Portugais au XVᵉ siècle a eu des effets à la fois positifs et dramatiques.","tache":"Rédiger un texte qui explique le nom et les deux faces des contacts avec les Portugais."},"gratuit":true});
VRT_L("1re-d-philo-origine-objet",{"c":"1re D","m":"philo","rang":2,"titre":"Origine et objet de la philosophie","duree":25,"accroche":"La philosophie est-elle née en Grèce, ou y a-t-elle seulement pris son nom ?","intro":"On enseigne souvent que la philosophie est née en Grèce au VIᵉ siècle avant notre ère, comme par « miracle ». Des historiens africains ont contesté ce récit en rappelant la dette des Grecs envers l'Égypte. Après l'origine, il faut aussi se demander de quoi s'occupe la philosophie.","objectifs":["expliquer les conditions de naissance de la philosophie en Grèce","présenter la thèse du « miracle grec » et sa critique","définir l'objet de la philosophie"],"parties":[{"t":"La naissance de la philosophie en Grèce","html":"<p>Au VIᵉ siècle av. J.-C., en Ionie (côte de l'actuelle Turquie), à <strong>Milet</strong>, des penseurs cherchent à expliquer la nature par des causes naturelles et non par les dieux : on passe du <strong>mythos</strong> (récit mythique) au <strong>logos</strong> (discours rationnel).</p><ul><li><strong>Thalès</strong> : le principe (arkhè) de toutes choses est l'eau.</li><li><strong>Anaximène</strong> : l'air ; <strong>Héraclite</strong> : le feu et le changement perpétuel ; <strong>Pythagore</strong> : le nombre.</li></ul><div class='def'><b>Les conditions</b>La <strong>cité</strong> (polis) où l'on débat sur l'agora ; l'<strong>écriture alphabétique</strong> ; le <strong>loisir</strong> (scholè) des citoyens ; le commerce et les voyages, qui mettent en contact avec d'autres savoirs.</div>","retenir":"Milet, VIᵉ s. av. J.-C. : du mythos au logos ; Thalès, l'eau principe de toute chose."},{"t":"« Miracle grec » ou héritage égyptien ?","verrou":true},{"t":"L'objet de la philosophie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Montrer l'universalité de la démarche philosophique","situation":"En 1re D à Kribi, un élève déclare pendant l'exposé : « La philosophie, c'est un truc d'Européens ; nous, Africains, nous n'avons rien à y faire. »","tache":"Lui répondre en s'appuyant sur l'origine et l'objet de la philosophie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-ponctuation",{"c":"1re D","m":"francais","rang":4,"titre":"Morphosyntaxe : la ponctuation, rôles et emplois","duree":55,"accroche":"« Mangeons, les enfants ! » ou « Mangeons les enfants ! » : une virgule sauve des vies.","intro":"Leçon de langue (rubrique Morphosyntaxe). On observe un même communiqué ponctué de deux façons, on découvre comment la ponctuation organise la phrase et change le sens, puis on formule la règle et on s'entraîne au format de l'épreuve : repérage, analyse, interprétation.","objectifs":["identifier les signes de ponctuation et leurs rôles","employer correctement la virgule, le point-virgule et les deux-points","analyser les effets de la ponctuation dans un texte littéraire"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (phrases composées pour la leçon) :</p><blockquote>1. « Le proviseur dit : “Le délégué est absent.” »<br>2. « Le proviseur, dit le délégué, est absent. »<br>3. « Attention ! Les élèves qui n'ont pas leur tenue ne composeront pas. »<br>4. « Attention ! Les élèves, qui n'ont pas leur tenue, ne composeront pas. »<br>5. « Ils avaient tout préparé : les chaises, les tables, les micros… Personne ne vint. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Dans les phrases 1 et 2, qui est absent ? Quels signes changent le sens ?</li><li>Dans les phrases 3 et 4, tous les élèves sont-ils concernés ? Explique le rôle des virgules.</li><li>Dans la phrase 5, à quoi servent les deux-points ? et les points de suspension ?</li><li>Quels signes terminent une phrase ? Lesquels sont à l'intérieur de la phrase ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Phrase 1 : le délégué est absent (paroles rapportées entre guillemets après les deux-points) ; phrase 2 : le proviseur est absent (« dit le délégué » est une incise entre virgules). 2. Phrase 3 : seuls ceux qui n'ont pas leur tenue (relative <strong>déterminative</strong>, sans virgules) ; phrase 4 : tous les élèves, car la relative entre virgules est <strong>explicative</strong> (tous n'ont pas leur tenue). 3. Les deux-points annoncent une <strong>énumération</strong> ; les points de suspension marquent une <strong>énumération inachevée</strong> et préparent la chute. 4. Point, point d'interrogation, point d'exclamation, points de suspension terminent la phrase ; virgule, point-virgule, deux-points, guillemets, tirets, parenthèses sont à l'intérieur.</p></details><div class='def'><b>Ce que montre l'observation</b>La <strong>ponctuation</strong> est l'ensemble des signes qui organisent l'écrit : elle délimite les phrases, structure leurs éléments, rapporte les paroles, et peut <strong>changer le sens</strong> d'un énoncé.</div>","retenir":"La ponctuation délimite, organise, rapporte les paroles et peut changer le sens."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Ponctuer correctement un écrit pour qu'il soit compris sans ambiguïté","situation":"Le communiqué suivant doit être affiché au lycée bilingue de Buea : « attention les élèves de 1re C et D qui n'ont pas payé l'APEE ne composeront pas lundi le proviseur recevra les parents mardi à 9 heures »","tache":"Rétablir la ponctuation et justifier trois signes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-industrialisation",{"c":"1re D","m":"histoire","rang":2,"titre":"L'industrialisation de l'Europe (XVIIIᵉ-XIXᵉ siècles)","duree":25,"accroche":"La machine à vapeur a changé l'Europe… puis le destin de l'Afrique.","intro":"À partir de la fin du XVIIIᵉ siècle, l'Europe passe d'une économie agricole et artisanale à une économie industrielle fondée sur les machines, le charbon et les usines. Cette révolution transforme les sociétés européennes et pousse les puissances industrielles à conquérir de nouveaux territoires, notamment en Afrique.","objectifs":["expliquer les causes et les étapes de la révolution industrielle","décrire ses conséquences économiques et sociales","établir le lien entre industrialisation et impérialisme en Afrique"],"parties":[{"t":"La première révolution industrielle","html":"<p>Elle commence en <strong>Grande-Bretagne</strong> vers <strong>1760-1780</strong>, puis gagne la France, la Belgique et l'Allemagne au XIXᵉ siècle.</p><div class='def'><b>Les causes</b>Une <strong>révolution agricole</strong> qui nourrit plus d'habitants et libère de la main-d'œuvre ; une <strong>croissance démographique</strong> ; des <strong>capitaux</strong> issus du commerce, y compris le commerce triangulaire ; du <strong>charbon</strong> et du <strong>fer</strong> en abondance ; des inventions.</div><ul><li><strong>Textile</strong> : navette volante (Kay, 1733), machines à filer.</li><li><strong>Machine à vapeur</strong> perfectionnée par <strong>James Watt</strong> (1769).</li><li><strong>Chemin de fer</strong> : locomotive de Stephenson ; ligne Liverpool-Manchester (1830) ; bateaux à vapeur.</li></ul>","retenir":"Grande-Bretagne, fin du XVIIIᵉ siècle : charbon, fer, textile, machine à vapeur (Watt), chemin de fer."},{"t":"La deuxième révolution industrielle","verrou":true},{"t":"Conséquences : sociétés nouvelles et expansion coloniale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Expliquer l'origine historique de la place de l'Afrique dans les échanges mondiaux","situation":"Lors d'une sortie au port de Douala, tu observes des grumes de bois et des fèves de cacao chargées vers l'Europe, et des voitures et des machines déchargées. Ton camarade demande : « Pourquoi exportons-nous des produits bruts et importons-nous des produits finis ? »","tache":"Expliquer l'origine de cette situation et proposer une piste de changement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-methode",{"c":"1re D","m":"philo","rang":3,"titre":"La méthode de la philosophie","duree":25,"accroche":"Le physicien a son laboratoire ; le philosophe a sa méthode.","intro":"La philosophie n'utilise ni microscope ni expérience de laboratoire. Elle avance pourtant avec méthode : elle questionne, définit, problématise, argumente. Des philosophes ont même décrit leur méthode, de Socrate à Descartes. Ces outils te serviront dans toutes les disciplines.","objectifs":["identifier les étapes de la démarche philosophique","présenter la méthode socratique et la méthode cartésienne","appliquer la démarche à une question de la vie courante"],"parties":[{"t":"Les quatre gestes du philosophe","html":"<div class='def'><b>Définition</b>Une <strong>méthode</strong> (du grec <em>methodos</em>, « chemin vers ») est une démarche ordonnée pour parvenir à la vérité. En philosophie, elle consiste à questionner, définir, problématiser et argumenter.</div><ol><li><strong>Questionner</strong> : transformer une évidence en question (« Est-il toujours juste d'obéir à la loi ? »).</li><li><strong>Conceptualiser</strong> : définir précisément les notions, distinguer les sens (loi juridique, loi morale, loi scientifique).</li><li><strong>Problématiser</strong> : montrer pourquoi la question fait difficulté, en opposant des réponses possibles.</li><li><strong>Argumenter</strong> : justifier chaque affirmation par des raisons, des exemples, des références, et examiner les objections.</li></ol><div class='astuce'><b>Astuce</b>Ces quatre gestes sont exactement ceux de la dissertation : introduction (questionner, définir, problématiser), développement (argumenter).</div>","retenir":"Questionner, conceptualiser, problématiser, argumenter."},{"t":"La méthode socratique","verrou":true},{"t":"La méthode cartésienne et la dialectique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Appliquer une méthode rigoureuse pour examiner une information","situation":"Un message circule dans le groupe WhatsApp de ta classe à Bafia : « Boire de l'eau chaude avec du citron guérit le paludisme. Partagez ! »","tache":"Examiner le message avec la méthode cartésienne et la démarche philosophique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-narratif",{"c":"1re D","m":"francais","rang":5,"titre":"Stylistique : le texte narratif","duree":55,"accroche":"Un narrateur, des personnages, une intrigue : tout récit obéit à une architecture.","intro":"Leçon de langue (rubrique Stylistique, types de textes). On observe un court récit, on découvre ses marques (temps, narrateur, structure), puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier le narrateur et les points de vue","appliquer le schéma narratif et le schéma actantiel","dégager les fonctions d'un récit"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (récit composé pour la leçon) :</p><blockquote>« Ce matin-là, le vieux pêcheur Ebénézer poussa sa pirogue vers le large. La mer était calme et le ciel, d'un bleu parfait. Soudain, le vent se leva ; les vagues grossirent et l'embarcation se mit à tanguer. Ebénézer rama de toutes ses forces. Après une heure de lutte, il aperçut enfin la plage de Kribi. Depuis ce jour, il ne sort plus sans regarder le ciel. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Qui raconte l'histoire ? Le narrateur participe-t-il à l'action ?</li><li>Relève les verbes au passé simple et à l'imparfait. Lesquels font avancer l'action ? Lesquels décrivent le décor ?</li><li>Découpe le récit en cinq moments.</li><li>Relève les indicateurs de temps. Quel rôle jouent-ils ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Un narrateur extérieur à l'histoire (3e personne) : <strong>narrateur hétérodiégétique</strong>. 2. Passé simple (poussa, se leva, rama, aperçut) : actions de premier plan ; imparfait (était) : arrière-plan, description. 3. <strong>Situation initiale</strong> (la mer calme), <strong>élément perturbateur</strong> (le vent se leva), <strong>péripéties</strong> (vagues, lutte), <strong>dénouement</strong> (la plage), <strong>situation finale</strong> (il regarde le ciel). 4. Ce matin-là, soudain, après une heure, enfin, depuis ce jour : ils organisent la chronologie et marquent les étapes.</p></details><div class='def'><b>Ce que montre l'observation</b>Le <strong>texte narratif</strong> raconte une suite d'événements organisés dans le temps, par un <strong>narrateur</strong>, selon un <strong>schéma narratif</strong>, avec une alternance de temps (passé simple et imparfait, ou présent de narration).</div>","retenir":"Narrateur, schéma narratif, temps du récit, indicateurs chronologiques."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Analyser et construire un récit à l'aide des outils de la narratologie","situation":"Pour le concours de nouvelles du club de lecture de ton lycée à Edéa, tu dois écrire un récit court sur un jeune qui quitte son village pour chercher du travail à Douala.","tache":"Établir les schémas narratif et actantiel, le narrateur, la focalisation et la fonction du récit."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-recherche-idees",{"c":"1re D","m":"francais","rang":6,"titre":"La dissertation : rechercher les idées et les exemples","duree":25,"accroche":"Une page blanche n'est pas un manque d'idées : c'est un manque de méthode.","intro":"Une fois le sujet analysé et la problématique posée, beaucoup d'élèves restent bloqués : « je n'ai pas d'idées ». La recherche des idées est pourtant une technique, qui s'apprend : questionner le sujet, puiser dans ses lectures, classer ce que l'on trouve. C'est l'étape qui prépare le plan.","objectifs":["utiliser des techniques pour trouver des arguments","choisir des exemples littéraires précis et pertinents","classer les idées pour préparer un plan"],"parties":[{"t":"Trouver des arguments","html":"<ol><li><strong>Le remue-méninges</strong> : noter au brouillon, sans trier, tout ce que le sujet évoque (idées, œuvres, auteurs, souvenirs de lecture).</li><li><strong>Les questions clés</strong> : Pourquoi ? Comment ? Dans quels cas ? Jusqu'à quel point ? Pour qui ?</li><li><strong>Le pour et le contre</strong> : chercher ce qui justifie la thèse du sujet, puis ce qui la limite.</li><li><strong>Les notions voisines</strong> : un sujet sur le roman fait penser au lecteur, au réalisme, à l'engagement, au plaisir.</li></ol><div class='def'><b>Argument et exemple</b>L'<strong>argument</strong> est une idée générale qui justifie une affirmation ; l'<strong>exemple</strong> est un fait précis (une œuvre, une scène, un personnage) qui illustre l'argument.</div>","retenir":"Remue-méninges, questions clés, pour et contre, notions voisines ; argument ≠ exemple."},{"t":"Choisir de bons exemples","verrou":true},{"t":"Classer les idées","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Rechercher et organiser des idées pour construire une dissertation","situation":"En devoir à Sangmélima, le sujet est : « La lecture des œuvres littéraires est-elle encore utile à l'ère du numérique ? » Ta voisine a écrit au brouillon : « oui c'est utile », et rien d'autre.","tache":"Proposer des arguments avec exemples et les classer en plan."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-imperialisme",{"c":"1re D","m":"histoire","rang":3,"titre":"Les fondements de l'impérialisme européen","duree":25,"accroche":"Pourquoi l'Europe a-t-elle voulu se partager l'Afrique à la fin du XIXᵉ siècle ?","intro":"Entre 1880 et 1914, les puissances européennes se lancent dans une course aux colonies : en une trentaine d'années, presque toute l'Afrique est conquise et partagée. Cette expansion, appelée impérialisme, a des causes économiques, politiques, démographiques, idéologiques et scientifiques, que les Européens de l'époque exposaient sans détour.","objectifs":["définir l'impérialisme","expliquer ses fondements économiques, politiques, démographiques et idéologiques","porter un regard critique sur les justifications de la colonisation"],"parties":[{"t":"Définition et fondements économiques","html":"<div class='def'><b>Définition</b>L'<strong>impérialisme</strong> est la volonté d'un État d'étendre sa domination politique, économique et culturelle sur d'autres territoires et peuples. La <strong>colonisation</strong> en est la forme la plus directe.</div><ul><li>Les industries européennes ont besoin de <strong>matières premières</strong> (caoutchouc, huile de palme, coton, cacao, minerais).</li><li>Elles cherchent des <strong>débouchés</strong> pour leurs produits manufacturés, protégés par le <strong>protectionnisme</strong> des pays rivaux.</li><li>Les banques veulent placer des <strong>capitaux</strong> dans des investissements rentables (chemins de fer, mines, plantations).</li></ul><div class='ex'><b>Jules Ferry (1885)</b>« La politique coloniale est fille de la politique industrielle. »</div>","retenir":"Impérialisme : domination ; fondements économiques : matières premières, débouchés, capitaux."},{"t":"Fondements politiques et démographiques","verrou":true},{"t":"Fondements idéologiques, religieux et scientifiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Analyser les fondements de l'impérialisme avec un regard critique","situation":"Lors d'une exposition au musée national de Yaoundé, un visiteur affirme devant une carte de l'Afrique en 1914 : « Les Européens sont venus pour nous civiliser, c'était une bonne chose. »","tache":"Lui répondre en exposant les vrais fondements de l'impérialisme et les limites de cet argument."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-dissertation",{"c":"1re D","m":"francais","rang":3,"titre":"Dissertation littéraire : analyser le sujet et formuler la problématique","duree":25,"accroche":"Le sujet contient déjà la moitié de la copie : encore faut-il savoir le lire.","intro":"La dissertation littéraire demande de discuter une opinion sur la littérature (le roman, la poésie, le théâtre, le rôle de l'écrivain) à partir de tes lectures. Les copies échouent rarement par manque d'idées : elles échouent parce que le sujet a été mal lu. Cette leçon apprend à le décortiquer.","objectifs":["identifier les éléments d'un sujet de dissertation","analyser les mots clés et la thèse proposée","formuler une problématique pertinente"],"parties":[{"t":"Les éléments d'un sujet","html":"<p>Un sujet de dissertation comprend en général :</p><ul><li>une <strong>citation</strong> ou une affirmation (souvent d'un écrivain ou d'un critique) ;</li><li>une <strong>consigne</strong> : « Commentez », « Discutez », « Partagez-vous ce point de vue ? », « Vous illustrerez votre réponse d'exemples précis ».</li></ul><div class='def'><b>Les types de consigne</b><strong>Explicative</strong> (« expliquez », « justifiez ») : on montre que la thèse est juste. <strong>Dialectique</strong> (« discutez », « partagez-vous… ») : on examine la thèse puis ses limites. <strong>Comparative</strong> : on confronte deux thèses.</div><div class='attention'><b>Attention</b>La consigne commande le plan : « discutez » appelle un plan dialectique, « expliquez » un plan analytique.</div>","retenir":"Citation + consigne ; c'est la consigne qui décide du type de plan."},{"t":"Analyser les mots clés","verrou":true},{"t":"Formuler la problématique","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première D","famille":"Vie sociale et culturelle","agir":"Analyser un sujet de dissertation pour construire une réflexion pertinente","situation":"Le club de lecture de ton lycée à Limbé prépare un débat. Sujet affiché : « L'écrivain africain doit être un combattant. » Discutez cette affirmation en vous appuyant sur des exemples précis.","tache":"Analyser le sujet et formuler une problématique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-importance",{"c":"1re D","m":"philo","rang":4,"titre":"L'importance de la philosophie","duree":25,"accroche":"« Vivre sans philosopher, c'est avoir les yeux fermés. » (Descartes)","intro":"« À quoi sert la philosophie ? » La question revient souvent, surtout en série scientifique. Elle ne produit ni pont ni médicament. Pourtant, elle forme le jugement, libère des préjugés, éclaire nos choix et ceux de la société. Cette leçon examine son utilité pour l'individu et pour l'Afrique.","objectifs":["présenter les apports de la philosophie à l'individu","montrer son rôle dans la société et le développement","répondre aux critiques qui la jugent inutile"],"parties":[{"t":"Pour l'individu","html":"<div class='def'><b>Définition</b>L'<strong>importance</strong> de la philosophie désigne la valeur et les services qu'elle rend : former un esprit libre, capable de juger par lui-même et de bien conduire sa vie.</div><ul><li><strong>Libérer des préjugés</strong> : Descartes : « C'est proprement avoir les yeux fermés, sans tâcher jamais de les ouvrir, que de vivre sans philosopher » (<em>Principes</em>, préface).</li><li><strong>Apprendre à bien vivre</strong> : Épicure : il n'est jamais trop tôt ni trop tard pour philosopher, car il s'agit de la santé de l'âme (<em>Lettre à Ménécée</em>).</li><li><strong>Former l'esprit critique</strong> : raisonner, argumenter, repérer les sophismes.</li></ul>","retenir":"Pour l'individu : liberté de jugement, art de bien vivre, esprit critique."},{"t":"Pour la société et l'Afrique","verrou":true},{"t":"Répondre aux critiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Justifier l'utilité de la philosophie pour un futur scientifique","situation":"Le conseil de classe de 1re D d'un lycée de Kumba propose de supprimer les heures de philosophie pour ajouter des heures de SVT avant le probatoire.","tache":"Rédiger une dissertation courte sur l'utilité de la philosophie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-science",{"c":"1re D","m":"philo","rang":5,"titre":"Philosophie et science : quels rapports ?","duree":25,"accroche":"« Science sans conscience n'est que ruine de l'âme. » (Rabelais)","intro":"Pendant des siècles, philosophie et science ne faisaient qu'un. Puis les sciences se sont séparées et ont conquis le savoir sur la nature. Faut-il en conclure que la philosophie est dépassée ? Ou les deux démarches restent-elles complémentaires ?","objectifs":["distinguer démarche scientifique et démarche philosophique","présenter l'histoire de leurs rapports","montrer leur complémentarité"],"parties":[{"t":"Deux démarches distinctes","html":"<div class='def'><b>Définitions</b>La <strong>science</strong> est une connaissance <strong>objective</strong>, <strong>méthodique</strong> et <strong>vérifiable</strong> des phénomènes, qui établit des lois par l'observation, l'hypothèse et l'expérimentation. La <strong>philosophie</strong> est une réflexion critique sur les <strong>fondements</strong>, le <strong>sens</strong> et les <strong>valeurs</strong>.</div><ul><li>La science répond à la question <strong>comment ?</strong> ; la philosophie à <strong>pourquoi ?</strong> et <strong>que vaut ?</strong></li><li>La science spécialise ; la philosophie cherche une vue d'ensemble.</li></ul>","retenir":"Science : comment, lois vérifiables ; philosophie : fondements, sens, valeurs."},{"t":"Une histoire de séparation","verrou":true},{"t":"Une complémentarité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Environnement, santé et bien-être","agir":"Articuler science et éthique pour protéger les personnes","situation":"Un laboratoire propose à des familles de Bertoua de tester gratuitement un nouveau médicament sur leurs enfants, sans leur expliquer les risques.","tache":"Rédiger une dissertation courte sur les rapports entre science et philosophie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-conquetes-francaises",{"c":"1re D","m":"histoire","rang":5,"titre":"Les conquêtes françaises en Afrique","duree":25,"accroche":"De Dakar au lac Tchad : la France taille un empire à coups de colonnes militaires.","intro":"Entre 1830 et 1912, la France conquiert un immense domaine en Afrique du Nord, de l'Ouest, du Centre et à Madagascar. Elle se heurte partout à des résistances. Une de ses batailles décisives se déroule sur le sol actuel du Cameroun, à Kousséri.","objectifs":["situer les étapes et les zones des conquêtes françaises","décrire les méthodes de conquête","présenter les grandes résistances et l'organisation des colonies (AOF, AEF)"],"parties":[{"t":"Les étapes de la conquête","html":"<div class='def'><b>Définition</b>La <strong>conquête coloniale</strong> est la prise de contrôle militaire, politique et économique d'un territoire et de ses habitants par une puissance étrangère.</div><ul><li><strong>Afrique du Nord</strong> : Algérie (à partir de 1830), protectorats sur la Tunisie (1881) et le Maroc (1912).</li><li><strong>Afrique de l'Ouest</strong> : à partir du Sénégal (gouverneur Faidherbe, 1854-1865), pénétration vers le Niger ; Dahomey (1892-1894).</li><li><strong>Afrique centrale</strong> : Savorgnan de Brazza signe le traité avec le roi Makoko (1880) ; vers le Tchad.</li><li><strong>Madagascar</strong> : conquise en 1895-1896.</li></ul>","retenir":"Algérie 1830, Tunisie 1881, Maroc 1912 ; Sénégal-Niger ; Congo-Tchad ; Madagascar 1896."},{"t":"Les méthodes et les résistances","verrou":true},{"t":"L'organisation de l'empire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les conquêtes coloniales et en garder une mémoire juste","situation":"En visite à Kousséri, un groupe d'élèves de Maroua découvre une stèle commémorant la bataille de 1900, qui ne cite que les officiers français.","tache":"Rédiger un panneau complémentaire sur la bataille, Rabah et les populations."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-conquetes-anglaises",{"c":"1re D","m":"histoire","rang":6,"titre":"Les conquêtes anglaises en Afrique","duree":25,"accroche":"« Du Cap au Caire » : le rêve d'un empire britannique d'un bout à l'autre de l'Afrique.","intro":"Première puissance industrielle et maritime du XIXᵉ siècle, la Grande-Bretagne veut contrôler les routes vers l'Inde et les richesses de l'Afrique. Elle conquiert l'Égypte, le Soudan, l'Afrique australe, une partie de l'Afrique de l'Ouest et de l'Est, en se heurtant à de fortes résistances, et gouverne souvent par l'intermédiaire des chefs locaux.","objectifs":["situer les principales conquêtes britanniques","présenter les résistances africaines","expliquer l'indirect rule"],"parties":[{"t":"Les grandes zones de conquête","html":"<div class='def'><b>Définition</b>L'<strong>Empire britannique</strong> est l'ensemble des territoires dominés par la Grande-Bretagne ; en Afrique, il vise la maîtrise des routes vers l'Inde (canal de Suez, Le Cap) et des ressources (or, diamants, huile de palme).</div><ul><li><strong>Égypte</strong> : occupée en 1882 (bataille de Tell el-Kébir) pour contrôler le canal de Suez.</li><li><strong>Soudan</strong> : Kitchener écrase les mahdistes à <strong>Omdurman</strong> (1898).</li><li><strong>Afrique australe</strong> : colonie du Cap ; Cecil Rhodes et sa compagnie conquièrent les Rhodésies ; guerre contre les Boers (1899-1902).</li><li><strong>Afrique de l'Ouest</strong> : Nigeria (Lagos 1861, Royal Niger Company), Gold Coast (Ghana), Sierra Leone, Gambie.</li><li><strong>Afrique de l'Est</strong> : Kenya, Ouganda.</li></ul>","retenir":"Égypte (1882), Soudan (1898), Afrique australe (Rhodes, Boers), Nigeria, Gold Coast, Kenya."},{"t":"Les résistances","verrou":true},{"t":"L'administration : l'indirect rule","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les héritages coloniaux pour renforcer l'unité nationale","situation":"Lors d'un débat au lycée bilingue de Buea, un élève demande pourquoi les régions du Nord-Ouest et du Sud-Ouest ont un système scolaire et juridique différent.","tache":"Expliquer l'origine historique de cette différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-enonciation",{"c":"1re D","m":"francais","rang":7,"titre":"Communication : l'énonciation, marques explicites et implicites","duree":55,"accroche":"Qui parle, à qui, quand, où ? Et que dit-il sans le dire ?","intro":"Leçon de langue (rubrique Communication). On observe un message affiché dans un lycée, on y repère qui parle, à qui, où et quand, et ce qui est dit sans être écrit, puis on formule la règle et on s'entraîne au format de l'épreuve : repérage, analyse, interprétation.","objectifs":["identifier la situation d'énonciation","repérer les marques explicites (indices personnels, déictiques, modalisateurs)","dégager les marques implicites (présupposés, sous-entendus)"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (texte composé pour la leçon) :</p><blockquote>« Chers camarades, ici, dans notre lycée d'Ebolowa, nous avons encore trouvé des papiers sous les tables ce matin. Je vous demande, une dernière fois, de respecter la salle. Sans doute certains pensent-ils que d'autres nettoieront à leur place… Merci à ceux qui gardent la classe aussi propre que d'habitude ! — Le délégué. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Qui parle ? À qui ? Où ? Quand ? Relève les mots qui l'indiquent.</li><li>Ces mots auraient-ils le même sens écrits par quelqu'un d'autre, ailleurs, un autre jour ?</li><li>Relève les mots qui montrent l'opinion ou le sentiment de l'émetteur.</li><li>La dernière phrase est-elle un vrai remerciement ? Qu'entend-on derrière ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Émetteur : le délégué (« je », signature) ; récepteurs : les camarades (« vous », « Chers camarades ») ; lieu : « ici, dans notre lycée d'Ebolowa » ; moment : « ce matin ». 2. Non : « je », « vous », « ici », « ce matin » ne prennent leur sens que dans la situation : ce sont des <strong>déictiques</strong>. 3. « encore », « une dernière fois », « sans doute » : agacement et doute (<strong>modalisateurs</strong>). 4. Non : c'est de l'<strong>ironie</strong> ; le message implicite est que la classe est sale et que certains sont visés.</p></details><div class='def'><b>Ce que montre l'observation</b>L'<strong>énonciation</strong> est l'acte de produire un énoncé dans une situation donnée : qui parle, à qui, où, quand. Les <strong>marques explicites</strong> (pronoms personnels, déictiques de lieu et de temps, temps verbaux) la rendent visible ; les <strong>marques implicites</strong> (modalisateurs, ironie, sous-entendus) disent l'attitude de l'émetteur sans la déclarer.</div>","retenir":"Énonciation : qui, à qui, où, quand ; marques explicites (déictiques) et implicites (modalisateurs, ironie, sous-entendus)."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Analyser les marques de l'énonciation pour comprendre les intentions d'un message","situation":"Sur le tableau d'affichage de ton lycée à Ebolowa, un élève a écrit : « Merci à ceux qui gardent les toilettes aussi propres que d'habitude… Certains se reconnaîtront. »","tache":"Analyser la situation d'énonciation, les marques explicites et implicites et l'effet produit."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-modals",{"c":"1re D","m":"anglais","rang":2,"titre":"Modals: permission, possibility, obligation, advice and deduction","duree":25,"accroche":"May I go out? You must be tired! You needn't come: small words, big differences.","intro":"Modal verbs (can, may, must, should…) add an attitude to the main verb: permission, ability, possibility, obligation, advice or deduction. They are tested in almost every Probatoire and Baccalauréat paper.","objectifs":["form sentences with modal verbs","choose the right modal for permission, possibility, obligation, absence of obligation and advice","use must and can't for deduction"],"parties":[{"t":"What is a modal verb?","html":"<div class='def'><b>Definition</b>A <strong>modal verb</strong> is an auxiliary placed before a <strong>bare infinitive</strong> (without « to ») to express the speaker's attitude. It never takes « -s » and makes its question and negative without « do »: <em>She can swim. Can she swim? She cannot (can't) swim.</em></div><ul><li><strong>Permission</strong>: <em>can</em>, <em>may</em> (more polite): <em>May I come in, sir?</em></li><li><strong>Possibility</strong>: <em>can</em> (general), <em>could</em>, <em>may</em>, <em>might</em> (less sure): <em>It might rain this afternoon.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>Never « He cans » or « She must to go ». Modal + bare infinitive: <em>She must go.</em></div>","retenir":"Modal + bare infinitive; no -s, no do."},{"t":"Obligation, no obligation, advice","verrou":true},{"t":"Deduction","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première D","famille":"Citoyenneté","agir":"Use modal verbs to give rules, advice and permission in real-life situations","situation":"Your school in Kribi is organising a clean-up campaign on the beach on Saturday. As class prefect, you write the rules for your classmates.","tache":"Write a notice using different modals."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-purpose-result",{"c":"1re D","m":"anglais","rang":5,"titre":"Expressing purpose, result and preference; let's / let's not","duree":25,"accroche":"I study hard so that I can pass. It rained so much that the road was closed. I'd rather walk.","intro":"To argue, explain or plan, you must say why you do something (purpose), what happens as a consequence (result) and what you prefer. These structures are essential in essays, letters and dialogues.","objectifs":["express purpose with to, in order to, so as to, so that","express result with so … that, such … that, so, therefore","express preference with prefer, would rather, had better, and make suggestions with let's"],"parties":[{"t":"Purpose","html":"<div class='def'><b>Definition</b><strong>Purpose</strong> is the aim of an action: it answers the question « Why? / What for? ».</div><ul><li><strong>to / in order to / so as to + infinitive</strong> (same subject): <em>She saves money (in order) to buy a laptop.</em> Negative: <em>in order not to / so as not to</em>: <em>He left early so as not to miss the bus.</em></li><li><strong>so that + subject + can / could / will / would</strong> (different subjects possible): <em>The teacher speaks slowly so that everybody can understand.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>« Pour + infinitif » is <em>to</em>, never « for to »: <em>I came to see you</em>, not « for to see you ».</div>","retenir":"to / in order to / so as to + infinitive; so that + subject + can / could."},{"t":"Result","verrou":true},{"t":"Preference, advice and suggestion","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première D","famille":"Vie sociale et culturelle","agir":"Express purpose, result and preference to take decisions in a group","situation":"Your class in Bafoussam wants to raise money for the end-of-year trip. The class meeting must choose between selling snacks at break time and organising a cultural evening.","tache":"Write a dialogue using purpose, result, preference and let's."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-prepositions",{"c":"1re D","m":"anglais","rang":8,"titre":"Prepositions of place, time, manner and direction","duree":20,"accroche":"In Douala, on Monday, at 7 a.m., by taxi, towards the port: prepositions place everything.","intro":"Prepositions are short words, but they cause many mistakes, because they rarely translate word for word from French. This lesson organises them by meaning: place, time, manner and direction.","objectifs":["use prepositions of place and time correctly","use prepositions of direction and manner","avoid the most common French-speaker mistakes"],"parties":[{"t":"Place and time: at, on, in","html":"<div class='def'><b>Definition</b>A <strong>preposition</strong> is a word placed before a noun or pronoun to show its relation to another word: place, time, direction, manner. A <strong>prepositional phrase</strong> is the preposition + its noun: <em>under the table, in the morning</em>.</div><ul><li><strong>Place</strong>: <em>at</em> a point (at the bus stop, at school), <em>on</em> a surface or a street (on the wall, on Joss Street), <em>in</em> an enclosed space, town or country (in the classroom, in Garoua, in Cameroon).</li><li><strong>Time</strong>: <em>at</em> + clock time and festivals (at 7 o'clock, at Christmas), <em>on</em> + days and dates (on Monday, on 20th May), <em>in</em> + months, years, seasons, parts of the day (in May, in 1960, in the dry season, in the morning).</li></ul>","retenir":"at (point / hour), on (surface / day), in (inside / month, year)."},{"t":"Direction and movement","verrou":true},{"t":"Manner and fixed expressions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première D","famille":"Vie sociale et culturelle","agir":"Use prepositions to give precise directions and times","situation":"A pen friend from Ghana is coming to visit you in Buea. She will arrive at the Douala airport and must find your house alone.","tache":"Write an e-mail with precise directions using prepositions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-conditionals",{"c":"1re D","m":"anglais","rang":10,"titre":"Conditionals: types 1, 2 and 3","duree":25,"accroche":"If it rains, we'll stay. If I were rich, I'd build a school. If I had revised, I would have passed.","intro":"Conditional sentences link a condition (the if-clause) and its consequence. English has three main types, each with its own tenses. They are among the most frequent grammar questions at the Probatoire and the Baccalauréat.","objectifs":["form the three types of conditional sentences","choose the type according to the meaning (real, unreal present, unreal past)","use unless, provided that and as long as"],"parties":[{"t":"Type 1: real or possible","html":"<div class='def'><b>Definition</b>A <strong>conditional sentence</strong> has two clauses: the <strong>if-clause</strong> (condition) and the <strong>main clause</strong> (result). <strong>Type 1</strong> describes a <strong>real or likely</strong> situation in the present or future.</div><p class='formule'>If + simple present → will + bare infinitive</p><ul><li><em>If you study hard, you will pass.</em></li><li><em>If it rains, the match will be cancelled.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>No « will » in the if-clause: <em>If he comes</em>, not « If he will come ».</div>","retenir":"Type 1: if + present, will + infinitive (possible)."},{"t":"Type 2: unreal present","verrou":true},{"t":"Type 3 and other conjunctions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première D","famille":"Citoyenneté","agir":"Use conditionals to imagine solutions and express regrets","situation":"Your school's English club in Ngaoundéré organises an essay competition on the topic: « If I were the mayor of my town ».","tache":"Write a short essay using the three types of conditionals."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-pharaonique",{"c":"1re D","m":"philo","rang":6,"titre":"La philosophie de la période pharaonique","duree":25,"accroche":"Deux mille ans avant Socrate, des sages d'Égypte enseignaient déjà la vérité et la justice.","intro":"On fait souvent commencer la philosophie en Grèce. Pourtant, l'Égypte pharaonique, civilisation africaine, a produit des enseignements de sagesse, une réflexion sur l'origine du monde et une morale fondée sur la Maât. Des historiens comme Cheikh Anta Diop et Théophile Obenga y voient la première philosophie africaine.","objectifs":["présenter les grands textes de sagesse de l'Égypte ancienne","expliquer la notion de Maât et la théologie de Memphis","évaluer la place de l'Égypte dans l'histoire de la philosophie"],"parties":[{"t":"Des sages et des enseignements","html":"<div class='def'><b>Définition</b>La <strong>philosophie de la période pharaonique</strong> désigne l'ensemble des réflexions sur le monde, l'homme et la conduite juste produites en Égypte ancienne (environ 2700 à 330 avant notre ère), sous forme de maximes, d'enseignements et de récits de création.</div><ul><li><strong>Imhotep</strong> (vers 2650 av. J.-C.), architecte de la pyramide à degrés de Saqqarah et médecin, vénéré comme un sage.</li><li>Les <strong>Maximes de Ptahhotep</strong> (vers 2400 av. J.-C.) : conseils d'un vizir à son fils sur la modestie, la parole juste, l'écoute.</li><li>Les enseignements de <strong>Kagemni</strong> et d'<strong>Amenemope</strong> : maîtrise de soi, honnêteté, respect du pauvre.</li></ul><div class='ex'><b>Une maxime</b>Ptahhotep : « Ne sois pas orgueilleux de ton savoir ; prends conseil de l'ignorant comme du savant. »</div>","retenir":"Imhotep, Ptahhotep, Kagemni, Amenemope : une sagesse pratique écrite."},{"t":"La Maât et la pensée de l'origine","verrou":true},{"t":"L'Égypte et la philosophie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Situer l'Égypte pharaonique dans l'histoire de la pensée","situation":"Au club d'histoire de ton lycée à Bertoua, un camarade affirme : « Les Égyptiens construisaient des pyramides, mais ils ne pensaient pas : la philosophie, ce sont les Grecs. »","tache":"Rédiger une dissertation courte sur l'existence d'une philosophie égyptienne."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-presocratiques",{"c":"1re D","m":"philo","rang":7,"titre":"Les présocratiques : Héraclite et Parménide","duree":25,"accroche":"Tout change, dit l'un ; rien ne change, répond l'autre.","intro":"Avant Socrate, des penseurs grecs cherchent le principe de toute chose. Deux d'entre eux s'opposent sur la question la plus simple et la plus vertigineuse : le monde est-il fait de changement ou de permanence ? Héraclite et Parménide fondent deux grandes manières de penser le réel.","objectifs":["situer les présocratiques","exposer la pensée du devenir d'Héraclite","exposer la pensée de l'être de Parménide et en mesurer la portée"],"parties":[{"t":"Les présocratiques","html":"<div class='def'><b>Définition</b>On appelle <strong>présocratiques</strong> les penseurs grecs antérieurs (ou contemporains) à Socrate, aux VIᵉ-Vᵉ siècles av. J.-C., qui cherchent l'<strong>arkhè</strong>, le principe premier de la nature (physis).</div><ul><li>Les Milésiens : Thalès (l'eau), Anaximène (l'air).</li><li>Pythagore : le nombre.</li><li><strong>Héraclite d'Éphèse</strong> et <strong>Parménide d'Élée</strong> : le devenir et l'être.</li></ul><p>Leurs œuvres ne nous sont parvenues que par <strong>fragments</strong> cités par d'autres auteurs.</p>","retenir":"Présocratiques : la recherche de l'arkhè ; œuvres en fragments."},{"t":"Héraclite : tout change","verrou":true},{"t":"Parménide : l'être est","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Réfléchir au changement et à la permanence","situation":"Ton grand-père de Foumban répète : « Les jeunes d'aujourd'hui ne sont plus comme avant. » Ta petite sœur lui répond : « Mais toi, tu es toujours le même grand-père ! »","tache":"Rédiger une dissertation courte sur la question : tout change-t-il ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-socrate-platon",{"c":"1re D","m":"philo","rang":8,"titre":"Socrate et Platon","duree":25,"accroche":"Un homme qui ne savait rien, et son élève qui voulut tout comprendre.","intro":"Socrate n'a rien écrit ; nous le connaissons surtout par son élève Platon. Le premier a fait de la philosophie un art de questionner et de vivre ; le second en a fait un système qui distingue le monde sensible et le monde des Idées. Leur pensée reste au cœur des sujets de philosophie.","objectifs":["présenter la vie et la méthode de Socrate","exposer la théorie des Idées et l'allégorie de la caverne","montrer l'actualité de leur pensée"],"parties":[{"t":"Socrate, le questionneur","html":"<div class='def'><b>Repères</b><strong>Socrate</strong> (470-399 av. J.-C.), Athénien, interroge ses concitoyens sur l'agora. Accusé d'impiété et de corrompre la jeunesse, il est <strong>condamné à boire la ciguë</strong> en 399 av. J.-C. et refuse de fuir pour respecter les lois.</div><ul><li><strong>Ironie</strong> et <strong>maïeutique</strong> : feindre l'ignorance, puis faire « accoucher » les esprits.</li><li>« Connais-toi toi-même » ; « Ce que je sais, c'est que je ne sais rien. »</li><li>« Nul n'est méchant volontairement » : le mal vient de l'ignorance du bien.</li></ul>","retenir":"Socrate : ironie, maïeutique, connaissance de soi ; condamné en 399 av. J.-C."},{"t":"Platon et la théorie des Idées","verrou":true},{"t":"Politique et actualité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Examiner les apparences avant de les croire","situation":"Ton cousin à Limbe passe ses nuits sur les réseaux sociaux et croit tout ce qu'il y voit : « Si c'est en vidéo, c'est vrai. »","tache":"Rédiger une dissertation courte sur les apparences avec Socrate et Platon."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-reactions-africaines",{"c":"1re D","m":"histoire","rang":8,"titre":"Les réactions africaines face aux agressions européennes : résistances et collaborations","duree":25,"accroche":"Résister ou s'allier : deux réponses africaines à une même conquête.","intro":"Face à la conquête européenne, les sociétés africaines n'ont pas réagi d'une seule façon. Beaucoup ont résisté par les armes ou autrement ; d'autres ont choisi de collaborer, par calcul, par contrainte ou pour se protéger de voisins rivaux. Comprendre ces choix évite de juger le passé avec simplisme.","objectifs":["présenter les formes de résistance","expliquer les raisons et les formes de la collaboration","illustrer ces réactions par des exemples africains et camerounais"],"parties":[{"t":"Les résistances","html":"<div class='def'><b>Définitions</b>La <strong>résistance</strong> est l'opposition à la conquête et à la domination coloniales. La <strong>collaboration</strong> est le choix de coopérer avec le colonisateur.</div><ul><li><strong>Résistance armée</strong> : Samory Touré (capturé en 1898), Béhanzin au Dahomey (1894), Menelik II à Adoua (1896), Rabah (Kousséri, 1900), les Zoulous (Isandhlwana, 1879).</li><li><strong>Résistances passives</strong> : fuite, refus de l'impôt et du travail forcé.</li><li><strong>Résistances religieuses</strong> : mouvements prophétiques.</li><li>Au Cameroun : les Bakweri de Kuva Likenye, le soulèvement des Bulu (1899-1901), Rudolf Duala Manga Bell et Martin-Paul Samba, exécutés en 1914.</li></ul>","retenir":"Résistances armées (Samory, Béhanzin, Menelik, Rabah), passives, religieuses ; au Cameroun : Bakweri, Bulu, Duala Manga Bell, Samba."},{"t":"Les collaborations","verrou":true},{"t":"Des choix complexes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Analyser les réactions africaines à la conquête sans simplisme","situation":"Lors d'un exposé à Foumban, un élève accuse le roi Njoya d'avoir « trahi l'Afrique » en s'alliant aux Allemands ; un autre répond qu'il a sauvé son royaume.","tache":"Expliquer la complexité des réactions africaines et donner un point de vue argumenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-exploitation-colonies",{"c":"1re D","m":"histoire","rang":9,"titre":"L'exploitation économique des colonies","duree":25,"accroche":"Cacao, caoutchouc, coton : produire pour la métropole, à n'importe quel prix.","intro":"Une fois la conquête achevée, les puissances coloniales organisent l'exploitation économique de l'Afrique au profit de la métropole. Les colonies doivent fournir des matières premières à bas prix et acheter des produits manufacturés. Ce système repose sur la contrainte : impôt, cultures obligatoires, travail forcé.","objectifs":["décrire l'économie de traite","présenter les méthodes de l'exploitation (impôt, travail forcé, sociétés concessionnaires)","mesurer les conséquences pour les Africains et pour l'économie actuelle"],"parties":[{"t":"L'économie de traite","html":"<div class='def'><b>Définition</b>L'<strong>économie de traite</strong> est le système dans lequel la colonie produit des matières premières agricoles ou minières pour l'exportation et achète des produits manufacturés à la métropole, par l'intermédiaire de maisons de commerce.</div><ul><li><strong>Cultures d'exportation</strong> : cacao, café, arachide, coton, huile de palme, caoutchouc, banane.</li><li><strong>Produits miniers</strong> : cuivre du Katanga (Congo belge), or de Gold Coast.</li><li><strong>Infrastructures</strong> orientées vers les ports : chemins de fer et routes de l'intérieur vers la côte (au Cameroun, lignes Douala-Nkongsamba et Douala-Yaoundé).</li></ul>","retenir":"Exporter des matières premières, importer des produits manufacturés ; routes et rails vers les ports."},{"t":"Les méthodes : la contrainte","verrou":true},{"t":"Les conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Expliquer l'origine coloniale de problèmes économiques et fonciers actuels","situation":"Les terres de la Cameroon Development Corporation (CDC), autour de Buea et Tiko, sont d'anciennes plantations allemandes. Des descendants de familles bakweri en réclament une partie.","tache":"Expliquer l'origine du problème et proposer un règlement pacifique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-plan-detaille",{"c":"1re D","m":"francais","rang":9,"titre":"Élaborer le plan détaillé d'une dissertation","duree":25,"accroche":"Un plan détaillé, c'est la copie déjà écrite… en squelette.","intro":"Après l'analyse du sujet et la recherche des idées, il faut organiser : choisir un type de plan, ordonner les arguments, placer les exemples. Le plan détaillé permet de rédiger ensuite sans se perdre, et c'est lui que le correcteur reconnaît dans une copie claire.","objectifs":["choisir le type de plan adapté au sujet","construire un plan détaillé hiérarchisé (I, A, 1)","rédiger les transitions"],"parties":[{"t":"Choisir le type de plan","html":"<div class='def'><b>Définition</b>Le <strong>plan détaillé</strong> est l'organisation hiérarchisée des idées d'une dissertation : grandes parties, sous-parties, arguments et exemples, avant la rédaction.</div><ul><li><strong>Dialectique</strong> (thèse, antithèse, synthèse) : pour « discutez », « partagez-vous… ? ».</li><li><strong>Analytique</strong> (causes, manifestations, conséquences, ou problème, causes, solutions) : pour « expliquez », « montrez ».</li><li><strong>Thématique</strong> : les différents aspects d'une notion.</li></ul><div class='attention'><b>Attention</b>Le plan doit répondre à la problématique : chaque partie est une étape de la réponse, pas un « tiroir » de connaissances.</div>","retenir":"Dialectique, analytique, thématique : la consigne et la problématique décident."},{"t":"Construire et hiérarchiser","verrou":true},{"t":"Les transitions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Organiser ses idées en un plan détaillé de dissertation","situation":"En devoir à Kribi, le sujet est : « Le théâtre est un miroir de la société. Discutez cette affirmation. » Ton camarade a trouvé des idées mais les a écrites dans le désordre.","tache":"Proposer un plan détaillé complet avec transitions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-denotation-connotation",{"c":"1re D","m":"francais","rang":8,"titre":"Sémantique : le sens des mots, dénotation et connotation","duree":55,"accroche":"« Lion » : un animal… ou une équipe de football et tout un pays fier.","intro":"Leçon de langue (rubrique Sémantique et lexicologie). On observe des noms de produits et un court texte, on distingue le sens premier des mots et ce qu'ils évoquent, puis on formule la règle et on s'entraîne au format de l'épreuve : repérage, analyse, interprétation.","objectifs":["distinguer dénotation et connotation","identifier les connotations mélioratives et péjoratives","analyser l'effet des connotations dans un texte"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (textes composés pour la leçon) :</p><blockquote>1. Trois noms proposés pour une eau minérale : « Source des Lions », « Eau du Puits », « Rosée du Mont Cameroun ».<br>2. « Le soir tombait sur Douala. La ville, fourmilière épuisée, laissait monter vers le ciel rouge la plainte de ses moteurs. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Cherche le sens de « lion », « puits » et « rosée » dans le dictionnaire.</li><li>Quelles idées, quelles impressions chacun de ces mots fait-il naître dans le nom d'une eau ?</li><li>Dans le texte 2, que désigne « fourmilière » au sens propre ? Qu'évoque-t-il ici ?</li><li>« ciel rouge », « plainte » : quel sentiment ces mots suggèrent-ils ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Lion : grand félin ; puits : trou creusé pour atteindre l'eau ; rosée : gouttes d'eau déposées le matin. 2. Lion : force, fierté nationale (les Lions indomptables) ; puits : eau ordinaire, parfois douteuse ; rosée : pureté, fraîcheur, nature de montagne. 3. Au sens propre, l'habitat des fourmis ; ici, la ville grouillante de gens affairés, épuisés. 4. La tristesse, la souffrance (« plainte »), et peut-être la violence ou la fin du jour (« rouge »).</p></details><div class='def'><b>Ce que montre l'observation</b>La <strong>dénotation</strong> est le sens premier, objectif et stable d'un mot, celui du dictionnaire. La <strong>connotation</strong> est l'ensemble des sens seconds, des valeurs et des impressions qu'un mot suggère selon le contexte, la culture ou l'individu.</div>","retenir":"Dénotation : sens du dictionnaire ; connotation : sens seconds, impressions, valeurs."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie économique","agir":"Analyser les connotations pour comprendre et choisir un message","situation":"Une entreprise de Douala lance une eau minérale et hésite entre trois noms : « Source des Lions », « Eau du Puits » et « Rosée du Mont Cameroun ».","tache":"Analyser les connotations et recommander un nom."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-reading-disputes",{"c":"1re D","m":"anglais","rang":7,"titre":"Reading comprehension: settling community disputes","duree":25,"accroche":"Read, understand, explain in your own words: the keys to Section C.","intro":"In the Probatoire and the Baccalauréat, the reading comprehension section tests your ability to understand a text, find information, explain words and statements in your own words, and give your opinion. This lesson trains these skills on a text about settling disputes in a Cameroonian community.","objectifs":["use reading strategies: skimming, scanning, guessing meaning from context","answer comprehension questions in your own words","use the vocabulary of conflict and mediation"],"parties":[{"t":"Reading strategies","html":"<div class='def'><b>Definitions</b><strong>Skimming</strong>: reading quickly to get the general idea. <strong>Scanning</strong>: looking for a specific piece of information (a name, a date). <strong>Inferring</strong>: guessing the meaning of a word or idea from the context.</div><ol><li>Read the questions first, then the text.</li><li>Skim the text for the main idea (title, first and last sentences).</li><li>Scan for the answers; underline the lines.</li><li>Answer in <strong>your own words</strong> unless you are asked to quote.</li></ol>","retenir":"Skim for the main idea, scan for details, infer from context, answer in your own words."},{"t":"The text","verrou":true},{"t":"Vocabulary of disputes","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re D","famille":"Citoyenneté","agir":"Read and understand texts on conflict resolution and propose peaceful solutions","situation":"In your quarter in Bamenda, two neighbours have been quarrelling for weeks about a fence. The quarter head asks students to suggest a way to settle the dispute.","tache":"Write a letter proposing a mediation meeting and a fair solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-logique",{"c":"1re D","m":"philo","rang":10,"titre":"La logique : définition et importance","duree":25,"accroche":"Bien penser, ce n'est pas seulement avoir des idées : c'est les enchaîner correctement.","intro":"Nous raisonnons sans cesse : « s'il pleut, le match sera annulé ; il pleut, donc… ». Mais nos raisonnements sont parfois faux sans que nous le voyions. La logique étudie les règles qui rendent un raisonnement valide. Née avec Aristote, elle est aujourd'hui au cœur des mathématiques et de l'informatique.","objectifs":["définir la logique et ses principes","distinguer validité et vérité","montrer l'importance de la logique dans la pensée, les sciences et la vie sociale"],"parties":[{"t":"Définition et principes","html":"<div class='def'><b>Définition</b>La <strong>logique</strong> (du grec <em>logos</em>, raison, discours) est la science des <strong>règles de la pensée correcte</strong> : elle étudie les conditions auxquelles un raisonnement est <strong>valide</strong>, c'est-à-dire auxquelles la conclusion découle nécessairement des prémisses.</div><ul><li><strong>Aristote</strong> (IVᵉ s. av. J.-C.) la fonde dans l'<em>Organon</em> (« l'instrument » de la pensée).</li><li><strong>Principes</strong> : <strong>identité</strong> (A est A) ; <strong>non-contradiction</strong> (une chose ne peut être à la fois A et non-A sous le même rapport) ; <strong>tiers exclu</strong> (une proposition est vraie ou fausse, sans troisième possibilité).</li></ul>","retenir":"Logique : règles de la pensée correcte ; Aristote ; identité, non-contradiction, tiers exclu."},{"t":"Le raisonnement : validité et vérité","verrou":true},{"t":"L'importance de la logique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Citoyenneté","agir":"Utiliser la logique pour démasquer les raisonnements trompeurs","situation":"Un message circule à Ngaoundéré : « Tous ceux qui ont réussi sont allés à l'étranger. Mon cousin est allé à l'étranger. Donc il a réussi. Partez tous ! »","tache":"Rédiger une dissertation courte sur la logique et l'erreur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-chine-traites",{"c":"1re D","m":"histoire","rang":10,"titre":"La Chine, des traités inégaux à l'éveil du nationalisme","duree":25,"accroche":"L'opium, des canonnières et des traités : un empire millénaire humilié.","intro":"Au XIXᵉ siècle, la Chine des Qing, longtemps puissante, est contrainte par les puissances européennes puis par le Japon à signer des « traités inégaux ». Ces humiliations provoquent des révoltes, puis l'éveil d'un nationalisme chinois qui renverse l'empire en 1911.","objectifs":["expliquer les guerres de l'opium et les traités inégaux","présenter les réactions chinoises (Taiping, Boxers)","décrire la naissance du nationalisme et de la République"],"parties":[{"t":"Les guerres de l'opium et les traités inégaux","html":"<div class='def'><b>Définition</b>Un <strong>traité inégal</strong> est un accord imposé par la force, qui accorde des avantages à une seule partie : ouverture de ports, cession de territoires, privilèges pour les étrangers.</div><ul><li>Les Britanniques vendent illégalement de l'<strong>opium</strong> venu d'Inde ; la Chine l'interdit et détruit des stocks (1839).</li><li><strong>Première guerre de l'opium</strong> (1839-1842) : <strong>traité de Nankin</strong> (1842) : Hong Kong cédée au Royaume-Uni, ports ouverts.</li><li><strong>Seconde guerre de l'opium</strong> (1856-1860) : sac du palais d'Été à Pékin (1860) ; nouveaux ports et privilèges.</li><li>Défaite face au <strong>Japon</strong> (1894-1895) : perte de Taïwan.</li></ul>","retenir":"Opium ; Nankin (1842), Hong Kong ; palais d'Été (1860) ; défaite face au Japon (1895)."},{"t":"Les réactions chinoises","html":"<ul><li><strong>Révolte des Taiping</strong> (1850-1864) : immense soulèvement contre la dynastie Qing ; des millions de morts.</li><li>Tentatives de modernisation, limitées par la cour impériale.</li><li><strong>Révolte des Boxers</strong> (1900) : société secrète qui attaque les étrangers et les missions ; écrasée par une coalition de huit puissances.</li></ul><div class='attention'><b>Le « dépeçage »</b>À la fin du siècle, les puissances se partagent la Chine en zones d'influence, sans la coloniser entièrement.</div>","retenir":"Taiping (1850-1864), Boxers (1900) ; zones d'influence étrangères.","labo":{"type":"etapes","invite":"Avance étape par étape.","items":[["opium","Guerres de l'opium (1839-1842 ; 1856-1860)."],["Traité de Nankin","Traité de Nankin (1842) : Hong Kong ; traités inégaux."],["Défaite face au Japon","Défaite face au Japon (1895) ; zones d'influence."],["Taiping","Révoltes : Taiping (1850-1864), Boxers (1900)."],["Sun Yat-sen","Sun Yat-sen ; République (1912) ; 4 mai 1919 ; PCC (1921)."]]}},{"t":"L'éveil du nationalisme","html":"<ul><li><strong>Sun Yat-sen</strong> fonde un mouvement républicain ; ses « trois principes du peuple » : nationalisme, démocratie, bien-être du peuple.</li><li><strong>Révolution de 1911</strong> : l'empire s'effondre ; la <strong>République</strong> est proclamée le <strong>1er janvier 1912</strong> ; le parti nationaliste (Kuomintang) est créé.</li><li><strong>Mouvement du 4 mai 1919</strong> : les étudiants protestent contre le traité de Versailles, qui donne au Japon des droits sur le Shandong.</li><li>Le <strong>Parti communiste chinois</strong> est fondé en <strong>1921</strong>.</li></ul><div class='ex'><b>Comparaison</b>Comme en Afrique, l'humiliation coloniale a nourri un nationalisme moderne ; il conduira, en Chine, à la victoire communiste de 1949.</div>","retenir":"Sun Yat-sen ; République (1912) ; 4 mai 1919 ; PCC (1921)."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources (9 points)</h3><p><strong>1.</strong> Présente et analyse deux formes de réaction des nationalistes chinois face à la domination étrangère, de la fin du XIXe siècle à 1921. Le candidat répondra par un texte de 10 à 15 lignes, en un seul paragraphe. (5 pts)</p><p><strong>2. Texte à corriger (4 pts).</strong> Le texte ci-dessous contient quatre informations erronées.</p><blockquote>« Le traité de Nankin (1842) cède Taïwan au Royaume-Uni. Le traité de Shimonoseki (1895) est signé avec la Russie. La révolte des Taiping a lieu en 1900. Sun Yat-sen proclame la République le 1er janvier 1949. »</blockquote><p>a) Relève les quatre informations erronées. (2 pts) b) Réécris le texte en corrigeant ces erreurs. (2 pts)</p><details><summary>Voir le corrigé de la première partie</summary><p><strong>1.</strong> Préambule : humiliée par les traités inégaux, la Chine voit naître au tournant du XXe siècle un nationalisme moderne. Éléments : la révolte des Boxers (1900), soulèvement contre les étrangers, écrasé par une coalition de huit puissances ; la révolution de 1911 menée par Sun Yat-sen, qui renverse l'empire et proclame la République le 1er janvier 1912 ; on peut citer le mouvement du 4 mai 1919 contre le traité de Versailles. Explications : la xénophobie populaire puis un programme politique moderne (Trois principes du peuple). Bilan : le nationalisme chinois passe de la révolte à la construction d'un État moderne.</p><p><em>Barème : préambule 1 pt (existence 0,5, pertinence 0,5) ; deux éléments 2 pts ; explications 1 pt ; bilan 1 pt.</em></p><p><strong>2.</strong> Erreurs : 1) Taïwan → Hong Kong ; 2) avec la Russie → avec le Japon ; 3) la révolte des Taiping en 1900 → la révolte des Boxers (les Taiping : 1850-1864) ; 4) 1949 → 1912. Texte corrigé : « Le traité de Nankin (1842) cède Hong Kong au Royaume-Uni. Le traité de Shimonoseki (1895) est signé avec le Japon. La révolte des Boxers a lieu en 1900. Sun Yat-sen proclame la République le 1er janvier 1912. »</p></details><h3>Deuxième partie : l'évaluation des compétences (9 points)</h3><p><strong>Thème : Défense de la souveraineté nationale</strong></p><p><strong>Document 1 : Le traité de Shimonoseki</strong></p><blockquote>« … Signé à l'issue de la guerre sino-japonaise de 1895, ce traité exigeait l'indépendance de la Corée, qui fut annexée par le Japon en 1910. Le traité reconnaissait aussi l'autorité du Japon sur l'île de Formose et les îles Pescadores. »</blockquote><p><em>Source : fr.wikipedia.org (document du sujet officiel de Probatoire, histoire, session 2023).</em></p><p><strong>Document 2 : Les Trois principes du peuple de Sun Yat-sen</strong></p><blockquote>Le programme de Sun Yat-sen repose sur le nationalisme (libérer la Chine de la domination étrangère), la démocratie (gouvernement par le peuple) et le bien-être du peuple (meilleure répartition de la terre et des richesses).</blockquote><p><em>Source : Réalisation VÉRITAS (livret HGECM 2026-2027), synthèse.</em></p><p><strong>Consigne.</strong> À partir des documents et de tes connaissances, rédige une production cohérente dont les grandes lignes reposent sur les tâches suivantes :</p><ol><li>Explique, à partir du document 1, en quoi le traité de Shimonoseki illustre la domination subie par la Chine à la fin du XIXe siècle. (3 pts)</li><li>Présente, à partir du document 2 et de tes connaissances, le projet des nationalistes chinois. (3 pts)</li><li>Montre ce que l'exemple chinois enseigne aux pays africains sur la défense de leur souveraineté. (3 pts)</li></ol><p><em>Ta production comportera trois paragraphes, sans numéros ni tirets. Présentation : 2 points.</em></p><details><summary>Voir le corrigé de la deuxième partie</summary><p>Tâche 1 : vaincue par le Japon, la Chine doit renoncer à la Corée et céder Formose (Taïwan) et les Pescadores : comme les traités de Nankin et de Tianjin, c'est un traité imposé par la force qui démembre le pays. Tâche 2 : Sun Yat-sen veut libérer la Chine des étrangers, établir la démocratie et améliorer la vie du peuple ; la révolution de 1911 renverse l'empire et la République est proclamée en 1912 ; le mouvement du 4 mai 1919 prolonge ce nationalisme. Tâche 3 : l'unité nationale, un projet politique clair et le développement économique sont les conditions de la souveraineté ; les divisions favorisent la domination étrangère.</p><p><em>Barème de chaque tâche : pertinence 1 pt, correction de la langue 1 pt, cohérence 1 pt. Présentation : 2 pts.</em></p></details></div>","retenir":"Savoir-être mobilisé : ouverture sur le monde et esprit critique."}],"revision":["Guerres de l'<strong>opium</strong> (1839-1842 ; 1856-1860).","<strong>Traité de Nankin</strong> (1842) : Hong Kong ; traités <strong>inégaux</strong>.","Défaite face au Japon (1895) ; zones d'influence.","Révoltes : <strong>Taiping</strong> (1850-1864), <strong>Boxers</strong> (1900).","<strong>Sun Yat-sen</strong> ; République (1912) ; 4 mai 1919 ; PCC (1921)."],"exo":"<p>Explique pourquoi on parle de traités « inégaux ». <em>(Réponse : Ils sont imposés par la force après des défaites militaires et n'accordent des avantages (ports, territoires, privilèges) qu'aux puissances étrangères.)</em></p>","quiz":[{"q":"La première guerre de l'opium oppose la Chine :","r":["au Royaume-Uni","au Japon","à la France seule","aux États-Unis"],"b":0,"e":"1839-1842."},{"q":"Un traité inégal est :","r":["un accord équilibré","un accord imposé par la force et favorable à une seule partie","un traité de paix africain","une constitution"],"b":1,"e":"Ports ouverts, territoires cédés."},{"q":"La révolte des Boxers a lieu en :","r":["1842","1864","1900","1919"],"b":2,"e":"Écrasée par huit puissances."},{"q":"La République de Chine est proclamée en :","r":["1842","1895","1949","1912"],"b":3,"e":"Le 1er janvier 1912."},{"q":"Les « trois principes du peuple » sont de :","r":["Sun Yat-sen","Mao Zedong","Deng Xiaoping","l'empereur"],"b":0,"e":"Nationalisme, démocratie, bien-être."},{"q":"Après la guerre de 1894-1895, la Chine perd :","r":["Hong Kong","Taïwan","Pékin","Macao"],"b":1,"e":"Au profit du Japon."},{"q":"Le mouvement du 4 mai 1919 proteste contre :","r":["l'opium","les Taiping","le traité de Versailles","la République"],"b":2,"e":"Droits donnés au Japon sur le Shandong."},{"q":"Le Parti communiste chinois est fondé en :","r":["1900","1912","1949","1921"],"b":3,"e":"Il prendra le pouvoir en 1949."},{"q":"La révolte des Taiping dure de :","r":["1850 à 1864","1900 à 1901","1911 à 1912","1839 à 1842"],"b":0,"e":"Des millions de morts."},{"q":"Le palais d'Été est saccagé en :","r":["1842","1860","1900","1911"],"b":1,"e":"Seconde guerre de l'opium."}],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comparer les dominations étrangères et les nationalismes","situation":"Dans un débat à ton lycée de Kumba, un camarade s'étonne : « La Chine aujourd'hui puissante a-t-elle aussi été dominée comme l'Afrique ? »","tache":"Expliquer la domination subie par la Chine et la comparer à l'Afrique."},"gratuit":true});
VRT_L("1re-d-histoire-inde-indochine",{"c":"1re D","m":"histoire","rang":11,"titre":"L'impérialisme européen en Inde et en Indochine","duree":25,"accroche":"Le joyau de la couronne britannique et la perle de l'empire français.","intro":"En Asie, deux empires coloniaux se construisent au XIXᵉ siècle : l'Inde britannique, « joyau de la couronne », et l'Indochine française. Comme en Afrique, la conquête est suivie d'une exploitation économique et d'une domination politique qui provoquent révoltes et nationalismes.","objectifs":["retracer la conquête de l'Inde par les Britanniques","retracer la formation de l'Indochine française","décrire l'exploitation et les premières résistances"],"parties":[{"t":"L'Inde britannique","html":"<div class='def'><b>Définition</b>Le <strong>Raj britannique</strong> désigne la domination directe de la Couronne britannique sur l'Inde, de 1858 à 1947.</div><ul><li>La <strong>Compagnie anglaise des Indes orientales</strong> s'impose après la bataille de <strong>Plassey</strong> (1757).</li><li>La <strong>révolte des Cipayes</strong> (1857), soldats indiens de la Compagnie, est durement réprimée.</li><li>En <strong>1858</strong>, la Couronne prend le contrôle ; en <strong>1877</strong>, la reine Victoria devient impératrice des Indes.</li><li>Exploitation : coton brut exporté, textiles anglais importés qui ruinent l'artisanat indien ; thé, jute, opium ; chemins de fer vers les ports.</li><li>Le <strong>Congrès national indien</strong> est fondé en <strong>1885</strong>.</li></ul>","retenir":"Plassey (1757), Cipayes (1857), Raj (1858), Victoria impératrice (1877), Congrès (1885)."},{"t":"L'Indochine française","verrou":true},{"t":"Résistances et nationalismes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comparer les colonisations d'Asie et d'Afrique","situation":"Pour un exposé en classe à Bafoussam, ton groupe doit montrer que « la colonisation a suivi les mêmes logiques en Asie et en Afrique ».","tache":"Rédiger le plan détaillé de l'exposé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-texte-descriptif",{"c":"1re D","m":"francais","rang":13,"titre":"Stylistique : le texte descriptif","duree":55,"accroche":"Faire voir avec des mots : l'art du texte descriptif.","intro":"Leçon de langue (rubrique Stylistique, types de textes). On observe la description d'un marché, on découvre comment elle est organisée et à qui appartient le regard, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les caractéristiques du texte descriptif","repérer l'organisation et le point de vue de la description","dégager les fonctions d'une description"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (description composée pour la leçon) :</p><blockquote>« Au premier plan, les bayam-sellam ont étalé leurs régimes de plantain, jaunes et lourds. Plus loin, sous des parasols délavés, des tas de tomates rouges brillent au soleil. À droite, un vendeur de poisson fumé chasse les mouches d'un geste las. Au fond, la gare routière gronde de klaxons. Une odeur de friture et de terre mouillée flotte sur le tout. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Que décrit le texte ? D'où le regard semble-t-il porté ?</li><li>Relève les indicateurs de lieu : quel ordre suit la description ?</li><li>Relève les adjectifs et les mots qui renvoient aux cinq sens.</li><li>À quel temps sont les verbes ? Pourquoi ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Un marché ; d'un observateur placé à l'entrée, qui regarde du proche au lointain. 2. Au premier plan, plus loin, à droite, au fond : <strong>organisation spatiale</strong> du proche au lointain. 3. Adjectifs : jaunes, lourds, délavés, rouges, fumé, las ; sens : vue (couleurs), ouïe (klaxons), odorat (odeur de friture), toucher (lourds). 4. Présent (ou imparfait dans un récit au passé) : la description arrête le temps, c'est une <strong>pause</strong>.</p></details><div class='def'><b>Ce que montre l'observation</b>Le <strong>texte descriptif</strong> fait voir un lieu, un objet ou une personne : il suit un <strong>ordre</strong> (spatial, du général au particulier…), adopte un <strong>point de vue</strong> et accumule <strong>expansions</strong> et notations sensorielles.</div>","retenir":"Ordre, point de vue, expansions du nom, cinq sens, présent ou imparfait."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Produire une description organisée et évocatrice","situation":"L'office du tourisme de Kribi organise un concours : « Décrivez les chutes de la Lobé à un visiteur qui ne les a jamais vues. »","tache":"Rédiger une description riche et préciser sa fonction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-introduction-dissertation",{"c":"1re D","m":"francais","rang":17,"titre":"Dissertation : rédiger l'introduction","duree":20,"accroche":"Une introduction réussie, et le correcteur lit la suite avec confiance.","intro":"L'introduction de la dissertation montre au correcteur que le sujet a été compris et que la réflexion est organisée. Elle comprend quatre temps : l'amorce, la présentation du sujet, la problématique et l'annonce du plan. Elle se rédige au brouillon, une fois le plan établi.","objectifs":["connaître les quatre temps de l'introduction","rédiger une amorce pertinente","formuler la problématique et annoncer le plan avec aisance"],"parties":[{"t":"Les quatre temps","html":"<div class='def'><b>Définition</b>L'<strong>introduction</strong> de la dissertation est un paragraphe qui conduit vers le sujet (<strong>amorce</strong>), le <strong>présente</strong> (citation ou reformulation), pose la <strong>problématique</strong> et <strong>annonce le plan</strong>.</div><ol><li><strong>Amorce</strong> : une idée générale en lien direct avec le sujet, un fait d'histoire littéraire, une citation.</li><li><strong>Présentation du sujet</strong> : citation exacte entre guillemets, avec son auteur.</li><li><strong>Problématique</strong> : la question centrale.</li><li><strong>Annonce du plan</strong>.</li></ol>","retenir":"Amorce, sujet, problématique, annonce du plan."},{"t":"Réussir l'amorce et l'annonce","verrou":true},{"t":"Un modèle","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Rédiger l'introduction d'une dissertation","situation":"Pour la préparation au Bac, ton professeur à Yaoundé propose : « La lecture des romans est une perte de temps pour un élève de série scientifique. » Discutez.","tache":"Rédiger une introduction complète en quatre temps."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-community-celebrations",{"c":"1re D","m":"anglais","rang":3,"titre":"Vocabulary: interacting with others at community celebrations","duree":20,"accroche":"Could you…? Would you like…? Thank you for having us! Polite English for every celebration.","intro":"National Day, Youth Day, the Ngondo, the Nguon, a wedding or a funeral: community celebrations bring together classmates, neighbours, elders and school authorities. Each situation needs the right words to greet, invite, ask permission, thank and congratulate. This vocabulary is useful for the speaking, dialogue and letter-writing tasks of the exam.","objectifs":["use polite expressions to greet, invite, ask and thank","adapt your register to classmates, neighbours, adults and school authorities","use the vocabulary of community celebrations"],"parties":[{"t":"Celebrations and their vocabulary","html":"<div class='def'><b>Definition</b>A <strong>community celebration</strong> is an event in which members of a community gather to mark an occasion: a <strong>national holiday</strong> (National Day on 20th May, Youth Day on 11th February), a <strong>cultural festival</strong> (the Ngondo of the Sawa, the Nguon of the Bamoun, the Lela of Bali Nyonga), a <strong>wedding</strong>, a <strong>graduation</strong> or a <strong>funeral</strong>.</div><ul><li>Words: <strong>a parade</strong>, <strong>a march-past</strong>, <strong>a rehearsal</strong>, <strong>a guest</strong>, <strong>a host</strong>, <strong>a dignitary</strong>, <strong>a feast</strong>, <strong>traditional dances</strong>, <strong>attire</strong> (clothing for an occasion).</li><li>Verbs: <strong>to celebrate</strong>, <strong>to attend</strong>, <strong>to host</strong>, <strong>to rehearse</strong>, <strong>to march</strong>, <strong>to congratulate</strong>.</li></ul>","retenir":"parade, march-past, rehearsal, guest, host, feast, attire; to attend, to host, to congratulate."},{"t":"Polite expressions and register","verrou":true},{"t":"In context","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re D","famille":"Vie sociale et culturelle","agir":"Interact politely with others during community celebrations","situation":"Your class in Dschang is organising a cultural evening for Youth Day (11th February). You must invite the principal, the parents and the neighbours.","tache":"Write a formal letter of invitation asking permission to use the school hall."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-jugement",{"c":"1re D","m":"philo","rang":12,"titre":"Le jugement en logique","duree":25,"accroche":"« Tous », « aucun », « quelques » : trois petits mots qui changent la vérité d'une phrase.","intro":"Après le concept vient le jugement : penser, c'est affirmer ou nier quelque chose de quelque chose. « Le paludisme est une maladie » est un jugement. La logique classique les classe selon la quantité et la qualité, et étudie leurs rapports : c'est la base du raisonnement.","objectifs":["définir le jugement et la proposition","classer les jugements selon la quantité et la qualité","distinguer jugement de fait et jugement de valeur"],"parties":[{"t":"Définition et structure","html":"<div class='def'><b>Définition</b>Le <strong>jugement</strong> est l'acte de l'esprit qui <strong>affirme ou nie</strong> un rapport entre deux concepts. Exprimé par des mots, il s'appelle une <strong>proposition</strong>. Il comprend un <strong>sujet</strong> (ce dont on parle), un <strong>prédicat</strong> ou attribut (ce qu'on en dit) et une <strong>copule</strong> (le verbe « être » qui les relie).</div><div class='ex'><b>Exemple</b>« L'homme (sujet) est (copule) mortel (prédicat). »</div><ul><li>Seul le jugement peut être <strong>vrai</strong> ou <strong>faux</strong> : un concept isolé (« arbre ») n'est ni vrai ni faux.</li></ul>","retenir":"Jugement : affirmer ou nier ; proposition ; sujet, copule, prédicat ; seul lieu du vrai et du faux."},{"t":"Quantité et qualité : A, E, I, O","verrou":true},{"t":"Autres classements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Citoyenneté","agir":"Juger avec rigueur et refuser les généralisations abusives","situation":"Après un vol au marché de Bamenda, un commerçant crie : « Les jeunes de ce quartier sont tous des voleurs ! » Un attroupement se forme autour d'un adolescent.","tache":"Rédiger une dissertation courte sur les risques du jugement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-premiere-guerre",{"c":"1re D","m":"histoire","rang":12,"titre":"La Première Guerre mondiale (1914-1918)","duree":25,"accroche":"Une guerre européenne devenue mondiale, jusqu'au Cameroun.","intro":"De 1914 à 1918, la Première Guerre mondiale oppose deux alliances et fait près de 10 millions de morts militaires. Guerre de mouvement puis guerre des tranchées, elle mobilise les économies, les sociétés et les colonies. Au Cameroun allemand, elle se termine par la défaite allemande de 1916.","objectifs":["expliquer les causes de la guerre","décrire les grandes phases du conflit","mesurer son caractère total et mondial"],"parties":[{"t":"Les causes","html":"<div class='def'><b>Définition</b>Une <strong>guerre mondiale</strong> est un conflit qui implique des États de plusieurs continents et mobilise toutes leurs ressources ; on parle de <strong>guerre totale</strong> quand toute la société est mobilisée.</div><ul><li><strong>Causes profondes</strong> : rivalités <strong>coloniales</strong> et <strong>économiques</strong> (Royaume-Uni, Allemagne) ; <strong>nationalismes</strong> (France et l'Alsace-Lorraine, Balkans) ; course aux armements ; <strong>systèmes d'alliances</strong> : Triple-Entente (France, Royaume-Uni, Russie) contre Triple-Alliance (Allemagne, Autriche-Hongrie, Italie).</li><li><strong>Cause immédiate</strong> : l'assassinat de l'archiduc <strong>François-Ferdinand</strong> à <strong>Sarajevo</strong> le <strong>28 juin 1914</strong> ; le jeu des alliances déclenche la guerre en août.</li></ul>","retenir":"Rivalités coloniales et économiques, nationalismes, alliances ; Sarajevo (28 juin 1914)."},{"t":"Les phases de la guerre","verrou":true},{"t":"Une guerre totale et mondiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Montrer les effets de la Première Guerre mondiale sur l'Afrique et le Cameroun","situation":"Ton grand-père, à Yaoundé, affirme : « La guerre de 14-18 était une affaire de Blancs, elle n'a rien changé chez nous. »","tache":"Lui répondre en douze lignes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-texte-argumentatif",{"c":"1re D","m":"francais","rang":16,"titre":"Stylistique : le texte argumentatif","duree":55,"accroche":"Convaincre, persuader, réfuter : le texte qui veut faire changer d'avis.","intro":"Leçon de langue (rubrique Stylistique, types de textes). On observe une lettre ouverte au maire, on découvre la thèse, les arguments et les procédés pour convaincre et persuader, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les éléments du texte argumentatif","distinguer convaincre et persuader","repérer les marques de l'argumentation"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (lettre composée pour la leçon) :</p><blockquote>« Monsieur le Maire, notre quartier a besoin d'un terrain de sport. D'abord, nos jeunes n'ont aucun lieu pour se dépenser ; ils traînent donc dans la rue. Ensuite, le sport éduque : il apprend la discipline et le respect. Certes, le budget communal est limité ; pourtant, un simple terrain coûte moins cher qu'une seule semaine de délinquance. Monsieur le Maire, pensez à nos enfants : voulez-vous qu'ils grandissent dans la rue ? »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Quelle opinion l'auteur défend-il ? Où est-elle exprimée ?</li><li>Relève les arguments et les mots qui les organisent.</li><li>Quelle objection l'auteur prévoit-il ? Comment y répond-il ?</li><li>Dans la dernière phrase, l'auteur s'adresse-t-il à la raison ou aux sentiments du maire ?</li></ol><details><summary>Voir l'analyse</summary><p>1. La <strong>thèse</strong> : le quartier a besoin d'un terrain de sport (première phrase). 2. Deux <strong>arguments</strong> : l'absence de lieu (avec la conséquence « donc »), la valeur éducative du sport ; <strong>connecteurs</strong> : d'abord, ensuite. 3. <strong>Concession</strong> : « Certes, le budget est limité » ; <strong>réfutation</strong> : « pourtant… » (comparaison de coûts). 4. Aux sentiments : apostrophe, impératif, question rhétorique : il <strong>persuade</strong> après avoir <strong>convaincu</strong>.</p></details><div class='def'><b>Ce que montre l'observation</b>Le <strong>texte argumentatif</strong> défend une <strong>thèse</strong> par des <strong>arguments</strong> organisés par des connecteurs ; il peut <strong>convaincre</strong> (raison) et <strong>persuader</strong> (sentiments).</div>","retenir":"Thèse, arguments, exemples, connecteurs, concession, convaincre et persuader."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Défendre une opinion par une argumentation organisée","situation":"Le conseil d'établissement de ton lycée à Maroua envisage d'interdire totalement le téléphone portable dans l'enceinte de l'école. Le journal du lycée ouvre ses colonnes aux élèves.","tache":"Rédiger un texte argumentatif pour le journal du lycée."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-fonctions-langage",{"c":"1re D","m":"francais","rang":22,"titre":"Communication : les fonctions du langage","duree":55,"accroche":"« Allô ? », « Viens ! », « Ah ! » : chaque phrase a une fonction.","intro":"Leçon de langue (rubrique Communication). On observe des énoncés de la vie quotidienne, on cherche sur quel élément de la communication chacun est centré, puis on formule la règle des six fonctions de Jakobson et on s'entraîne au format de l'épreuve.","objectifs":["rappeler les six éléments de la communication","identifier les six fonctions du langage","repérer la fonction dominante d'un énoncé"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (énoncés composés pour la leçon) :</p><blockquote>1. « Le Mungo prend sa source dans la région du Sud-Ouest. »<br>2. « Ah ! que je suis heureuse de te revoir ! »<br>3. « Ferme la porte, s'il te plaît. »<br>4. « Allô ? Tu m'entends ? Allô ? »<br>5. « “Bayam-sellam” veut dire revendeuse au marché. »<br>6. « Le soleil se couche, la savane s'enflamme, et le soir doucement s'endort sur nos cases. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Pour chaque énoncé, dis qui parle, à qui, et de quoi.</li><li>Sur quel élément l'énoncé insiste-t-il : l'information, le locuteur, le destinataire, le contact, le code ou le message lui-même ?</li><li>Quels indices (pronoms, ponctuation, mode du verbe) le montrent ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Centré sur le <strong>référent</strong> (l'information) : fonction <strong>référentielle</strong> (phrase déclarative, 3e personne). 2. Centré sur l'<strong>émetteur</strong> : fonction <strong>expressive</strong> (interjection, exclamation, « je »). 3. Centré sur le <strong>récepteur</strong> : fonction <strong>conative</strong> (impératif, 2e personne). 4. Centré sur le <strong>canal</strong> : fonction <strong>phatique</strong> (vérifier le contact). 5. Centré sur le <strong>code</strong> : fonction <strong>métalinguistique</strong> (on explique un mot). 6. Centré sur le <strong>message</strong> : fonction <strong>poétique</strong> (rythme, images, sonorités).</p></details><div class='def'><b>Ce que montre l'observation</b>Selon l'élément de la communication sur lequel il insiste, un énoncé remplit une <strong>fonction</strong> différente : on en distingue six (R. Jakobson).</div>","retenir":"Six éléments de la communication, six fonctions."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie économique","agir":"Utiliser les fonctions du langage pour communiquer efficacement","situation":"La coopérative des producteurs de miel d'Oku veut une affiche pour vendre son miel blanc à Bamenda et à Yaoundé.","tache":"Rédiger l'affiche en mobilisant au moins quatre fonctions du langage."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-paragraphe-dissertation",{"c":"1re D","m":"francais","rang":20,"titre":"Dissertation : rédiger un paragraphe argumentatif","duree":20,"accroche":"Un bon paragraphe, c'est une idée, une explication, un exemple analysé.","intro":"Le développement de la dissertation est fait de paragraphes. Chacun défend un seul argument. Le correcteur attend une structure nette : l'argument, son explication, un exemple précis tiré des œuvres, l'analyse de cet exemple, et une phrase de bilan. C'est la méthode « AEI ».","objectifs":["connaître la structure d'un paragraphe argumentatif","choisir et analyser un exemple littéraire","relier les paragraphes par des transitions"],"parties":[{"t":"La structure du paragraphe","html":"<div class='def'><b>Définition</b>Le <strong>paragraphe argumentatif</strong> est l'unité du développement : il défend <strong>un seul argument</strong>, selon l'ordre <strong>A</strong>rgument, <strong>E</strong>xplication, <strong>I</strong>llustration (exemple analysé), et se termine par une phrase de bilan.</div><ul><li><strong>Alinéa</strong> au début, retour à la ligne à la fin.</li><li>Longueur : 10 à 15 lignes environ.</li><li>Un paragraphe = une idée ; deux idées = deux paragraphes.</li></ul>","retenir":"Un argument par paragraphe ; Argument, Explication, Illustration ; phrase de bilan ; alinéa."},{"t":"Choisir et analyser l'exemple","verrou":true},{"t":"Les transitions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Rédiger un paragraphe argumentatif structuré","situation":"Sujet proposé au devoir à Bertoua : « La poésie n'est qu'un jeu sur les mots. » Discutez. Un camarade a écrit : « La poésie dit aussi des choses importantes. Par exemple dans un poème de Senghor. »","tache":"Réécrire le passage selon la méthode AEI avec un exemple analysé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-buying-selling",{"c":"1re D","m":"anglais","rang":16,"titre":"Vocabulary: buying and selling at the market","duree":20,"accroche":"How much is it? Can you reduce the price? Here is your change!","intro":"Markets and small stores are part of daily life: we buy foodstuff, clothes, phone credit; we compare prices, bargain and pay. Knowing the vocabulary of buying and selling helps in real life and in the exam, where dialogues at the market and shopping situations are frequent.","objectifs":["use the vocabulary of buying and selling","ask for prices and bargain politely","understand measures, money and payment expressions"],"parties":[{"t":"Words of the market","html":"<div class='def'><b>Definition</b><strong>Buying and selling</strong> is the exchange of goods for money. The <strong>seller</strong> (vendor, trader, shopkeeper) offers <strong>goods</strong>; the <strong>buyer</strong> (customer, client) pays the <strong>price</strong>.</div><ul><li>Places: <strong>a market</strong>, <strong>a stall</strong>, <strong>a store / shop</strong>, <strong>a supermarket</strong>, <strong>a kiosk</strong>.</li><li>Quantities: <strong>a heap</strong> (un tas), <strong>a bunch</strong> (of plantains, un régime), <strong>a bag</strong>, <strong>a kilo</strong>, <strong>a litre</strong>, <strong>a dozen</strong>, <strong>a tin</strong>, <strong>a loaf</strong> (of bread).</li><li>Money: <strong>cash</strong>, <strong>change</strong> (la monnaie rendue), <strong>a receipt</strong>, <strong>mobile money</strong>, <strong>a discount</strong>, <strong>cheap</strong> / <strong>expensive</strong>, <strong>a bargain</strong> (une bonne affaire).</li><li>Extra: <strong>a dash</strong> (Cameroonian English: a small extra gift from the seller).</li></ul>","retenir":"seller, buyer, customer, stall, heap, bunch, change, receipt, discount, cheap, expensive, bargain, dash."},{"t":"Useful expressions","verrou":true},{"t":"In context","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re D","famille":"Vie économique","agir":"Buy and sell politely and safely at the market","situation":"Your English club in Buea is preparing a short play for the school's cultural week: a scene at the market between a customer, a seller and a pickpocket who is caught.","tache":"Write a dialogue at the market using the vocabulary of buying and selling."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-philo-raisonnement",{"c":"1re D","m":"philo","rang":13,"titre":"Le raisonnement : déduction, induction, analogie","duree":25,"accroche":"Du général au particulier, ou du particulier au général ?","intro":"Raisonner, c'est enchaîner des jugements pour en tirer un nouveau, la conclusion. Le mathématicien déduit, le physicien induit, le médecin raisonne par analogie. Chaque type de raisonnement a sa force et ses limites, et la logique permet d'en mesurer la valeur.","objectifs":["définir le raisonnement","distinguer déduction, induction et analogie","évaluer la valeur de chacun"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>raisonnement</strong> est l'opération de l'esprit qui consiste à tirer une proposition nouvelle, la <strong>conclusion</strong>, d'une ou plusieurs propositions admises, les <strong>prémisses</strong>. Après le concept et le jugement, c'est la troisième opération de l'esprit en logique classique.</div><ul><li>Le lien entre prémisses et conclusion s'appelle l'<strong>inférence</strong>.</li><li>Un raisonnement peut être <strong>nécessaire</strong> (la conclusion découle forcément) ou seulement <strong>probable</strong>.</li></ul>","retenir":"Raisonnement : des prémisses à la conclusion ; inférence ; nécessaire ou probable."},{"t":"Déduction et induction","verrou":true},{"t":"Autres raisonnements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première C et D","famille":"Vie sociale et culturelle","agir":"Raisonner avec rigueur à partir de l'expérience","situation":"À Ebolowa, un élève observe que ses trois derniers devoirs faits la nuit ont eu de mauvaises notes. Il conclut : « Travailler la nuit fait toujours échouer. » Son camarade réplique : « Moi, je travaille la nuit et je réussis. »","tache":"Rédiger une dissertation courte sur l'expérience et la vérité générale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-crise-1929",{"c":"1re D","m":"histoire","rang":15,"titre":"La crise économique de 1929","duree":25,"accroche":"Un jeudi d'octobre à New York, et le cacao du Cameroun ne vaut plus rien.","intro":"Le 24 octobre 1929, la Bourse de New York s'effondre. La crise boursière devient une crise bancaire, industrielle, agricole et sociale, puis s'étend au monde entier, colonies comprises. Elle provoque un chômage massif et favorise la montée des régimes totalitaires.","objectifs":["expliquer les causes de la crise de 1929","décrire son extension et ses manifestations","mesurer ses conséquences, en particulier en Afrique et au Cameroun"],"parties":[{"t":"Les causes et le krach","html":"<div class='def'><b>Définition</b>Une <strong>crise économique</strong> est une rupture brutale de la croissance, marquée par la baisse de la production et des prix, les faillites et le chômage. Le <strong>krach</strong> est l'effondrement brutal des cours de la Bourse.</div><ul><li>Dans les années 1920, les États-Unis connaissent une forte croissance (« prospérité ») mais aussi une <strong>surproduction</strong> agricole et industrielle et une <strong>spéculation</strong> boursière, souvent à crédit.</li><li>Le <strong>jeudi 24 octobre 1929</strong> (« jeudi noir »), les cours s'effondrent à <strong>Wall Street</strong> ; la panique continue les jours suivants.</li></ul>","retenir":"Surproduction, spéculation à crédit ; krach de Wall Street, jeudi noir (24 octobre 1929)."},{"t":"Une crise générale et mondiale","verrou":true},{"t":"Les conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Comprendre la dépendance des économies africaines aux crises mondiales","situation":"En 2020, pendant la pandémie, un commerçant de Douala se plaint : « Quand l'économie mondiale tousse, c'est nous qui tombons malades. » Ton camarade affirme que cela n'est jamais arrivé avant.","tache":"Expliquer, à partir de 1929, comment une crise extérieure touche l'Afrique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-conclusion-dissertation",{"c":"1re D","m":"francais","rang":23,"titre":"Dissertation : rédiger la conclusion","duree":20,"accroche":"La dernière impression compte : une conclusion nette laisse le correcteur convaincu.","intro":"La conclusion de la dissertation est le dernier paragraphe que lit le correcteur. Elle fait le bilan du développement, répond clairement à la problématique et ouvre la réflexion. Courte et dense, elle ne doit ni répéter mot pour mot l'introduction ni apporter d'arguments nouveaux.","objectifs":["connaître la structure de la conclusion","formuler une réponse nette à la problématique","proposer une ouverture pertinente"],"parties":[{"t":"Structure de la conclusion","html":"<div class='def'><b>Définition</b>La <strong>conclusion</strong> de la dissertation est le paragraphe final qui fait le <strong>bilan</strong> du développement, apporte une <strong>réponse</strong> à la problématique et propose une <strong>ouverture</strong>.</div><ol><li><strong>Bilan</strong> : reprendre en une phrase chacune les étapes du développement.</li><li><strong>Réponse</strong> : prendre position clairement, en nuançant si nécessaire.</li><li><strong>Ouverture</strong> : élargir à une question voisine.</li></ol>","retenir":"Bilan, réponse, ouverture."},{"t":"Réussir la conclusion","verrou":true},{"t":"Un modèle","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale C et D","famille":"Vie sociale et culturelle","agir":"Conclure une dissertation avec netteté","situation":"Ton groupe de travail à Garoua a traité le sujet : « Le théâtre doit-il seulement divertir ? » Plan : I. Le théâtre divertit (rire, spectacle). II. Il instruit et corrige les mœurs (Molière, Oyônô Mbia). III. Il divertit pour mieux instruire.","tache":"Rédiger la conclusion avec bilan, réponse et ouverture."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-figures-construction",{"c":"1re D","m":"francais","rang":31,"titre":"Stylistique : les figures de construction","duree":55,"accroche":"L'ordre des mots aussi a un sens : parallélisme, ellipse, asyndète, polysyndète.","intro":"Leçon de langue (rubrique Stylistique et rhétorique). On observe des phrases d'un discours de fin d'année, on découvre en les manipulant les figures qui jouent sur la construction de la phrase, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les principales figures de construction","en interpréter l'effet","les employer dans ses propres écrits"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (discours composé pour la leçon) :</p><blockquote>1. « Nous avons travaillé, nous avons douté, nous avons réussi. »<br>2. « Et les parents, et les maîtres, et les élèves ont donné le meilleur d'eux-mêmes. »<br>3. « Le travail paie ; la paresse, jamais. »<br>4. « Ce diplôme, nous l'avons mérité. »<br>5. « Riches de savoir, pauvres d'argent, nous partons. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Phrase 1 : que remarques-tu sur les liens entre les propositions et sur leur forme ?</li><li>Phrase 2 : supprime les « et » : quel effet perd-on ?</li><li>Phrase 3 : quel mot manque dans la seconde partie ? Rétablis-le.</li><li>Phrase 4 : écris la phrase dans l'ordre habituel. Qu'est-ce qui est mis en relief ?</li><li>Phrase 5 : comment les deux groupes sont-ils construits ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Les propositions sont <strong>juxtaposées</strong>, sans mot de liaison (<strong>asyndète</strong>), et construites pareil (<strong>parallélisme</strong>), avec une <strong>gradation</strong> jusqu'à « réussi ». 2. La répétition de « et » (<strong>polysyndète</strong>) insiste sur chaque groupe et sur l'union. 3. « paie » est sous-entendu : <strong>ellipse</strong>. 4. « Nous avons mérité ce diplôme » : le COD est détaché en tête et repris par « l' » : <strong>dislocation</strong> (mise en relief). 5. Même construction (adjectif + de + nom) avec des mots opposés : <strong>parallélisme</strong> qui souligne une <strong>antithèse</strong> (riches / pauvres).</p></details><div class='def'><b>Ce que montre l'observation</b>Les <strong>figures de construction</strong> jouent sur l'ordre des mots, leur répétition ou leur suppression : elles donnent du rythme, insistent et mettent en relief.</div>","retenir":"Asyndète, polysyndète, ellipse, parallélisme, dislocation, gradation."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Citoyenneté","agir":"Utiliser les figures de construction pour convaincre","situation":"Le gouvernement des élèves de ton lycée à Bafang lance une campagne contre la tricherie aux examens. On te demande le discours d'ouverture.","tache":"Rédiger un discours mobilisant quatre figures de construction."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-quantifiers",{"c":"1re D","m":"anglais","rang":18,"titre":"Grammar: determiners and quantifiers","duree":20,"accroche":"A few or a little? Much or many? Each or every?","intro":"Determiners and quantifiers tell us how much or how many of something there is. They are used every day (shopping, planning, describing) and are frequently tested in Section A of the exam. The key is to know whether the noun is countable or uncountable.","objectifs":["distinguish countable and uncountable nouns","use some, any, no, none, much, many, few, little correctly","use all, both, each, every and most"],"parties":[{"t":"Countable and uncountable nouns","html":"<div class='def'><b>Definition</b><strong>Determiners</strong> are words placed before a noun to specify it (a, the, this, my…). <strong>Quantifiers</strong> are determiners that express <strong>quantity</strong>: some, any, much, many, few, little, all, both, each, every, most, no, none. Their use depends on whether the noun is <strong>countable</strong> (books, oranges) or <strong>uncountable</strong> (water, rice, information, advice).</div><ul><li><strong>many / few / a few</strong> + plural countable: many students, a few oranges.</li><li><strong>much / little / a little</strong> + uncountable: much money, a little sugar.</li><li><strong>How many</strong> students? <strong>How much</strong> rice?</li></ul><div class='attention'><b>Watch out</b><em>information, advice, furniture, luggage, news</em> are uncountable in English: « much information », not « many informations ».</div>","retenir":"many / few + countable ; much / little + uncountable ; information, advice, news: uncountable."},{"t":"Some, any, no, none ; few and a few","verrou":true},{"t":"All, both, each, every, most","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re D","famille":"Citoyenneté","agir":"Express quantities precisely to organise a community activity","situation":"Your class in Bafoussam is organising a clean-up day at the market. You must write the notice that lists what is available and what is missing.","tache":"Write a notice listing what is available and what is missing."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-reglement-premiere-guerre",{"c":"1re D","m":"histoire","rang":14,"titre":"Le règlement de la Première Guerre mondiale","duree":25,"accroche":"Versailles, la SDN, et le Cameroun partagé.","intro":"Après l'armistice du 11 novembre 1918, les vainqueurs réunis à Paris redessinent la carte du monde. Les traités de paix punissent l'Allemagne et démembrent les empires vaincus ; la Société des Nations est créée pour garantir la paix. Les colonies allemandes, dont le Cameroun, sont confiées aux vainqueurs sous forme de mandats.","objectifs":["présenter la conférence de la paix et les principes de Wilson","décrire les principaux traités, dont celui de Versailles","expliquer le système des mandats et le partage du Cameroun"],"parties":[{"t":"La conférence de la paix","html":"<div class='def'><b>Définition</b>Le <strong>règlement de la guerre</strong> désigne l'ensemble des traités et décisions qui fixent les conditions de la paix après 1918 ; un <strong>mandat</strong> est un territoire confié par la SDN à une puissance chargée de l'administrer au nom de la communauté internationale.</div><ul><li>La <strong>conférence de la paix</strong> s'ouvre à Paris en janvier 1919, sans les vaincus ; elle est dominée par les « Quatre » : Wilson (États-Unis), Clemenceau (France), Lloyd George (Royaume-Uni), Orlando (Italie).</li><li>Les <strong>Quatorze Points</strong> du président <strong>Wilson</strong> (8 janvier 1918) : droit des peuples à disposer d'eux-mêmes, liberté des mers, création d'une société des nations.</li></ul>","retenir":"Conférence de Paris (1919), les Quatre, Quatorze Points de Wilson ; mandat."},{"t":"Les traités","verrou":true},{"t":"Les mandats et le Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les origines historiques du bilinguisme camerounais","situation":"Un élève de Buea demande : « Pourquoi le Cameroun a-t-il deux langues officielles héritées de deux colonisateurs différents ? »","tache":"Expliquer le règlement de la Première Guerre mondiale et ses conséquences."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-histoire-cameroun-interets-europeens",{"c":"1re D","m":"histoire","rang":21,"titre":"Le Cameroun au centre des intérêts européens (XVe-XIXe siècle)","duree":25,"accroche":"Des crevettes de l'estuaire au traité de 1884 : quatre siècles de convoitises.","intro":"Bien avant la colonisation, la côte camerounaise attire les Européens : navigateurs portugais, négriers, commerçants, missionnaires. Au XIXᵉ siècle, Britanniques, Allemands et Français se disputent l'influence sur l'estuaire du Wouri. En 1884, l'Allemagne l'emporte par le traité germano-douala.","objectifs":["retracer les premiers contacts entre Européens et Camerounais","présenter les intérêts commerciaux, religieux et politiques au XIXᵉ siècle","expliquer comment l'Allemagne s'empare du Cameroun en 1884"],"parties":[{"t":"Des premiers contacts à la traite","html":"<div class='def'><b>Définition</b>Les <strong>intérêts européens</strong> désignent les motivations économiques, religieuses, scientifiques et politiques qui poussent les puissances européennes à s'implanter sur la côte camerounaise.</div><ul><li>Vers <strong>1472</strong>, le navigateur portugais <strong>Fernando Póo</strong> atteint l'estuaire du Wouri ; les crevettes abondantes lui font nommer le fleuve <strong>Rio dos Camarões</strong> (rivière des crevettes), d'où le nom « Cameroun ».</li><li>Du XVIᵉ au XIXᵉ siècle, la côte participe à la <strong>traite atlantique</strong> : les chefs côtiers (Douala, Bimbia) servent d'intermédiaires.</li><li>Après l'abolition de la traite par le Royaume-Uni (1807), le <strong>commerce dit « légitime »</strong> se développe : huile de palme, ivoire, caoutchouc contre tissus, alcool, armes.</li></ul>","retenir":"Fernando Póo (vers 1472), Rio dos Camarões ; traite atlantique ; commerce « légitime » après 1807."},{"t":"Britanniques, Allemands, Français au XIXᵉ siècle","verrou":true},{"t":"Le traité germano-douala de 1884","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comprendre comment le Cameroun est devenu une colonie","situation":"Au musée maritime de Douala, ton petit frère voit une copie du traité de 1884 et demande : « Pourquoi les rois douala ont-ils signé avec les Allemands ? »","tache":"Expliquer le contexte et le contenu du traité, puis porter un jugement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-formation-mots",{"c":"1re D","m":"francais","rang":34,"titre":"Lexicologie : la formation des mots","duree":55,"accroche":"Ndolè, taxi-moto, BEPC, courriel : comment naissent les mots ?","intro":"Leçon de langue (rubrique Sémantique et lexicologie). On observe des mots entendus au marché et à la radio, on les décompose pour découvrir comment se forment les mots du français, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["identifier les procédés de formation des mots","distinguer néologie de forme et néologie de sens","reconnaître les emprunts et leurs usages"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (phrases composées pour la leçon) :</p><blockquote>« Au marché Mokolo, une revendeuse de plantain discute avec un moto-taximan. À la radio, on parle de la déforestation, de l'informatisation des mairies et du covoiturage. Mon petit frère, lui, réclame un portable et un ordi. Le prof d'anglais dit que le <i>week-end</i> est trop court. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Décompose « revendeuse », « déforestation », « informatisation » : quel élément porte le sens de base ? Quels éléments s'y ajoutent ?</li><li>Comment sont formés « moto-taximan » et « covoiturage » ?</li><li>Que remarques-tu sur « ordi » et « prof » ?</li><li>D'où vient « week-end » ?</li><li>« Portable » est-il un nom ou un adjectif ? Comment est-il devenu ce qu'il est ici ?</li></ol><details><summary>Voir l'analyse</summary><p>1. re- + vend + -euse ; dé- + forest + -ation ; informat(ique) + -is(er) + -ation : un <strong>radical</strong> auquel s'ajoutent des <strong>préfixes</strong> (avant) et des <strong>suffixes</strong> (après) : c'est la <strong>dérivation</strong>. 2. « moto-taximan » réunit des mots existants (moto + taxi + -man) : <strong>composition</strong> ; « covoiturage » (co- + voiture + -age) mêle préfixe et suffixe. 3. Ce sont des mots raccourcis : <strong>troncation</strong> (ordinateur, professeur). 4. De l'anglais : c'est un <strong>emprunt</strong>. 5. L'adjectif « portable » est employé comme nom : <strong>conversion</strong> (changement de classe grammaticale).</p></details><div class='def'><b>Ce que montre l'observation</b>Les mots nouveaux se forment par <strong>dérivation</strong>, <strong>composition</strong>, <strong>troncation</strong>, <strong>conversion</strong> ou <strong>emprunt</strong> à une autre langue.</div>","retenir":"Dérivation, composition, troncation, conversion, emprunt."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première D","famille":"Vie sociale et culturelle","agir":"Analyser la formation des mots et maîtriser les registres","situation":"Le club de journalisme de ton lycée prépare un petit lexique des mots inventés ou empruntés que les jeunes de Douala utilisent, pour une exposition sur « La vie des mots ».","tache":"Présenter six mots en usage au Cameroun et leur procédé de formation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-francais-structures-phrase",{"c":"1re D","m":"francais","rang":19,"titre":"Morphosyntaxe : juxtaposition, coordination, subordination","duree":55,"accroche":"Une proposition, deux, ou une principale et ses subordonnées ?","intro":"Leçon de langue (rubrique Morphosyntaxe). On observe un même fait divers raconté de plusieurs manières, on découvre en manipulant les phrases comment s'unissent les propositions, puis on formule la règle et on s'entraîne au format de l'épreuve.","objectifs":["distinguer phrase simple, composée et complexe","identifier juxtaposition, coordination et subordination","repérer la nature des propositions subordonnées"],"parties":[{"t":"Observation et analyse du corpus","html":"<p><strong>Corpus</strong> (phrases composées pour la leçon) :</p><blockquote>1. « Le car est tombé en panne. Les passagers ont attendu. »<br>2. « Le car est tombé en panne ; les passagers ont attendu. »<br>3. « Le car est tombé en panne, donc les passagers ont attendu. »<br>4. « Comme le car était tombé en panne, les passagers ont attendu. »<br>5. « Les passagers, qui étaient fatigués, ont attendu que le car soit réparé. »</blockquote><p><strong>Questionnaire guide</strong></p><ol><li>Compte les verbes conjugués de chaque phrase : combien de propositions ?</li><li>Comment les propositions sont-elles reliées dans les phrases 2, 3 et 4 ?</li><li>Dans la phrase 4, supprime « Les passagers ont attendu » : la proposition restante peut-elle exister seule ? Et dans la phrase 3, si l'on supprime la première ?</li><li>Dans la phrase 5, quels mots introduisent les propositions dépendantes ?</li></ol><details><summary>Voir l'analyse</summary><p>1. Phrase 1 : deux phrases simples ; phrases 2 à 4 : deux propositions ; phrase 5 : trois. 2. Phrase 2 : par un signe de ponctuation (<strong>juxtaposition</strong>) ; phrase 3 : par « donc » (<strong>coordination</strong>) ; phrase 4 : par « comme » (<strong>subordination</strong>). 3. « Comme le car était tombé en panne » ne peut pas exister seule : elle <strong>dépend</strong> de la principale ; dans la phrase 3, chaque proposition reste autonome. 4. « qui » (pronom relatif) et « que » (conjonction de subordination).</p></details><div class='def'><b>Ce que montre l'observation</b>Une phrase <strong>complexe</strong> réunit plusieurs propositions par <strong>juxtaposition</strong>, <strong>coordination</strong> (propositions autonomes) ou <strong>subordination</strong> (une proposition dépend d'une principale).</div>","retenir":"Juxtaposition et coordination : autonomie ; subordination : dépendance."},{"t":"Vérification et formulation de la règle (Je retiens)","verrou":true},{"t":"Consolidation (repérer, analyser, interpréter)","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première C et D","famille":"Vie sociale et culturelle","agir":"Varier la structure des phrases pour mieux raconter","situation":"Le récit d'un camarade de Ngaoundéré n'est fait que de phrases simples : « Le car partit. Il pleuvait. La route était glissante. Le chauffeur roulait vite. Un pneu éclata. Les passagers crièrent. Personne ne fut blessé. »","tache":"Réécrire le récit avec des phrases composées et complexes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-anglais-polite-requests",{"c":"1re D","m":"anglais","rang":15,"titre":"Grammar: polite requests and suggestions","duree":20,"accroche":"Could you…? Would you mind…? Let me… Why don't we…? Politeness is grammar too.","intro":"In English, the way we ask for something or make a suggestion is as important as the request itself. A command like « Give me the book! » sounds rude; « Could you give me the book, please? » is polite. Requests and suggestions are frequent in dialogues and in Section A of the exam.","objectifs":["make polite requests with can, could, would, would you mind","make suggestions with let's, shall we, why don't we, how about","offer help with let me and shall I"],"parties":[{"t":"Polite requests","html":"<div class='def'><b>Definition</b>A <strong>polite request</strong> is a way of asking someone to do something, or asking for permission, without giving an order. A <strong>suggestion</strong> is a proposal of an idea or action.</div><ul><li><strong>Can you</strong> + bare infinitive (informal): <em>Can you pass the salt?</em></li><li><strong>Could you</strong> + bare infinitive (more polite): <em>Could you open the window, please?</em></li><li><strong>Would you</strong> + bare infinitive: <em>Would you help me, please?</em></li><li><strong>Would you mind</strong> + verb-<strong>ing</strong>: <em>Would you mind closing the door?</em> Answer « No, not at all » means you agree!</li><li>Permission: <strong>May I / Could I</strong> + bare infinitive: <em>May I come in?</em> ; <strong>Would you mind if I</strong> + past: <em>Would you mind if I sat here?</em></li></ul>","retenir":"Can / could / would you + bare infinitive ; would you mind + -ing ; may I / could I ; would you mind if I + past."},{"t":"Offers and suggestions","verrou":true},{"t":"Answering","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re D","famille":"Vie sociale et culturelle","agir":"Make polite requests and suggestions in school life","situation":"Your class in Kumba wants to organise a revision weekend at school before the exams. You need the principal's permission and the help of some teachers and parents.","tache":"Write a formal letter requesting permission and making suggestions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r01",{"duree":20,"titre":"L'IA dans les métiers et les filières professionnelles","accroche":"L'IA transforme le travail.","intro":"L'intelligence artificielle s'invite dans presque tous les métiers. Connaître ses usages professionnels aide à choisir sa filière et à se préparer.","objectifs":["citer des usages professionnels de l'IA","identifier les compétences nouvelles","mesurer les effets de l'IA sur l'emploi"],"parties":[{"t":"L'IA au travail","html":"<div class='def'><b>Définition</b>Une <strong>application professionnelle de l'IA</strong> est l'usage d'un système d'intelligence artificielle pour accomplir ou faciliter une tâche de travail : analyser, rédiger, diagnostiquer, prévoir, automatiser.</div><ul><li><strong>santé</strong> : aide au diagnostic sur images ;</li><li><strong>droit et administration</strong> : recherche et résumé de textes ;</li><li><strong>agriculture</strong> : prévision des récoltes, détection des maladies ;</li><li><strong>banque</strong> : détection des fraudes, analyse du risque de crédit ;</li><li><strong>communication</strong> : rédaction, traduction, création d'images.</li></ul>"},{"t":"Effets sur l'emploi","html":"<p>L'IA automatise des tâches répétitives, transforme des métiers et en crée de nouveaux (analyste de données, ingénieur en IA, spécialiste de l'éthique des données). Les compétences clés deviennent : esprit critique, maîtrise des outils numériques, créativité, communication.</p>","retenir":"Automatiser, transformer, créer des métiers.","labo":{"type":"trier","invite":"Choisis un secteur.","items":[["Santé","aide au diagnostic sur images."],["Banque","détection des fraudes et du risque."],["Agriculture","prévision des récoltes."],["Communication","rédaction et traduction assistées."]]}},{"t":"Se préparer","html":"<p>Quelle que soit la filière, l'élève a intérêt à maîtriser les outils, à apprendre à vérifier les résultats d'une IA et à développer les compétences humaines que la machine remplace mal : relation, jugement, sens éthique.</p><div class='attention'><b>Attention</b>l'IA ne supprime pas la responsabilité du professionnel : c'est lui qui répond de la décision.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans un cabinet médical, l'IA peut servir à :</p><ol type='a'><li>signer les ordonnances à la place du médecin</li><li>remplacer définitivement tous les infirmiers</li><li>analyser des radiographies</li><li>décider seule des traitements sans aucun contrôle</li></ol><details><summary>Voir la réponse</summary><p><strong>analyser des radiographies</strong>. Elle aide au diagnostic ; le médecin décide.</p></details><p><strong>Exercice.</strong></p><p>Cite un nouveau métier lié à l'IA.</p><details><summary>Voir la réponse</summary><p>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique."}],"revision":["Usages : santé, droit, agriculture, banque, communication.","Effets : automatisation, transformation, nouveaux métiers.","Compétences : esprit critique, outils, créativité, éthique."],"exo":"<p>Cite un nouveau métier lié à l'IA. <em>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</em></p>","quiz":[{"q":"Dans un cabinet médical, l'IA peut servir à :","r":["signer les ordonnances à la place du médecin","remplacer définitivement tous les infirmiers","analyser des radiographies","décider seule des traitements sans aucun contrôle"],"b":2,"e":"Elle aide au diagnostic ; le médecin décide."},{"q":"L'automatisation par l'IA touche surtout :","r":["les décisions éthiques les plus délicates","les métiers qui demandent de l'empathie","les relations humaines entre collègues","les tâches répétitives"],"b":3,"e":"Saisie, tri, classement, réponses standard."},{"q":"Un métier né avec l'IA est :","r":["ingénieur en données","porteur d'eau dans les quartiers anciens","conducteur de calèche dans les grandes villes","allumeur de réverbères à huile"],"b":0,"e":"Collecte, préparation et analyse des données."},{"q":"Dans le domaine juridique, l'IA peut :","r":["rendre seule les jugements à la place du juge et des avocats","rechercher rapidement des textes et des décisions","voter les lois à la place des parlementaires","arrêter les suspects dans la rue sans policier"],"b":1,"e":"Elle facilite la recherche documentaire."},{"q":"Une compétence essentielle face à l'IA est :","r":["la capacité à tout recopier sans lire","la mémorisation des mots de passe d'autrui","l'esprit critique","l'utilisation exclusive du papier et du crayon"],"b":2,"e":"Il faut juger la qualité des réponses."},{"q":"En agriculture, des drones avec IA permettent :","r":["de remplacer totalement la pluie et le soleil","de supprimer le besoin de semences de qualité","de récolter sans aucune intervention humaine","de surveiller l'état des cultures"],"b":3,"e":"Ils repèrent maladies et manque d'eau."},{"q":"Dans la banque, l'IA sert notamment à :","r":["évaluer les risques de crédit","imprimer elle-même la monnaie nationale","fixer seule le taux directeur de la BEAC","fermer les agences les jours de marché"],"b":0,"e":"Elle analyse l'historique des clients."},{"q":"En communication, l'IA générative aide à :","r":["garantir que toutes les publicités sont vraies et honnêtes","produire des premières versions de textes et de visuels","remplacer la loi sur la protection des données","interdire la publication de toute fausse information"],"b":1,"e":"Le professionnel relit et corrige."},{"q":"L'IA transforme un métier quand :","r":["elle supprime toutes les compétences humaines nécessaires","elle interdit l'usage de l'ordinateur au bureau","elle modifie la manière d'exécuter les tâches","elle rend le diplôme inutile pour tous les postes"],"b":2,"e":"Le métier évolue sans disparaître."},{"q":"Pour se préparer aux métiers de demain, il faut :","r":["éviter tout contact avec les outils numériques modernes","attendre que l'IA choisisse sa filière à sa place","abandonner les mathématiques et le français à l'école","apprendre à utiliser les outils d'IA avec éthique"],"b":3,"e":"Outils, créativité et éthique se complètent."}],"c":"1re D","m":"info","rang":1,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ta cousine, comptable dans une PME de Douala, craint que « l'IA lui prenne son travail » depuis qu'un logiciel saisit automatiquement les factures.","tache":"Montre-lui comment son métier se transforme plutôt qu'il ne disparaît, et propose deux compétences à développer."},"gratuit":true});
VRT_L("1re-d-info-r02",{"duree":20,"titre":"Réalisation d'un projet scolaire assisté par l'IA","accroche":"Travailler avec l'IA, pas la laisser travailler.","intro":"L'IA peut aider à mener un projet scolaire, à condition de garder la maîtrise de chaque étape et de vérifier ce qu'elle produit.","objectifs":["planifier un projet scolaire","utiliser l'IA à chaque étape de façon pertinente","vérifier et déclarer l'usage de l'IA"],"parties":[{"t":"Le projet et l'IA","html":"<div class='def'><b>Définition</b>Un <strong>projet assisté par l'IA</strong> est un travail mené par l'élève dans lequel l'IA intervient comme outil d'aide (idées, plan, explications, relecture), sous son contrôle.</div>"},{"t":"Les étapes","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":2,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ton groupe de quatre élèves doit réaliser en trois semaines un dossier sur le traitement des déchets plastiques à Yaoundé ; un membre propose de « tout demander à l'IA la veille ».","tache":"Propose un plan de travail en cinq étapes où l'IA intervient de façon pertinente, en précisant à chaque étape ce qui reste à la charge du groupe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r03",{"duree":20,"titre":"Cadre juridique et protection des données face à l'IA","accroche":"Nos données nourrissent l'IA.","intro":"Les systèmes d'IA utilisent d'énormes quantités de données, dont des données personnelles. La loi encadre leur collecte et leur usage.","objectifs":["définir une donnée personnelle","connaître le cadre juridique camerounais et international","protéger ses données face aux outils d'IA"],"parties":[{"t":"Données personnelles","html":"<div class='def'><b>Définition</b>Une <strong>donnée personnelle</strong> est toute information qui permet d'identifier une personne directement ou indirectement : nom, numéro de téléphone, photo, voix, adresse, localisation, numéro de compte.</div><p>Certaines sont dites <strong>sensibles</strong> : santé, religion, opinions politiques, données biométriques.</p>"},{"t":"Le cadre juridique","verrou":true},{"t":"Se protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":3,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Pour « faire rire la classe », un élève veut fournir à une application d'IA la photo et des enregistrements vocaux de son professeur afin de produire une fausse vidéo.","tache":"Identifie les données personnelles en jeu, les règles violées et les risques pour l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r04",{"duree":20,"titre":"Biais algorithmiques et équité de l'IA","accroche":"Une IA peut être injuste.","intro":"Une IA apprend à partir de données produites par des humains. Si ces données sont déséquilibrées, ses décisions peuvent être injustes envers certains groupes.","objectifs":["définir un biais algorithmique","en identifier les causes","proposer des moyens de réduire les biais"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>biais algorithmique</strong> est une erreur systématique d'une IA qui la conduit à traiter de façon injuste ou défavorable certaines personnes ou certains groupes.</div><p>Exemples : reconnaissance faciale moins précise sur les peaux foncées parce que les données d'entraînement contenaient surtout des visages clairs ; outil de recrutement qui défavorise les femmes parce qu'il a appris sur des recrutements passés.</p>"},{"t":"Les causes","verrou":true},{"t":"Vers une IA équitable","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":4,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Une banque teste une IA d'octroi de crédit : sur 1 000 dossiers, elle accepte 62 % des demandes d'hommes et 31 % des demandes de femmes au profil financier comparable.","tache":"Montre qu'il s'agit d'un biais, explique sa cause probable et propose trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r05",{"duree":20,"titre":"Écriture des algorithmes simples","accroche":"Rappels de base de l'algorithmique.","intro":"Cette leçon révise la structure d'un algorithme, les types de données et les instructions de base avant d'aborder les itérations.","objectifs":["écrire un algorithme complet","utiliser les types et opérateurs","exécuter une trace"],"parties":[{"t":"Rappels","html":"<div class='def'><b>Définition</b>Un <strong>algorithme</strong> est une suite finie et ordonnée d'instructions non ambiguës qui résout un problème. Il comporte un en-tête, une partie déclarative (constantes, variables typées) et un corps (Début ... Fin).</div><p>Types : entier, réel, caractère, chaîne, booléen. Opérateurs : +, −, *, /, div (division entière), mod (reste), comparaisons, ET, OU, NON.</p>"},{"t":"Exemple","verrou":true},{"t":"La trace","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":5,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un commerçant veut convertir une durée donnée en secondes en heures, minutes et secondes (par exemple 7 384 s).","tache":"Écris l'algorithme utilisant div et mod, puis fais sa trace pour 7 384 s."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r06",{"duree":20,"titre":"Les structures itératives","accroche":"Répéter efficacement.","intro":"Les boucles permettent de répéter un traitement sans réécrire les instructions. On distingue Pour, Tant que et Répéter ... Jusqu'à.","objectifs":["écrire les trois boucles","choisir la boucle adaptée","éviter les boucles infinies"],"parties":[{"t":"Les trois boucles","html":"<div class='def'><b>Définition</b>Une <strong>structure itérative</strong> (boucle) répète un bloc d'instructions un certain nombre de fois ou tant qu'une condition est remplie.</div><pre>Pour i ← 1 à n Faire ... FinPour\nTant que condition Faire ... FinTantque\nRépéter ... Jusqu'à condition</pre>"},{"t":"Choisir","verrou":true},{"t":"Exemple : somme de 1 à n","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":6,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Une épargnante place 100 000 F sur un compte à 5 % d'intérêts par an (intérêts composés) et veut savoir au bout de combien d'années elle aura au moins 150 000 F.","tache":"Écris l'algorithme avec une boucle Tant que et donne le résultat attendu."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r07",{"duree":20,"titre":"Les structures de données","accroche":"Ranger plusieurs valeurs sous un même nom.","intro":"Pour traiter les notes de 40 élèves, déclarer 40 variables serait absurde. On utilise des structures de données comme les tableaux et les enregistrements.","objectifs":["définir une structure de données","déclarer un tableau","déclarer un enregistrement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>structure de données</strong> est une manière d'organiser plusieurs données en mémoire pour les manipuler facilement. Un <strong>tableau</strong> regroupe un nombre fixe d'éléments de même type, repérés par un <strong>indice</strong>.</div>"},{"t":"Les tableaux","verrou":true},{"t":"Les enregistrements","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":7,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"La bibliothèque du lycée veut gérer 500 livres, chacun ayant un titre, un auteur, une année et un état (disponible ou emprunté).","tache":"Propose une structure de données adaptée en déclarant le type et la variable nécessaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r08",{"duree":20,"titre":"Opérations sur les tableaux","accroche":"Remplir, parcourir, calculer.","intro":"Les tableaux se manipulent presque toujours avec des boucles : saisie, affichage, somme, recherche du maximum, comptage.","objectifs":["remplir et afficher un tableau","calculer somme et moyenne","rechercher le maximum et compter des éléments"],"parties":[{"t":"Remplir et afficher","html":"<div class='def'><b>Définition</b><strong>Parcourir un tableau</strong>, c'est accéder successivement à chacun de ses éléments, généralement avec une boucle Pour de l'indice de début à l'indice de fin.</div><pre>Pour i ← 1 à n Faire\n   Lire(T[i])\nFinPour</pre>"},{"t":"Somme, moyenne, maximum","verrou":true},{"t":"Compter et décaler","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":8,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Les températures maximales de Garoua pendant 7 jours sont relevées dans un tableau : 38, 41, 40, 43, 39, 42, 37.","tache":"Écris l'algorithme qui calcule la moyenne, la température maximale et le nombre de jours à plus de 40 °C, puis donne les résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r09",{"duree":20,"titre":"Exécution d'un algorithme utilisant les tableaux","accroche":"Suivre pas à pas un traitement de tableau.","intro":"Pour vérifier un algorithme sur un tableau, on fait une trace qui suit l'indice et le contenu des cases.","objectifs":["construire une trace avec un tableau","détecter une erreur par la trace","exécuter un algorithme d'inversion"],"parties":[{"t":"La trace d'un tableau","html":"<div class='def'><b>Définition</b><strong>Exécuter un algorithme à la main</strong>, c'est simuler son fonctionnement en notant, à chaque étape, la valeur des variables et le contenu du tableau.</div>"},{"t":"Exemple : inverser un tableau","verrou":true},{"t":"Détecter les erreurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":9,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un camarade a écrit : Pour i ← 1 à 4 Faire T[i] ← T[i + 1] FinPour, pour décaler vers la gauche le tableau T = [4 ; 6 ; 8 ; 10 ; 12].","tache":"Fais la trace de cet algorithme et donne le contenu final de T, puis explique ce qu'il fait."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r10",{"duree":20,"titre":"Fonctions et procédures","accroche":"Découper un problème en sous-problèmes.","intro":"Un long algorithme devient lisible quand on le découpe en sous-algorithmes réutilisables : les fonctions et les procédures.","objectifs":["distinguer fonction et procédure","déclarer et appeler un sous-algorithme","expliquer l'intérêt de la modularité"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>sous-algorithme</strong> est un bloc d'instructions nommé, appelé depuis l'algorithme principal. Une <strong>fonction</strong> renvoie une valeur ; une <strong>procédure</strong> exécute une action sans renvoyer de valeur.</div>"},{"t":"Syntaxe","verrou":true},{"t":"Intérêts","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":10,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Un programme de gestion de notes doit calculer plusieurs fois la moyenne de trois notes avec coefficients et afficher une appréciation (« Bien » à partir de 14, « Passable » de 10 à 14, « Insuffisant » sinon).","tache":"Écris une fonction de moyenne et une procédure d'appréciation, puis montre comment les appeler."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r11",{"duree":20,"titre":"Modes de passage des paramètres","accroche":"Par valeur ou par adresse.","intro":"Quand on appelle un sous-algorithme, ses paramètres peuvent recevoir une copie de la valeur ou désigner directement la variable d'origine.","objectifs":["distinguer paramètres formels et effectifs","distinguer passage par valeur et par référence","choisir le mode adapté"],"parties":[{"t":"Paramètres","html":"<div class='def'><b>Définition</b>Les <strong>paramètres formels</strong> sont ceux écrits dans la déclaration du sous-algorithme ; les <strong>paramètres effectifs</strong> sont les valeurs ou variables fournies lors de l'appel.</div>"},{"t":"Les deux modes","verrou":true},{"t":"Choisir","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":11,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Une procédure Augmenter(p : entier) contient p ← p + 500. Dans l'algorithme principal, prix ← 2000 puis Augmenter(prix) ; Écrire(prix).","tache":"Indique la valeur affichée et explique-la, puis corrige la procédure pour que le prix soit réellement augmenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r12",{"duree":20,"titre":"Exécution d'un algorithme intégrant fonctions et procédures","accroche":"Suivre les appels.","intro":"Exécuter à la main un algorithme qui appelle des sous-algorithmes demande de suivre le passage des paramètres et le retour des valeurs.","objectifs":["tracer un appel de fonction","suivre les variables locales","vérifier le passage des paramètres"],"parties":[{"t":"La pile d'appels","html":"<div class='def'><b>Définition</b>Lors d'un <strong>appel</strong>, l'exécution passe au sous-algorithme avec ses paramètres ; à la fin, elle revient à l'instruction qui suit l'appel, avec la valeur renvoyée pour une fonction.</div>"},{"t":"Exemple","verrou":true},{"t":"Méthode de trace","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":12,"apc":{"module":"Algorithmique : itérations, tableaux et sous-algorithmes","famille":"Algorithmique et programmation","agir":"Résoudre un problème par un algorithme structuré","situation":"Fonction F(n : entier) : entier ; Début : Si n mod 2 = 0 Alors Retourner n div 2 Sinon Retourner 3 * n + 1 FinSi ; FinFonction. L'algorithme principal part de x ← 6 et applique x ← F(x) jusqu'à obtenir 1, en comptant les étapes.","tache":"Fais la trace complète et donne le nombre d'étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r13",{"duree":20,"titre":"Installation d'un compilateur","accroche":"Préparer son poste pour programmer en C.","intro":"Pour programmer en C, il faut un compilateur qui traduit le code source en programme exécutable, souvent intégré à un environnement de développement.","objectifs":["définir compilateur et environnement de développement","installer un compilateur C","compiler un premier programme"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>compilateur</strong> traduit un programme écrit dans un langage de haut niveau (C) en langage machine exécutable. Un <strong>environnement de développement intégré</strong> (EDI) réunit un éditeur, un compilateur et un débogueur (Code::Blocks, Dev-C++, Visual Studio Code avec GCC).</div>"},{"t":"Installer","html":"<ol><li>Télécharger un EDI depuis son site officiel, de préférence avec le compilateur inclus (par exemple Code::Blocks avec MinGW/GCC).</li><li>Lancer l'installation et accepter les options par défaut.</li><li>Vérifier que l'EDI détecte le compilateur dans ses réglages.</li><li>Créer un projet « Console application » en C.</li></ol>","retenir":"Éditeur + compilateur + débogueur = EDI.","labo":{"type":"etapes","items":[["Télécharger","EDI avec compilateur."],["Installer","options par défaut."],["Vérifier","compilateur détecté."],["Créer","un projet console."],["Compiler et exécuter","Build and run."]]}},{"t":"Premier programme","html":"<pre>#include &lt;stdio.h&gt;\nint main(void)\n{\n   printf(\"Bonjour le Cameroun !\\n\");\n   return 0;\n}</pre><p>Compiler puis exécuter (« Build and run ») : la console affiche le message. Les étapes de la compilation : prétraitement, compilation, édition des liens.</p><div class='attention'><b>Attention</b>un message d'erreur de compilation indique la ligne : on lit le premier message en priorité.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Un compilateur transforme :</p><ol type='a'><li>un programme exécutable en image affichable</li><li>un texte en fichier audio</li><li>un tableur en base de données</li><li>le code source en programme exécutable</li></ol><details><summary>Voir la réponse</summary><p><strong>le code source en programme exécutable</strong>. Langage C → exécutable.</p></details><p><strong>Exercice.</strong></p><p>Quel fichier d'en-tête faut-il inclure pour utiliser printf ?</p><details><summary>Voir la réponse</summary><p>(Réponse : stdio.h.)</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Compilateur : source → exécutable.","EDI : éditeur, compilateur, débogueur (Code::Blocks, GCC).","Premier programme : include, main, printf, return 0."],"exo":"<p>Quel fichier d'en-tête faut-il inclure pour utiliser printf ? <em>(Réponse : stdio.h.)</em></p>","quiz":[{"q":"Un compilateur transforme :","r":["un programme exécutable en image affichable","un texte en fichier audio","un tableur en base de données","le code source en programme exécutable"],"b":3,"e":"Langage C → exécutable."},{"q":"Code::Blocks est :","r":["un environnement de développement intégré","un système d'exploitation libre pour les serveurs","un tableur en ligne","un antivirus gratuit"],"b":0,"e":"EDI : éditeur, compilateur, débogueur."},{"q":"GCC est :","r":["un navigateur web","un compilateur C","un logiciel de dessin","un traitement de texte"],"b":1,"e":"GNU Compiler Collection."},{"q":"Un EDI regroupe notamment :","r":["un clavier, une souris et un écran","un tableur, un traitement de texte et un antivirus","un éditeur, un compilateur et un débogueur","une imprimante, un scanner et un modem"],"b":2,"e":"Integrated Development Environment."},{"q":"Tout programme C commence son exécution par la fonction :","r":["printf","scanf","include","main"],"b":3,"e":"C'est le point d'entrée."},{"q":"return 0; à la fin de main signifie :","r":["que le programme s'est bien terminé","que le programme a rencontré une erreur","que le programme recommence au début","que l'affichage est effacé"],"b":0,"e":"Code de retour 0 = succès."},{"q":"Le fichier source d'un programme C porte l'extension :","r":[".exe",".c",".html",".docx"],"b":1,"e":"Par exemple bonjour.c."},{"q":"Le débogueur sert à :","r":["traduire automatiquement le programme en langue anglaise","imprimer le code source en couleur","exécuter pas à pas pour trouver les erreurs","installer automatiquement le compilateur"],"b":2,"e":"Points d'arrêt, inspection des variables."},{"q":"Dev-C++ est :","r":["un tableur pour les programmeurs","un réseau social","un système de fichiers","un EDI pour le langage C"],"b":3,"e":"Comme Code::Blocks."},{"q":"Une erreur de compilation est signalée :","r":["avec la ligne concernée","uniquement après l'exécution","par un son de l'ordinateur","jamais par le compilateur"],"b":0,"e":"On corrige puis on recompile."}],"c":"1re D","m":"info","rang":13,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Dans la salle informatique, Code::Blocks affiche « Can't find compiler executable » quand un élève clique sur « Build ».","tache":"Explique la cause de ce message et la démarche pour corriger le problème."},"gratuit":true});
VRT_L("1re-d-info-r14",{"duree":20,"titre":"Bibliothèques et fonctions d'entrée/sortie en C","accroche":"Lire et afficher en langage C.","intro":"Le langage C s'appuie sur des bibliothèques standard. Les fonctions printf et scanf de stdio.h permettent d'afficher et de lire des données.","objectifs":["inclure une bibliothèque","afficher avec printf","lire avec scanf"],"parties":[{"t":"Bibliothèques","html":"<div class='def'><b>Définition</b>Une <strong>bibliothèque</strong> est un ensemble de fonctions déjà écrites, que l'on rend disponibles par une directive <code>#include</code>. Exemples : stdio.h (entrées-sorties), math.h (fonctions mathématiques), string.h (chaînes).</div>"},{"t":"Afficher et lire","verrou":true},{"t":"Déclarations et types","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":14,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un élève veut écrire un programme C qui lit le prix unitaire d'un cahier et la quantité, puis affiche le montant à payer ; son programme se compile mais plante dès la saisie.","tache":"Écris un programme correct et indique l'erreur la plus probable de l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r15",{"duree":20,"titre":"Structures itératives en C","accroche":"Les boucles for, while et do while.","intro":"Les boucles de l'algorithmique se traduisent directement en C par for, while et do ... while.","objectifs":["traduire une boucle Pour en for","traduire Tant que et Répéter","écrire un programme avec boucle"],"parties":[{"t":"Correspondances","html":"<div class='def'><b>Définition</b>En C, une <strong>boucle</strong> s'écrit avec <code>for</code> (Pour), <code>while</code> (Tant que) ou <code>do ... while</code> (Répéter ... Jusqu'à, avec la condition inversée).</div>"},{"t":"Syntaxe","verrou":true},{"t":"Opérateurs utiles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":15,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un programme doit afficher la table de multiplication d'un nombre lu au clavier (de 1 à 10) et redemander le nombre tant qu'il n'est pas compris entre 1 et 12.","tache":"Écris le programme C en utilisant do ... while et for."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r16",{"duree":20,"titre":"Tableaux et fichiers multimédias dans une page web","accroche":"Structurer et enrichir une page HTML.","intro":"Le langage HTML décrit le contenu d'une page web à l'aide de balises. On peut y insérer des tableaux, des images, du son et de la vidéo.","objectifs":["créer un tableau HTML","insérer image, audio et vidéo","respecter la structure d'une page"],"parties":[{"t":"Les tableaux","html":"<div class='def'><b>Définition</b>Le <strong>HTML</strong> (HyperText Markup Language) est le langage de description des pages web ; il utilise des <strong>balises</strong> comme &lt;p&gt; ... &lt;/p&gt;. Un tableau se construit avec &lt;table&gt;, des lignes &lt;tr&gt;, des cellules d'en-tête &lt;th&gt; et des cellules &lt;td&gt;.</div><pre>&lt;table&gt;\n  &lt;tr&gt;&lt;th&gt;Région&lt;/th&gt;&lt;th&gt;Chef-lieu&lt;/th&gt;&lt;/tr&gt;\n  &lt;tr&gt;&lt;td&gt;Littoral&lt;/td&gt;&lt;td&gt;Douala&lt;/td&gt;&lt;/tr&gt;\n&lt;/table&gt;</pre>"},{"t":"Les médias","verrou":true},{"t":"Fusion de cellules","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":16,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Pour le site du club de tourisme, tu dois créer une page présentant trois sites touristiques (nom, région, photo) et une courte vidéo de présentation stockée dans le dossier videos.","tache":"Décris le code HTML de la page : tableau avec images et insertion de la vidéo."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r17",{"duree":20,"titre":"Création des formulaires","accroche":"Recueillir des informations sur le web.","intro":"Un formulaire HTML permet à l'utilisateur de saisir des informations : inscription, contact, commande.","objectifs":["créer un formulaire","utiliser les principaux champs","rendre un formulaire clair et accessible"],"parties":[{"t":"Le formulaire","html":"<div class='def'><b>Définition</b>Un <strong>formulaire</strong> est une zone de page web, délimitée par &lt;form&gt;, qui contient des champs de saisie et un bouton d'envoi transmettant les données à un programme (attribut action).</div>"},{"t":"Les champs","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":17,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le lycée veut un formulaire d'inscription au tournoi de football : nom, classe (liste), poste (gardien, défenseur, milieu, attaquant : un seul choix), téléphone, et acceptation du règlement.","tache":"Indique pour chaque information le champ HTML adapté et ses attributs essentiels."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r18",{"duree":20,"titre":"Mise en forme d'une page web avec le CSS","accroche":"Séparer le fond et la forme.","intro":"Le HTML décrit le contenu ; le CSS (Cascading Style Sheets) décrit sa présentation : couleurs, polices, marges, disposition.","objectifs":["définir le CSS","écrire des règles CSS","lier une feuille de style à une page"],"parties":[{"t":"Le CSS","html":"<div class='def'><b>Définition</b>Le <strong>CSS</strong> est le langage qui décrit la présentation des pages HTML. Une <strong>règle</strong> se compose d'un sélecteur et de déclarations propriété : valeur.</div><pre>h1 { color: #142554; text-align: center; }\np { font-family: Arial, sans-serif; font-size: 16px; }\n.important { background-color: #FFC93C; }\n#menu { margin: 0; padding: 10px; }</pre>"},{"t":"Les sélecteurs","verrou":true},{"t":"Intégrer le CSS","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":18,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le site du club compte six pages dont chacune contient ses propres attributs de couleur ; le président veut changer la couleur de tous les titres en une seule opération.","tache":"Explique pourquoi une feuille de style externe résout le problème et écris la règle et la ligne de liaison nécessaires."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r19",{"duree":20,"titre":"Organisation des dossiers d'un site web","accroche":"Une arborescence claire pour un site qui fonctionne.","intro":"Un site web est un ensemble de fichiers liés entre eux. Une bonne organisation des dossiers évite les liens cassés et facilite la mise en ligne.","objectifs":["organiser l'arborescence d'un site","écrire des chemins relatifs","créer des liens entre pages"],"parties":[{"t":"L'arborescence","html":"<div class='def'><b>Définition</b>L'<strong>arborescence d'un site</strong> est l'organisation de ses fichiers en dossiers : la page d'accueil index.html à la racine, et des dossiers par type de ressource.</div><pre>monsite/\n   index.html\n   contact.html\n   css/style.css\n   images/logo.png\n   js/script.js\n   pages/activites.html</pre>"},{"t":"Les chemins relatifs","verrou":true},{"t":"Règles de nommage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":19,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Le site du club fonctionne sur l'ordinateur de Paul, mais après copie sur une clé et ouverture sur un autre poste, aucune image ne s'affiche ; ses balises contiennent src=\"C:\\Users\\Paul\\Desktop\\Photo Club.JPG\".","tache":"Explique la cause du problème et propose une organisation et un chemin corrects."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r20",{"duree":20,"titre":"Introduction au JavaScript","accroche":"Rendre une page web interactive.","intro":"HTML structure, CSS présente, JavaScript fait agir : il réagit aux clics, calcule, modifie la page sans la recharger.","objectifs":["situer JavaScript par rapport à HTML et CSS","insérer un script dans une page","utiliser alert, console.log et document"],"parties":[{"t":"Rôle de JavaScript","html":"<div class='def'><b>Définition</b><strong>JavaScript</strong> est un langage de programmation interprété par le navigateur, qui permet de rendre une page web interactive : réagir aux actions de l'utilisateur, effectuer des calculs, modifier le contenu de la page.</div>"},{"t":"Insérer un script","verrou":true},{"t":"Agir sur la page","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":20,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Sur la page d'accueil du club, un paragraphe d'identifiant « date » doit afficher automatiquement la date du jour, et un message de bienvenue doit apparaître dans la console.","tache":"Écris le script et indique où le placer."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r21",{"duree":20,"titre":"Variables et instructions d'entrée/sortie en JavaScript","accroche":"Lire et afficher en JavaScript.","intro":"Comme en algorithmique, un programme JavaScript manipule des variables et échange des informations avec l'utilisateur.","objectifs":["déclarer des variables","lire une donnée","afficher un résultat"],"parties":[{"t":"Variables","html":"<div class='def'><b>Définition</b>En JavaScript, une <strong>variable</strong> se déclare avec <code>let</code> (valeur modifiable) ou <code>const</code> (valeur fixe). Les types sont dynamiques : nombre, chaîne, booléen, tableau, objet.</div><pre>let nom = \"Awa\";\nconst TVA = 0.1925;\nlet age = 16;</pre>"},{"t":"Entrées et sorties","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":21,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un élève écrit : let a = prompt(\"a ?\"); let b = prompt(\"b ?\"); alert(a + b); il saisit 15 et 10 et obtient 1510.","tache":"Explique le résultat et corrige le programme."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r22",{"duree":20,"titre":"Opérations de base en JavaScript","accroche":"Calculer et comparer.","intro":"JavaScript dispose d'opérateurs arithmétiques, de comparaison et logiques, ainsi que de l'objet Math pour les calculs.","objectifs":["utiliser les opérateurs arithmétiques","utiliser les comparaisons et opérateurs logiques","utiliser l'objet Math"],"parties":[{"t":"Opérateurs","html":"<div class='def'><b>Définition</b>Un <strong>opérateur</strong> est un symbole qui réalise une opération sur des valeurs : +, −, *, / (division), % (reste), ** (puissance).</div><pre>let r = 17 % 5;   // 2\nlet p = 2 ** 10;  // 1024\nlet q = Math.floor(17 / 5); // 3</pre>"},{"t":"Comparaisons et logique","verrou":true},{"t":"L'objet Math","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":22,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Une boutique en ligne applique une remise de 15 % si le montant dépasse 20 000 F et si le client est membre.","tache":"Écris l'instruction JavaScript qui calcule le montant à payer à partir de montant et membre (booléen), arrondi au franc."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r23",{"duree":20,"titre":"Traduction des algorithmes en JavaScript","accroche":"De l'algorithme au programme.","intro":"Les structures de l'algorithmique se traduisent presque mot pour mot en JavaScript.","objectifs":["traduire les structures alternatives","traduire les boucles","traduire les tableaux"],"parties":[{"t":"Table de correspondance","html":"<div class='def'><b>Définition</b><strong>Traduire un algorithme</strong>, c'est réécrire chacune de ses instructions dans la syntaxe d'un langage de programmation, sans changer sa logique.</div><ul><li>x ← 5 → <code>x = 5;</code></li><li>Si ... Alors ... Sinon → <code>if (...) { } else { }</code></li><li>Pour i ← 1 à n → <code>for (let i = 1; i &lt;= n; i++) { }</code></li><li>Tant que → <code>while (...) { }</code></li><li>Tableau[1..n] → <code>let t = [];</code> (indices à partir de 0)</li></ul>"},{"t":"Exemple","verrou":true},{"t":"Les fonctions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":23,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"L'algorithme suivant compte les élèves admis : nb ← 0 ; Pour i ← 1 à n : Si T[i] ≥ 10 Alors nb ← nb + 1 ; Écrire(nb).","tache":"Traduis-le en une fonction JavaScript qui reçoit un tableau de notes, puis donne le résultat pour [9, 14, 10, 7, 16]."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r24",{"duree":20,"titre":"Fonctions et évènements en JavaScript","accroche":"Réagir aux actions de l'utilisateur.","intro":"Une page devient interactive quand des fonctions s'exécutent en réponse à des évènements : clic, saisie, chargement.","objectifs":["écrire une fonction JavaScript","associer une fonction à un évènement","modifier la page en réponse"],"parties":[{"t":"Évènements","html":"<div class='def'><b>Définition</b>Un <strong>évènement</strong> est une action détectée par le navigateur : clic (click), saisie (input), survol (mouseover), chargement de la page (load), envoi d'un formulaire (submit). Un <strong>gestionnaire d'évènement</strong> est la fonction exécutée quand il se produit.</div>"},{"t":"Associer une fonction","verrou":true},{"t":"Lire un champ","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":24,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Une page doit calculer l'indice de masse corporelle (IMC = poids ÷ taille²) quand on clique sur « Calculer », à partir de deux champs d'identifiants poids et taille.","tache":"Écris la fonction et l'association à l'évènement, avec un affichage arrondi à une décimale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r25",{"duree":20,"titre":"Programmation d'un convertisseur","accroche":"Un projet complet en HTML, CSS et JavaScript.","intro":"Ce projet réunit les acquis : une page avec un formulaire, une présentation soignée et un script qui convertit des valeurs.","objectifs":["concevoir l'interface d'un convertisseur","programmer la conversion","tester et améliorer l'application"],"parties":[{"t":"Le projet","html":"<div class='def'><b>Définition</b>Un <strong>convertisseur</strong> est une application qui transforme une valeur d'une unité dans une autre : francs CFA en euros, degrés Celsius en Fahrenheit, kilomètres en miles.</div><p>Rappel : 1 euro = 655,957 F CFA (parité fixe).</p>"},{"t":"Le code","verrou":true},{"t":"Tester","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":25,"apc":{"module":"Programmation en C, HTML, CSS et JavaScript","famille":"Algorithmique et programmation","agir":"Traduire un algorithme en programme et créer une page web","situation":"Un vendeur de pièces détachées de Douala reçoit des prix en euros de ses fournisseurs et veut une page qui convertit un montant en euros en F CFA, en ajoutant 10 % de frais de transport.","tache":"Écris la fonction de conversion et donne le résultat pour 250 €."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r26",{"duree":20,"titre":"Besoins matériels pour l'installation d'un système d'exploitation","accroche":"Vérifier avant d'installer.","intro":"Avant d'installer un système d'exploitation, on vérifie que l'ordinateur dispose des ressources minimales demandées.","objectifs":["définir un système d'exploitation","lire une configuration minimale","vérifier la compatibilité d'un ordinateur"],"parties":[{"t":"Le système d'exploitation","html":"<div class='def'><b>Définition</b>Le <strong>système d'exploitation</strong> (SE) est le logiciel de base qui gère le matériel (processeur, mémoire, disques, périphériques) et permet l'exécution des applications. Exemples : Windows, Linux (Ubuntu), macOS, Android.</div>"},{"t":"La configuration requise","verrou":true},{"t":"Vérifier un poste","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":26,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un système demande au minimum un processeur 64 bits, 4 Go de RAM et 64 Go d'espace disque. Le vieil ordinateur du secrétariat possède un processeur 64 bits, 2 Go de RAM et 120 Go de disque dont 70 Go libres.","tache":"Indique si l'installation est possible et propose une solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r27",{"duree":20,"titre":"Installation d'un système d'exploitation","accroche":"Les étapes d'une installation propre.","intro":"Installer un système d'exploitation suit une démarche précise, de la sauvegarde des données à la configuration du premier compte.","objectifs":["préparer une installation","suivre les étapes d'installation","partitionner un disque"],"parties":[{"t":"Préparer","html":"<div class='def'><b>Définition</b>L'<strong>installation d'un système d'exploitation</strong> consiste à copier ses fichiers sur le disque, à préparer ce disque et à configurer les réglages de base pour que l'ordinateur démarre sur ce système.</div><ol><li>Sauvegarder les données personnelles.</li><li>Créer un support d'installation (clé USB démarrable) depuis l'image officielle.</li><li>Régler l'ordre de démarrage dans le BIOS/UEFI pour démarrer sur la clé.</li></ol>"},{"t":"Installer","verrou":true},{"t":"Partitions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":27,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Le technicien de ton lycée doit réinstaller le système d'un ordinateur infecté contenant les bulletins de l'année non sauvegardés.","tache":"Décris dans l'ordre les étapes à suivre, en insistant sur celle qui protège les bulletins."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r28",{"duree":20,"titre":"Configuration d'un système d'exploitation","accroche":"Adapter le système à l'utilisateur.","intro":"Après l'installation, on configure le système : comptes, pilotes, réseau, mises à jour, sécurité et personnalisation.","objectifs":["créer et gérer des comptes utilisateurs","installer des pilotes","régler mises à jour, réseau et sécurité"],"parties":[{"t":"Les comptes","html":"<div class='def'><b>Définition</b><strong>Configurer un système d'exploitation</strong>, c'est régler ses paramètres pour l'adapter au matériel et aux utilisateurs : comptes, pilotes, réseau, sécurité, apparence.</div><p>Un compte <strong>administrateur</strong> peut installer des logiciels et modifier les réglages ; un compte <strong>standard</strong> a des droits limités. Pour un poste partagé (salle informatique), les élèves utilisent des comptes standards.</p>"},{"t":"Pilotes et périphériques","verrou":true},{"t":"Réseau, mises à jour, sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":28,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Après installation, l'imprimante du secrétariat n'imprime que des caractères incompréhensibles et la résolution de l'écran est très faible ; tous les employés utilisent le compte administrateur.","tache":"Identifie les causes de ces problèmes et propose une configuration correcte."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r29",{"duree":20,"titre":"Introduction à l'invite de commandes","accroche":"Commander l'ordinateur au clavier.","intro":"L'invite de commandes permet de piloter l'ordinateur en tapant des instructions. Elle est rapide et indispensable aux techniciens.","objectifs":["définir l'invite de commandes","ouvrir l'interpréteur","se repérer dans l'arborescence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>invite de commandes</strong> (interface en ligne de commande) est une interface textuelle dans laquelle l'utilisateur tape des commandes interprétées par le système : cmd ou PowerShell sous Windows, le terminal (bash) sous Linux.</div>"},{"t":"Se repérer","html":"<p>L'invite affiche le dossier courant, par exemple <code>C:\\Users\\Eleve&gt;</code>. Commandes de base sous Windows :</p><ul><li><code>cd dossier</code> : entrer dans un dossier ; <code>cd ..</code> : remonter ;</li><li><code>dir</code> : lister le contenu (ls sous Linux) ;</li><li><code>cls</code> : effacer l'écran (clear sous Linux) ;</li><li><code>cd \\</code> : revenir à la racine du lecteur (C:\\) ;</li><li><code>help</code> : aide.</li></ul><p>Pour ouvrir l'invite : touches Windows + R, taper <code>cmd</code>, puis Entrée (ou rechercher « Invite de commandes » dans le menu Démarrer).</p>","retenir":"cd, dir, cls, help.","labo":{"type":"trier","invite":"Choisis une commande.","items":[["cd","changer de dossier."],["cd ..","remonter au dossier parent."],["dir","lister le contenu du dossier."],["cls","effacer l'écran."]]}},{"t":"Intérêt","html":"<p>Exécuter des tâches rapides ou répétitives, diagnostiquer le réseau, gérer un ordinateur à distance, écrire des scripts d'automatisation.</p><div class='attention'><b>Attention</b>certaines commandes suppriment des fichiers sans passer par la corbeille : on vérifie avant d'appuyer sur Entrée.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> L'invite de commandes est :</p><ol type='a'><li>une interface textuelle</li><li>un logiciel de dessin vectoriel</li><li>un navigateur web</li><li>un tableur</li></ol><details><summary>Voir la réponse</summary><p><strong>une interface textuelle</strong>. On tape des commandes au clavier.</p></details><p><strong>Exercice.</strong></p><p>Quelle commande permet de remonter d'un dossier ?</p><details><summary>Voir la réponse</summary><p>(Réponse : cd ..)</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Invite : interface textuelle (cmd, PowerShell, bash).","cd, cd .., dir, cls, help.","Rapidité, diagnostic, scripts."],"exo":"<p>Quelle commande permet de remonter d'un dossier ? <em>(Réponse : cd ..)</em></p>","quiz":[{"q":"L'invite de commandes est :","r":["une interface textuelle","un logiciel de dessin vectoriel","un navigateur web","un tableur"],"b":0,"e":"On tape des commandes au clavier."},{"q":"Sous Windows, l'invite de commandes s'ouvre avec :","r":["paint","cmd","calc","notepad"],"b":1,"e":"Windows + R, puis cmd."},{"q":"La commande cd sert à :","r":["créer un nouveau dossier vide","copier un fichier","changer de dossier","effacer l'écran"],"b":2,"e":"Change directory."},{"q":"cd .. permet de :","r":["entrer dans le dernier dossier","supprimer le dossier courant","copier le dossier","remonter au dossier parent"],"b":3,"e":"Un niveau plus haut."},{"q":"cd \\ permet de :","r":["revenir à la racine du lecteur","remonter d'un seul dossier dans l'arborescence","ouvrir le bureau","fermer l'invite"],"b":0,"e":"Par exemple C:\\."},{"q":"La commande dir sert à :","r":["supprimer le dossier courant","lister le contenu du dossier","renommer un fichier","tester le réseau"],"b":1,"e":"Équivalent de ls sous Linux."},{"q":"La commande cls sert à :","r":["fermer l'ordinateur","copier un fichier","effacer l'écran","lister les fichiers"],"b":2,"e":"De l'anglais clear screen."},{"q":"Sous Linux, l'équivalent de dir est :","r":["cd","rm","cp","ls"],"b":3,"e":"De l'anglais list (lister)."},{"q":"L'invite C:\\Users\\Eleve&gt; indique :","r":["le dossier courant","le nom de l'imprimante","l'adresse IP","la date du jour"],"b":0,"e":"On se trouve dans Eleve."},{"q":"Un intérêt de l'invite de commandes est :","r":["d'afficher de belles images en haute définition","d'automatiser des tâches répétitives","de retoucher des photos","de jouer à des jeux vidéo"],"b":1,"e":"Par des scripts."}],"c":"1re D","m":"info","rang":29,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"L'invite affiche C:\\Users\\Eleve> et tu dois afficher le contenu du dossier C:\\Users\\Eleve\\Documents\\Projets.","tache":"Écris la suite de commandes à taper et explique chacune."},"gratuit":true});
VRT_L("1re-d-info-r30",{"duree":20,"titre":"Utilisation de l'invite de commandes","accroche":"Gérer fichiers et réseau en ligne de commande.","intro":"Au-delà de la navigation, l'invite de commandes permet de créer, copier, renommer et supprimer des fichiers, et de diagnostiquer le réseau.","objectifs":["gérer des fichiers et dossiers","utiliser des commandes réseau","écrire un petit script"],"parties":[{"t":"Fichiers et dossiers","html":"<div class='def'><b>Définition</b>Une <strong>commande</strong> est une instruction tapée dans l'invite, composée d'un nom et éventuellement de paramètres (arguments) qui précisent sur quoi elle agit.</div><ul><li><code>mkdir Projet</code> : créer un dossier ;</li><li><code>copy a.txt b.txt</code> : copier ;</li><li><code>ren ancien.txt nouveau.txt</code> : renommer un fichier ou un dossier (<code>ren Mathematiques Informatique</code>) ;</li><li><code>del fichier.txt</code> : supprimer un fichier ;</li><li><code>rmdir Projet</code> : supprimer un dossier vide.</li></ul>"},{"t":"Commandes réseau","verrou":true},{"t":"Les scripts","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":30,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un poste de la salle informatique n'accède plus à internet. Le technicien veut savoir si la carte réseau a une adresse IP et si un serveur extérieur répond.","tache":"Indique les commandes à utiliser, dans l'ordre, et ce que chacune permet de conclure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r31",{"duree":20,"titre":"Concepts fondamentaux de la sécurité informatique","accroche":"Confidentialité, intégrité, disponibilité.","intro":"La sécurité informatique protège les informations et les systèmes contre les menaces. Elle repose sur quelques objectifs fondamentaux.","objectifs":["définir la sécurité informatique","citer les objectifs de sécurité","distinguer menace, vulnérabilité et risque"],"parties":[{"t":"Les objectifs","html":"<div class='def'><b>Définition</b>La <strong>sécurité informatique</strong> est l'ensemble des moyens techniques, organisationnels et humains qui protègent les systèmes d'information et leurs données.</div><ul><li><strong>confidentialité</strong> : seules les personnes autorisées accèdent à l'information ;</li><li><strong>intégrité</strong> : l'information n'est pas modifiée sans autorisation ;</li><li><strong>disponibilité</strong> : l'information est accessible quand on en a besoin ;</li><li><strong>authentification</strong> : on vérifie l'identité de l'utilisateur ;</li><li><strong>non-répudiation</strong> : on ne peut nier une action effectuée.</li></ul>"},{"t":"Menace, vulnérabilité, risque","verrou":true},{"t":"Le facteur humain","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":31,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Dans un cybercafé, le mot de passe administrateur est écrit sur un papier collé à l'écran, l'antivirus n'est pas à jour et une panne électrique a rendu le serveur inaccessible deux jours.","tache":"Pour chaque fait, identifie la vulnérabilité ou l'objectif de sécurité touché et propose une mesure."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r32",{"duree":20,"titre":"Introduction à la cybercriminalité et à la cybersécurité","accroche":"Connaître les attaques pour s'en protéger.","intro":"Les cybercriminels utilisent de nombreuses techniques pour voler des données ou de l'argent. La cybersécurité organise la défense.","objectifs":["définir cybercriminalité et cybersécurité","décrire les principales attaques","connaître les acteurs de la cybersécurité au Cameroun"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>cybercriminalité</strong> regroupe les infractions commises au moyen ou contre des systèmes informatiques ; la <strong>cybersécurité</strong> est l'ensemble des mesures qui protègent le cyberespace contre ces attaques.</div>"},{"t":"Les principales attaques","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":32,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Ta tante reçoit un SMS : « Vous avez gagné 500 000 F. Envoyez 5 000 F de frais et votre code secret au numéro ci-dessous pour recevoir votre gain. »","tache":"Identifie le type d'attaque, deux indices qui la trahissent et la conduite à tenir."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r33",{"duree":20,"titre":"Techniques de protection des données","accroche":"Sauvegarder, chiffrer, contrôler l'accès.","intro":"Protéger les données passe par des techniques complémentaires : mots de passe solides, sauvegardes, chiffrement, antivirus et mises à jour.","objectifs":["créer un mot de passe robuste","mettre en place une stratégie de sauvegarde","expliquer le chiffrement"],"parties":[{"t":"Contrôler l'accès","html":"<div class='def'><b>Définition</b>La <strong>protection des données</strong> est l'ensemble des mesures qui empêchent leur perte, leur vol ou leur modification non autorisée.</div><p>Un mot de passe robuste compte au moins 12 caractères, mêle majuscules, minuscules, chiffres et symboles, et n'est utilisé que pour un seul compte. L'<strong>authentification à deux facteurs</strong> ajoute un code reçu par SMS ou une application.</p>"},{"t":"Sauvegarder","verrou":true},{"t":"Chiffrer et protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":33,"apc":{"module":"Système d'exploitation, invite de commandes et sécurité","famille":"Environnement numérique","agir":"Installer, configurer et protéger un poste de travail","situation":"Un cybercafé de Bamenda conserve toutes les fiches de ses clients sur un seul ordinateur, protégé par le mot de passe « cyber2020 », sans aucune sauvegarde.","tache":"Identifie trois risques et propose un plan de protection en trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r34",{"duree":20,"titre":"Notions sur les images numériques","accroche":"Pixels, définition et couleurs.","intro":"Une image numérique est une grille de points colorés. Sa qualité dépend du nombre de points et de la manière de coder les couleurs.","objectifs":["définir pixel, définition et résolution","expliquer le codage RVB","comparer les formats d'images"],"parties":[{"t":"Pixels et définition","html":"<div class='def'><b>Définition</b>Un <strong>pixel</strong> est le plus petit point d'une image matricielle. La <strong>définition</strong> est le nombre de pixels (largeur × hauteur, par exemple 1920 × 1080) ; la <strong>résolution</strong> est le nombre de pixels par unité de longueur (pixels par pouce, ppp).</div>"},{"t":"Le codage des couleurs","verrou":true},{"t":"Les formats","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":34,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le journal du lycée veut publier un logo avec un fond transparent et des photos d'un match ; un élève propose de tout enregistrer en BMP « pour la qualité ».","tache":"Conseille le format adapté à chaque image et explique pourquoi le BMP n'est pas un bon choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r35",{"duree":20,"titre":"Calcul de la résolution et de la taille des fichiers multimédias","accroche":"Combien pèse une image, un son, une vidéo ?","intro":"La taille d'un fichier multimédia non compressé se calcule à partir de ses caractéristiques. Ces calculs aident à choisir supports et formats.","objectifs":["calculer la taille d'une image","calculer la taille d'un son","estimer la taille d'une vidéo"],"parties":[{"t":"Taille d'une image","html":"<div class='def'><b>Définition</b>La <strong>taille d'un fichier</strong> est la quantité de mémoire qu'il occupe, exprimée en octets et ses multiples.</div><p><strong>Taille (octets) = largeur × hauteur × profondeur de couleur (en octets)</strong>. Exemple : 1920 × 1080 × 3 = 6 220 800 octets ≈ 5,9 Mo. Dimension imprimée : pixels ÷ résolution (ppp) ; 3000 pixels à 300 ppp donnent 10 pouces, soit 25,4 cm.</p>"},{"t":"Taille d'un son","verrou":true},{"t":"Taille d'une vidéo","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":35,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le club radio du lycée enregistre une émission de 5 minutes en qualité CD (44 100 Hz, 16 bits, stéréo) et veut l'envoyer par une messagerie limitée à 16 Mo par fichier.","tache":"Calcule la taille du fichier non compressé et conclus, puis propose une solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r36",{"duree":20,"titre":"Notion d'entreprise","accroche":"L'organisation qui produit.","intro":"Pour comprendre les systèmes d'information, il faut d'abord comprendre l'entreprise : ses activités, sa structure et ses flux.","objectifs":["définir l'entreprise","décrire ses fonctions","identifier les flux d'informations"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>entreprise</strong> est une organisation qui combine des moyens humains, matériels et financiers pour produire des biens ou des services destinés à être vendus.</div><p>Elle peut être classée selon sa taille (TPE, PME, grande entreprise), son statut (publique, privée, mixte) ou son secteur.</p>"},{"t":"Fonctions et structure","verrou":true},{"t":"Les flux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":36,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une PME de transformation de manioc à Ebolowa reçoit des commandes par téléphone, les note sur des papiers volants, et oublie souvent des livraisons ; les factures sont faites à la main.","tache":"Identifie les flux en jeu et les problèmes d'information, puis propose une amélioration."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r37",{"duree":20,"titre":"Introduction aux systèmes d'information (1)","accroche":"L'information, ressource de l'organisation.","intro":"Toute organisation produit, stocke et utilise des informations. Le système d'information organise ces activités.","objectifs":["définir le système d'information","décrire ses fonctions","distinguer SI et système informatique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>système d'information</strong> (SI) est l'ensemble organisé de ressources (personnes, données, procédures, matériels, logiciels) qui permet de collecter, mémoriser, traiter et diffuser l'information utile à une organisation.</div>"},{"t":"Les quatre fonctions","verrou":true},{"t":"SI et système informatique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":37,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Au lycée, les notes sont saisies par les enseignants dans un logiciel, la moyenne est calculée automatiquement, et les bulletins sont imprimés puis remis aux parents.","tache":"Associe chaque étape à une fonction du SI et cite deux ressources humaines et deux ressources techniques de ce système."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r38",{"duree":20,"titre":"Introduction aux systèmes d'information (2)","accroche":"Composants, acteurs et niveaux de décision.","intro":"Ce second volet étudie les composants du SI, ses utilisateurs et le rôle de l'information dans la prise de décision.","objectifs":["décrire les composants du SI","identifier les niveaux de décision","connaître les qualités d'une information utile"],"parties":[{"t":"Les composants","html":"<div class='def'><b>Définition</b>Les <strong>composants d'un SI</strong> sont les ressources humaines (utilisateurs, informaticiens), les ressources matérielles (ordinateurs, réseaux), les ressources logicielles (applications, bases de données), les données et les procédures (règles de fonctionnement).</div>"},{"t":"Les niveaux de décision","verrou":true},{"t":"Une information utile","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":38,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Le directeur d'une chaîne de trois pharmacies reçoit les chiffres de ventes avec un mois de retard et découvre trop tard des ruptures de stock de médicaments contre le paludisme.","tache":"Identifie les défauts de l'information reçue et propose une amélioration du SI."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r39",{"duree":20,"titre":"Notion de base de données","accroche":"Stocker des données organisées et partagées.","intro":"Les fichiers séparés entraînent doublons et incohérences. La base de données regroupe les informations de façon structurée et partagée.","objectifs":["définir une base de données","citer les avantages par rapport aux fichiers","donner des exemples d'utilisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>base de données</strong> est un ensemble structuré de données enregistrées sur un support, organisées pour être facilement consultées, mises à jour et partagées par plusieurs utilisateurs.</div>"},{"t":"Avantages","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":39,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Au lycée, l'adresse d'un élève figure dans trois fichiers différents (scolarité, cantine, infirmerie) ; après son déménagement, seul le fichier de scolarité a été corrigé.","tache":"Explique le problème et montre comment une base de données le résout."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r40",{"duree":20,"titre":"Notion de table","accroche":"Lignes, colonnes et clés.","intro":"Dans une base de données relationnelle, les informations sont rangées dans des tables liées entre elles par des clés.","objectifs":["définir table, enregistrement et champ","identifier une clé primaire","relier deux tables par une clé étrangère"],"parties":[{"t":"Table, champ, enregistrement","html":"<div class='def'><b>Définition</b>Une <strong>table</strong> est un ensemble de données organisé en colonnes et en lignes. Une colonne est un <strong>champ</strong> (attribut) avec un type ; une ligne est un <strong>enregistrement</strong> (n-uplet).</div><p>Exemple : table ELEVE (matricule, nom, prenom, date_naissance, classe).</p>"},{"t":"La clé primaire","verrou":true},{"t":"La clé étrangère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":40,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une bibliothèque veut enregistrer ses livres et ses emprunts : chaque emprunt concerne un livre et un élève, à une date donnée.","tache":"Propose trois tables avec leurs champs, en soulignant les clés primaires et en indiquant les clés étrangères."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-d-info-r41",{"duree":20,"titre":"Notion de SGBD","accroche":"Le logiciel qui gère la base.","intro":"Une base de données est gérée par un logiciel spécialisé, le SGBD, qui permet de la créer, de l'interroger et de la protéger.","objectifs":["définir un SGBD","citer ses fonctions","donner des exemples de SGBD"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>système de gestion de base de données</strong> (SGBD) est un logiciel qui permet de créer, de stocker, de consulter, de modifier et de protéger les données d'une base, tout en gérant les accès de plusieurs utilisateurs.</div>"},{"t":"Les fonctions","verrou":true},{"t":"Exemples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re D","m":"info","rang":41,"apc":{"module":"Multimédia, systèmes d'information et bases de données","famille":"Systèmes d'information","agir":"Organiser l'information d'une organisation","situation":"Une petite pharmacie gère ses stocks dans un tableur ; deux employés modifient le fichier en même temps et écrasent mutuellement leurs saisies, et n'importe qui peut supprimer des lignes.","tache":"Montre comment un SGBD résoudrait ces deux problèmes et propose un SGBD adapté."},"verrou":true,"nq":10,"labo":true});
